local P = LoreForeverPacks.Begin("LoreForever_Voice_Default_MoreQuests2")
P.transportVersion = 1
P.transport = {}
P.transport["quest:100"] = {
  hash = "328255",
  fullHash = "328255",
  text = "Call of Water. At Silverpine's coast, you finish the Call of Water at the Brazier of Everfount. The rite clears nearby corruption, and a spirit of pure water appears. At the Brazier of Everfount, your final words summon a burst of light. It scatters the minor spirits threatening the spring, and the shore falls quiet. Once the spirits are gone, a Minor Manifestation of Water appears beside the brazier. The spirit thanks you for the rite and says the taint here has ebbed. Yet life across Silverpine's decaying lands continues to wane, so the Horde's shamans must stay watchful to preserve it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_100-96d3b169ba946aca93e7/1-0000.mp3", duration = 46.8636735, start = 0},
  },
}
P.transport["quest:1007"] = {
  hash = "65c5d2",
  fullHash = "65c5d2",
  text = "The Ancient Statuette. Near Zoram Strand, Talen searches for the statuette lost in the naga attack. The elf has made camp on Ashenvale’s northwestern coast and needs you to recover the relic he dropped in the surf. Naga attacked Talen as he guided a small vessel through the shallows near Zoram’s sunken ruins. He reached shore with only bare provisions and made camp in haste. In his flight, he dropped the ancient statuette he had found among the ruins into the sand. Talen braved the naga at Zoram Strand to seek the ancient statuette. When you return it, he tells you the drowned city holds centuries of forgotten mysteries. He believes the delicate carving may unlock what remains hidden beneath the tides.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1007-d1754f26cf008347469f/1-0000.mp3", duration = 44.7477551, start = 0},
  },
}
P.transport["quest:1009"] = {
  hash = "87d9c8",
  fullHash = "87d9c8",
  text = "Ruuzel. On the Zoram Strand, Talen seeks a ring that may open an ancient statuette. The naga have taken it to their island sanctuary. Talen believes the Ring of Zoram can open an ancient statuette found on the coast. Before the Great Sundering broke Kalimdor and sank its coastal cities, powerful night elven nobles ruled Zoram. The ring belonged among their regalia.\n\nAfter the cataclysm, the ring vanished beneath the waves for millennia. The secrets of sunken relics remained hidden from curious eyes. Naga have recently come to the Zoram Strand and begun searching the ruins of their former homeland. Ruuzel leads the local brood. She found the Ring of Zoram and took it to her sanctuary on an island to the north.\n\nTalen, a night elf, asks Alliance travelers to hunt Ruuzel and reclaim the heirloom. He hopes to use it to open the statuette recovered from the shallows.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1009-edf561a610a81ff3d3d4/1-0000.mp3", duration = 54.7787755, start = 0},
  },
}
P.transport["quest:101"] = {
  hash = "b86e54",
  fullHash = "b86e54",
  text = "The Totem of Infliction. In Darkshire, Madame Eva offers travelers a ward against Duskwood's dangers. She needs ghoul fangs, skeleton fingers, and spider venom to enchant a charm that strikes back at attackers. Madame Eva reads fortunes in her candle-lit home in Darkshire. She sees danger and violence ahead, then offers practical sorcery beside her divinations. To ward against Duskwood's predators, she needs ten ghoul fangs, ten skeleton fingers, and five vials of spider venom from the haunted woods. Madame Eva binds ghoul fangs, fingers from restless skeletons, and spider venom with enchantments. When its bearer faces mortal peril, the totem gives off a magical aura. It reflects cruelty and harms anyone who strikes its bearer.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_101-380b41dd6568afdb6cff/1-0000.mp3", duration = 51.7485714, start = 0},
  },
}
P.transport["quest:1010"] = {
  hash = "9695b9",
  fullHash = "9695b9",
  text = "Bathran's Hair. At Maestra's Post in western Ashenvale, Orendil Broadleaf seeks Bathran's Hair for a sick child in Astranaar. He believes the illness afflicts the child's spirit, so he sends you north to ancient ruins where the uncommon restorative herb was gathered in the past. At Maestra's Post, Orendil Broadleaf faces a troubling illness. He is a night elf herbalist, and the post lies just south of the Darkshore border. A young child in Astranaar is gravely ill, and ordinary remedies have failed. Orendil believes the sickness touches the child's spirit as well as the flesh. So he seeks Bathran's Hair, an uncommon restorative herb gathered in the ancient elven ruins to the north.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1010-3a6a9924d43d1a8f136f/1-0000.mp3", duration = 49.2146939, start = 0},
  },
}
P.transport["quest:1011"] = {
  hash = "2354f9",
  fullHash = "2354f9",
  text = "Forsaken Diseases. Kayneth Stillwind watches the Forsaken draw nearer in eastern Ashenvale. He fears they are brewing blights to ravage sacred elven lands, so he sends Alliance champions to a camp near Dor'Danil Barrow Den to seize a sample. Ashenvale's night elves have long contended with satyrs, raging elementals, and orcish logging crews. Now the Forsaken bring a darker danger. The undead arm of the Horde is taking root near ancient ruins and sacred barrow dens. Their presence brings war and fear that alchemical plague may spread through Kaldorei groves. South of Forest Song, near Dor'Danil Barrow Den, Forsaken apothecaries and scouts have fortified a camp. They bottle untested toxins among brewing caldrons and foul reagents. Kayneth Stillwind sends scouts inside to recover an intact Bottle of Disease. Its volatile contents can then be studied before the Forsaken unleash it across the forest.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1011-4e8bd432b21894caaa0c/1-0000.mp3", duration = 62.5893878, start = 0},
  },
}
P.transport["quest:1013"] = {
  hash = "d9c2e9",
  fullHash = "d9c2e9",
  text = "The Book of Ur. Keeper Bel'dugur sends Horde champions into Shadowfang Keep to find Ur's book. In the Undercity's Apothecarium, he seeks the work of Ur, a dead mage of Dalaran, for the Forsaken to use its research into other planes. Before the Third War destroyed Dalaran, the brilliant human wizard Ur devoted his scholarship to realms beyond Azeroth. The Kirin Tor governed conjuration and contact with outer planes closely, but Ur studied beings from other dimensions, including the savage worgen. He hesitated to wield their alien powers, judging them dangerously uncontrollable. So his written work became a prize for those with fewer scruples. Archmage Arugal took Ur's treatise and used its research before settling in Shadowfang Keep. Without Ur's reservations, Arugal summoned bloodthirsty worgen into Silverpine. Their curse consumed Pyrewood and the surrounding valleys. Now the volume lies neglected in the keep's towers, watched by Arugal's feral pets.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1013-df244084b1c0de16d8d5/1-0000.mp3", duration = 75.1542857, start = 0},
  },
}
P.transport["quest:1014"] = {
  hash = "ce6776",
  fullHash = "ce6776",
  text = "Arugal Must Die. At the Sepulcher, Dalar Dawnweaver calls champions to face Arugal. The rogue archmage rules Shadowfang Keep, and his worgen threaten the Forsaken’s hold on Silverpine Forest. Shadowfang Keep rises above the woods, and Archmage Arugal commands the worgen within. The Forsaken have made the Sepulcher their base, yet Silverpine Forest remains dangerous and fiercely contested. Guilt and dark sorcery drove Arugal mad. He unleashed the feral worgen upon Lordaeron, and now his ravenous beasts roam the forest paths, hindering Lady Sylvanas Windrunner’s effort to secure the region. Dalar Dawnweaver knows that hunting worgen across the forest will not end the danger. Their source lies within Shadowfang Keep. You must breach the old stronghold, fight through Arugal’s worgen brood, and confront the mad wizard in his aerie. His severed head proves his death, and his defeat can break his hold over the region.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1014-61d51b2d195d942d648a/1-0000.mp3", duration = 69.6946939, start = 0},
  },
}
P.transport["quest:1016"] = {
  hash = "b56ccc",
  fullHash = "b56ccc",
  text = "Elemental Bracers. At Silverwind Refuge, Sentinel Velene Starstrike seeks the hand behind the tainted waters. She asks you to gather intact bracers from hostile elementals so a divining scroll can reveal who summoned them. Rogue water elementals trouble Ashenvale’s sacred waters. Unlike the wild spirits that belong to the world, these creatures bear signs of conjuration. Their sudden arrival at Silverwind Refuge warns the Sentinels that outside corruption is reaching deeper into the forest’s waterways. Sentinel Velene Starstrike believes someone bound and unleashed the elementals. She gives you a magical divining scroll to identify the culprit. The spell needs intact bracers taken from the spirits before they dissipate. Their lingering arcane signature can lead the scroll to whoever called the elementals into being.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1016-b48552dae098e9d07796/1-0000.mp3", duration = 51.0955102, start = 0},
  },
}
P.transport["quest:1017"] = {
  hash = "cf0330",
  fullHash = "cf0330",
  text = "Mage Summoner. At Silverwind Refuge, Sentinel Velene Starstrike sends a strike south after water elementals near Mystral Lake are corrupted. The Sentinels send adventurers across the border to kill the undead mage Sarilus Foulborne atop Dreadmist Peak. Night elves rarely send scouts south into the Barrens without grave cause. Sentinel Velene Starstrike traced unnatural disturbances among the water elementals around Mystral Lake to Sarilus Foulborne, a Forsaken conjurer practicing his arts just across the border. For the Sentinels at Silverwind Refuge, an enemy sorcerer defiling nature so close to home cannot be tolerated. Sarilus Foulborne has made his lair high on Dreadmist Peak, a craggy mountain crawling with Burning Blade cultists. From there, he summons ranks of water elementals and bends them to his will, defying night elf authority from Horde lands. Reaching him means braving enemy territory and cutting through his summoned forces. The Sentinels demand his severed head as proof that their vengeance reaches beyond the forest line.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1017-c2d2fc99b16722128b73/1-0000.mp3", duration = 71.4187755, start = 0},
  },
}
P.transport["quest:1020"] = {
  hash = "335ffd",
  fullHash = "335ffd",
  text = "Orendil's Cure. In Ashenvale, a child in Astranaar waits for Orendil's Cure. Orendil Broadleaf sends you with a remedy made from rare flora. Pelturas Whitemoon watches his daughter Relara waste away in Astranaar. A severe sickness has baffled those nearby. So he sought help from herbalists across Ashenvale before hope began to fade. Orendil Broadleaf brews a draught to halt Relara's affliction. It calls for several components, including Bathran's hair. He entrusts the cure to you and sends you south and east along the forest highway to Astranaar, where Relara waits.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1020-9f5c8b78ad699e3f81e4/1-0000.mp3", duration = 37.3812245, start = 0},
  },
}
P.transport["quest:1022"] = {
  hash = "857c56",
  fullHash = "857c56",
  text = "The Howling Vale. Worgen have overrun a ruined shrine at the Howling Vale near Felwood. Sentinel Melyria Frostshadow seeks the cause of their arrival in Ashenvale. Worgen cries echo from a ruined shrine in northern Ashenvale. Beyond a cavern path near the Felwood border, the shrine of Mel'Thandris lies overrun. Sentinel Melyria Frostshadow fears the worgen may bring another disaster to the woodland realm. Night elf sentinels already spend great effort holding back demonic corruption from Felwood.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1022-285c3520017fcac8def0/1-0000.mp3", duration = 35.7616327, start = 0},
  },
}
P.transport["quest:1023"] = {
  hash = "0c5588",
  fullHash = "0c5588",
  text = "Raene's Cleansing. At Lake Falathim, Raene Wolfrunner's search for Teronis has become a search for what he left behind. You are to bring his journal and a glowing gem held by the murlocs back to her in Astranaar. Raene Wolfrunner sent you to Lake Falathim to find Teronis, a night elf sentinel. You find him dead beside the water. His journal is intact, with an account of his assignment and what he learned about Ashenvale's strange disturbances. Teronis traced a rare, glowing stone to Lake Falathim. Now the lake's aggressive murlocs hold it. Recover the gem and Teronis' journal, and his work can continue.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1023-763d83bbe57c18e2e7c0/1-0000.mp3", duration = 44.277551, start = 0},
  },
}
P.transport["quest:1024"] = {
  hash = "25e7c1",
  fullHash = "25e7c1",
  text = "Raene's Cleansing. In Ashenvale, Raene Wolfrunner seeks a way to restore Dartol's ancient rod. A Glowing Gem has brought her to Shael'dryn, a dryad east of Iris Lake. Raene Wolfrunner studies the field notes of Teronis, the sentinel who died investigating Ashenvale's troubled furbolgs. His work points to an ancient rod made by a night elf named Dartol. Raene has found a Glowing Gem, yet her skill as a huntress cannot explain the relic's arcane and natural mysteries. Raene sends you northeast toward Iris Lake to find Shael'dryn, a dryad who lives beside a moonwell. As one of the Daughters of Cenarius, Shael'dryn understands the forest and its ancient relics. Bring her the Glowing Gem, and she may tell you what else is needed to restore Dartol's Rod.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1024-e5de661de90ab9a86fb4/1-0000.mp3", duration = 59.6636735, start = 0},
  },
}
P.transport["quest:1025"] = {
  hash = "bbc947",
  fullHash = "bbc947",
  text = "An Aggressive Defense. In Ashenvale, Raene Wolfrunner sends Alliance defenders against the Foulweald furbolgs. Corruption has made the tribe dangerous along the road east of Astranaar. Furbolgs attack travelers on the road east from Astranaar toward the Falfarren River. Sentinel Raene Wolfrunner sends capable defenders to strike the Foulweald camps just south of the highway. Their attacks have made this vital road through Ashenvale dangerous for all who travel it. The Foulweald were once friends and allies of the night elves. For ages, the kaldorei and furbolgs shared reverence for nature and the wild gods. The Burning Legion's invasion left a taint that shattered many furbolg minds. Peaceful neighbors became violent reavers, and innocent travelers now face their attacks.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1025-12f1dfcca544a6e7c1ae/1-0000.mp3", duration = 51.2522449, start = 0},
  },
}
P.transport["quest:1026"] = {
  hash = "e9965c",
  fullHash = "e9965c",
  text = "Raene's Cleansing. In Ashenvale, Raene's Cleansing brings Dartol's Rod closer to wholeness. Shael'dryn knows where its iron shaft lies, in a chest near the Felwood border. The search leads toward treants changed by corruption. Raene Wolfrunner sends you to Shael'dryn, a keeper who watches over a moonwell deep in Ashenvale. Shael'dryn knows where Dartol's Rod's iron shaft lies. To reach it, you must face the taint spreading through the northern woods. The shaft rests in an old chest in a quiet glade near the Felwood border. A wooden key will open the chest, and Crazed and Withered Ancients carry it. These treants wander the mountain road north toward Felwood. Corruption from the demonic wastes spreads south and has shattered their natural harmony. Once guardians of the wild, they are now tormented and hostile. The key lies with them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1026-78c5e4218fbb34e9e850/1-0000.mp3", duration = 62.8767347, start = 0},
  },
}
P.transport["quest:1027"] = {
  hash = "abcfb1",
  fullHash = "abcfb1",
  text = "Raene's Cleansing. In Ashenvale, Raene Wolfrunner and Shael'dryn seek the last piece of Dartol's Rod. They hope the relic can cleanse the forest and slow the furbolg attacks on its night elves. At Dor'Danil barrow den, night elf druids guarded the iron pommel of Dartol's Rod. Disaster struck, and the druids were slain. Their refuge fell, and the pommel's hiding place was lost. Now scavengers and wandering oozes consume what remains in the ruins east of the southern road. Dartol was an evil wizard, and he has died. Yet the rod he made holds powers that can transform. Raene Wolfrunner and Shael'dryn seek to reassemble it, hoping it can slow the furbolg attacks on Ashenvale's night elves. The iron pommel is the last piece Shael'dryn needs before she can try to mend the broken rod at the moonwell.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1027-d132adc6a9bb7e940946/1-0000.mp3", duration = 60.682449, start = 0},
  },
}
P.transport["quest:1028"] = {
  hash = "1fd1ca",
  fullHash = "1fd1ca",
  text = "Raene's Cleansing. At Shael'dryn's direction, you climb toward a mountain shrine in southeastern Ashenvale. The basin there holds the magic to restore the rebuilt Rod of Dartol. Shael'dryn sends you from her moonwell into Ashenvale's wild southeastern slopes. There, ancient shrines often stood high among mountain crags, far from roads and hidden beneath dense forest canopies. You cross unmarked ground along rock faces and climb winding trails known mostly to Sentinels and woodland hermits. A stone basin waits in a quiet forest alcove. Though dormant, the shrine holds protective magic placed there by night elves long ago. Rest the rebuilt Rod of Dartol in the basin, and the shrine's sleeping power awakens. Its magic flows into the rod and restores its enchantment, so it can cleanse the land.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1028-847ac039591c555350fb/1-0000.mp3", duration = 61.8579592, start = 0},
  },
}
P.transport["quest:1029"] = {
  hash = "206436",
  fullHash = "206436",
  text = "Raene's Cleansing. At Iris Lake, Shael'dryn entrusts you with a restored rod for Raene Wolfrunner in Astranaar. You carry it back to report success and honor Teronis, the fallen scout. Dartol's Rod of Transformation has been reforged from components and ancient gem fragments gathered in corrupted reaches of Ashenvale. Near Iris Lake, the dryad Shael'dryn renews its magic. Then she sends you along the forest roads to Astranaar, where Raene Wolfrunner awaits the restored rod.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1029-e1194b55d0083fc0dc1c/1-0000.mp3", duration = 32.757551, start = 0},
  },
}
P.transport["quest:1030"] = {
  hash = "827f02",
  fullHash = "827f02",
  text = "Raene's Cleansing. In Ashenvale, Raene Wolfrunner seeks a way to speak with an uncorrupted furbolg. Southeast of Mystral Lake, Krolg reveals the resentment some surviving furbolgs hold toward the night elves. Raene Wolfrunner believes the late night elf meant to approach the furbolgs using Dartol’s restored Rod of Transformation. Ashenvale’s woods have grown perilous, and madness spreads through the tribes. There is no path to direct diplomacy. The rod gives you a furbolg’s shape, so you can try to pass their territorial rage and find someone willing to speak.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1030-80e1ad8b5ebccf8259c7/1-0000.mp3", duration = 40.4114286, start = 0},
  },
}
P.transport["quest:1033"] = {
  hash = "ae90ae",
  fullHash = "ae90ae",
  text = "Elune's Tear. In Astranaar, Pelturas Whitemoon seeks a cure for his ailing daughter, Relara. A brew made from Bathran's hair slowed her sickness, but did not cleanse it. Now Pelturas asks you to bring Elune's Tear from Iris Lake, hoping its sacred power can drive the corruption from her. Pelturas Whitemoon's young daughter, Relara, lies gravely ill in Astranaar. Orendil Broadleaf's brew, made from Bathran's hair, slowed her sickness but did not clear it from her body. Ordinary remedies have failed. So Pelturas turns to the old traditions of his people and seeks a cure touched by divine cleansing light. Orendil Broadleaf named a stronger remedy in case the herbal brew failed: Elune's Tear, a sacred stone found on an island in Iris Lake, east of Astranaar. Night elves believe the stone bears the Moon Goddess's blessing and can purge corruption from the living. Troubled water elementals patrol the lake's shallows and banks, guarding its waters.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1033-9785617131077071b128/1-0000.mp3", duration = 66.037551, start = 0},
  },
}
P.transport["quest:1034"] = {
  hash = "df5c18",
  fullHash = "df5c18",
  text = "The Ruins of Stardust. In Astranaar, Pelturas Whitemoon searches for a way to save his daughter, Relara. Elune's Tear eased her nightmares, yet a fierce fever still grips her. Orendil Broadleaf sends him south to find cooling stardust among the ancient night elven stones. Pelturas Whitemoon keeps watch beside his daughter, Relara, as a malignant illness burns through her. Elune's Tear eased her nightmares, but the sickness remains. A fierce fever still racks her, beyond the reach of ordinary medicines. With the temple healers stretched thin, Pelturas turns to remedies drawn from nature and hopes to save her life. Orendil Broadleaf, an elder herbalist, points Pelturas south across the river from Astranaar to the Ruins of Stardust. Frosted, shimmering dust gathers on plants among the fallen marble columns and archways of this ancient kaldorei sanctuary. Called stardust, the powder is naturally cold enough to draw out unnatural heat. Pelturas hopes to grind it into a poultice and ease Relara's fever. Water elementals and wildlife make gathering the frosted dust dangerous among the flooded stones. Corrupted or stirred by changes in Ashenvale's balance, the elementals surge around sunken plazas where the bushes grow thickest. You wade through shallows that look calm and watch for ambushes from the murky depths. The sparkling bushes must yield enough clean dust to carry back to Astranaar.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1034-de2330488ca58668fcae/1-0000.mp3", duration = 102.217143, start = 0},
  },
}
P.transport["quest:1035"] = {
  hash = "a44df4",
  fullHash = "a44df4",
  text = "Fallen Sky Lake. At Fallen Sky Lake, a moonstone may restore Relara before her strength is gone. Her father, Pelturas Whitemoon, sends you southeast of Astranaar to find one among the fallen stones. For days, Pelturas Whitemoon has watched his young daughter, Relara, draw closer to death. Remedies made from Bathran's hair and stardust broke her fever, but left her weak and frail. He fears she has only a few breaths left before her spirit fades into the night. Pelturas turns to moonstones to restore Relara's strength. These fragments fell into Fallen Sky Lake, southeast of Astranaar, and night elves gathered them for their healing power. Aggressive elementals or corrupted bark now claim the stones. You must face danger with blade and spell to gather one.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1035-f78a63ffc0730330f094/1-0000.mp3", duration = 49.3191837, start = 0},
  },
}
P.transport["quest:1037"] = {
  hash = "5f49d0",
  fullHash = "5f49d0",
  text = "Velinde Starsong. In Ashenvale, Melyria Frostshadow seeks word of the commander who came before her. Velinde Starsong vanished while fighting the corruption spreading from Felwood, and Melyria sends you to Darnassus for answers. Melyria Frostshadow keeps watch in Ashenvale, following the path Velinde Starsong once held. Velinde was a priestess charged with containing the demonic corruption spreading south from Felwood. Early reports said she had the danger under control, but her campaign faltered with time. Then she vanished without warning or formal relief, leaving the fight unfinished and her fate unknown.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1037-9f95f0e52c15dad5741f/1-0000.mp3", duration = 44.4081633, start = 0},
  },
}
P.transport["quest:1038"] = {
  hash = "d12188",
  fullHash = "d12188",
  text = "Velinde's Effects. In Darnassus, the Sentinels are searching into Velinde's disappearance. Sentinel Velinde Starsong vanished after many years of service, and Thyn'tel Bladeweaver asks you to retrieve her journal from the Sentinels' quarters. Priestess Velinde Starsong served the night elves for many years and won their deep trust. When she quietly left her duties, the Sentinels thought she had personal reasons and expected her to return. Outsiders later found clues connected to the Tome of Mel'Thandris. Only then did Sentinel leaders permit a search of Velinde's private belongings.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1038-402de0724ea39914958a/1-0000.mp3", duration = 41.8220408, start = 0},
  },
}
P.transport["quest:1039"] = {
  hash = "f286db",
  fullHash = "f286db",
  text = "The Barrens Port. Thyn'tel Bladeweaver sends you south to Ratchet in search of Velinde Starsong. The Sentinels believe she sailed across the Great Sea to the Eastern Kingdoms, and her trail runs through dangerous Horde lands. Clues among Velinde Starsong's personal effects point to passage across the sea toward the Eastern Kingdoms. Ratchet is the Barrens' only working harbor. There, travelers from northern Kalimdor can find passage south or east without sailing from night elf lands. Thyn'tel Bladeweaver sends you to search the harbor master's ledgers for Velinde's name. The road to Ratchet crosses the heart of Horde lands. South of Ashenvale, orc outriders and Tauren patrols range over the Mor'shan Rampart and the dry Barrens. Neutral goblins of the Steamwheedle Cartel govern Ratchet, putting trade ahead of faction rivalries. At the docks, Wharfmaster Dizzywig records each passenger and cargo crate.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1039-e778691bd73e64f56205/1-0000.mp3", duration = 59.8987755, start = 0},
  },
}
P.transport["quest:104"] = {
  hash = "9735d9",
  fullHash = "9735d9",
  text = "The Coastal Menace. On Westfall's rocky shore, Captain Grayson's ghost calls travelers to face The Coastal Menace. His ship broke on the rocks after murlocs drove the lighthouse keeper's family from their post. The family returned, but Old Murk-Eye led another attack and killed them. Now Grayson seeks the chieftain's death and justice for the shore. The Westfall Lighthouse once guided ships through the jagged shallows along the southern coast. After murlocs frightened the lighthouse keeper's family from their post, Captain Grayson's ship struck the rocks in the dark. The family returned and lit the flame again, but danger still stalked the shore. Old Murk-Eye rallied the weaker-minded murlocs along the coast and led them against the lighthouse. In that second attack, the keeper's family died while Captain Grayson watched, helpless. Now the ghostly captain calls for Murk-Eye's death and asks for a scale as proof. He hopes to bring peace to the dead and protect sailors on the Great Sea.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_104-07308db3f44a863611b7/1-0000.mp3", duration = 71.68, start = 0},
  },
}
P.transport["quest:1040"] = {
  hash = "1d00e8",
  fullHash = "1d00e8",
  text = "Passage to Booty Bay. In Booty Bay, the trail for Velinde Starsong leads from Ratchet to Caravaneer Ruzzgot. Alliance travelers now seek the goblin caravan driver. Wharfmaster Dizzywig’s records carry the search for Velinde Starsong from Ashenvale to the sea. The night elf Sentinel booked passage on the Black Osprey in Ratchet. Old shipping manifests show the vessel was bound for Booty Bay in Stranglethorn Vale. A goblin ferry carries travelers across the Great Sea from Ratchet to the southern tip of the Eastern Kingdoms. In Booty Bay, the trail leads to Caravaneer Ruzzgot, the goblin transport master Dizzywig recommended to Velinde. She had asked about dangerous overland journeys through the southern wilderness.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1040-77b9cf67f2eb2943015a/1-0000.mp3", duration = 46.1844898, start = 0},
  },
}
P.transport["quest:1041"] = {
  hash = "c134ee",
  fullHash = "c134ee",
  text = "The Caravan Road. In Booty Bay, the search for Velinde Starsong turns north toward Darkshire. Caravaneer Ruzzgot recalls carrying the missing night elf priestess through Stranglethorn Vale. Caravaneer Ruzzgot remembers Velinde Starsong as a passenger on his caravan. Your search for the missing night elf priestess has brought you from Ashenvale to Booty Bay, at the southern edge of Stranglethorn Vale. She traveled with his caravan through the jungle, an unusual path for a night elf priestess. Ruzzgot says he and Velinde parted ways as they traveled north through Stranglethorn Vale. She set out for Duskwood, and her trail leads to Darkshire. Clerk Daltry keeps the town's records, including the names of unfamiliar travelers who enter. His ledger may hold the next clue to Velinde's whereabouts.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1041-a7e228d7a22e603e2f6c/1-0000.mp3", duration = 49.9722449, start = 0},
  },
}
P.transport["quest:1042"] = {
  hash = "2e059f",
  fullHash = "2e059f",
  text = "The Carevin Family. In Darkshire, the search for Velinde Starsong draws strangers to the Carevin family. Clerk Daltry hears of wolf-men in Ashenvale and sends them to the hunters. The search for Velinde Starsong leads from Kalimdor’s ancient forests to Duskwood. In Darkshire, Clerk Daltry finds no town record of an elven priestess staying there. But when he hears of savage wolf-men in Ashenvale, he listens closely. Beasts like those have begun terrorizing the woods around town. The Carevin family hunts the horrors troubling Duskwood. Locals know them for tracking demons, undead, and other monsters, and they have already faced the wolf-men. Their tracker, Calor, recently hauled a grisly string of severed wolf-men heads through Darkshire’s streets. So Clerk Daltry sends you to Jonathan Carevin, the stern head of the household, to learn what the hunters know about the worgen.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1042-ad5a3345bbfa1c5c294e/1-0000.mp3", duration = 54.282449, start = 0},
  },
}
P.transport["quest:1043"] = {
  hash = "6cf017",
  fullHash = "6cf017",
  text = "The Scythe of Elune. In Darkshire, the search for the Scythe of Elune turns toward the worgen hunt. Jonathan Carevin sends you to Roland's Doom, where the beasts first appeared, linking an ancient night elf relic in Kalimdor to the worgen troubling Duskwood. You have traced Priestess Velinde Starsong across Kalimdor and spoken with the Carevin household in Darkshire. Now you and Jonathan Carevin share a purpose. Nightbane worgen have overrun southern Duskwood, driven miners out and threatened what remains of the township. Carevin does not understand their supernatural origin, but he knows a willing hunter is valuable. He points you toward Roland's Doom, where the fiends were first sighted.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1043-a3b88e0ba131aa195d19/1-0000.mp3", duration = 54.3869388, start = 0},
  },
}
P.transport["quest:1044"] = {
  hash = "4105d5",
  fullHash = "4105d5",
  text = "Answered Questions. The search for Velinde Starsong carries you from Ashenvale to Darnassus, where a report awaits.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1044-d0f4cedb8cd3a2cc387d/1-0000.mp3", duration = 7.47102041, start = 0},
  },
}
P.transport["quest:1045"] = {
  hash = "b4a7c9",
  fullHash = "b4a7c9",
  text = "Raene's Cleansing. At Lake Mystral, Krolg asks you to kill Ran Bloodtooth. Disguised by Dartol's Rod of Transformation, you can earn the uncorrupted furbolgs' trust. Krolg resents the night elves and fears the rot among his people. He wants the furbolgs to answer for their own. Near Lake Mystral, Krolg lives apart from the others, displaced and weary. He blames the night elves' ancient pride for the ruin brought upon Kalimdor and the dark rot spreading through Ashenvale. Dartol's Rod of Transformation lets you approach the furbolgs in disguise. Krolg hates the kaldorei, yet he calls for neither slaughter nor the deaths of innocents. Krolg believes his people must answer for their own deeds instead of yielding to the demonic taint gripping the tribes. The corruption did not give them their flaws; it magnified their worst impulses. Ran Bloodtooth shows the danger. Ruthless and hungry for power even before the taint, the chieftain embraced the darkness. Now he threatens elves and innocent beasts alike. Krolg will not let one furbolg speak for them all.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1045-560ec07c09a6a579c564/1-0000.mp3", duration = 67.082449, start = 0},
  },
}
P.transport["quest:1046"] = {
  hash = "937bbf",
  fullHash = "937bbf",
  text = "Raene's Cleansing. In Astranaar, you bring Raene's Cleansing to its end with Ran Bloodtooth's skull. The search began with Teronis, and Ashenvale's furbolg threat is now diminished. Krolg sends you back to Astranaar after Ran Bloodtooth falls. You carry the chieftain's severed skull to Sentinel Raene Wolfrunner. It proves that the threat prowling the forest depths has been struck down.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1046-8b4c638f9d882533371d/1-0000.mp3", duration = 24.6857143, start = 0},
  },
}
P.transport["quest:1054"] = {
  hash = "23a08f",
  fullHash = "23a08f",
  text = "Culling the Threat. Astranaar fears an attack from the Thistlefur furbolgs gathering to the north. Raene Wolfrunner asks you to kill their chieftain, Dal Bloodclaw, before they strike. Astranaar lies in the heart of Ashenvale, with danger close on every side. The Thistlefur furbolgs live just north of town. Once peaceful forest dwellers, they have fallen to madness and aggression, as have many of their kin. Sentinel scouts have watched their numbers grow over recent months. Now they fear the tribe will attack Astranaar as one. Raene Wolfrunner calls on travelers to strike before the Thistlefur overrun Astranaar's palisades. Dal Bloodclaw leads the tribe and gives its members order and courage. The Sentinels ask you to bring his skull back to Astranaar. They hope his death will break the furbolgs' unity and buy the beleaguered town precious time.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1054-5d838416d5ab8d3f693e/1-0000.mp3", duration = 52.4016327, start = 0},
  },
}
P.transport["quest:1055"] = {
  hash = "e710e2",
  fullHash = "e710e2",
  text = "Raene's Cleansing. At the hidden shrine in Ashenvale, you have restored the Rod of Transformation. Now you must carry it back to Shael'dryn at her moonwell sanctuary. You have restored the Rod of Transformation at the hidden shrine in Ashenvale. Its shaft, pommel, and glowing gem are joined, and its magic has been renewed. Shael'dryn needs the rod for Raene's investigation of the furbolg attacks. Shael'dryn waits beside the forest moonwell where she guided the rod's restoration. You bring her the finished relic and confirm its magic has returned. Then the Sentinel defenders can take their next steps to protect their besieged homeland.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1055-0ebc6f66be158a8fe100/1-0000.mp3", duration = 47.9346939, start = 0},
  },
}
P.transport["quest:1057"] = {
  hash = "0a96da",
  fullHash = "0a96da",
  text = "Reclaiming the Charred Vale. Keeper Albagorm sends Alliance fighters from Stonetalon Peak to drive Bloodfury harpies from the ruined Charred Vale. Their removal will clear the way for druids and caretakers to heal the scorched land. South of Stonetalon Peak, the Charred Vale lies in ash and smoldering ruins. A lush alpine haven once stood there. A mechanized logging and mining army stripped the trees and let fires rage unchecked. For the guardians of Stonetalon, the woodland's loss to industrial greed is a wound they cannot ignore. Bloodfury harpies claimed the ashes left by the mechanical fires. They swarm the smoking lowlands, nest there, and ambush anyone who approaches. Keeper Albagorm and his allies cannot cross the soil to sow seeds of renewal. The harpies bar every outsider's way. The Bloodfury roosts must be broken before restoration can begin. Keeper Albagorm sends seasoned Alliance fighters deep among the tribe to slay its hunters, ambushers, and roguefeathers. Their numbers must fall before the land can be reclaimed for nature and the forest spirits can breathe freely again.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1057-fec068158346b4852a77/1-0000.mp3", duration = 74.9453061, start = 0},
  },
}
P.transport["quest:1058"] = {
  hash = "214cb9",
  fullHash = "214cb9",
  text = "Jin'Zil's Forest Magic. In Malaka'jin, Witch Doctor Jin'Zil holds three night elven scouts in crude iron cages. He sends Horde travelers north to gather reagents for a grim forest magic. Witch Doctor Jin'Zil practices his craft in Malaka'jin's red-rock defile, under the Horde's watch. When three night elf captives fall into his hands, he chooses a mocking ritual for his woodland foes instead of ordinary butchery. He sends you north into the peaks for thick tree sap, feline whiskers from predatory twilight runners, a shimmering fey dragon scale, and scores of eyes from local forest coursers.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1058-c3cbdf538b02d06f2045/1-0000.mp3", duration = 37.8253061, start = 0},
  },
}
P.transport["quest:1059"] = {
  hash = "5f9ca4",
  fullHash = "5f9ca4",
  text = "Reclaiming the Charred Vale. Far to the south, Keeper Albagorm looks for help to restore the Charred Vale. The Bloodfury harpies have been driven back for now, but force alone cannot heal the wounded land. Ash covers the Charred Vale in southern Stonetalon Mountains, where terrible destruction has scarred the land. Alliance forces under Keeper Albagorm drove the Bloodfury harpies from their nests in the ruins, but the harpies may return. Force can only hold them back. The ravaged earth must heal before they come back to claim the Vale. The grove tenders cannot restore the scorched land alone. So Keeper Albagorm sends you south, past the salt flats and canyons of Thousand Needles, to Thalanaar on the border of Feralas. Falfindel Waywarder waits there. The night elf druid is known for a rare gift: calling ancient forest spirits to bring life back to dead soil.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1059-b9dd1680eea903fed8c5/1-0000.mp3", duration = 57.2342857, start = 0},
  },
}
P.transport["quest:1060"] = {
  hash = "179ab4",
  fullHash = "179ab4",
  text = "Letter to Jin'Zil. Darsok Swiftdagger sends you into Stonetalon Mountains with news for his old friend, Witch Doctor Jin'Zil. Serena Bloodfeather has fallen, and Darsok wants Jin'Zil to hear of her death. After Serena Bloodfeather falls, Darsok Swiftdagger sends you into Stonetalon Mountains. The Witchwing and Bloodfeather broods came from the rugged ridges northwest of the northern Barrens, not the scrublands. You have defeated Serena, and Darsok asks you to carry news of her death to Witch Doctor Jin'Zil, an old acquaintance. Jin'Zil lives at Malaka'jin, a troll settlement in the dangerous mountain peaks.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1060-bd888c8e5dd9c771d33f/1-0000.mp3", duration = 40.5681633, start = 0},
  },
}
P.transport["quest:1066"] = {
  hash = "b0b3bd",
  fullHash = "b0b3bd",
  text = "Blood of Innocents. In Tarren Mill, Apothecary Lydon prepares a remedy for the Venture Company in Stonetalon Mountains. The Royal Apothecary Society turns to blood taken by local bandits to pacify the company. Horde leaders in Kalimdor have turned to the Royal Apothecary Society for help against the Venture Company. The company ravages the wilderness and harms its people, so Apothecary Lydon proposes alchemy instead of sending armies to blunt their axes. He means to brew an agent that will paralyze and pacify the mercenaries, leaving them weak and docile. Apothecary Lydon needs a rare and troubling ingredient: innocent blood. He will not send Horde agents to kill innocents, so he turns to the Syndicate's crimes. Fallen nobles and cutthroats occupy Durnholde Keep, where rogue shadow mages harvest innocent blood for profane rituals. Lydon targets those mages for alchemical supplies.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1066-68c58339d7bfef2956ae/1-0000.mp3", duration = 63.3469388, start = 0},
  },
}
P.transport["quest:1067"] = {
  hash = "ed27ca",
  fullHash = "ed27ca",
  text = "Return to Thunder Bluff. In Thunder Bluff, Zamah awaits the toxin Lydon made. She needs its formula to build a device that can spread it against the Venture Company. Apothecary Lydon made the toxin from ingredients gathered in the Hillsbrad Foothills. He wants to test it on living subjects, but first it needs a way to spread. You carry the vial across the Great Sea to Mulgore, where Apothecary Zamah waits.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1067-2f9058f8c8546be6e2a3/1-0000.mp3", duration = 29.44, start = 0},
  },
}
P.transport["quest:1068"] = {
  hash = "1e2a1e",
  fullHash = "1e2a1e",
  text = "Shredding Machines. In Windshear Crag, Venture Company shredders wound the spirits of Stonetalon. Seereth Stonebreak hears their cries as XT:4 and XT:9 cut through the forest. Orc shaman Seereth Stonebreak keeps watch along the dusty border between the Barrens and the Stonetalon Mountains. She listens to the unseen realm, but chaos drowns much of Stonetalon’s spiritual voice. One vision came through clear: man-shaped contraptions tearing through ancient woods at unnatural speed. Marked XT:4 and XT:9, the goblin-engineered shredders cut Windshear Crag’s timberlands and send waves of distress through the surrounding nature spirits. The Venture Company works in Windshear Crag, northwest of Greatwood Vale. To curb the damage, Horde champions go there and hunt down the logging constructs. Wrecking XT:4 and XT:9 strikes at the mountains’ commercial deforestation and quiets the wounded tree spirits’ immediate cries. Seereth warns that unless the Venture Company leaves Stonetalon entirely, far darker atrocities await the land.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1068-aa9db37e0d31ff1c12a3/1-0000.mp3", duration = 75.6244898, start = 0},
  },
}
P.transport["quest:1069"] = {
  hash = "a0c172",
  fullHash = "a0c172",
  text = "Deepmoss Spider Eggs. In Ratchet, Mebok Mizzyrix sees a chance to sell Deepmoss Spider Eggs to Booty Bay. Spider egg omelettes have become a craze there, so he sends travelers into the Stonetalon Mountains to gather fresh clutches for trade across the sea. Wealthy patrons and eccentric pirates in Booty Bay have taken to spider egg omelettes. Their taste has driven demand for rare ingredients across the Great Sea. Ratchet merchant Mebok Mizzyrix sees a chance to make a fortune by supplying the southern port. The Eastern Kingdoms have no spiders that provide these eggs, so Mebok looks to Kalimdor’s wilderness. Deepmoss spider eggs lie in the Stonetalon Mountains, where the Venture Company has cut timber. Find clutches beneath the trees still standing at Windshear Crag, or farther in, among the web-covered depths of Sishir Canyon. Gathering them means facing venomous bites and thick infestations. Even seasoned scavengers may find the swarms hard to stomach. Fresh eggs must cross the sea before they spoil or hatch. Mebok works with Ratchet’s Wharfmaster Dizzywig to book freight aboard goblin merchant ships bound for the docks of Stranglethorn Vale. Once the eggs are packed into crates, Mebok earns a tidy profit from the high seas trade in fine food.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1069-2c07b27894b1ff5ebf87/1-0000.mp3", duration = 78.7853061, start = 0},
  },
}
P.transport["quest:1070"] = {
  hash = "f6c418",
  fullHash = "f6c418",
  text = "On Guard in Stonetalon. In Ashenvale, Sentinel Thenysil asks travelers to check on Kaela Shadowspear. Kaela went into Stonetalon to watch Venture Company incursions alongside a gnome mage, but no word has come from her. In Astranaar, Sentinel Thenysil watches for threats near the ancient forest. Her friend Kaela Shadowspear entered the Stonetalon Mountains at Sentinel Wolfrunner’s order, to survey trouble in the heights. Thenysil asks passing Alliance champions to find Kaela. No word has come, and she fears for her friend’s safety. A gnome mage assigned by Alliance leaders accompanies Kaela. The night elves joined the Grand Alliance for strategic reasons, yet many Sentinels distrust arcane practitioners and gnome tinkers in the wilderness. Kaela keeps an outpost on the bluffs above Windshear Crag. From there, she watches the Venture Company’s widespread devastation.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1070-3a0edfeaecc7ce0fb3bb/1-0000.mp3", duration = 54.0212245, start = 0},
  },
}
P.transport["quest:1071"] = {
  hash = "b372e2",
  fullHash = "b372e2",
  text = "A Gnome's Respite. At Windshear Crag, the Venture Company presses into the forest while Gaxim Rustfizzle struggles to slow its advance. He asks travelers to drive back its workers so he can prepare new defenses. Gaxim Rustfizzle represents the Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences. In Stonetalon's ancient groves, he hopes to show the nature-worshipping night elves that gnomish invention can defend their threatened lands. He joins magic, chemical brews and mechanics, yet the Venture Company's relentless pace leaves him little time to build defenses. At Windshear Crag, Gaxim sends travelers into the smoking works to turn back the Venture Co. Loggers and Deforesters. If they retreat, he will have time to organize his workshop and devise his next defense: controlled, strategic high explosives.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1071-7ad6a2e81ded17afa4e1/1-0000.mp3", duration = 53.2636735, start = 0},
  },
}
P.transport["quest:1072"] = {
  hash = "7ce3ad",
  fullHash = "7ce3ad",
  text = "An Old Colleague. In the Stonetalon Mountains, Gaxim Rustfizzle seeks fuel for a powerful device. He sends you across the sea to Ironforge, where his old acquaintance Lomac Gearstrip can make the hazardous explosive Nitromirglyceronium. Gaxim Rustfizzle is planning his boldest engineering work yet in the Stonetalon Mountains. A mechanism of that scale needs fuel stronger than ordinary gunpowder or crude oil. He needs Nitromirglyceronium, also called NG-5. It is an explosive mix potent enough to ensure destruction if all goes according to plan. Lomac Gearstrip is the only person Gaxim knows who can refine NG-5. His old acquaintance lives far to the east in Tinker Town, the gnome quarter deep inside Ironforge. You make the long journey as Gaxim's courier. Lomac greets you with suspicion and paranoid questions.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1072-76b3bafa5f6990188cc1/1-0000.mp3", duration = 58.9322449, start = 0},
  },
}
P.transport["quest:1073"] = {
  hash = "892a30",
  fullHash = "892a30",
  text = "Ineptitude + Chemicals = Fun. In the Stonetalon Mountains, Gaxim Rustfizzle seeks a powerful answer to the Venture Company. He asks you to travel across the sea to Ironforge, where Lomac Gearstrip will brew Nitromirglyceronium if you bring the needed alchemical reagents. Gaxim Rustfizzle needs powerful explosives for his finest device against the Venture Company. He is stationed high in the craggy passes of the Stonetalon Mountains, far from his former colleague Lomac Gearstrip in Ironforge. Lomac created Nitromirglyceronium, a brew so unstable and destructive that he laughs at the thought of anyone using it, whoever gets blown apart. Lomac wants to see goblin machinery blown to pieces, and perhaps you too. But his Ironforge workshop has run out of Nitromirglyceronium. Before he brews another batch, he asks you for Minor Mana Potions and Elixirs of Minor Fortitude. These draughts provide the raw reagents for his mixture, and gathering them lets Lomac judge whether you have any respect for alchemy.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1073-506c5dead2d33c56a099/1-0000.mp3", duration = 72.0457143, start = 0},
  },
}
P.transport["quest:1074"] = {
  hash = "55feb9",
  fullHash = "55feb9",
  text = "Ineptitude + Chemicals = Fun. In the Stonetalon Mountains, Lomac Gearstrip sends volatile NG-5 to Gaxim Rustfizzle. The chemical can ignite wagons packed with dynamite, drawing enemies away while Alliance forces pursue their goals in the disputed crags. Lomac Gearstrip gives you Nitromirglyceronium, or NG-5, an unstable compound made through gnomish engineering. He warns you to handle it with care. Mishandled, it could blow you to pieces on the road back to Gaxim Rustfizzle.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1074-cd380ff9281c4c40e8a5/1-0000.mp3", duration = 33.1493878, start = 0},
  },
}
P.transport["quest:1075"] = {
  hash = "8c9e5f",
  fullHash = "8c9e5f",
  text = "A Scroll from Mauren. Gaxim Rustfizzle seeks a spell from Collin Mauren in Stormwind's Mage Quarter. He needs arcane help to trigger his NG-5 explosives from afar. Mechanical fuses cannot give Gaxim the control he needs. He wants to ignite the charges with one button while he stays beyond the blast. Arcane magic may carry a command from his hand to the explosives. Collin Mauren is a human spellcaster with practical knowledge of the arcane. He considers how to bind an explosive ignition to a distant command. Then he begins the incantation Gaxim needs for his dangerous project.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1075-6f345cd385cd018137e0/1-0000.mp3", duration = 41.8742857, start = 0},
  },
}
P.transport["quest:1076"] = {
  hash = "0aab45",
  fullHash = "0aab45",
  text = "Devils in Westfall. Dust devils roam Westfall, and Collin Mauren needs their remains for a spell. The Mage Quarter wizard is helping Gaxim Rustfizzle with an unusual experiment. Their work calls for a messaging scroll, and the dust holds what Mauren needs to enchant it. Collin Mauren is preparing a messaging scroll for Gaxim Rustfizzle. The wizard is helping the tinkerer with an unusual venture, but the spell needs more than ink and vellum. Dust devils roam Westfall with elemental magic swirling within them. Their remains provide the volatile medium Mauren needs to bind Gaxim's spell to parchment. Westfall was once Stormwind's fertile breadbasket. Drought, banditry, and neglect have left its fields arid and wild. Dust devils roam there, threatening travelers and lone homesteaders. Their residue holds the focused elemental essence Mauren needs to complete the enchantment.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1076-02264fda531567d1e127/1-0000.mp3", duration = 54.7787755, start = 0},
  },
}
P.transport["quest:1077"] = {
  hash = "27504f",
  fullHash = "27504f",
  text = "Special Delivery for Gaxim. Gaxim Rustfizzle waits in Stonetalon for an enchanted scroll from Stormwind. Its magic may let him set off an explosive from afar and hinder the Venture Company's deforestation. Gaxim Rustfizzle is trying to hinder the Venture Company's destructive work in the Stonetalon Mountains. He has made an explosive compound called NG-5, but has no sure way to set it off from afar. So he sought help across the Great Sea. In Stormwind's Mage Quarter, Collin Mauren has made an enchanted Scroll of Messaging for him.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1077-4bc39022fe0dcdbddc34/1-0000.mp3", duration = 32.9404082, start = 0},
  },
}
P.transport["quest:1078"] = {
  hash = "de58d8",
  fullHash = "de58d8",
  text = "Retrieval for Mauren. In Stormwind, Collin Mauren asks travelers bound for Kalimdor to bring rare basilisk scales. He wants scales from the Charred Vale in Stonetalon, ground to dust for his spellcraft. In Stormwind's Mage Quarter, wizard Collin Mauren listens to tales from wandering adventurers. He has heard that travelers venture deep into Kalimdor, where Stonetalon draws those seeking wild wyverns, unruly elementals, or dealings and clashes with the Venture Company. Mauren seeks neither riches nor glory. He wants to learn what rare natural wonders survive in the region's harshest corners. Deep in Stonetalon, the Charred Vale is an ash-choked basin scarred by the Venture Company's devastation. Mauren's studies say a peculiar breed of basilisk once lived there. Ground to fine powder, their scales can catalyze specialized arcane spells he has devised. Mauren does not know whether the basilisks survived the Vale's harsh transformation. So he asks explorers to bring back fresh crystallised scales and learn whether the breed endures.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1078-6d62554ab887aac8237f/1-0000.mp3", duration = 76.3559184, start = 0},
  },
}
P.transport["quest:1079"] = {
  hash = "8ae73e",
  fullHash = "8ae73e",
  text = "Covert Ops - Alpha. Alliance agents move against the Venture Company in the Stonetalon Mountains. Under Gaxim Rustfizzle, they enter the lumber mill in Windshear Crag to recover its engineering schematics. From Windshear Crag, Gaxim Rustfizzle directs a covert effort against the Venture Company's aggressive logging. Goblin loggers cut timber south of Cragpool Lake. Destruction alone cannot stop them, so Plan Alpha sends agents past the loggers and overseers to take the mill's technical schematics. The Venture Company's schematics interest gnomes for more than the night elves' forests. They reveal how goblin loggers, mechanical cutters and mechanized transports work. Alliance engineers can study their structural flaws to break up future operations. They can also adapt goblin designs for their own projects in Ironforge.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1079-a3c8f8d8a810e5d69269/1-0000.mp3", duration = 61.5967347, start = 0},
  },
}
P.transport["quest:1080"] = {
  hash = "e4881a",
  fullHash = "e4881a",
  text = "Covert Ops - Beta. In Stonetalon, Gaxim Rustfizzle sends an agent into the Venture Company’s mine. Explosives draw the goblins away while the agent takes letters that reveal company plans and help defend Sentinel lands. After the first blows against the Venture Company’s logging at Windshear Crag, Gaxim Rustfizzle turns to its supply heart. As before, explosives will scatter goblin workers and mercenaries. Then an agent searches the mine for written orders and records. At the eastern edge of Windshear Crag, Windshear Mine is the Venture Company’s base beneath the mountain. Goblins dig for rock and cut timber there, keeping records of supply routes and orders from their leaders. An agent slips inside, sets Gaxim’s explosive packs, and takes the Venture Co. Letters. The blast disrupts the mine’s guard, and the letters reveal more of the company’s plans in Kalimdor. Gaxim takes pleasure in clever devices and explosions. His work also matters to the night elves. In Stonetalon, the Sentinels face the Horde and the companies cutting and digging through their lands. Letters from the mine give commanders such as Kaela Shadowspear information to anticipate threats to the sacred woods.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1080-ed24e100e69438b871c5/1-0000.mp3", duration = 92.0555102, start = 0},
  },
}
P.transport["quest:1081"] = {
  hash = "7d0142",
  fullHash = "7d0142",
  text = "Reception from Tyrande. At the Temple of the Moon, Tyrande Whisperwind receives you after your aid in Stonetalon. Sentinel Thenysil sends you from Astranaar to Darnassus for an audience with the High Priestess. The Venture Company presses the night elf outposts across the Stonetalon Mountains. Sentinel Thenysil directs their defense from Astranaar, but the distant bases are difficult to supply. Supplies and intelligence help the Sentinels hold an Alliance presence in Kalimdor's interior. Your aid strengthens their position. After your aid bolsters the Sentinels in Stonetalon, Sentinel Thenysil sends you back to Teldrassil. Tyrande Whisperwind, the High Priestess, receives you at the Temple of the Moon in Darnassus. She recognizes your deeds across Kalimdor and welcomes you as an ally fighting beside the kaldorei.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1081-46502b22813759703070/1-0000.mp3", duration = 56.9730612, start = 0},
  },
}
P.transport["quest:1082"] = {
  hash = "9bcf18",
  fullHash = "9bcf18",
  text = "Update for Sentinel Thenysil. In Astranaar, Sentinel Tara Thenysil awaits word from Stonetalon. After helping Kaela Shadowspear and Gaxim Rustfizzle against the Venture Company, you carry news that their outpost still holds. Stonetalon's jagged passes leave the night elf frontier isolated and exposed. The Venture Company cuts into the crags and pollutes the waterways, threatening the outpost where Kaela Shadowspear and the gnome tinkerer Gaxim Rustfizzle serve. With the immediate danger blunted, Kaela sends you northeast across the border into Ashenvale. You are to report that they remain safe. In Astranaar, Sentinel Tara Thenysil watches Ashenvale's interior roads and worries over scouts sent into harsher lands. News that Kaela and her engineering partner are alive and working to heal the land brings relief. Though their forces dwindle and threats press on several fronts, cooperation with Alliance allies can slow the destruction.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1082-ca1bebfc35ddfdf95f28/1-0000.mp3", duration = 63.4253061, start = 0},
  },
}
P.transport["quest:1083"] = {
  hash = "0d6e68",
  fullHash = "0d6e68",
  text = "Enraged Spirits. In the Charred Vale, Enraged Spirits overrun the burned basin. Fire and heavy machinery laid waste to the land, and the freed elementals now rage there. Alliance champions are asked to quell them so the wounded land may heal under Elune’s grace. The Charred Vale was once a lush haven in Stonetalon. The Venture Company’s greed turned it to ash as goblins sought to log the forest and strip its resources. They used incendiary devices and heavy machinery, setting the canopy ablaze. The trees fell, and the fragile elemental balance beneath the earth was shattered. The Venture Company’s work stirred ancient spirits of fire, stone, and fury from the depths. The elementals’ fury fell upon the goblins, driving them back as the spirits claimed the smoldering crater. Kaela Shadowspear says nature cannot begin to recover while these chaotic elementals remain.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1083-94baeef57488218b2af4/1-0000.mp3", duration = 73.0644898, start = 0},
  },
}
P.transport["quest:1084"] = {
  hash = "c5f5e9",
  fullHash = "c5f5e9",
  text = "Wounded Ancients. Goblin weapons may be poisoning the treants in the Stonetalon Mountains. Kaela Shadowspear asks you to gather shrapnel from the maddened guardians for Gaxim Rustfizzle to study. The treants once guarded Stonetalon's groves, fierce in defense and bound to the land's health. When the Venture Company came with buzzsaws, explosives, and strip-mining, the forest fought back. The treants drove the invaders from parts of the vale, but they did not return to their peaceful watch. Now they are hostile and maddened. Kaela Shadowspear, an Alliance scout in the mountains, believes no natural sickness afflicts the treants. Gaxim Rustfizzle, a gnome engineer, suspects goblin weapons and chemicals harmed them during the Venture Company's chaotic retreat. He hopes corroded shrapnel from the wounded treants will show whether Venture Company ordnance is poisoning Stonetalon's ancient protectors.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1084-647a143979f0c21c9d4d/1-0000.mp3", duration = 63.8171429, start = 0},
  },
}
P.transport["quest:1085"] = {
  hash = "1115d8",
  fullHash = "1115d8",
  text = "On Guard in Stonetalon. At a camp near Windshear Crag, Kaela Shadowspear sends Alliance travelers to Gaxim Rustfizzle for aid against the Venture Company. Together, the cautious night elf sentinel and eccentric gnome tinkerer guard the mountain pass from the company's rampant despoilment. The Venture Company cuts into the wilderness of Stonetalon Mountains and fells its ancient trees. Kaela Shadowspear, a night elf sentinel, knows martial skill alone cannot stop such industrial pillaging. So she turns to gnome ingenuity, though night elves and gnomes seldom agree about technology or the natural world. Their alliance shows how precarious the struggle has become. Gaxim Rustfizzle brings the eccentric pragmatism of the Alliance's smaller allies. Night elf society turned from arcane excess millennia ago, but Gaxim believes rejecting magic and technical innovation leaves the night elves vulnerable. He hopes to show his Kaldorei hosts that practical science can defend nature alongside bow and glaive.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1085-ab6c3876c94b363b19e5/1-0000.mp3", duration = 66.8734694, start = 0},
  },
}
P.transport["quest:1086"] = {
  hash = "0f284a",
  fullHash = "0f284a",
  text = "The Flying Machine Airport. Apothecary Zamah sends you to silence The Flying Machine Airport above Stonetalon. Carry her Toxic Fogger into the Venture Company’s logging grounds and strike at the cartel’s link to the outside world. Apothecary Zamah prepares Apothecary Lydon’s toxin for the Venture Company. The tauren want to protect Stonetalon from deforestation and ravaging machinery, while the Forsaken take another path. Zamah aims at the cartel’s connection beyond the mountains, not its foot soldiers or loggers. Rumor speaks of a copter pad carrying light cargo and messages between Stonetalon and distant corporate offices. The Venture Company’s copter pad lies high in the Cragpool Lake area, south of the great waterwheel. A small platform there serves lightweight flying machines, not massive zeppelins. You are sent to set off the Toxic Fogger, filling the pad with toxic vapor before a pilot, courier, or mechanic can alert the company’s commanders.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1086-dac4a653c856a8b0cb7d/1-0000.mp3", duration = 70.0342857, start = 0},
  },
}
P.transport["quest:1087"] = {
  hash = "a4ee26",
  fullHash = "a4ee26",
  text = "Cenarius' Legacy. Near Sun Rock Retreat, Cenarius' Legacy turns Braelyn Firehand's grievance into a call to arms. The blood elf mage says the night elves and Cenarius's children suppress the land's magic. She wants them culled at Stonetalon Peak so raw arcane power can flow freely, while their defeat weakens the Alliance presence in the mountains. Braelyn Firehand lives in the hills near Sun Rock Retreat, frustrated by Stonetalon's natural wards. She says the druids of the Cenarion Circle and the offspring of the demigod Cenarius choke the land's arcane currents. To Braelyn, channeling power here is like drawing water with a perforated bucket. She wants to strip away those defenses and let raw magical energy surge freely again. Braelyn sends Horde champions north to Stonetalon Peak to break the wardens' hold. Ancient kaldorei groves and temple grounds there are patrolled by Cenarion Botanists and the proud Sons and Daughters of Cenarius. Striking them down would weaken the wards that muffle Braelyn's spellcraft. It would also deal a bloody blow to the night elf enclave that threatens the Horde's foothold in the mountains.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1087-e5d39b86dee7b8622bb4/1-0000.mp3", duration = 73.9004082, start = 0},
  },
}
P.transport["quest:1088"] = {
  hash = "a8cb50",
  fullHash = "a8cb50",
  text = "Ordanus. At Sunrock Retreat, Braelyn Firehand hunts Keeper Ordanus, an elder son of Cenarius who fled Stonetalon Peak. She believes his people desecrated ancient Highborne ruins, so she sends Horde champions across the border into Ashenvale to take his head. Braelyn Firehand came to Stonetalon Mountains on her master's orders. She was sent to reclaim the sacred ruins of Azshara's ancient temples. At the peak, she found night elves treating relics of her Highborne forebears as wilderness to be contained. Keeper Ordanus escaped her and crossed into Ashenvale. Using arcane vision, Braelyn found him high in a wooden refuge at Raynewood Retreat, then enlisted the Horde to finish the hunt. Keeper Ordanus is counted among the eldest of Cenarius's sons, with deep ties to Kalimdor's wild magics. Night elf guardians moved him from Stonetalon Peak to Raynewood Retreat to shield him from arcane forces encroaching on sacred groves. Loyal Cenarion Vindicators and summoned woodland treants defend him. To Braelyn, Ordanus carries the forest demigod's ancient authority and stands in the way of her vengeance.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1088-dff9fd54a5e8c600e1cc/1-0000.mp3", duration = 81.9983673, start = 0},
  },
}
P.transport["quest:1089"] = {
  hash = "168e79",
  fullHash = "168e79",
  text = "The Den. At the Talon Den, Braelyn Firehand sends Horde champions into hidden barrow chambers to take the druids' relics. Beneath Stonetalon Peak, they face defenses built to keep those treasures safe. The Talon Den lies high in the Stonetalon Mountains, where night elf druids shelter in halls carved deep into living stone. Its barrow chambers protect meditating guardians and sacred treasures. Braelyn Firehand knows what lies within, so she questions a captured druid to learn how the defenses work.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1089-83ea54f3605ee18143b8/1-0000.mp3", duration = 34.8995918, start = 0},
  },
}
P.transport["quest:1090"] = {
  hash = "28282e",
  fullHash = "28282e",
  text = "Gerenzo's Orders. At the Venture Company dig site in Stonetalon, Piznik works against his new boss, Gerenzo. The ousted goblin digs a sample to expose the ore operation while an ally guards him from patrols at the camp. At Windshear Crag, the Venture Company rewards ruthlessness over loyalty. Piznik once served as second-in-command at the excavation. Then Gerenzo seized power, fired supervisor Ziz Fizziks, and sent Piznik back to the mines with a pick. Yet Piznik stayed. At Ziz's instruction, he became an informant, watching Gerenzo's every move and waiting for a chance to strike back at the supervisor who displaced him. Gerenzo's takeover began with an obsession: strange gold-green ore in the Stonetalon rock. He believes the mineral is worth an extraordinary sum, and ordered miners to tear it from the earth in huge quantities. Ziz Fizziks now has a mysterious employer who may pay well for news of the venture. So Piznik risks discovery to dig out a sample. An ally holds off aggressive diggers, vermin, and overseers who police the operation.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1090-f27199879385e6b31dd9/1-0000.mp3", duration = 75.6244898, start = 0},
  },
}
P.transport["quest:1091"] = {
  hash = "3cd553",
  fullHash = "3cd553",
  text = "Kaela's Update. Gaxim Rustfizzle sends you back to Kaela Shadowspear with letters taken from the Venture Company. Their contents help the Sentinels track the goblin cartel's work in Stonetalon. With his magic, Gaxim Rustfizzle hinders the Venture Company on the Sentinels' side. You helped the gnome mage uncover Venture Company movements, and he gathered correspondence about the cartel's operations. Kaela, a night elf Sentinel coordinator near Windshear Crag, is waiting for the letters. Gaxim also asks you to tell her how his magic helped the investigation. The Sentinels watch Stonetalon's crags with concern. Horde forces contest the lower trails, while the Venture Company cuts trees and mines the land. Its letters show Kaela how the cartel communicates, helping the Alliance plan defenses along the ridges.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1091-4644eee3786c9ef51d60/1-0000.mp3", duration = 57.8873469, start = 0},
  },
}
P.transport["quest:1092"] = {
  hash = "6b26dd",
  fullHash = "6b26dd",
  text = "Gerenzo's Orders. At Windshear Crag, Piznik sends an ore sample from the Venture Company workings to Ziz Fizziks, his contact beyond the dig site. The delivery ends a dangerous act of espionage. Piznik's cover at Windshear Crag is blown, and he can no longer stay with the Venture Company crew. Management in Undermine punishes sabotage within its ranks, so the nervous goblin plans to slip away and find another employer.\n\nBefore he leaves, Piznik gives an outsider the Unidentified Ore mined under Gerenzo's orders. The sample must reach its destination without drawing suspicion to him.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1092-8c50cce68ac8a6cdcc27/1-0000.mp3", duration = 37.9036735, start = 0},
  },
}
P.transport["quest:1093"] = {
  hash = "44a327",
  fullHash = "44a327",
  text = "Super Reaper 6000. At Windshear Crag, Ziz Fizziks hopes to win favor with his new boss, Sputtervalve. He wants the Venture Company’s plans for a great woodcutting machine designed by his rival, Gerenzo Wrenchwhistle. At Windshear Crag, the Venture Trading Company cuts into the Stonetalon Mountains to supply its logging operation. Ziz Fizziks, a goblin engineer cast out of the company, now works for Sputtervalve. He hopes to prove his worth by taking the plans for the company’s massive automated woodcutting machine, the Super Reaper 6000.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1093-01c5c71c3077103c8706/1-0000.mp3", duration = 34.5861224, start = 0},
  },
}
P.transport["quest:1094"] = {
  hash = "072b60",
  fullHash = "072b60",
  text = "Further Instructions. Ziz Fizziks sends stolen Venture Company plans from Windshear Crag to Ratchet. They may give his rival Sputtervalve an edge. Ziz Fizziks carries the Venture Company’s secrets from Windshear Crag. The company cast him out of its logging operations, and he took sensitive documents with him. He sealed internal manuals and technical schematics in an envelope bound for Ratchet. Among them are blueprints for the experimental Super Reaper 6000. Bitter over his dismissal, Fizziks hopes to find a buyer or ally willing to use what he stole. In Ratchet, the neutral port in the Barrens, engineer Sputtervalve waits. He has little trust or affection for Fizziks, yet their common rival makes the offer hard to refuse. The Steamwheedle-aligned goblins seek ways to weaken the ruthless Venture Company. They eagerly reverse-engineer superior mechanical inventions they come across.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1094-eb4c94abfd840ae33584/1-0000.mp3", duration = 56.1371429, start = 0},
  },
}
P.transport["quest:1095"] = {
  hash = "6acacf",
  fullHash = "6acacf",
  text = "Further Instructions. In the Stonetalon Mountains, Sputtervalve carries an order from Undermine to Ziz Fizziks. Gerenzo Wrenchwhistle, hired by Mogul Razdunk, must be eliminated. The Trade Princes have heard that Mogul Razdunk hired Gerenzo Wrenchwhistle, and the news has stirred trouble in Undermine. Director Riddlevox tells Sputtervalve to intervene quietly. Believing the order comes from the highest trade authorities, Sputtervalve passes the work to Ziz Fizziks, the operative nearest the scene.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1095-c748793286e236b2324a/1-0000.mp3", duration = 37.0155102, start = 0},
  },
}
P.transport["quest:1096"] = {
  hash = "c8d1a3",
  fullHash = "c8d1a3",
  text = "Gerenzo Wrenchwhistle. Above Cragpool Lake, Gerenzo Wrenchwhistle awaits a bounty in the Stonetalon Mountains. The rogue gnome overseer has replaced much of his rotting flesh with gears, clockwork machinery, and artificial limbs. Ziz Fizziks wants his mechanical arm as proof of his death, hoping it will win him a promotion. Gerenzo’s body bears the marks of his transformations. Those who have seen him say his natural flesh rots beneath grafted gears, iron plating, and whirring clockwork limbs. Near the great water wheel above Cragpool Lake, he watches the operations. His failing flesh does not concern him. Ziz Fizziks works for Sputtervalve and hopes Gerenzo’s death will carry him out of Stonetalon. Ziz cannot climb the cliffs and defeat the augmented overseer alone, so he asks you to bring back Gerenzo’s mechanical arm. He hopes the arm will prove his worth and earn him a transfer to the Tinkers’ Union workshops in Gadgetzan or Undermine. Gerenzo’s mechanical arm reflects a sharp divide between gnome and goblin engineering. He cut away failing flesh to make room for complex prosthetics, a choice goblins find baffling. Ziz believes goblin ingenuity would keep the natural limb and add an explosive third arm beside it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1096-ec58f83cd5956fce2b29/1-0000.mp3", duration = 83.4873469, start = 0},
  },
}
P.transport["quest:1098"] = {
  hash = "bddf55",
  fullHash = "bddf55",
  text = "Deathstalkers in Shadowfang. At Shadowfang Keep, Deathstalkers Adamant and Vincent are missing. High Executor Hadrec sends Horde champions inside to find the scouts and recover their reports. Their intelligence is needed before the Forsaken can strike at Archmage Arugal and his worgen packs. Silverpine Forest is still contested, and Archmage Arugal's worgen hold Shadowfang Keep. At the Sepulcher, the Forsaken seek to break his siege on their southern borders. High Executor Hadrec sent Deathstalkers Adamant and Vincent into the fortress to chart its defenses. Days pass without word, and Hadrec grows desperate for their reports. So he sends Horde champions inside to find the agents and salvage the operation.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1098-1be371e5b1bda3731807/1-0000.mp3", duration = 46.7330612, start = 0},
  },
}
P.transport["quest:1100"] = {
  hash = "0ba868",
  fullHash = "0ba868",
  text = "Lonebrow's Journal. At the Great Lift in Thousand Needles, Henrig Lonebrow lies dead with Lonebrow's Journal in his hand. Its pages trace his last journey and ask you to carry the book west to a night elf druid at the Feralas border. Henrig Lonebrow lies near the Great Lift, the huge machine that carries travelers from the Barrens to the floor of Thousand Needles. His journal remains in his hand, filled with notes from his travels through the canyon. Centaur and tauren hold this harsh country. His death shows the peril of traveling here alone. Henrig's journal records the route he meant to take and his final wish. He hoped his records would reach friendly hands instead of decaying in the canyon. Follow the road west across Thousand Needles and out of its dry gullies toward Thalanaar. The night elf outpost guards the Feralas border, where its druid, Falfindel Waywarder, awaits news from you.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1100-1be7789db01bf8628d2e/1-0000.mp3", duration = 60.6302041, start = 0},
  },
}
P.transport["quest:1101"] = {
  hash = "e03f32",
  fullHash = "e03f32",
  text = "The Crone of the Kraul. At Thalanaar, between Feralas and the Thousand Needles, Falfindel Waywarder seeks help against Charlga Razorflank. Henrig Lonebrow's recovered journal warns of growing danger inside Razorfen Kraul. At secluded Thalanaar, the night elf outpost, Falfindel Waywarder mourns the druid Heralath and the dwarf Henrig Lonebrow. Lonebrow traveled with the Explorers' League before the quilboar captured him. He escaped Razorfen Kraul, but died on the road. His tattered journal tells of the growing menace within.\n\nThere is no time to send a runner to Darnassus for military aid. So Falfindel turns to passing adventurers, sending them into the thorned dens to face the danger at its heart. Charlga Razorflank is an ancient geomancer and ruthless matriarch. She has united the fractious Razorfen quilboar under her iron rule. From deep within the Kraul, she marshals a bristling army that threatens neighboring lands.\n\nThick thorn mazes, battlement walls and swarms of fanatical quilboar warriors guard the way to Charlga. Her medallion, taken from her lifeless body, will prove her downfall.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1101-d95557be68b9aac3c513/1-0000.mp3", duration = 84.1404082, start = 0},
  },
}
P.transport["quest:1103"] = {
  hash = "b62347",
  fullHash = "b62347",
  text = "Call of Water. Along Silverpine Forest's coast, Tiev Mordune waits to help shamans whose spirit-sight fades too soon. A fresh Water Sapta lets them return to the shrine and speak with the purified water spirit. Shamans drink a Water Sapta to see spirits near the elemental shrines. If its magic fades before they speak with the Minor Manifestation of Water, they can no longer enter the spirit realm to finish the trial. On Silverpine Forest's fog-shrouded shore, fellow shaman Tiev Mordune helps those whose visions end too soon. Tiev Mordune has defeated the corrupt water spirit off the coast and waits with the ritual remnants he gathered. To show you are ready, bring a fresh Water Sapta from Islen Waterseer in the Barrens. Tiev casts his gathered bracers and droplets into the shrine's brazier. The pure manifestation appears again, so you can speak with it and seal your bond with the element.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1103-45902048ac2b0a93924e/1-0000.mp3", duration = 57.1036735, start = 0},
  },
}
P.transport["quest:1104"] = {
  hash = "9b6fc1",
  fullHash = "9b6fc1",
  text = "Salt Flat Venom. At the Mirage Raceway, Fizzle Brassbolts seeks hotter fuel for his rocket car. He believes scorpid venom from the Shimmering Flats can give it the fierce burn he needs. At the Mirage Raceway, gnomish precision meets goblin audacity in contests of speed and invention. Fizzle Brassbolts wants more from fuel and clockwork parts. He seeks a mixture that burns hotter than common propellants and sends rocket cars racing across the dry salt lake at blistering speed. Scorpids in the Shimmering Flats may hold the key to Fizzle's new fuel. They endure an arid wasteland crusted with salt, and their venom carries an unusual amount of it. Fizzle sees a useful chemical payload in their deadly sting. He believes boiling and refining the venom, then treating it with exotic catalysts, can create the fierce combustion needed to leave the goblin pit crews behind.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1104-12ed30a7e0d351559840/1-0000.mp3", duration = 53.3942857, start = 0},
  },
}
P.transport["quest:1105"] = {
  hash = "139213",
  fullHash = "139213",
  text = "Hardened Shells. At the Mirage Raceway, Wizzle Brassbolts fears his brother’s fuel will eat through their racer. He seeks tortoise shells to shield the tanks. At the Mirage Raceway, Wizzle Brassbolts and his brother race to outdo goblin engineers. Their custom rocket car runs on an experimental fuel mixture his brother has made. The mixture is so potent that Wizzle fears it will eat through the car’s usual chassis and tanks. He needs a container sturdy enough to hold it across the Shimmering Flats. Wizzle turns to the tortoises native to Thousand Needles. Their shells resist harsh elements and mechanical wear, so they may hold where refined metal fails. He hopes to gather the hardened shells and shape them into fuel tanks. They must contain the volatile mixture and keep the rocket car from blowing to pieces.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1105-00ae6a3c6f74de8592bb/1-0000.mp3", duration = 49.1363265, start = 0},
  },
}
P.transport["quest:1110"] = {
  hash = "31f8b8",
  fullHash = "31f8b8",
  text = "Rocket Car Parts. At the Mirage Raceway, Rocket Car Parts lie scattered across the Shimmering Flats after racers crash. Kravel Koalbeard pays travelers to gather the wreckage and sell it back to rival crews. Goblin and gnomish engineers race to outdo one another across the Shimmering Flats. Their experimental rocket cars often fail at speed. Twisted gears, cylinders, and jagged metal scatter over the white desert. As pit crews build and tune their next machines, the salt flats gather what the racers leave behind. Kravel Koalbeard makes his profit as a middleman at the Mirage Raceway instead of competing on the track. Gnome and goblin mechanics use parts quickly and are always short of spare mechanisms for their vehicles. So Koalbeard pays travelers to gather thirty bundles of shattered debris. He turns each crash into stock he can sell back to the crews.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1110-9d96e251925d645fecbe/1-0000.mp3", duration = 53.2636735, start = 0},
  },
}
P.transport["quest:1130"] = {
  hash = "05c228",
  fullHash = "05c228",
  text = "Melor Sends Word. In the Barrens, Jorn Skyseer carries Melor Stonehoof's summons to promising hunters. Hunters who have proved their grit across Kalimdor are called to Hunter's Rise in Thunder Bluff for a harder trial. Jorn Skyseer watches the crossings and encampments of the Barrens. He carries word from the elders of Hunter's Rise to hunters and warriors who have shown promise in the surrounding lands. Melor Stonehoof, a revered tauren mentor, has marked out a path for them. At Hunter's Rise in Thunder Bluff, you meet Melor Stonehoof. The elder hunter asks whether you have the resolve to enter distant and perilous wilderness. His summons leads to trials far beyond Mulgore's safety, where hunters face the continent's fiercest predators.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1130-9e016e60707e9ae8cc71/1-0000.mp3", duration = 50.155102, start = 0},
  },
}
P.transport["quest:1131"] = {
  hash = "0ff8fa",
  fullHash = "0ff8fa",
  text = "Steelsnap. In Thousand Needles, Melor Stonehoof sends you after Steelsnap and his pack, which terrorize the wildlife. This hunt serves a different purpose from the usual reasons tauren take a life. Tauren hunters take life for food, honor, or wisdom from the Earthmother. Melor Stonehoof sends you after Steelsnap for another reason. The hyena threatens nature’s balance with senseless violence and fear, rather than keeping the cycle of life. Steelsnap roams the canyons of northern Thousand Needles, south of the centaur enclave at Camp E'thok. Fierce hyenas follow him, and together they attack the gentler wildlife on the canyon floor. Slay Steelsnap and bring back his rib to end his hold over the needles.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1131-edf931ccf52ea8eb65a7/1-0000.mp3", duration = 45.0612245, start = 0},
  },
}
P.transport["quest:1132"] = {
  hash = "4c7305",
  fullHash = "4c7305",
  text = "Fiora Longears. From Menethil Harbor, you sail west across the Great Sea to meet Fiora Longears in Theramore. Red Jack Flint sends you to his high elf contact at the town inn. Many humans, dwarves, and gnomes look upon the Eastern Kingdoms and see old conflicts and damaged earth. At Menethil Harbor, sailor Red Jack Flint urges travelers to board a ship across the Great Sea. He speaks of Kalimdor as an uncharted land of fortune and opportunity. Then he sends you to Theramore to meet his associate, the elf Fiora Longears. Your voyage ends at Theramore, an Alliance port on the coast of Dustwallow Marsh. Fiora Longears waits at the town inn for travelers sent by Flint. She trusts his judgment of character and welcomes the Alliance heroes who have just arrived. From there, she prepares to guide you inland toward Ashenvale's ancient forests.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1132-54726745ab47a47bfbd9/1-0000.mp3", duration = 59.2457143, start = 0},
  },
}
P.transport["quest:1133"] = {
  hash = "1df5a7",
  fullHash = "1df5a7",
  text = "Journey to Astranaar. From Theramore, Fiora Longears sends Alliance travelers north to Astranaar. There, they report to Shindrell Swiftfire as war and unrest trouble Ashenvale. Alliance travelers reach Dustwallow Marsh by ferry from Menethil Harbor, often seeking purpose in northern Kalimdor. At Theramore, Fiora Longears sends capable hands inland to Astranaar, Ashenvale's main night elven settlement. The road passes beneath ancient, shadowed canopies and enters a forest strained by war and unrest. Fiora asks travelers not to mention her name in Astranaar, because Shindrell Swiftfire does not know her. Fiora directs fresh Alliance talent to places where help is needed, and Shindrell welcomes able-bodied defenders when they arrive. Ashenvale remains breathtaking, though it is no longer the peaceful sanctuary it once was.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1133-e4fcc9e662c8186e79fa/1-0000.mp3", duration = 56.084898, start = 0},
  },
}
P.transport["quest:1134"] = {
  hash = "10d089",
  fullHash = "10d089",
  text = "Pridewings of Stonetalon. In the Stonetalon Mountains, Shindrell hears that pridewing venom may threaten the uneasy peace. Theramore reports an unconfirmed claim that orc assassins gather the poison for covert raids. Astranaar's Sentinels send scouts south to claim the venom sacs first. The Alliance and Horde have not declared open war across northern Kalimdor. Yet their peace is fragile. Skirmishes break out beneath the forest canopy, and quiet attacks take the place of full armies. In Astranaar, Sentinel commanders watch enemy movements. One careless moment could put their sanctuary at risk. Shindrell has heard an unconfirmed report from contacts in Theramore about activity in the crags of Stonetalon. Orcish stalkers are said to gather venom from wild pridewings around Mirkfallon Lake, then coat their blades for deadly ambushes against Alliance forces.\n\nSo Shindrell Swiftfire sends champions to kill the beasts and claim their venom sacs before Horde agents can reach them. Shindrell Swiftfire regrets ordering the deaths of native beasts. Night elves revere Kalimdor's wilderness, and these creatures had no part in choosing the war. Yet Astranaar's defenders cannot let an enemy gather poison for lethal attacks. The beasts pay for that defense with their lives.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1134-b6ec18e2a20b8f90319a/1-0000.mp3", duration = 85.8383673, start = 0},
  },
}
P.transport["quest:1135"] = {
  hash = "d1595a",
  fullHash = "d1595a",
  text = "Highperch Venom. From Theramore, Fiora Longears sends hunters west for wyvern venom. At Highperch in Thousand Needles, the wyverns carry venom sacs buyers value across Kalimdor. In Theramore, Fiora Longears seeks hunters willing to travel far for a trade beyond the Horde’s use of wyverns as flying mounts. Buyers across Kalimdor value the creatures’ lethal venom, often more than the beasts themselves. The journey means dangerous heights and a hunt for fresh venom sacs. Highperch lies west of Dustwallow Marsh, among the sandstone mesas of Thousand Needles. Its wyverns carry unusually concentrated toxin, but reaching their nests means crossing Horde territory and climbing treacherous ground. You must slay the wyverns and take their venom sacs intact, then carry them back to Theramore.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1135-650465591bbde8cbe5ad/1-0000.mp3", duration = 45.1918367, start = 0},
  },
}
P.transport["quest:1140"] = {
  hash = "0942c8",
  fullHash = "0942c8",
  text = "The Tower of Althalaxx. From Maestra's Post, Delgren's crusade reaches its sixth chapter. He deciphers Orcish writings recovered from the cult's emissaries and learns Athrikus Narassin hid two trapped Highborne soulgems in satyr strongholds deep in Ashenvale. Champions are sent to Night Run and Satyrnaar to shatter the vessels, free the tormented spirits, and weaken Athrikus's power. After Ilkrud Magthrull, an orcish courier, is cut down, Delgren the Purifier puts his study of Orcish to use. His peers in the Holy Light often scoffed at learning an adversary's tongue. Yet Delgren's practical wisdom lets him decipher notes recovered from the cult's emissaries. They reveal that Athrikus Narassin hid two potent soulgems containing ancient Highborne essences far to the northeast, in the defiled groves of Night Run and Satyrnaar.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1140-1f132772ac3b8100dd5f/1-0000.mp3", duration = 61.1004082, start = 0},
  },
}
P.transport["quest:1142"] = {
  hash = "8089f4",
  fullHash = "8089f4",
  text = "Mortality Wanes. In Razorfen Kraul, Heralath Fallowbrook has one last plea for the living. He asks you to carry his wife's stolen pendant to Darnassus and tell her he has died. Heralath Fallowbrook lies mortally wounded among the brambles of Razorfen Kraul. Savage quilboar and dark magic have overrun the stronghold, far from Alliance lands. His strength is fading, and he can manage only broken whispers.\n\nHe speaks of Lonebrow, a brave dwarf sent ahead to warn Falfindel. Heralath knows he will not leave the Kraul alive. Heralath asks you to recover the pendant that marks his marriage to Treshala Fallowbrook. One of the lair's aggressors tore it from him. He asks any traveler who stops beside him to carry it across Kalimdor to Darnassus, so Treshala learns of his death and does not wait in vain.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1142-16227870cd9625daf94d/1-0000.mp3", duration = 55.4840816, start = 0},
  },
}
P.transport["quest:1143"] = {
  hash = "a84ddd",
  fullHash = "a84ddd",
  text = "The Tower of Althalaxx. Dark rites at the Tower of Althalaxx threaten northern Darkshore. Balthule Shadowstrike leads an Alliance assault on Athrikus Narassin, the ancient sorcerer who commands the cult from the tower’s peak. In northern Darkshore, the ruined Tower of Althalaxx shelters demonic rites. Balthule Shadowstrike watches from nearby and sees the danger must be faced now. Athrikus Narassin, an ancient night elf warlock, dwells at the summit. Beneath the shattered roof, he directs the dark rituals.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1143-281f36007720a0658896/1-0000.mp3", duration = 39.1314286, start = 0},
  },
}
P.transport["quest:1149"] = {
  hash = "34e52f",
  fullHash = "34e52f",
  text = "Test of Faith. At Dorn Plainstalker's camp above Thousand Needles, Horde adventurers face a test of faith. The hermit asks them to step from a wooden plank into the chasm and trust their resolve. Above Thousand Needles, Dorn Plainstalker reflects on the mind, body, and spirit. He sets trials to measure what lies within an adventurer instead of relying on simple tribal traditions. Conviction takes many forms, he believes. At its heart is faith strong enough to risk one's life.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1149-167e465b403d10650d4e/1-0000.mp3", duration = 33.5934694, start = 0},
  },
}
P.transport["quest:115"] = {
  hash = "a1a304",
  fullHash = "a1a304",
  text = "Shadow Magic. Marshal Marris needs the midnight orbs taken from Blackrock shadowcasters in Redridge. Their dark power threatens Lakeshire's defenders and the town's line. The Blackrock clan has long relied on brute force. Now its raids in the Redridge Mountains bring a darker threat. Shadowcasters wield dark powers and channel fel and shadow energies through demon-tainted midnight orbs. These relics have dealt terrible losses to the local militia, and the war is turning against the defenders. Marshal Marris directs Lakeshire's strained defense from the town center. He knows ordinary steel cannot easily overcome dark relics. If Blackrock orcs keep their midnight orbs, Redridge's eastern borders may collapse. Marris orders the shadowcasters slain and the orbs seized, so the demonic relics can be destroyed instead of put to use.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_115-44cc1ffa0739cde18789/1-0000.mp3", duration = 55.9542857, start = 0},
  },
}
P.transport["quest:1150"] = {
  hash = "442247",
  fullHash = "442247",
  text = "Test of Endurance. In Thousand Needles, challengers face the second rite in Dorn Plainstalker's spiritual trials. After proving their courage of spirit, they enter Roguefeather Den to test their physical endurance and draw out its fierce leader, Grenka Bloodscreech. At the Weathered Nook, Dorn Plainstalker prepares young warriors for a wider, harsher world. This trial tests the body's strength. Dorn believes readiness calls for spiritual devotion, mental discipline, and the stamina to endure sustained brutality. Roguefeather Den lies within Screeching Canyon, west of Freewind Post. Hostile harpies fill the cavern, making it perilous to wander in alone. Challengers fight deep into the roost and vandalize the harpies' gathered provisions. Then they endure the flock's fierce retaliation until its matriarch, Grenka Bloodscreech, enters the fight.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1150-fafc2a607a711481c64b/1-0000.mp3", duration = 58.1485714, start = 0},
  },
}
P.transport["quest:1151"] = {
  hash = "fecf75",
  fullHash = "fecf75",
  text = "Test of Strength. In Thousand Needles, Dorn Plainstalker asks you to prove your strength. Your trial brings you against Rok'Alim the Pounder, an ancient rock elemental, and calls for pieces of his shattered form. Long ago, primordial elementals covered the world and served the Old Gods. When those powers were overthrown and sealed beneath the earth, the spirits lost their hold on this realm. Most faded from the physical world unless modern spellcraft bound and summoned them. A few were strong enough to remain on Azeroth without such magic. Rok'Alim the Pounder is one of them, wandering the arid canyons of Thousand Needles as an echo of that age. The centaur clans named Rok'Alim for the deafening crashes of his stone fists against the canyon floor. Anyone who crosses his path risks being hammered into dust. Dorn Plainstalker sends initiates to face this force of raw might and prove their warrior spirit. They return with fragments of the elemental's stony heart as proof of victory.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1151-cde02562c1467d4d818c/1-0000.mp3", duration = 70.9485714, start = 0},
  },
}
P.transport["quest:1152"] = {
  hash = "aaa274",
  fullHash = "aaa274",
  text = "Test of Lore. In Thousand Needles, Dorn Plainstalker sends Horde champions north to face a trial of the world's history. Braug Dimspirit waits in Stonetalon Mountains to test what they know of Azeroth and its shared suffering. At the Weathered Nook, Dorn Plainstalker tests initiates in faith, endurance, and combat. Yet strength and faith alone do not make a true Horde champion. Dorn knows the bounds of what he can teach, so he sends those who have proved themselves to Stonetalon Mountains. There, an elder shaman will test their minds and knowledge of the world. The road runs north over the Barrens' dry scrub and into the crags of Stonetalon. High in the mountains, near the entrance to Talondeep Path, Braug Dimspirit keeps his hermitage. The cavern cuts through the rock toward Ashenvale. From there, Braug looks upon a frontier at war: goblin logging ventures despoil the forests, while hostile night elves fiercely defend their ancestral borders.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1152-e2a41dec3dbb050403de/1-0000.mp3", duration = 72.0718367, start = 0},
  },
}
P.transport["quest:1153"] = {
  hash = "201097",
  fullHash = "201097",
  text = "A New Ore Sample. At Camp Taurajo, Tatternack Steelforge seeks ore in Thousand Needles to strengthen the Horde’s arms. He sends you south for a sample to test. Tatternack Steelforge is a blacksmith in Camp Taurajo, watched closely by Orgrimmar. He has already made weapons from local centaur armaments. Yet he still hopes to prove his craft to Warchief Thrall. Travelers passing through showed him strange ore taken from a kobold to the south. When they refused to sell it, he took the refusal as an insult to his craft and the Horde. You leave the southern Barrens’ flat plains for the towering canyon maze of Thousand Needles. Kobold diggers tunnel through its crags and cliffs. Bring back chunks of unrefined ore taken directly from them. Then Tatternack can judge whether the raw mineral can be forged into weapons for Thrall’s war effort.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1153-e4301e65f407dc54b209/1-0000.mp3", duration = 51.722449, start = 0},
  },
}
P.transport["quest:1154"] = {
  hash = "796d1b",
  fullHash = "796d1b",
  text = "Test of Lore. At Talondeep Path, Horde seekers face the Test of Lore. Braug Dimspirit asks them to find and study a tome of dragon history before he tests what they remember. After trials across Thousand Needles' salt flats and plateaus, Dorn Plainstalker's candidates travel north to Braug Dimspirit in the Stonetalon Mountains. He waits near the mouth of Talondeep Path. Braug counts those earlier trials as tests of body and faith. Yet the Horde also needs disciplined minds and knowledge of ancient history, not only skill against beasts. Braug sends seekers through Talondeep Path into southern Ashenvale. Beneath the trees south of Splintertree Post lies Dor'Danil Barrow Den, a dangerous ruin haunted by fallen night elf druids and the creatures that slaughtered them. Deep in its lower chambers, a stone podium holds 'Legacy of the Aspects'. The rare manuscript tells of the ancient creation and corruption of the great Dragon Aspects.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1154-33c2f209ba1006060526/1-0000.mp3", duration = 66.1942857, start = 0},
  },
}
P.transport["quest:1159"] = {
  hash = "ecca46",
  fullHash = "ecca46",
  text = "Test of Lore. Across the Great Sea, Horde seekers now carry the Test of Lore to the ruins of Lordaeron. You have answered Braug Dimspirit's first riddle in the Stonetalon Mountains. Now he sends you to a former human scholar among the Forsaken in Undercity. After you prove your mettle and learn the Dragon Aspects' history in the Legacy of the Aspects, Braug Dimspirit admits his knowledge has limits. The trial now reaches beyond Kalimdor and shows the Horde's far-reaching ties. So Braug sends you toward the undead capital beneath the ruins of Lordaeron. Parqual Fintallas lives in the damp corridors of the Apothecarium. Once a respected human chronicler of the northern kingdoms, he kept seeking knowledge through the Scourge and his transformation into one of the Forsaken. You arrive as an outsider, claiming to have completed the spiritual and physical trials of Thousand Needles. Parqual doubts you are more than an opportunistic mercenary, and expects you to prove your worth to him.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1159-3f7971d7ce71d503fa82/1-0000.mp3", duration = 70.7134694, start = 0},
  },
}
P.transport["quest:1167"] = {
  hash = "1530d7",
  fullHash = "1530d7",
  text = "The Tower of Althalaxx. Before you face Athrikus Narassin, Delgren sends you north to speak with Balthule Shadowstrike. The scout has watched the Tower of Althalaxx and can tell you what has changed there. Delgren the Purifier sends you north to meet Balthule Shadowstrike, his sentinel partner. You have purified corrupted relics and weakened the cult's hold along Darkshore's border. Before you confront Athrikus, Delgren wants fresh intelligence from Balthule. The sentinel has kept watch from the ruins overlooking the tower.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1167-880f09b884db96fb7332/1-0000.mp3", duration = 36.5191837, start = 0},
  },
}
P.transport["quest:1176"] = {
  hash = "590e02",
  fullHash = "590e02",
  text = "Load Lightening. At the Mirage Raceway, Pozzik’s goblin crew seeks lighter parts for its racers. Hollow vulture bones may strengthen the steering and frame without adding heavy metal. Across the Shimmering Flats, goblin and gnome engineers race to win by fractions of a second. Raw engine thrust matters little if a car carries too much weight. Gnome teams favor intricate gears and brass fittings. Pozzik’s goblins strip away dense iron framing and replace it with lighter hollow parts wherever they can. Pozzik looks to the salt wastes around Thousand Needles instead of importing costly composites. Salt Flats vultures are plentiful, and their bones are hollow, honeycombed, strong under strain, and light. His mechanics work them into the racers’ steering rigs and smaller braces. They hope the machines can outmaneuver the gnomes without shaking apart at top speed.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1176-3458674c2254401fd22c/1-0000.mp3", duration = 53.6816327, start = 0},
  },
}
P.transport["quest:1179"] = {
  hash = "96cb62",
  fullHash = "96cb62",
  text = "The Brassbolts Brothers. Pilot Longbeard in Ironforge needs a traveler to carry helmets to the Brassbolts Brothers. Their test drivers keep crashing rocket cars at the Shimmering Flats, so the gnomes need head protection. Pilot Longbeard, a dwarven aviator in Ironforge, has an urgent request from the Shimmering Flats in southern Kalimdor. His friends, the inventive gnome Brassbolts brothers, have settled on its vast salt pans to race experimental machines. Longbeard's military and piloting duties keep him busy, so he cannot carry their supplies himself. The Brassbolts' rocket car races across the salt beds at extraordinary speed. Yet its test drivers keep crashing and suffering severe concussions. Longbeard has gathered a crate of heavy-duty dwarven Siege Engine helmets to protect them. You carry the crate across the sea to Kalimdor, giving the gnomes the protection they need to bring reluctant pilots back behind the wheel.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1179-dfed49c4378f444c671b/1-0000.mp3", duration = 64.2089796, start = 0},
  },
}
P.transport["quest:1195"] = {
  hash = "59c909",
  fullHash = "59c909",
  text = "The Sacred Flame. Zangen Stonehoof sends you after a sacred flame and an ancient relic. To aid Rau Cliffrunner in Thousand Needles, you seek a moonwell phial in Ashenvale. The Galak centaur guard an ancient relic in Thousand Needles. The artifact dates to the beginning of their race, and sacred flames protect it. Zangen Stonehoof needs water blessed by the moon to quench those flames. He sends you north to Ashenvale, where the old forests hold the moonwell water he seeks. Pure moonwell water needs a vessel that will not taint it. You seek an etched phial carried by the Laughing Sisters, dryads near Raynewood Retreat. Submerge the phial in a moonwell along the western banks of the Falfarren River, then carry it back to Mulgore.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1195-d1425d2d519ec7d25e84/1-0000.mp3", duration = 49.4759184, start = 0},
  },
}
P.transport["quest:1196"] = {
  hash = "d1b0c3",
  fullHash = "d1b0c3",
  text = "The Sacred Flame. A phial of moonwell water travels south from Ashenvale to Freewind Post. Rau Cliffrunner needs it to break the eternal flame guarding an ancient centaur relic in Thousand Needles. Zangen Stonehoof sends you south across central Kalimdor with an etched phial of purified moonwell water. You cross the sun-baked Barrens, descend the Great Lift, and continue to Freewind Post. Rau Cliffrunner waits on the high mesa above the canyon floor. From there, he watches the centaur clans below.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1196-a7dbcaa0375ecc6781cd/1-0000.mp3", duration = 31.8693878, start = 0},
  },
}
P.transport["quest:1197"] = {
  hash = "c34c44",
  fullHash = "c34c44",
  text = "The Sacred Flame. At Splithoof Hold, Rau Cliffrunner seeks to silence the Galak centaur's sacred fire. You carry blessed water into their stronghold, quench the brazier, and take the Cloven Hoof. North of Freewind Post, Splithoof Crag lies at the heart of Galak territory in Thousand Needles. Deep in its cavern, Splithoof Hold shelters a fire the centaur hold sacred. Rau Cliffrunner prepares an etched phial of purified water for his allies. You enter the hold and use the water to quench the flame for a moment. Then you take the Cloven Hoof relic guarded within.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1197-4adbfef71f270771d68b/1-0000.mp3", duration = 38.0342857, start = 0},
  },
}
P.transport["quest:1198"] = {
  hash = "861ed2",
  fullHash = "861ed2",
  text = "In Search of Thaelrid. Dawnwatcher Shaedlass sends you into Blackfathom Deeps to find a missing scout. The Argent Dawn fears naga and Twilight's Hammer cultists have joined forces in the flooded ruins. The Argent Dawn watches for threats across Kalimdor, as well as the Scourge in Lordaeron. In Darnassus, Dawnwatcher Shaedlass gathers reports of dangers beyond the natural world. Word reaches him that naga have made a pact with the doomsday zealots of Twilight's Hammer in Blackfathom Deeps. The flooded ruins lie along the Ashenvale shore, and the order fears what this alliance may bring. Argent Guard Thaelrid entered the caverns to investigate rumors from the coast. Weeks have passed without word, and Shaedlass's other scouts are away on separate operations. He fears Thaelrid has fallen or been taken by the dark powers beneath the waves. So he sends you into Blackfathom Deeps to bring the missing scout back alive.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1198-3e06e88e8a976161ad63/1-0000.mp3", duration = 59.2718367, start = 0},
  },
}
P.transport["quest:1199"] = {
  hash = "956ee8",
  fullHash = "956ee8",
  text = "Twilight Falls. At Blackfathom Deeps, Twilight's Hammer cultists have joined the naga beneath the Ashenvale coast. Argent Guard Manados in Darnassus calls on Alliance champions to gather pendants from fallen cultists and hinder their plans to awaken ancient evils. Beneath Ashenvale's Zoram Strand, Blackfathom Deeps lies in ruins. Once a sacred night elf temple to Elune, it held a powerful moonwell. The Sundering shattered the temple and plunged it beneath the sea. Now naga and cultists fill its halls. The waters have turned foul, and the cultists revere powers darker than the sea. Twilight's Hammer worships the chaotic Old Gods and seeks their return. Its followers hope to spread madness and ruin across the world. Reports in Darnassus say the cultists have joined the naga in Blackfathom Deeps. There they perform rituals in the submerged halls and use the temple's tainted waters to feed their dark masters' resurgence. Argent Guard Manados watches over threats to Azeroth from Darnassus on behalf of the Argent Dawn. He sees danger in Blackfathom Deeps, where horrors could reach every civilized race. The order offers aid and recognition to heroes who enter the flooded labyrinth, cull the cultists, and bring back the Twilight Pendants from their necks as proof of defeat.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1199-99d90ce74d1892866c8c/1-0000.mp3", duration = 85.524898, start = 0},
  },
}
P.transport["quest:1200"] = {
  hash = "a4e519",
  fullHash = "a4e519",
  text = "Blackfathom Villainy. At Blackfathom Deeps, Argent Guard Thaelrid calls the Alliance to stop Twilight Lord Kelris. The cult leader sacrifices captives to Aku'mai, and Thaelrid asks you to bring Kelris's severed head to the Argent Dawn in Darnassus as proof. Blackfathom Deeps was once a night elven temple devoted to Elune. Corruption from an ancient Old God rose through the rock and fouled the Moon Well. From the tainted waters beneath the depths, Aku'mai crawled forth, a voracious servant of that darkness. After the temple was defiled, the Twilight's Hammer joined forces with local naga. Its holy halls became a place of ritual murder. Argent Guard Thaelrid entered Blackfathom Deeps on behalf of his order. There, he was grievously wounded and drained of strength. Surrounded by enemies, he knows he cannot finish his mission alone. So he pleads with brave Alliance travelers who reach him to kill Twilight Lord Kelris. Kelris leads the cultists in sacrificing innocents to Aku'mai for dark power.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1200-55870b5a14e9887f410e/1-0000.mp3", duration = 76.0163265, start = 0},
  },
}
P.transport["quest:1221"] = {
  hash = "13fa84",
  fullHash = "13fa84",
  text = "Blueleaf Tubers. Mebok Mizzyrix sends trained gophers into Razorfen Kraul to find Blueleaf Tubers. The Ratchet merchant seeks the buried delicacy for trade. In the southern Barrens, Blueleaf Tubers lie deep beneath the roots of Razorfen Kraul. Their rarity makes them a delicacy prized across the world. They grow far from open fields and ordinary wild groves, so foragers must search underground. Mebok Mizzyrix, a merchant in Ratchet, has devised a way to find buried tubers. He trains snufflenose gophers to catch a tuber's scent from fifty paces away. Foragers receive a command stick, a ventilated crate, and an instruction manual to guide the creatures through quilboar territory. The harvest lies in the lands of the hostile Death's Head quilboar tribe. In the Kraul, you must guard your trained gopher from feral beasts and thorny briars, then command it to dig up the buried bulbs. The tubers go back to Ratchet, where Mizzyrix's foreign buyers await.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1221-b5690686af2f3b54f063/1-0000.mp3", duration = 61.8057143, start = 0},
  },
}
P.transport["quest:124"] = {
  hash = "2ff75d",
  fullHash = "2ff75d",
  text = "A Baying of Gnolls. Gnolls have reached Verner Osgood’s stable in Lakeshire, where Blackrock orcs already threaten the region. Verner asks you to drive away the brutes and mystics that endanger his horses. Verner Osgood’s stable in Lakeshire has grown dangerous to tend. Blackrock orcs hold the heights, while gnoll packs roam the ridges around town. Now gnoll raiders have reached the northern edge of Verner’s paddocks. They prey on horses that stray too close to the bluffs.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_124-4f1e5624cd1834debfd2/1-0000.mp3", duration = 30.4326531, start = 0},
  },
}
P.transport["quest:1241"] = {
  hash = "d4b95e",
  fullHash = "d4b95e",
  text = "The Missing Diplomat. In Stormwind, the inquiry begins urgently when a diplomat fails to reach Theramore Isle. Bishop DeLavey suspects Defias foul play and sends trusted operatives to Jorgen, a discreet contact in the Valley of Heroes. A high-ranking diplomat sailed from the Eastern Kingdoms to meet Lady Jaina Proudmoore in Theramore Isle for sensitive talks. The diplomat never arrived. Royal investigators search Stormwind for clues. The disappearance remains secret to prevent panic and keep conspirators from learning the crown is watching. Bishop DeLavey believes the Defias Brotherhood abducted the diplomat, but he does not rely only on the king’s guard. He turns to discreet contacts and seeks out Jorgen, an old acquaintance who keeps a low profile fishing in the Valley of Heroes. Jorgen is just inside the city gates.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1241-72ef0a884de1a41c80a3/1-0000.mp3", duration = 64.0522449, start = 0},
  },
}
P.transport["quest:1242"] = {
  hash = "00f901",
  fullHash = "00f901",
  text = "The Missing Diplomat. Jorgen sends trusted operatives across Stormwind with a sealed note for Elling Trias. From the Valley of Heroes to Trias' Cheese in the Trade District, the delivery carries the search for the missing diplomat. After the first inquiries into the diplomat's disappearance, Jorgen asks trusted operatives to keep silent and carry a sealed note across Stormwind. It is bound for Trias' Cheese in the Trade District, not a barracks or magistrate's office. As concern spreads beyond the palace, the handoff avoids the usual guard channels.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1242-343409c453d21c619576/1-0000.mp3", duration = 41.3257143, start = 0},
  },
}
P.transport["quest:1243"] = {
  hash = "5fb05a",
  fullHash = "5fb05a",
  text = "The Missing Diplomat. Elling Trias sends you south from Stormwind to seek news of the missing diplomat. His lead points toward Duskwood and Watcher Backus, a contact near Darkshire who may know of Defias activity. After a frustrating exchange with Jorgen, Elling Trias, the cheesemonger, turns to his wider circle of informants. To save his own coin, he sends you to do the fieldwork instead of hiring agents. You carry a sealed missive across the border into Duskwood, where beasts and the undead make travel dangerous. Watcher Backus patrols the northern approach to Darkshire as a member of the Night Watch. Trias trusts him to report illicit movements through Duskwood. Show Backus the sealed dispatch, and he can share guard records and local gossip about Defias Brotherhood operations in the south.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1243-01b2c210cf74980df5f6/1-0000.mp3", duration = 52.2187755, start = 0},
  },
}
P.transport["quest:1244"] = {
  hash = "cc8a28",
  fullHash = "cc8a28",
  text = "The Missing Diplomat. Watcher Backus has brought the search for Stormwind’s missing diplomat to Duskwood. A gathering of Defias bandits at Addle’s Stead may hold a lead. Watcher Backus of the Night Watch brings you to Duskwood. Several weeks ago, an unusually large gathering of Defias bandits came to Addle’s Stead. They usually keep to themselves across the border in Westfall, so their presence in the dark woods is a troubling change. Now you search the abandoned farmstead for the papers they left behind.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1244-766b43d71da044b0785a/1-0000.mp3", duration = 37.2767347, start = 0},
  },
}
P.transport["quest:1245"] = {
  hash = "6e301f",
  fullHash = "6e301f",
  text = "The Missing Diplomat. You bring the recovered Defias Docket to Stormwind, where the search for a missing diplomat grows more dangerous. Watcher Backus in Duskwood wants no part of the Defias Docket you recovered. Its papers lay out plans too intricate for simple banditry or a diversion. Fearing royal punishment and wary of his Night Watch superiors, Backus asks you to keep his part quiet. The schemes could end careers or cost lives, so you carry the papers to Stormwind.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1245-0f3b822db0a9dbea1d20/1-0000.mp3", duration = 34.7689796, start = 0},
  },
}
P.transport["quest:1246"] = {
  hash = "dd7eb9",
  fullHash = "dd7eb9",
  text = "The Missing Diplomat. In Old Town, Elling Trias sends you after a name tied to the missing diplomat’s case. Dashel Stonefist may know more about suspicious papers, and the search leads into Stormwind’s rough streets. Elling Trias recalls Dashel Stonefist, known as Fist, among the names tied to the coded notes and leads. A rough street fighter, Stonefist keeps to the cramped alleys of Old Town. Finding him takes the search from Stormwind Keep’s grand halls into the city’s criminal circles.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1246-689ea2f18def44454aab/1-0000.mp3", duration = 32.4440816, start = 0},
  },
}
P.transport["quest:1247"] = {
  hash = "d89b81",
  fullHash = "d89b81",
  text = "The Missing Diplomat. In Old Town, Dashel Stonefist gives up a warning for Elling Trias. His confession names a backup abduction plot and a contact in Menethil Harbor. Dashel Stonefist gives in when he fears for his health. In an Old Town alley, he admits the conspirators' first plan to kidnap the envoy failed, and his part in it fell apart. To shift blame, he tells you of a secret meeting weeks ago at Addle's Stead in Duskwood. He also names a lead in their backup plan: an insider in Menethil Harbor known only as Slim.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1247-989bfab795308d5ecd39/1-0000.mp3", duration = 38.4261224, start = 0},
  },
}
P.transport["quest:126"] = {
  hash = "f97b05",
  fullHash = "f97b05",
  text = "Howling in the Hills. Gnoll cries trouble the hills around Lakeshire, where Verner Osgood offers a bounty on Yowler. With Stormwind's forces stretched thin by the Blackrock orcs, the town relies on visitors to face the gnolls. Gnoll cries still echo through the Redridge hills, though lesser gnolls have been driven from the paths around Lakeshire. Verner Osgood, the town's farrier, knows the pack will keep raiding while its leader lives. Yowler is a huge, cunning gnoll whose calls direct the pack across the hills. Verner asks for Yowler's paw as proof of the kill and of the calls' silence. Stormwind's eastern border towns face danger with little help from the kingdom's army. King Varian Wrynn is missing, and disputes over the regency have paralyzed high command. Royal soldiers focus on the Blackrock orc clans in the north, leaving Lakeshire without defenders against gnolls. So townsfolk such as Verner Osgood arrange their own bounties to keep their homes from being overrun.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_126-564eab6af5a19bc49b4f/1-0000.mp3", duration = 64.0261224, start = 0},
  },
}
P.transport["quest:127"] = {
  hash = "bfac08",
  fullHash = "bfac08",
  text = "Selling Fish. Dockmaster Baren needs spotted sunfish from Lake Everstill. The fish feed Lakeshire, but murlocs along the shore make them dangerous to gather. Spotted sunfish are prized around Lake Everstill, and townspeople and passing merchants keep demand high. Yet Lakeshire's supplies often run thin, though the fish swim below the surface. Local threats stretch the town's strength, so even basic trade depends on travelers. Anglers nearby could once fill Dockmaster Baren's orders with ease. Now aggressive murloc tribes haunt the shallows and banks, keeping ordinary townsfolk from the water. You can fish while watching for danger, or take sunfish from the foraging murlocs that trouble the shore.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_127-fad39c227daba156e18b/1-0000.mp3", duration = 44.4604082, start = 0},
  },
}
P.transport["quest:1274"] = {
  hash = "13dd91",
  fullHash = "13dd91",
  text = "The Missing Diplomat. A quiet request in Stormwind draws you to Bishop DeLavey at Stormwind Keep. The Church and crown need help with a matter too perilous for public channels. As you travel through Stormwind, Thomas, an altar boy, approaches with a quiet request. Bishop DeLavey, a respected cleric of the Church of the Holy Light, needs an outsider's help at Stormwind Keep. He calls the matter delicate and urgent. You must keep it discreet, lest the people panic.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1274-b62a529b02137ac87634/1-0000.mp3", duration = 34.6383673, start = 0},
  },
}
P.transport["quest:1275"] = {
  hash = "b1f9e5",
  fullHash = "b1f9e5",
  text = "Researching the Corruption. In Auberdine, Gershala Nightwhisper seeks corrupted brain stems from Blackfathom Deeps. Blood elves across the sea are said to be turning to demonic magic. He hopes the naga and satyr can teach him how to keep history from repeating itself. Night elves across Kalimdor still remember the ruin of their ancient kin. Ten thousand years ago, the Highborne gave in to demonic energies and became satyrs or naga. Now the high elves call themselves blood elves and embrace dark magic. Gershala Nightwhisper sees the old disaster taking shape again. Blackfathom Deeps gives Gershala a place to study the corruption. Its temple ruins lie beneath the Zoram Strand in Ashenvale, where satyr cultists and naga dwell. He asks you to gather brain stems from both. He hopes to trace the link between arcane addiction, demonic corruption, and the body's ruin.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1275-5b5425b5c6b39211dabe/1-0000.mp3", duration = 62.7983673, start = 0},
  },
}
P.transport["quest:128"] = {
  hash = "a08be4",
  fullHash = "a08be4",
  text = "Blackrock Bounty. In Lakeshire, Blackrock Bounty draws fighters as Blackrock forces gather in northern Redridge. Stormwind sends no royal soldiers, so Magistrate Solomon and Guard Howe offer payment to independent fighters who strike at Blackrock Champions and disrupt the clan’s assault. Redridge belongs to the Kingdom of Stormwind, yet the Blackrock clan ignores human borders. Orcs pour through mountain passes from the Burning Steppes and fortify camps across northern Redridge. King Varian Wrynn is missing, and Stormwind’s regency withholds royal soldiers. As Lakeshire’s coffers dwindle, Magistrate Solomon and other local leaders offer bounties to protect the town. Guard Howe names the Blackrock Champions as the backbone of the invading vanguard. These squad leaders are battle-hardened veterans who coordinate their warbands and drive lesser grunts forward. Lakeshire’s defenders hope a bounty on the Champions will break the clan’s tactical leadership and stall a full-scale push south. The town’s outer defenses may soon collapse.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_128-2430d7df344ea8d286e9/1-0000.mp3", duration = 68.4930612, start = 0},
  },
}
P.transport["quest:133"] = {
  hash = "1cbb6a",
  fullHash = "1cbb6a",
  text = "Ghoulish Effigy. In Duskwood, the dead press against Abercrombie’s shack. He asks you for ghoul ribs to make a grim scarecrow and guard his home. Beyond Darkshire’s guarded bounds, Abercrombie lives alone among Duskwood’s shadowed trees. Flesh Eaters and Bone Chewers roam the wilds freely. He says ravenous corpses recently battered down his walls, so he asks you to bring him their ribs. He hopes a grisly effigy will keep the hungry dead from his home. For his wooden shack, Abercrombie trusts a grim plan over the Night Watch or stronger walls. He believes an effigy made from ghoul remains will frighten off other scavenging dead. A scarecrow built from slain undead is unsettling. Yet travelers in Duskwood often do as the hermit asks to earn needed coin.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_133-757e7d60cac453d19d98/1-0000.mp3", duration = 48.9795918, start = 0},
  },
}
P.transport["quest:134"] = {
  hash = "f03355",
  fullHash = "f03355",
  text = "Ogre Thieves. In western Duskwood, Abercrombie sends travelers to the ogres’ stronghold at Vul'Gol Ogre Mound. He says they ambushed him while he foraged and took a crate of irreplaceable herbs and tools. On the damp roads of western Duskwood, Abercrombie says he was attacked while gathering supplies. Brutes from the southern ogre mound drove the aged hermit off. He left behind a sturdy wooden crate filled with precious herbs and delicate instruments. In southern Duskwood, Vul'Gol Ogre Mound is a danger to unwary wanderers. Hostile ogres harass travelers there, and Abercrombie's crate rests near the entrance among roaring brutes and spell-weaving magi.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_134-ccde2ef2bd4be2f1f926/1-0000.mp3", duration = 42.5795918, start = 0},
  },
}
P.transport["quest:1366"] = {
  hash = "94e7f0",
  fullHash = "94e7f0",
  text = "Centaur Bounty. In Desolace, Felgur Twocuts calls for blood after Khan Dez'hepah. He wants fifteen ears from centaur of any clan. Felgur Twocuts says the centaur clans have been scared. Now, he says, it is time to bleed them. As you travel across Desolace, hunt centaur from any clan and gather fifteen ears. Felgur wants to thin their numbers and weaken their resolve. He means to end any thoughts of expansion.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1366-8e0a8c5dc8179d3e7879/1-0000.mp3", duration = 26.7232653, start = 0},
  },
}
P.transport["quest:1387"] = {
  hash = "4f7da5",
  fullHash = "4f7da5",
  text = "Centaur Bounty. At Nijel's Point, Corporal Melkins sends you after Desolace's centaur clans. He asks for fifteen ears, believing peace cannot come while they remain. At Nijel's Point, Corporal Melkins speaks of Desolace's centaur clans. Each has its own leader and plans. Yet all share the same cruelty. Melkins says peace can come only when the centaur are gone. As you wander Desolace, you hunt centaur and take their ears. Melkins asks you to bring fifteen. He calls this service to the Alliance, bringing the war's end nearer.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1387-177eb3a740b8aa0a1fa2/1-0000.mp3", duration = 38.7395918, start = 0},
  },
}
P.transport["quest:1431"] = {
  hash = "8c664f",
  fullHash = "8c664f",
  text = "Alliance Relations. Thrall seeks a careful hand to keep peace with the Alliance. In Orgrimmar, Craven Drok sends seasoned Horde adventurers to Keldran, near the western exit. Quiet diplomacy and intelligence may help protect Thrall’s fragile peace. Thrall fears that war with the Alliance could ruin his young nation. Raised in human captivity, the Warchief learned human statecraft and military strategy. So Craven Drok watches for warriors and champions who can look beyond raw force and choose a subtler path. Near Orgrimmar’s western exit, Keldran keeps a humble dwelling. He practices magic and covert arts, working with appearances, perception, and statecraft. As the Horde faces a tense standoff with its bitter rivals, Keldran seeks discreet operatives to serve the Warchief.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1431-008f88283eca35e0ac3c/1-0000.mp3", duration = 53.8906122, start = 0},
  },
}
P.transport["quest:1432"] = {
  hash = "ffd340",
  fullHash = "ffd340",
  text = "Alliance Relations. In Orgrimmar, Alliance advances across Kalimdor put the Horde under pressure. Thrall's people send orders to Desolace to purge demons before the Alliance can accuse them of renewed ties to the Burning Legion. Alliance scouts and expeditions cross Kalimdor, leaving the Horde in a delicate position. Demonic remnants in central Kalimdor could confirm old suspicions that the orcs and their allies still serve the Burning Legion. With Warchief Thrall's sanction, Keldran oversees the effort from Orgrimmar. They must clear those remnants before hostile Alliance factions use them to justify war. The orders lead south through the Charred Vale in the Stonetalon Mountains and onward into Desolace. Ghost Walker Post stands just north of the vast Kodo Graveyard. Horde agents such as Takata Steelblade watch over these wastes. Rampant centaur tribes and spreading demonic corruption both threaten the region.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1432-aff705ea5c49661e3842/1-0000.mp3", duration = 59.9771429, start = 0},
  },
}
P.transport["quest:1442"] = {
  hash = "ef8ff9",
  fullHash = "ef8ff9",
  text = "Seeking the Kor Gem. You cross the sea to Darkshore seeking a Kor gem for Jordan Stilwell. Thundris Windweaver sends an Alliance paladin initiate into Blackfathom Deeps, where naga have corrupted the potent stone. Jordan needs it for his craft. Paladins in training travel across the sea to Darkshore for materials Jordan Stilwell needs. In Auberdine, the night elf Thundris Windweaver remembers the human blacksmith with respect. Night elves keep their distance, and some fallen humans have betrayed their trust. Yet Thundris believes paladins can still follow a righteous path. He tells them where ancient gems may be found. Blackfathom Deeps lies beneath Ashenvale's foggy northwestern coast. Twilight's Hammer cultists and treacherous sea-dwellers dwell in its submerged halls. Naga priestesses channel foul magic through ancient Kor gems. The gem you seek lies deep within the temple complex, among its dark halls and dangerous inhabitants.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1442-da8b5737cf7f4982964f/1-0000.mp3", duration = 64.4440816, start = 0},
  },
}
P.transport["quest:1447"] = {
  hash = "bdd30c",
  fullHash = "bdd30c",
  text = "The Missing Diplomat. In Stormwind, you seek the missing diplomat and find Dashel Stonefist in Old Town. You need answers from a man who would rather keep them to himself. In Old Town, your search leads through cutpurses and shady brokers, beyond the Cathedral’s watchful eye. Dashel Stonefist is a local contact with ties to Stormwind’s criminal factions. He knows about the abduction, but has no wish to share what he knows with investigators asking sensitive questions.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1447-84d472b8e6f995f33dcf/1-0000.mp3", duration = 31.1118367, start = 0},
  },
}
P.transport["quest:1472"] = {
  hash = "3a5fe1",
  fullHash = "3a5fe1",
  text = "Devourer of Souls. In the Temple of the Damned, Carendin Halgar teaches Forsaken warlocks to bind a succubus. Godrick Farsan knows how to draw one from the Twisting Nether with the hearts of pure, loving mortals. Carendin Halgar teaches that a succubus must be lured across the threshold, not called by command. The demon hungers to ruin virtue and consume mortal essence. Offer the hearts of genuinely virtuous, loving men as bait. Halgar sends you to Godrick Farsan, who knows where such rare quarry can be found. Deep in the Temple of the Damned, Godrick Farsan helps Carendin prepare for demonic binding. Farsan has lost his physical sight, but says this has given him a deeper one. He claims to perceive spiritual currents and distant souls with uncanny clarity. With that sight, he can guide you to the pure hearts needed to draw out the demon.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1472-50441aae776a51241d1b/1-0000.mp3", duration = 63.6342857, start = 0},
  },
}
P.transport["quest:1474"] = {
  hash = "5de215",
  fullHash = "5de215",
  text = "The Binding. In the Undercity, Carendin Halgar puts an initiate's command of a succubus to the test. Pure Hearts draw the demon from the Twisting Nether into a ritual circle, where the warlock must master it through combat. In the Undercity's Magic Quarter, Forsaken warlocks learn to command demons. Summoning a succubus marks a hard passage in that training. A voidwalker depends on brute force, and an imp on lesser malice. A succubus can turn seductive and mental enchantments against its summoner. So Carendin Halgar requires each initiate to prove mind and magic unshakable before granting lasting dominion over such a demon.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1474-454f1732e36f7984093d/1-0000.mp3", duration = 48.4571429, start = 0},
  },
}
P.transport["quest:1476"] = {
  hash = "abe740",
  fullHash = "abe740",
  text = "Hearts of the Pure. In the Undercity, Godrick Farsan sets a trial for Carendin Halgar’s succubus binding. You seek two righteous human men whose pure hearts will tempt a demon. Carendin Halgar, master summoner in the Temple of the Damned, gives Godrick Farsan the groundwork for binding a succubus. Succubi prey on desire and ruin. Yet untainted virtue draws them from the Twisting Nether, where they are ripe for corruption. So Godrick searches human lands for souls whose goodness remains pristine and unbroken. Godrick Farsan names two men whose virtue marks them for sacrifice. Dalin Forgewright cares for desperate Lordaeron refugees barred from sanctuary outside the sealed Greymane Wall in southern Silverpine. Comar Villard tirelessly searches the perilous marshlands of the Wetlands for any trace of his lost wife. Their devotion, empathy and loyalty make them prime sacrifices to a Forsaken warlock.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1476-484d231f1112f3fadbaa/1-0000.mp3", duration = 61.1265306, start = 0},
  },
}
P.transport["quest:148"] = {
  hash = "ebba38",
  fullHash = "ebba38",
  text = "Supplies from Darkshire. Abercrombie in western Duskwood asks you to fetch a rare thread from Darkshire. He says he is too frail to cross the haunted woods and asks for Ghost Hair Thread from Madame Eva. North of Raven Hill Cemetery, you find Abercrombie alone in a shack in western Duskwood. Age and frailty keep him from making the dangerous journey through the woods to buy goods in Darkshire. So he asks you to go to the township's town square and speak with Madame Eva for a spool of Ghost Hair Thread.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_148-eb2fa380b5a96bf29646/1-0000.mp3", duration = 29.7273469, start = 0},
  },
}
P.transport["quest:1483"] = {
  hash = "684f21",
  fullHash = "684f21",
  text = "Ziz Fizziks. On Windshear Crag’s western ridge, Ziz Fizziks has left the Venture Company for the Tinkers' Union. A gnome engineer’s arrival drove him away, though his new superior works him just as hard. The Venture Company hired Gerenzo Wrenchwhistle, a gnome engineer, and Ziz Fizziks took it as an insult. He could not bear to work beside a gnomish rival, so he sought a way out. Ziz contacted Sputtervalve, a representative of the Tinkers' Union, and begged for a transfer away from Gerenzo’s oversight. The Tinkers' Union gave Ziz Fizziks a new position, but the easy life he expected never came. On Windshear Crag’s western edge, he found that Sputtervalve drove him as hard as any Venture Company foreman. Still, Ziz would rather labor under a demanding goblin superior than share an engineering workshop with a gnome.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1483-b9b50fb212b142bff8cd/1-0000.mp3", duration = 52.0881633, start = 0},
  },
}
P.transport["quest:1487"] = {
  hash = "dbe620",
  fullHash = "dbe620",
  text = "Deviate Eradication. In the Wailing Caverns, Ebru sends you to thin the deviate beasts. The night elf druid watches over the caverns while other disciples try to wake Naralex. His twisted vision has spawned mutated creatures whose numbers threaten to carry corruption beyond the underground springs and into the Barrens. Naralex brought his followers to the Barrens' underground springs, hoping to draw on the Emerald Dream and restore the dry plains as woodland. Instead, the Dream ensnared him, and his sleep turned to nightmare. Power coursing through the caverns warped native plants and animals into aggressive mutants called deviate beasts. Ebru watches from a cliffside cave above the entrance with the few Disciples of Naralex who remain. Their numbers dwindle. Some work to wake their fallen leader, but Ebru sees danger in the deviate vipers, shamblers, ravagers, and dreadfangs. They multiply quickly and may spread into the Barrens. So Ebru asks you to enter the deep tunnels and cull the monsters at their source.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1487-e56b9b8c5d8f756bb3a2/1-0000.mp3", duration = 73.2734694, start = 0},
  },
}
P.transport["quest:149"] = {
  hash = "e8bd9f",
  fullHash = "e8bd9f",
  text = "Ghost Hair Thread. In Duskwood, Madame Eva seeks ghost hair to spin into Ghost Hair Thread for Abercrombie. She sends you south of Darkshire to Blind Mary at an abandoned farmhouse, where an ethereal comb can gather hair from the tormented spirit. Madame Eva needs ghost hair to spin thread for Abercrombie. Linen and wool cannot serve Duskwood's rituals, so she gives you a Spectral Comb to gather strands from a spirit. The comb passes through the veil of death and catches loose spectral hair without violence. South of Darkshire, Blind Mary haunts an abandoned farmhouse. The tormented spirit despairs over her appearance and screams at intruders to look away. In anguish over what she had become, she tore out her own eyes. The Spectral Comb offers brief comfort: she can groom her ghostly hair, though her torment continues.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_149-27b703622bb1bd37b76a/1-0000.mp3", duration = 51.8791837, start = 0},
  },
}
P.transport["quest:150"] = {
  hash = "c46213",
  fullHash = "c46213",
  text = "Murloc Poachers. Along Lake Everstill, murlocs are stripping Lakeshire's waters of fish. Dockmaster Baren asks you to thin their ranks before the town loses its main food supply. Dockmaster Baren asks you to protect the fish that feed Lakeshire. Lake Everstill supplies the mountain town and its market with fresh catches. Large murloc tribes now crowd the shallows and scour the water for food. Left unchecked, they could wipe out the local fish and leave Lakeshire without its main food supply. Murlocs usually scavenge along the coast, so their numbers high in the Redridge Mountains are hard to explain. Dockmaster Baren wonders why they have come so far from the open ocean. They may be fleeing predators at sea, losing territorial fights, or drawn by Lake Everstill's plentiful waters. Whatever brought them inland, their presence points to trouble elsewhere in the region.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_150-cbf0f0ecd1720a8646c8/1-0000.mp3", duration = 54.2040816, start = 0},
  },
}
P.transport["quest:1507"] = {
  hash = "913ac1",
  fullHash = "913ac1",
  text = "Devourer of Souls. In Orgrimmar, Gan'rul Bloodeye sends an aspiring Horde warlock to seek Cazul's counsel. There, the warlock begins learning how to lure and bind a succubus. Horde warlocks who master lesser demons such as imps and voidwalkers may seek a succubus next. Beneath Orgrimmar, Gan'rul Bloodeye oversees the dark arts and judges when a warlock is ready to call one from the Twisting Nether. A succubus can turn the frail against themselves, so binding one takes subtlety as well as strength. A succubus preys on mortal desire, so raw incantations alone cannot call one. The summoner must lure it with an object filled with pure love and devotion. Gan'rul cannot or will not provide such a relic, so he sends the warlock across the Cleft of Shadow to Cazul. The ancient warlock knows the arcane and demonic rites needed for the next part of the ritual.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1507-f3cc8a13b3d5ba35e8c7/1-0000.mp3", duration = 60.1338776, start = 0},
  },
}
P.transport["quest:1508"] = {
  hash = "55742e",
  fullHash = "55742e",
  text = "Blind Cazul. In the Cleft of Shadow, Blind Cazul guides an initiate seeking to summon a succubus. He points toward an object charged with mortal emotion. A succubus answers to longing, sorrow, and desire. To draw one across the veil, a summoner needs more than willpower; the demon is known to devour souls. Blind Cazul understands what the initiate seeks. He knows where to find a fitting lure. Though blind, Blind Cazul senses the lives and sorrows within Orgrimmar’s red ramparts. He sends the initiate to Zankaja, an orc woman who lives atop the bluffs near the wind rider roost. She anxiously awaits her mate Dogran’s return. Her despair can draw a demon’s attention.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1508-09d5231cc9040cc21fb3/1-0000.mp3", duration = 52.0881633, start = 0},
  },
}
P.transport["quest:1509"] = {
  hash = "f72e9b",
  fullHash = "f72e9b",
  text = "News of Dogran. Zankaja waits in Orgrimmar for word of Dogran, her mate, who has been gone for days. She sends you to ask Gazrog at the Crossroads. On the bluffs of Orgrimmar, Zankaja fears for Dogran, her mate. He went to the Crossroads after an honorable promotion, but his return is overdue and she has heard nothing for days. So she asks you to seek news from his commander, Gazrog.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1509-981200a5c37e03be37f9/1-0000.mp3", duration = 25.2604082, start = 0},
  },
}
P.transport["quest:1510"] = {
  hash = "f6b97d",
  fullHash = "f6b97d",
  text = "News of Dogran. In Stonetalon, News of Dogran sends you into the foothills for a healing draught. The first runner never returned, and Ken'zigla at Malaka'jin may still have the medicine Dogran needs. Dogran lies badly wounded at Camp Taurajo in the southern Barrens. He was hurt fighting quilboar who had dug in, and the grunts who carried him back found his wounds festering. They feared the journey would harm him more before he could be treated. So Taurajo sent word north to the Crossroads for a healing draught made by the jungle trolls of Malaka'jin.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1510-4ef2f88f7c0345245fd6/1-0000.mp3", duration = 33.2538776, start = 0},
  },
}
P.transport["quest:1511"] = {
  hash = "607568",
  fullHash = "607568",
  text = "Ken'zigla's Draught. On the road to Camp Taurajo, Dogran's life depends on Ken'zigla's Draught. The troll apothecary prepared it in the Stonetalon Mountains for the missing operative. After the first courier failed to return, Ken'zigla prepared another dose. The troll apothecary had sent that emissary to find medicine for the missing scout Dogran. His draught is volatile and powerful. Half a dose gives a mortally wounded soldier strength to move without making the wounds bleed anew. The rest must wait until the next day, when it completes the recovery.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1511-294ccdcbc291aa453bd1/1-0000.mp3", duration = 38.7134694, start = 0},
  },
}
P.transport["quest:1512"] = {
  hash = "28fe86",
  fullHash = "28fe86",
  text = "Love's Gift. In Orgrimmar, Gan'rul Bloodeye waits for a pendant to draw a succubus. In the Barrens, Dogran gives up a treasured keepsake after he is found and revived. A warlock needs a talisman charged with strong, unblemished emotion to summon and control a succubus. These demons feed on mortal desire, twisting true affection into anguish. Dogran's pendant holds his devotion and the memory of their parting. Bring it to Gan'rul Bloodeye in Orgrimmar's shadowy clefts, where he cleans and polishes it. Its bright emotional force can draw the soul-devourer across the Twisting Nether.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1512-6f576af7e8a369c5d583/1-0000.mp3", duration = 41.5346939, start = 0},
  },
}
P.transport["quest:1513"] = {
  hash = "76e84d",
  fullHash = "76e84d",
  text = "The Binding. At Neeru Fireblade's circle in Orgrimmar, you face the trial of binding a succubus. Dogran's Pendant draws the demon from the Twisting Nether, where you must overcome it by spellcraft and force of arms. Beneath the clefts of Orgrimmar, Neeru Fireblade keeps a tent with a circle prepared for dangerous rites. Under Gan'rul Bloodeye's guidance, you activate its runes and face the summoned succubus in battle. Calling a demon is only the beginning. You must overpower it alone and bend its spirit to your will.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1513-556eaa5b12f7e1d992b8/1-0000.mp3", duration = 38.0342857, start = 0},
  },
}
P.transport["quest:1515"] = {
  hash = "5219fb",
  fullHash = "5219fb",
  text = "Dogran's Captivity. At Camp Taurajo, a warlock faces a vital trial in Horde training: rescue a captured orc warrior. With Ken'zigla's Draught, you must find battered Grunt Dogran and give him strength to escape. Grunt Logmar at Camp Taurajo will not risk Horde soldiers in a costly attack on the entrenched quilboar. So Grunt Dogran's fate rests with you, an aspiring warlock armed only with Ken'zigla's Draught. Travel north through the brambles and hostile camps to find where the quilboar hold him captive.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1515-2538d25bb2131ef9e924/1-0000.mp3", duration = 33.7240816, start = 0},
  },
}
P.transport["quest:1529"] = {
  hash = "ec2cf6",
  fullHash = "ec2cf6",
  text = "Call of Water. In Thunder Bluff, your training turns toward water and a journey to the Barrens shore. You travel east to meet Islen Waterseer and begin the path toward the Water Totem. You have mastered earth and fire, and your trainers now judge you ready to study water. In Thunder Bluff, Xanis Flameweaver sees that you have the discipline to approach this cleansing element. So you leave Mulgore's mesas and cross the dry plains of the Barrens to the east. Islen Waterseer lives in a fishing shack on the Barrens' eastern coast, south of Ratchet and the mouth of the Southfury River. She keeps apart from the settlements beside the open ocean. Islen reads your readiness in the elements around you. Earth, wind, and fire already touch your spirit, and she prepares trials to teach you the purity of water.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1529-f5f2a9a5be673be86ae4/1-0000.mp3", duration = 60.2122449, start = 0},
  },
}
P.transport["quest:1530"] = {
  hash = "c220ce",
  fullHash = "c220ce",
  text = "Call of Water. Horde shamans journey south through the Barrens at Islen Waterseer's bidding, seeking Brine. There, they learn how water cleanses and heals. Islen Waterseer teaches that water brings rebirth. It carves rock, washes away impurities, and mends flesh, but only when it is pure. Polluted water brings blight instead of life. Before seeking communion with water, every shaman must understand this balance. You travel far south through the arid Barrens to find Brine. Quilboar raids trouble the wastes, yet Brine lives alone, without guards or fear. She holds the knowledge and trials that will help you bind yourself to water.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1530-bdac82d2499b7f0736f2/1-0000.mp3", duration = 41.6391837, start = 0},
  },
}
P.transport["quest:1531"] = {
  hash = "7cffcb",
  fullHash = "7cffcb",
  text = "Call of Air. At Grommash Hold, Searn Firewarder sends seasoned shamans south for the Air Totem. Prate Cloudseer guides them through the final element of their craft. You have earned the favor of earth, fire, and water. Now you travel south from Orgrimmar across the Barrens, then down into the canyons of Thousand Needles to learn the last element: air. Troll trainer Searn Firewarder sends you when he sees you are ready for this final step in your early training. Prate Cloudseer waits in a high cave among the sandstone mesas of Thousand Needles. She lives quietly with her partner, far from Horde encampments, and expects you to show deference before she shares the secrets of the wind. Meet her with proper respect, and she teaches you the knowledge and focus to manifest the Air Totem. Then your circle of elemental craft is complete.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1531-f5b2c37f03d713668c28/1-0000.mp3", duration = 56.8163265, start = 0},
  },
}
P.transport["quest:1532"] = {
  hash = "54348c",
  fullHash = "54348c",
  text = "Call of Air. Xanis Flameweaver sends seasoned Horde shamans south from Thunder Bluff to seek Prate Cloudseer in Thousand Needles. There, they seek communion with the wind and the Air Totem, which channels its swift forces. You have attuned to earth, fire, and water. Now Xanis Flameweaver guides you from Thunder Bluff through a trial of humility, focus, and respect for the sky. Air is the final element, and its winds are fickle. They are harder to control than the elements you have already learned. Your path leads south, past the Barrens and into the canyons of Thousand Needles. Far to the east, Prate Cloudseer dwells in a secluded cave on the cliffs, where canyon drafts howl day and night. She tests your preparedness before giving you the Air Totem. It channels gusts, lightning, and swift wind spirits.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1532-825b37ba54444a3f47fc/1-0000.mp3", duration = 56.4244898, start = 0},
  },
}
P.transport["quest:1534"] = {
  hash = "0e26eb",
  fullHash = "0e26eb",
  text = "Call of Water. Brine sends a shaman north from the Barrens to gather water for Call of Water. This final essence comes from an ancient fountain in Ashenvale. After gathering water from the pool below Brine’s hut in the Barrens and the pure well of Tarren Mill, you need one final essence. Brine sends you north across the dry plains and into Ashenvale, an ancient woodland sacred to the night elves. The Barrens give way to Ashenvale’s deep canopy, where water takes another form. To live in harmony with the element, a shaman must understand its many forms. Past the shimmering waters of Mystral Lake, near the mountain pass between Ashenvale and the Stonetalon Mountains, lie the Ruins of Stardust. An ancient fountain rests among quiet waters and old stones in this secluded elven sanctum. Untamed elemental and nature spirits guard the ruins and resent intruders. Tread carefully as you draw water from the fountain.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1534-afc0217299a33e89647c/1-0000.mp3", duration = 69.3028571, start = 0},
  },
}
P.transport["quest:1535"] = {
  hash = "8d01fd",
  fullHash = "8d01fd",
  text = "Call of Water. Brine sends shamans across the Barrens to gather water for a sapta. Below her hill, a guarded pool provides the first sample, and water means survival. Brine asks shaman initiates to study water in all its forms before she grants the water sapta. The sapta opens an initiate’s perception and lets them commune with the spirits. In the dry Barrens, water means survival. Forests flourish where it flows, while deserts starve without it. Living beings will kill to protect even the humblest spring. Quilboar fiercely guard the watering hole beneath Brine’s hill. They treat every pool as a priceless hoard and feast when rain comes. Brine regrets the violence their hoarding brings. Yet their greed and divided clans keep their threat contained, leaving the other races on the plains in a precarious balance.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1535-3b0cb7daec79e3f1eb93/1-0000.mp3", duration = 53.8906122, start = 0},
  },
}
P.transport["quest:1536"] = {
  hash = "ae239a",
  fullHash = "ae239a",
  text = "Call of Water. You leave the Barrens for a pure spring in Forsaken-held Tarren Mill. Its water will help Brine prepare the Water Sapta, and its survival offers hope. Brine sends you across the sea to Tarren Mill in Hillsbrad Foothills. She needs water there to prepare the Water Sapta. Human resistance and the newly allied Forsaken surround the town, yet its small central well gives pure spring water. To Brine, it is a sacred remnant of cleanliness in an unhallowed land. For Brine, the pure well in Tarren Mill is more than an ingredient. She sees its endurance in Warchief Thrall, who bore hardship, captivity, and sorrow before rising to lead the orcish people. Thrall gives the Horde hope. The well shows that life and purity can endure through tragedy and corruption.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1536-ded76694c70be7aa4013/1-0000.mp3", duration = 54.9093878, start = 0},
  },
}
P.transport["quest:154"] = {
  hash = "380415",
  fullHash = "380415",
  text = "Return the Comb. In Darkshire, Madame Eva waits for the comb Blind Mary has returned. Its ghostly strands can be spun into Ghost Hair Thread. Blind Mary waits in a shack south of Darkshire, grieving the death that changed her. Madame Eva’s comb recalls the grooming of her mortal life, and deepens her sorrow. She sees only a wraith, a monster stripped of mortal grace. Certain no one can love her again, she thrusts the comb and the ghostly hair tangled in its teeth back into your hands. Madame Eva awaits the comb in Darkshire, knowing the work was grim. With the ghostly hair, the fortune teller can spin a spool of Ghost Hair Thread. She pays you for any strands left after the delicate work.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_154-109d0f45ab8cd8d1b638/1-0000.mp3", duration = 45.5314286, start = 0},
  },
}
P.transport["quest:156"] = {
  hash = "d79415",
  fullHash = "d79415",
  text = "Gather Rot Blossoms. In Duskwood, Tavernkeep Smitts needs rot blossoms for his zombie juice. They grow inside the skulls of skeletal horrors and fiends in the graveyards. At the Scarlet Raven Tavern, Tavernkeep Smitts sometimes brews a strange drink. His zombie juice calls for rot blossoms, which root inside the empty skulls of animated skeletons. Smitts avoids the undead, so passing mercenaries gather the blossoms for him. Rot blossoms grow on skeletal horrors and fiends in the overgrown plots of Tranquil Gardens Cemetery and Raven Hill Cemetery. The Night Watch militia is stretched thin against the terrors creeping through the woods. Smitts commends those who hunt the dead to Commander Althea Ebonlocke, helping thin the restless ranks that threaten Darkshire.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_156-b5d6da4b4eeae58bda80/1-0000.mp3", duration = 48.404898, start = 0},
  },
}
P.transport["quest:157"] = {
  hash = "2c6a9f",
  fullHash = "2c6a9f",
  text = "Deliver the Thread. In Darkshire, Madame Eva sends Ghost Hair Thread west through Duskwood to Abercrombie near Raven Hill Cemetery. The hermit says he needs it to guard his hut from restless spirits. Madame Eva gives you a spool of Ghost Hair Thread, spun from hair gathered from the ghost Blind Mary. You carry it west through Duskwood, where spiders and undead roam. Abercrombie waits in his ramshackle shack just north of Raven Hill Cemetery.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_157-e5111c18ab9b86820234/1-0000.mp3", duration = 28.3428571, start = 0},
  },
}
P.transport["quest:158"] = {
  hash = "45d8b9",
  fullHash = "45d8b9",
  text = "Zombie Juice. Abercrombie sends travelers from his lonely shack in Duskwood to Darkshire for Zombie Juice. He says the night’s chill leaves him cold. Abercrombie lives alone among the horrors of Duskwood’s shadowed woods and often sends travelers on strange errands. He says the creeping dusk drains his warmth and vitality, then asks you to travel east to Darkshire. At the Scarlet Raven Tavern, Tavernkeep Smitts sells the potent drink Abercrombie seeks. Its ominous name is Zombie Juice, and Abercrombie says it will put fire back in his veins. Tavernkeep Smitts serves weary guards and frightened townsfolk at Darkshire’s tavern, but few ask for Zombie Juice. The drink is known for its dangerous strength, and Smitts recognizes the vintage. Abercrombie’s taste for such a morbid brew raises quiet eyebrows in a region besieged by the restless dead.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_158-2fce62a5dcdcc923a102/1-0000.mp3", duration = 55.4579592, start = 0},
  },
}
P.transport["quest:159"] = {
  hash = "f45264",
  fullHash = "f45264",
  text = "Juice Delivery. In Darkshire, you carry Zombie Juice west to a hermit on Duskwood’s edge. Tavernkeep Smitts says the brew is stout enough to raise the dead. It is meant to warm Abercrombie, though its potency raises questions. Tavernkeep Smitts brews a legendary draught in Darkshire. When the Zombie Juice is ready, he hands you the bottle and warns you to handle it gently. He says the concoction is stout enough to raise the dead. You carry it across the haunted forest to an eccentric loner, in what seems a simple act of charity.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_159-cd6d6a2591844b751bd9/1-0000.mp3", duration = 32.3395918, start = 0},
  },
}
P.transport["quest:160"] = {
  hash = "cec41f",
  fullHash = "cec41f",
  text = "Note to the Mayor. In western Duskwood, Abercrombie sends a message to Darkshire, where the mayor awaits an unexpected delivery. He calls himself an old friend of Mayor Lord Ello Ebonlocke, but the note raises questions. You return Abercrombie’s stolen chest from the ogres at Vul'Gol Ogre Mound, then carry his message down the misty roads to town. The hermit laughs with delight. He says he and Mayor Lord Ello Ebonlocke are old friends, and insists the mayor will be just as thrilled by what you have done.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_160-ee0d7600fe85c17ab359/1-0000.mp3", duration = 34.56, start = 0},
  },
}
P.transport["quest:163"] = {
  hash = "8936fc",
  fullHash = "8936fc",
  text = "Raven Hill. In far western Duskwood, a light flickers in a ruined window at Raven Hill. Elaine Carevin sends travelers from Darkshire to learn what has taken shelter there. The Night Watch has long left Duskwood’s far west to the dead and the wilderness. Yet signs of life there demand attention. Calor, a watcher on the gloomy roads, saw movement among Raven Hill’s silent houses two nights in a row. A lantern flickered in a window. With ghouls, skeletons, and beasts across the land, the Night Watch cannot ignore what stirs among the ruins.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_163-0f0f8c65293299d8a628/1-0000.mp3", duration = 34.2465306, start = 0},
  },
}
P.transport["quest:164"] = {
  hash = "eca681",
  fullHash = "eca681",
  text = "Deliveries to Sven. In Darkshire, Elaine Carevin sends supplies to Sven Yorgen's camp in northwestern Duskwood. Sven and his few followers face the dangers of the blighted woods. Sven Yorgen and a few companions keep a camp on Duskwood's northwestern frontier. Wolves, spiders, and restless dead threaten Darkshire, yet Sven's band holds its ground beyond the town's walls. Danger keeps them from sparing anyone for the perilous journey back to town for provisions. Elaine Carevin arranges for travelers to carry supplies so the fighters can hold on. The Carevin family respects Sven and sees his stand as devotion to the Light. Elaine organizes supplies and sends them to his camp. When Sven receives the crate, he knows the Carevins are supporting him. His attention stays on the battle at hand.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_164-c42e7a313d4c4d1cdbd2/1-0000.mp3", duration = 50.8604082, start = 0},
  },
}
P.transport["quest:1649"] = {
  hash = "942ba3",
  fullHash = "942ba3",
  text = "The Tome of Valor. In Stormwind, The Tome of Valor calls paladins to prove their faith and courage. Duthorian Rall awaits those ready to petition the Church. The Tome teaches that valor is forged through hardship. Its sacred text likens virtues to precious ores, valuable when found but refined to endure. Through hard trials and true commitment, a paladin binds faith, compassion, and courage into strength against the evils threatening Azeroth. After reading the Tome, you are directed to Duthorian Rall, a respected paladin leader in Stormwind's Cathedral of Light. He hears petitions from those seeking the trials of valor. The tests are no mere ritual. Defending the innocent and upholding the Church may cost your life, and only the steadfast earn recognition in the order.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1649-a34c2005e7fcb3bf1235/1-0000.mp3", duration = 53.3159184, start = 0},
  },
}
P.transport["quest:165"] = {
  hash = "53128c",
  fullHash = "53128c",
  text = "The Hermit. In Darkshire, Elaine Carevin asks you to check on Abercrombie, an elderly recluse who has stopped coming for provisions. His rickety shack stands at the edge of Raven Hill Cemetery. Elaine Carevin recalls an old man who once came to Darkshire for provisions, then stopped appearing. With danger on Duskwood’s roads, she asks you to visit his shack by Raven Hill Cemetery and find out whether he is safe. At the shack, you find Abercrombie alive. He chuckles at the Carevins’ concern and says age and the monsters in the woods have kept him from town. Glad to have an able traveler at his door, he quickly asks for help with a few errands.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_165-2adebe36053911dd27e0/1-0000.mp3", duration = 41.717551, start = 0},
  },
}
P.transport["quest:1650"] = {
  hash = "1badde",
  fullHash = "1badde",
  text = "The Tome of Valor. Duthorian Rall sends you to guard Daphne Stilwell on Westfall’s distant shore. Her husband is away, and Defias bandits threaten their homestead. At Stormwind’s Cathedral of Light, Duthorian Rall tests those who seek to become paladins. He asks them to defend the people of the realm. Now you have taken up the mantle of valor, and must put those ideals to work where law and authority have failed. Daphne Stilwell and her husband Jordan keep an outpost at Westfall’s isolated Longshore. Jordan is away in Ironforge, consulting dwarven blacksmiths, while Defias Brotherhood activity runs rampant. So Duthorian sends you west to protect Daphne before thieves overwhelm her homestead.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1650-6155f4b3fcd242441e78/1-0000.mp3", duration = 51.3306122, start = 0},
  },
}
P.transport["quest:1651"] = {
  hash = "6f6625",
  fullHash = "6f6625",
  text = "The Tome of Valor. At her Westfall farm, Daphne Stilwell calls for aid as the Defias Brotherhood closes in. A paladin must answer her plea. The Defias Brotherhood still contests the land around Daphne's homestead. Earlier clashes have not ended the danger, and another assault is expected. You are sent to hold the ground beside her house. There is no retreat. Your pursuit of the virtues in the Tome of Valor now faces a test of courage. Daphne has only her own firearm, while you can call on the blessings of the Holy Light. Wave after wave of Defias raiders attacks, and the fight tests whether you can protect someone vulnerable under crushing pressure. True valor means standing between innocent civilians and ruthless violence, even when danger bears down on you.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1651-b0771e5d7851363dfa04/1-0000.mp3", duration = 46.6285714, start = 0},
  },
}
P.transport["quest:1652"] = {
  hash = "5538a0",
  fullHash = "5538a0",
  text = "The Tome of Valor. At Stormwind's Cathedral of Light, you tell Duthorian Rall that Daphne Stilwell is safe after the defense of her Westfall homestead. Your courage fulfills the Church's trials of valor and its charge to shield the innocent without thought for yourself. Your defense shows you can stand between danger and the defenseless, as the Church expects of an aspiring paladin. The homestead holds firm, and Daphne is safe from the bandits who threatened her. Jordan Stilwell, Daphne's husband, remains in Ironforge, lending his renowned craftsmanship to the Alliance. Duthorian Rall prepares to send word north, so Jordan can focus on his work knowing his family is protected.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1652-5ca4bd13167a9fd10a0b/1-0000.mp3", duration = 47.4906122, start = 0},
  },
}
P.transport["quest:1653"] = {
  hash = "c761ec",
  fullHash = "c761ec",
  text = "The Test of Righteousness. In Cathedral Square, Duthorian Rall sends you to Ironforge with news for Jordan Stilwell. His wife Daphne survived the Defias attack in Westfall. You guarded Daphne Stilwell at her Westfall homestead when Defias outlaws attacked, and she survived. Her husband had left for Ironforge, fearing his family was in danger. Now Rall sends you to tell Jordan in person, so he can learn what happened to Daphne. Jordan Stilwell once hoped to join the paladins, but chose his father's craft and became a master weaponsmith. He works at an anvil outside Ironforge's gates, holding fast to his faith as he shapes weapons. When you tell him Daphne survived, gratitude moves him to help you forge a blessed weapon of righteousness.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1653-ae687139562154ebac1f/1-0000.mp3", duration = 49.7893878, start = 0},
  },
}
P.transport["quest:1654"] = {
  hash = "2c811a",
  fullHash = "2c811a",
  text = "The Test of Righteousness. Jordan Stilwell has a sacred weapon in mind for a paladin worthy of the Light. The Ironforge smith needs rare materials from distant lands, including his lost family hammer. Outside Ironforge's gates, Jordan Stilwell cannot forge the paladin's weapon on his own. You gather the materials his craft demands. Jordan Stilwell needs four things for the weapon: Whitestone Oak lumber, refined ore from master prospectors, a purified Kor Gem, and his smithing hammer. He left the hammer behind while escaping Shadowfang Keep. Finding all four means facing dangers across the Eastern Kingdoms and beyond.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1654-413644b7d9b68b302c19/1-0000.mp3", duration = 43.3110204, start = 0},
  },
}
P.transport["quest:1655"] = {
  hash = "d1ecfa",
  fullHash = "d1ecfa",
  text = "Bailor's Ore Shipment. In Loch Modan, Bailor's Ore Shipment is bound for Jordan Stilwell's sanctified weapon. Mo'grosh ogres plundered the alloy on the road from the Wetlands. Jordan Stilwell awaits ore refined by his old friend Bailor Stonehand, but the shipment never reaches Ironforge. As the caravan travels south from the Wetlands into Loch Modan, Mo'grosh ogres ambush it and slaughter its guards. One wounded guard reaches a camp, then dies soon after. The shipment is left in ogre territory. Bailor Stonehand camps in Loch Modan and sends paladins across the Loch toward the northeastern hills. The stolen crate of alloy lies abandoned among the Mo'grosh camps. Recovering it means entering hostile territory, and will let Bailor keep his agreement with Jordan Stilwell.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1655-bb8453bd60f9a6ca9fad/1-0000.mp3", duration = 53.3681633, start = 0},
  },
}
P.transport["quest:166"] = {
  hash = "851a7d",
  fullHash = "851a7d",
  text = "The Defias Brotherhood. In Westfall, The Defias Brotherhood still keeps the farmlands in fear. Gryan Stoutmantle has found its stronghold beneath Moonbrook and calls for a final blow against its leader. Gryan Stoutmantle and the People's Militia have fought the Defias Brotherhood across Westfall for months. Now its stronghold lies exposed beneath Moonbrook. Stoutmantle orders Edwin VanCleef killed, believing his death will end the rebellion at last.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_166-3c7653a051e783c06ef0/1-0000.mp3", duration = 30.4587755, start = 0},
  },
}
P.transport["quest:167"] = {
  hash = "f6db6d",
  fullHash = "f6db6d",
  text = "Oh Brother. . .. In Stormwind, Wilder Thistlenettle waits after escaping a cave-in beneath Moonbrook. His brother, Foreman Thistlenettle, and the rest of the crew remain behind the rubble, and Wilder asks you to find his brother or recover the dwarf's Explorers' League Badge. Wilder Thistlenettle and his brother worked for a mining company in the tunnels beneath Moonbrook. Then thieves swarmed the mines, and a cave-in sealed the lower passages. Wilder escaped to Stormwind. His brother and the rest of the crew remained trapped behind the rubble.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_167-16342b8c6247e6dfbf6b/1-0000.mp3", duration = 37.9559184, start = 0},
  },
}
P.transport["quest:169"] = {
  hash = "d0c2bd",
  fullHash = "d0c2bd",
  text = "Wanted: Gath'Ilzogg. In Redridge, Magistrate Solomon offers a bounty for Gath'Ilzogg, the warlord behind Blackrock's invasion of Stonewatch. Anyone who storms the conquered keep and brings back the commander's severed head may claim it. Gath'Ilzogg leads Blackrock raids across the Redridge Mountains. His orcs seized Stonewatch Keep, once a human bastion, and turned it into a stronghold for attacks on nearby settlements. From its highest ramparts, he plans further strikes against Lakeshire. Redridge may be cut off from the rest of the kingdom. Stormwind's royal army has sent no reinforcements to the border, so Magistrate Solomon acts on his own. Lakeshire lacks the soldiers to retake Stonewatch Keep by force. Solomon offers a public bounty on Gath'Ilzogg, hoping to break Blackrock's leadership and begin reclaiming the keep for the crown.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_169-8963b5e526b466a6794f/1-0000.mp3", duration = 62.484898, start = 0},
  },
}
P.transport["quest:1698"] = {
  hash = "deac09",
  fullHash = "deac09",
  text = "Yorus Barleybrew. At the Lakeshire Inn, Yorus Barleybrew awaits bold Alliance warriors with an eccentric challenge. Trainers across Alliance capitals send seasoned fighters from Stormwind toward the Redridge borderlands to meet the dwarf and face his test of arms. Across Alliance capitals, warrior trainers watch fighters outgrow their first drills. When an apprentice proves their mettle around their twentieth season, Kelv Sternhammer, Wu Shen, and Darnath Bladesinger pass along word of Yorus Barleybrew. The dwarf offers no standard military order. Instead, he has issued an open wager and a test of arms to any Alliance warrior bold enough to answer. Yorus Barleybrew waits at the tavern in Lakeshire, on the front lines of Redridge's struggle against encroaching gnolls and Blackrock orcs. Those who find him meet a boastful dwarf with a hearty drink in hand, ready to judge any challenger who claims true fighting spirit. For warriors seeking to prove themselves beyond the capital's safe cobbled streets, his trial opens onto the harsher battles of the frontier.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1698-0b557c067d704a8200bb/1-0000.mp3", duration = 75.0236735, start = 0},
  },
}
P.transport["quest:1699"] = {
  hash = "df4f1a",
  fullHash = "df4f1a",
  text = "The Rethban Gauntlet. In Lakeshire, Yorus Barleybrew sends runners north toward Rethban Caverns and back. They drink his family's fiery Barleybrew Scalder, then race to return within an hour. Lakeshire's inn is full of grim talk about gnoll raids and missing town guards. Yorus Barleybrew offers travelers another diversion: a test of speed, courage, and endurance. Before they set out on foot for the northern foothills, they drink a draught of his family's Barleybrew Scalder. Redridge gnolls roam the hills between Lakeshire and Rethban Caverns. Runners must fight through their packs or slip past, reach the first fork in the dark tunnels, then hurry back to Yorus within an hour. The fiery drink makes the run harder, and challengers stagger through the hills.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1699-a4af2b397959e60bd62f/1-0000.mp3", duration = 47.7257143, start = 0},
  },
}
P.transport["quest:1700"] = {
  hash = "fe0ea3",
  fullHash = "fe0ea3",
  text = "Grimand Elmore. In Stormwind City, Grimand Elmore receives Furen Longbeard's technical notes. Their brief exchange carries intricate findings between two headstrong weaponsmiths who share the city. Furen Longbeard forged the specialized Fire Hardened Mail and uncovered intricate heat-treating techniques and elemental principles. He records his findings on parchment, then asks you to deliver them straight to Grimand Elmore, a seasoned crafter at a nearby weapon shop. Grimand Elmore bristles at the manuscript. He insists he taught Furen everything the younger dwarf knows, and the thought that his former pupil could teach him wounds his pride. Yet Grimand cannot resist reading the notes. Soon he finds an intriguing idea and is eager to test it himself.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1700-e5875a8fce74151dc71b/1-0000.mp3", duration = 55.7453061, start = 0},
  },
}
P.transport["quest:1701"] = {
  hash = "63c0ee",
  fullHash = "63c0ee",
  text = "Fire Hardened Mail. In Stormwind, Furen Longbeard offers an Alliance warrior a new design for Fire Hardened Mail. He will forge it if you bring rare materials from both continents. Furen Longbeard has forged an exceptional buckler for you. Now the dwarf armorer proposes a greater work: mail made to withstand fierce blows. His craft calls for more than iron or steel. He needs rare materials touched by elemental heat and natural resilience. Furen cannot leave his Stormwind forge, so you must gather these dangerous ingredients. Furen sends you to distant wilds and dangerous depths for the materials. The recipe calls for fangs from venomous spiders in the Wetlands' damp crevices. It also needs scorched and galvanized horns from fierce chimaeras in the Stonetalon Mountains. To bind and temper these beast parts into mail, Furen needs volatile phlogiston from Roogug, a geomancer deep within Razorfen Kraul's thorny maze in the Barrens.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1701-685c2d67ca0ea816a4c5/1-0000.mp3", duration = 63.5297959, start = 0},
  },
}
P.transport["quest:1702"] = {
  hash = "b39e8d",
  fullHash = "b39e8d",
  text = "The Shieldsmith. In Stormwind, Yorus Barleybrew sends warriors to claim the shield he promised. A hard trial in the Redridge Mountains is behind them, and a cask of Barleybrew Scalder is bound for Furen Longbeard, the smith who will shape their shield. You have faced the gnolls and dangers of the Rethban Gauntlet, and Yorus Barleybrew keeps his bargain. Lakeshire cannot provide the promised shield, so he sends proven fighters back to Stormwind City. There, a dwarven armorer is ready to repay a personal debt. Yorus gives you a heavy cask of Barleybrew Scalder in place of a letter of credit. Carry it to Furen Longbeard in Stormwind's Dwarven District. The seasoned smith knows whose name stands behind the cask and lends his skill to a warrior who seeks a stout shield.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1702-84961016b642189728da/1-0000.mp3", duration = 53.0808163, start = 0},
  },
}
P.transport["quest:1703"] = {
  hash = "c2a447",
  fullHash = "c2a447",
  text = "Mathiel. Across the sea, Furen Longbeard sends his crafting notes to Mathiel in Darnassus. On the Warrior's Terrace, the night elf smith may carry dwarven mail forging to another pair of hands. Furen Longbeard has mastered the forging of fire-hardened armor. Now he shares what he knows with other Alliance craftsmen. He copies his diagrams and sends you across the continents to Mathiel, a smith on Teldrassil. At Darnassus's Warrior's Terrace, Mathiel tends a forge for the Sentinels and others who defend the night elf capital. Furen's notes bring dwarven methods from the underground forges of Khaz Modan to kaldorei armorers. Their craft is shaped by their bond with nature.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1703-1434214434f139bdc2d6/1-0000.mp3", duration = 46.9159184, start = 0},
  },
}
P.transport["quest:1704"] = {
  hash = "7cdafa",
  fullHash = "7cdafa",
  text = "Klockmort Spannerspan. In Tinkertown, Furen Longbeard's fire-hardened mail findings reach Klockmort Spannerspan. The dwarf smith trusts his gnomish colleague to discover what the new techniques can do. You carry Furen's notes from Stormwind to Ironforge, then on to Tinkertown. There, Klockmort Spannerspan works as a blacksmith and can test the discoveries in his own craft. Gnomish blacksmiths are rare among their dwarven hosts. Klockmort is eager to move beyond traditional metalwork, and the notes excite him with the promise of a breakthrough. He is ready to try the fiery techniques in his own unusual projects.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1704-ed286bc46bc09fc6bd1c/1-0000.mp3", duration = 41.5869388, start = 0},
  },
}
P.transport["quest:1705"] = {
  hash = "bc6637",
  fullHash = "bc6637",
  text = "Burning Blood. In Stormwind, Grimand Elmore puts Furen Longbeard’s smithing methods to the test. To try them at his own forge, he needs burning blood and a burning rock from Duskwood. Grimand Elmore is one of the Alliance’s finest armorers. He seldom believes another smith can surpass his methods. Yet Furen Longbeard’s unusual discoveries have stirred his professional curiosity, and Grimand agrees to make a piece of armor using them.\n\nFor the work, he needs strange, volatile materials from the dark reaches of the south. They will quench and temper the metal to his exact requirements. Ordinary water and common coals will not do. Grimand sends you to Roland’s Doom, an abandoned mine in Duskwood. Savage Nightbane worgen have overrun its tunnels, and burning ichor pulses in their cursed veins.\n\nHe needs vials of their burning blood and a rare flaming core called a burning rock. Gutspill, leader of the pack, carries it. Bring both scorching materials back so Grimand can test Furen’s methods at the forge.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1705-c5290bf7dbad8a237947/1-0000.mp3", duration = 69.9297959, start = 0},
  },
}
P.transport["quest:1706"] = {
  hash = "566ed8",
  fullHash = "566ed8",
  text = "Grimand's Armor. Grimand Elmore now offers you a coif made from rare materials. It tests Furen Longbeard's smithing methods and is built to endure crushing blows, a hard-won step in your training as an Alliance warrior. The coif shows that Furen Longbeard's daring methods can strengthen armor against crushing impacts. Grimand Elmore forged it from rare elemental and beast components you gathered in hostile territory, putting the dwarven master armorer's theories to the test. Grimand Elmore treats the metal to bear pressure and blows that would warp ordinary steel. Then he gives you the finished coif. Its strength honors Furen Longbeard's craft and your resolve, and may help you hold the frontline against Azeroth's greatest threats.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1706-db1b1593cdfad171be32/1-0000.mp3", duration = 48.7967347, start = 0},
  },
}
P.transport["quest:1708"] = {
  hash = "f40e65",
  fullHash = "f40e65",
  text = "Iron Coral. In Tinker Town, Klockmort Spannerspan seeks searing coral for a new suit of armor. The gnome blacksmith hopes to test new smithing methods with this rare sea material on the Wetlands coast. Klockmort Spannerspan has shared discoveries with Furen Longbeard, a master dwarven smith. Now he hopes to unite Furen's skill in metallurgy with his own tinkering. Mountain ore alone will not give him the resilient armor he seeks. So he needs searing coral, a material hardened by the sea. Searing coral grows underwater off the Wetlands coast, south of Menethil Harbor. You need to bring back twenty clusters while aquatic predators prowl below. Then carry the harvest to Ironforge. Klockmort plans to smelt and hammer the coral into experimental armor plating.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1708-ffde3a3f19e9393aef16/1-0000.mp3", duration = 57.2081633, start = 0},
  },
}
P.transport["quest:1709"] = {
  hash = "f33b08",
  fullHash = "f33b08",
  text = "Klockmort's Creation. In Tinker Town, Klockmort Spannerspan puts Furen Longbeard's forging method to work on rare materials. The result is armor made to endure. Using Furen Longbeard's methods, Klockmort finishes a pair of armored gauntlets in Tinker Town. Dwarven metalworking and gnomish mechanical skill come together in gauntlets built to endure punishment that would crush ordinary steel. Klockmort says a siege engine could run over the armor without leaving lasting distortion. Peculiarly treated rare components give it resilience. Dwarven forging and gnomish ingenuity join in armor built to withstand the fiercest frontline battles.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1709-b7dc6f2a5e5fe7db784d/1-0000.mp3", duration = 47.3077551, start = 0},
  },
}
P.transport["quest:1710"] = {
  hash = "dfc67d",
  fullHash = "dfc67d",
  text = "Sunscorched Shells. In Darnassus, Mathiel seeks wyvern eggshells to strengthen a new way of crafting mail. He works with Furen Longbeard, a dwarven smith, and sends warriors to gather shells from Highperch in Thousand Needles. From the Warrior's Terrace in Darnassus, Mathiel looks beyond night elven methods. He corresponds with Furen Longbeard, a skilled dwarven armorer in Stormwind, and studies his discoveries in metalwork and armor-smithing. Mathiel hopes to reinforce mail with natural materials that can withstand great strain. To test his idea, he needs materials found nowhere near Teldrassil. Mathiel's experiment calls for shells from Highperch, far south across the sea in Thousand Needles' canyon gorges. Wyverns nest high above the salt flats and red stone mesas beneath Kalimdor's blazing sun. Heat and altitude harden their eggshells. Mathiel plans to grind the sun-baked fragments into a resilient lacquer and coat chainmail links, so the armor bends while enduring exceptional strain.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1710-5753179ca8d0677550fb/1-0000.mp3", duration = 67.9444898, start = 0},
  },
}
P.transport["quest:1711"] = {
  hash = "6015be",
  fullHash = "6015be",
  text = "Mathiel's Armor. At the Darnassus forge, Mathiel's Armor joins night elf and dwarven craft. In the Warrior's Terrace, Mathiel uses methods devised by Furen Longbeard to shape exotic materials into armor for Alliance warriors. For millennia, night elf armorers have shaped their work around nature, supple leathers, and carefully worked metals. Trade with the Eastern Kingdoms has led smiths such as Mathiel to try new ways. He joins elven craft with the dwarven techniques devised by Furen Longbeard. Mathiel needs sunscorched eggshells from the Highperch wyvern nests in Thousand Needles. He renders the sun-hardened shells into lacquer, then uses Furen's heat-treatment formulas to forge resilient leggings for the front lines.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1711-f3840c5d7314f150441e/1-0000.mp3", duration = 49.5542857, start = 0},
  },
}
P.transport["quest:1716"] = {
  hash = "85592e",
  fullHash = "85592e",
  text = "Devourer of Souls. In Stormwind, Gakin sends warlocks across the sea for counsel on summoning a succubus. Takar the Seer holds the wisdom they need. Beneath the Slaughtered Lamb in Stormwind’s Mage Quarter, Gakin the Darkbinder guides promising warlocks toward summoning a succubus. The demon devours souls, destroys hearts, and dominates minds, so no warlock should call one blindly into Azeroth. A potent lure is needed: an object tied to pure love. That token draws the succubus from the Twisting Nether, where the warlock can defeat and bind it. Stormwind’s covens cannot teach where to find such an object. Gakin sends his pupils across the Great Sea to Kalimdor for the needed catalyst. Takar the Seer waits in the arid Barrens, near the Horde settlement of Camp Taurajo. An Alliance warlock must cross wilderness patrolled by hostile centaur, quilboar, and Horde warriors to reach him. The journey tests whether a summoner can survive before the ritual begins.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1716-802b580dcca267e05b1f/1-0000.mp3", duration = 65.7763265, start = 0},
  },
}
P.transport["quest:1717"] = {
  hash = "3260ad",
  fullHash = "3260ad",
  text = "Gakin's Summons. From Ironforge, Gakin's Summons sends promising Alliance warlocks south to Stormwind. Beneath the Mage Quarter, Gakin the Darkbinder awaits to oversee their progress in commanding greater fiends. Demonology stays hidden across Alliance lands. In Ironforge, Lago Blackwrench quietly watches wandering practitioners for the brotherhood in Stormwind. When a warlock masters their first minions, word travels quickly. Lago sends word to leave the snowy mountains of Khaz Modan and report south without delay. Beneath The Slaughtered Lamb in Stormwind's Mage Quarter, Gakin the Darkbinder coordinates the city's warlocks. He sees every capable student as a valuable but hazardous investment. His summons marks the threshold of true demonic binding. Now begin the trials to subjugate a succubus from the Twisting Nether.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1717-6b70e12f1ca2f0fd078e/1-0000.mp3", duration = 57.5738776, start = 0},
  },
}
P.transport["quest:1718"] = {
  hash = "f3a3ec",
  fullHash = "f3a3ec",
  text = "The Islander. On Fray Island, warriors from across Azeroth face a trial among their peers. Their trainers send proven fighters there for the next step in their training. The island lies off the Merchant Coast, where chief warrior Klannoc Macleod awaits them. Warrior trainers in Alliance and Horde capitals send students who have outgrown basic drills to test themselves against their peers. Combat shows a fighter's progress, not rank or loyalty. So the journey leads beyond civilized sparring yards to a rugged isle in the Great Sea. Fray Island lies east of the Merchant Coast, just south of Ratchet in the Barrens. You can swim there across waters that pass over submerged sandbar shallows. Political ties matter little on the island. Fighters gather before Klannoc Macleod, its chief warrior, and await the trial he chooses.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1718-314ea5e6ea5cbf013157/1-0000.mp3", duration = 51.8269388, start = 0},
  },
}
P.transport["quest:1719"] = {
  hash = "49f7cf",
  fullHash = "49f7cf",
  text = "The Affray. On Fray Island, warriors face challengers before Klannoc Macleod will train them. The Affray tests their strength against the island’s fighters and its champion. Fray Island lies apart from the mainland and draws brawlers, outcasts, and combat instructors. Klannoc Macleod does not train every wanderer who arrives by boat. Warriors seeking his lessons must enter the Affray first. There, their stamina and awareness in battle show whether they can fight beyond mere boasting. A warrior begins the Affray by stepping onto the central iron grate among the spectators. Then Ringmaster Twiggy Flathead sends challengers into the ring one after another. Those who survive face the island’s heavyweight champion, Big Will. Only by defeating him can a warrior earn Klannoc’s respect.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1719-235e3b77547eadc713ba/1-0000.mp3", duration = 51.8269388, start = 0},
  },
}
P.transport["quest:173"] = {
  hash = "7743b9",
  fullHash = "7743b9",
  text = "Worgen in the Woods. In Darkshire, Calor sends hunters against Nightbane Shadow Weavers in Duskwood. The disillusioned former guardsman is stationed in town, and the hunt runs through Brightwood Grove and the Rotting Orchard. Those who face the worgen prove their mettle to Master Jonathan Carevin's monster hunters. The Night Watch struggles against undead, spiders, and outlaws along Darkshire's borders. Calor grew weary of guards too slow and complacent to cleanse the land. He left the Watch and joined Master Jonathan Carevin, turning his blade against heresy and corruption.\n\nCarevin admits no one lightly to his circle. Those who want to aid him must first show they can survive the woods' fiercest horrors. Feral worgen rule Brightwood Grove and the blighted Rotting Orchard. Among them, Nightbane Shadow Weavers use dark magic to blind and ensnare their victims before tearing them apart. Calor sends aspiring hunters to slay these spell-weaving beasts. Their courage is tested as the threat is thinned, though its origins deeply unsettle Darkshire's defenders.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_173-06445e4cabc4ba72b2aa/1-0000.mp3", duration = 65.3061224, start = 0},
  },
}
P.transport["quest:1738"] = {
  hash = "aa9e53",
  fullHash = "aa9e53",
  text = "Heartswood. In the years since the Third War, warlocks seek Heartswood for an old night elf tragedy. Takar the Seer sends them into Ashenvale for Gakin the Darkbinder, who needs the wood to lure and subjugate a succubus in Stormwind. Takar the Seer says Heartswood grew where the night elf lovers Anathera and Latherion fell during the War of the Ancients, ten thousand years ago. Their last breaths and devotion nourished the tree. To mortals, it marks a tragic love. To practitioners of the dark arts, its concentrated emotion is potent magical fuel. Succubi feed on mortal passion, desire, and torment. Takar knows ordinary temptations cannot match an artifact filled with thousands of years of devotion. A piece of Heartswood gives Gakin the Darkbinder the catalyst he needs to draw a cunning demon through the Nether and into a summoning circle in Stormwind's Mage Quarter.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1738-ff0793a9e1c9e53761c4/1-0000.mp3", duration = 63.6081633, start = 0},
  },
}
P.transport["quest:1739"] = {
  hash = "148466",
  fullHash = "148466",
  text = "The Binding. In Stormwind, warlocks seek to bind a succubus to their will. Beneath The Slaughtered Lamb, an initiate uses an enchanted Heartswood core to summon the demon and defeat it in combat. Beneath The Slaughtered Lamb in Stormwind's Mage Quarter, a crypt shelters the city's warlocks. They practice forbidden arts there, away from the city watch and the Cathedral of Light. Stone summoning circles channel the Nether's power and let initiates reach across the veil between worlds. A warlock needs a prepared Heartswood Core to summon a succubus. The ritual opens a breach at the summoning circle, but the demon can corrupt and overwhelm even a fortified mind. To master it, the warlock must defeat it in single combat. Its physical form returns to the Twisting Nether, while its true tether is secured.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1739-2e222af6927b1cf177b8/1-0000.mp3", duration = 57.9134694, start = 0},
  },
}
P.transport["quest:174"] = {
  hash = "29d1c8",
  fullHash = "29d1c8",
  text = "Look To The Stars. In Duskwood, Viktori Prism'Antras looks to the skies for answers to the forest's curse. He trusts observation over arcane superstition and asks you to gather parts for a telescope designed by his gnomish associate. Many in fearful Darkshire blame Duskwood's troubles on black magic, curses, and restless dead. Viktori Prism'Antras doubts these alone explain the land's corruption. He believes answers may lie above the canopy. With blueprints from his gnomish partner, Cog, he plans to build an instrument for studying the heavens. Viktori needs a sturdy frame to begin building his instrument for stargazing. Cog's plans call for a machined bronze tube, and Viktori asks you to find one. He trusts practical engineering and careful observation to shed light where mysticism has failed.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_174-0d1ca848942de3944b1a/1-0000.mp3", duration = 50.9126531, start = 0},
  },
}
P.transport["quest:1740"] = {
  hash = "bec691",
  fullHash = "bec691",
  text = "The Orb of Soran'ruk. In the southern Barrens, Doan Karhan gathers warlocks around the broken Orb of Soran'ruk. They seek to restore the scattered pieces and the essence bound within. When lesser demons lose favor with the Burning Legion, their sentence is eternal. Their spirits are bound in crystal orbs and given to mortal conjurers and warlocks as vessels of power under demonic control. Shattering an orb does not free its captive. Even the shards keep potent magic. Pieces of Soran'ruk lie across two continents. Twilight's Hammer cultists hold smaller fragments in the damp caverns of Blackfathom Deeps in Ashenvale. A sorcerer in the haunted ruins of Shadowfang Keep in Silverpine Forest claimed the larger, mostly intact half.\n\nDoan Karhan has spent his life studying Legion orbs and assembled the Orb of Zargain before. With the recovered pieces, he can restore Soran'ruk as a working implement.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1740-53a44817284f543a1623/1-0000.mp3", duration = 63.1640816, start = 0},
  },
}
P.transport["quest:175"] = {
  hash = "a5616b",
  fullHash = "a5616b",
  text = "Look To The Stars. Viktori Prism'Antras needs a mirror for the telescope he is building in Darkshire from Cog's blueprints. He sends you south to find Mary, known for carrying a looking glass. Viktori Prism'Antras has the bronze tube for his telescope. Cog's blueprints call for a mirror to guide and reflect light through it. Fine silvered glass is hard to make while Darkshire faces shortages. So Viktori recalls Mary, a local woman known across the region for carrying a looking glass. Mary's old home lies deep in southern Duskwood, just north of Tranquil Gardens Cemetery. To reach it, you pass beyond the Night Watch's safe patrols. Blighted groves lie ahead, where ravenous wolves, feral spiders, and wandering undead roam.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_175-4ad7a1cf9a1ee6c3997b/1-0000.mp3", duration = 47.1771429, start = 0},
  },
}
P.transport["quest:1758"] = {
  hash = "2cc231",
  fullHash = "2cc231",
  text = "Tome of the Cabal. Above Ratchet, Strahad Farsan sends an Alliance warlock to Ironforge. There, the Tome of the Cabal may hold what an unprepared summoner needs to bind a felhunter. An imp, a voidwalker, or a succubus may be subdued by ritual. A felhunter is another matter. It serves the Burning Legion and hunts arcane energy to devour. A common summoning circle crumbles before it can hold the demon. The felhunter drains its summoner’s magic before any binding takes hold. From his redoubt in the Barrens, Strahad Farsan watches over Ratchet. He knows no amateur should attempt the binding unprepared. An acolyte needs the Tome of the Cabal’s arcane formulas to summon and bind a felhunter safely. The manuscript was written by the first mortal cabal of warlocks to break one without outside aid. Its pages explain the geomancy, materials, and binding runes needed to withstand the creature’s hunger. The copy was lost long ago. Strahad and his circle no longer have the masterwork. Strahad cannot provide the text, so he sends Alliance warlocks across the Great Sea to the Hall of Explorers in Ironforge. Krom Stoutarm, an itinerant dwarven warlock, resides there. In his twilight years, he combs through ancient manuscripts and library records. If any trace of the lost grimoire remains recorded in the Eastern Kingdoms, it lies in Krom’s meticulous catalogs.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1758-a2737607c0ba5144005b/1-0000.mp3", duration = 92.6563265, start = 0},
  },
}
P.transport["quest:177"] = {
  hash = "8dbc7a",
  fullHash = "8dbc7a",
  text = "Look To The Stars. In Darkshire, Viktori Prism'Antras needs Blind Mary's looking glass for his telescope. An Insane Ghoul carried it to Tranquil Gardens Cemetery in southern Duskwood. Blind Mary once treasured an ornate looking glass. An incident took her sight and sanity and left her a weeping spirit. In despair, she threw the glass into the dirt behind her family barn. Now Viktori Prism'Antras, an astronomer in Darkshire, needs the mirror for his telescope. The looking glass was taken long before he began studying the heavens. An Insane Ghoul scavenged the looking glass from behind the ruined farmsteads. Restless hunger drove it south, carrying the mirror to Tranquil Gardens Cemetery. It haunts an abandoned chapel among overgrown tombstones. You face the flesh-eating horrors of the southern woods to reclaim Mary's lost treasure from its rotting claws.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_177-29cce39285760b4cee99/1-0000.mp3", duration = 55.0922449, start = 0},
  },
}
P.transport["quest:178"] = {
  hash = "4eb61e",
  fullHash = "4eb61e",
  text = "Theocritus' Retrieval. In Redridge, a strange voice reaches across the mountains through a Shadowhide Pendant. The speaker is Theocritus, High Mage of Tower of Azora, who has intercepted the gnolls' mystical network and urgently asks for the pendant to study. Travelers who fight the savage Shadowhide gnolls in the Redridge Mountains sometimes find a Shadowhide Pendant. Touch the enchanted trinket, and a calm, distant voice answers instead of barking or curses. The speaker is Theocritus, a human mage at Tower of Azora, across the border in Elwynn Forest. His message comes from long study of ways to break the dark sorceries that direct the gnoll packs.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_178-e5d4d22cc31aa16b6722/1-0000.mp3", duration = 43.8073469, start = 0},
  },
}
P.transport["quest:1782"] = {
  hash = "710b29",
  fullHash = "710b29",
  text = "Furen's Armor. In Stormwind, Furen Longbeard puts new armor to the test. An aspiring warrior gathers spider fangs, chimaera horns, and phlogiston for his trials. Furen then gives the fire-hardened mail to the warrior and promises to share what he learned with Alliance smiths. Furen Longbeard, a dwarven armorer in Stormwind, seeks stronger armor for the Alliance. He tests how well it withstands heat and crushing blows. For these trials, he asks an aspiring warrior to gather rare materials. The resulting mail succeeds, strengthening Furen's standing among Alliance armorers. Furen gives the finished fire-hardened mail to the warrior who gathered the materials. He is grateful for the help, and the experiments have deepened his knowledge of protective smithing. Now he plans to send his notes and findings to other Alliance smiths, so they can use the new methods.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1782-2bc8c4e23f9df88c5ca5/1-0000.mp3", duration = 58.2791837, start = 0},
  },
}
P.transport["quest:1791"] = {
  hash = "f00ffc",
  fullHash = "f00ffc",
  text = "The Windwatcher. Northward, warriors who master the berserker stance seek The Windwatcher. After the affray on Fray Island, klannoc macleod sends them to find a weapon worthy of their fury. You survived the affray on Fray Island and learned the berserker stance from klannoc macleod. Now he sends you across continents, far from the Barrens coast, to find a solitary craftsman who can forge an exceptional weapon. Bath'rah the Windwatcher lives beside the river that runs north past Tarren Mill. His camp lies among stone ruins in contested land between the Alterac Mountains and the blighted Western Plaguelands. The troll hermit crafts weapons and commands potent elemental shamanism. He waits for warriors set on forging a weapon of great power.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1791-8d9db070d5944a6f8fb1/1-0000.mp3", duration = 50.1028571, start = 0},
  },
}
P.transport["quest:1793"] = {
  hash = "6b0666",
  fullHash = "6b0666",
  text = "The Tome of Valor. In Stormwind and Ironforge, young Alliance paladins face a trial of courage and duty. Their mentors ask them to prove they can fight with skill and protect the innocent. Young paladins in Stormwind and Ironforge must face terrible danger without faltering. Their instructors test their resolve in the Cathedral of Light and the Hall of Mysteries. Dragons and demons may threaten those who cannot defend themselves. The paladins must stay beside them. A holy warrior needs bravery as much as a weapon and shield. The trial teaches paladins that strength means little without a firm vow to shelter the helpless. When danger threatens the Alliance, its defenders must hold their ground and protect those in their care.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1793-b11f83c842bd5b44acd6/1-0000.mp3", duration = 47.7779592, start = 0},
  },
}
P.transport["quest:1795"] = {
  hash = "1b5af1",
  fullHash = "1b5af1",
  text = "The Binding. Above Ratchet, warlocks face the rite that binds a felhunter to their will. Strahad Farsan uses the restored Tome of the Cabal to draw an aggressive demon from the Nether, then watches the warlock subdue it in combat. On Kalimdor’s bluffs above Ratchet, the goblin port, Strahad Farsan leads dangerous trials in demon summoning. A warlock first gathers the fragments and reagents needed to restore the ancient Tome of the Cabal. Then Strahad prepares the binding grounds. He lays an inner glyph of containment while his acolytes channel power through enchanted rods to complete the outer circle. Together, the circles isolate whatever emerges from the settlement below. The Tome of the Cabal holds the words that open a bridge into the Twisting Nether. Felhunters are ravenous demonic hounds that hunger for arcane power and feast on magical energy. No gentle enthrallment or persuasion can bind one. The warlock must violently subdue the summoned beast in combat and break its will before it recognizes its rightful master. Surviving the clash proves the summoner can wield the hound against enemy spellcasters.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1795-8841aa9ed4982c16537e/1-0000.mp3", duration = 77.035102, start = 0},
  },
}
P.transport["quest:1796"] = {
  hash = "b8c613",
  fullHash = "b8c613",
  text = "Components for the Enchanted Gold Bloodrobe. In Ratchet, Menara Voidrender seeks Robes of Arcana for a garment meant to bear powerful enchantments. Menara Voidrender asks warlocks who seek greater power to bring her a set of Robes of Arcana. She needs a garment strong enough to hold dark magic. A relic's strength depends on the skill, rarity, and effort invested in its materials. Ordinary rags would fail beneath deep enchantments, so the robe must be finely made and ready to receive them. Menara admires warlocks who weave the robe themselves, though ambition matters more to her than pride. You can sew the silk, commission a skilled artisan, or buy the robe at market. However you obtain it, the finished garment is ready to become a specialized tool of fel mastery.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1796-653fb6c5010d9f31ccd7/1-0000.mp3", duration = 50.6514286, start = 0},
  },
}
P.transport["quest:1798"] = {
  hash = "c32be9",
  fullHash = "c32be9",
  text = "Seeking Strahad. Warlocks seek Strahad Farsan in Ratchet, where he can teach them to summon felhunters. Beneath the goblin port, his knowledge opens a path to more dangerous demons. Gakin the Darkbinder sends you from Stormwind to learn how to summon a felhunter. He guides warlocks in the Slaughtered Lamb below the Mage Quarter, but the rites call for knowledge beyond his reach. So you cross the Great Sea to Kalimdor, where another warlock may know the way. Strahad Farsan lives in the arid hills above Ratchet, the goblin harbor. A human warlock and Gakin's peer in their secret cabal, he works from neutral territory. There, Alliance magistrates, church inquisitors, and Horde sentries are less likely to notice him. Warlocks come hoping to master demons that drain mana.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1798-3e5b0506ed5a1b96630a/1-0000.mp3", duration = 57.4955102, start = 0},
  },
}
P.transport["quest:180"] = {
  hash = "381aa7",
  fullHash = "381aa7",
  text = "Wanted: Lieutenant Fangore. In Lakeshire, a bounty calls for Lieutenant Fangore's death. Magistrate Solomon seeks hunters to stop the Shadowhide gnolls pressing into the Redridge Mountains. Fangore serves the renegade sorcerer Morganth, and his death would strike at Morganth's forces. Lakeshire faces growing danger. Stormwind's army is stretched thin, and King Varian Wrynn is mysteriously absent. Highlord Bolvar Fordragon has left frontier settlements like Redridge to defend themselves.\n\nThe Shadowhide clan raids trade routes, burns farmsteads, and presses against the town's perimeter. Magistrate Solomon posts bounties to draw mercenary blades where royal soldiers will not march. Lieutenant Fangore leads the Shadowhide gnolls as Morganth's enforcer. Morganth is a rogue dark wizard hiding in the Redridge hills. Under Fangore, the gnolls strike together instead of scattering like scavengers.\n\nTheir attacks threaten to sever Lakeshire from Elwynn Forest. Fangore's severed paw would give Magistrate Solomon proof that Morganth's brute vanguard has been broken.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_180-2b307cf37242eeb1bdb8/1-0000.mp3", duration = 72.2808163, start = 0},
  },
}
P.transport["quest:1801"] = {
  hash = "89ae21",
  fullHash = "89ae21",
  text = "Tome of the Cabal. In the Barrens, Strahad Farsan sends Horde warlocks east to seek a lost grimoire. Its rites teach how to summon and bind a felhunter, and the search leads first to cartographer Jorah Annison in the Undercity. Strahad Farsan warns that summoning a felhunter takes more than ordinary fel magic. These predators feed on magical energies and resist common summoning circles. An initiate needs special circles and an ancient grimoire called the Tome of the Cabal. The first warlocks to bind a felhunter without outside aid wrote it. Its rites and seals show how to enslave the dangerous demon. No copies of the Tome of the Cabal remain among warlocks in Kalimdor. So Strahad sends his student across the sea to Jorah Annison in the Undercity. Annison is a royal cartographer who maps Lordaeron, yet he knows much about ancient and obscure texts. He admits that mapmaking wears on him. His true hunger is for rare histories, occult narratives, and treatises on dark magic.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1801-041c8caad91cebcad72f/1-0000.mp3", duration = 80.1697959, start = 0},
  },
}
P.transport["quest:1802"] = {
  hash = "24b90b",
  fullHash = "24b90b",
  text = "Tome of the Cabal. From Ironforge, your search for the Tome of the Cabal leads to a lost manuscript and a sunken ship. Its scattered pages hold rites for binding a felhunter. Only one copy of the Tome of the Cabal was ever written. Violence tore it apart and defaced its pages, sending the remnants to distant corners of the world. A tattered manuscript crossed the sea to Kalimdor, where centaur clans took it. The other half sailed from Lordaeron toward Khaz Modan, but the vessel sank before reaching port. Two dangers guard the missing pages. Those lost at sea washed ashore on the Hillsbrad coast, west of Southshore. Shoreline murlocs near Azurelode Mine took the waterlogged relics and wreckage. The dry half rests in an ancient chest deep in the centaur caverns of Splithoof Hold in Thousand Needles. Once the pieces are together, Krom Stoutarm can inspect the lost text before it returns to Strahad Farsan.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1802-b4de4d2ab82e70587361/1-0000.mp3", duration = 67.84, start = 0},
  },
}
P.transport["quest:1803"] = {
  hash = "b59da3",
  fullHash = "b59da3",
  text = "Tome of the Cabal. In the Undercity, Horde warlocks seek the Tome of the Cabal's scattered halves for Jorah Annison. Once kept in Lordaeron, the grimoire was torn apart, and its remnants lie along the hostile waters of the Eastern Kingdoms and deep in Kalimdor's centaur lands. The Tome of the Cabal once rested in Lordaeron's library. Someone defaced the sinister grimoire, tore away nearly half its pages, and split it in two. The surviving bound text was sent to the dwarven halls of Ironforge. But its transport wrecked along the rocky coast west of Southshore, and the pages now rot in the shallows beneath scavenging murlocs.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1803-fcaae7e143ba159792a8/1-0000.mp3", duration = 46.5502041, start = 0},
  },
}
P.transport["quest:1804"] = {
  hash = "be03d7",
  fullHash = "be03d7",
  text = "Tome of the Cabal. In the Barrens, Strahad Farsan awaits the tome and rods needed to bind a felhunter. The warlock brings them so his circle can prepare the rite. Krom Stoutarm binds the Tome of the Cabal's tattered remnants in Ironforge's Hall of Explorers. The dwarf scholar parts with the rare work reluctantly, after securing a promise of a copy. He also gives the warlock a fresh missive from Strahad Farsan. The tome holds rites for breaching the Nether, but parchment alone cannot conduct them. Strahad's acolytes need implements to focus the energies used to bind a felhunter. Krom sends the warlock to the Wetlands, where Dragonmaw spellcasters carry rods of channeling. The hostile orcs guard the rods. Taken from them, the rods give Strahad's circle a conduit to control the rift and steady the summoned energies.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1804-4661558925d780a2199c/1-0000.mp3", duration = 51.1477551, start = 0},
  },
}
P.transport["quest:1805"] = {
  hash = "122b26",
  fullHash = "122b26",
  text = "Tome of the Cabal. Strahad Farsan's work with the Tome of the Cabal now reaches into hostile territory. After helping Jorah Annison restore the tome, you must claim three Rods of Channeling and bring them to Strahad in Ratchet. In the Undercity, Jorah Annison studies the recovered fragments of the Tome of the Cabal. The Forsaken scholar pieces together its eldritch passages and welcomes the rare knowledge they hold. Then Jorah brings an urgent word from Strahad Farsan. Knowledge alone cannot bind a felhunter; a warlock needs precise instruments to focus demonic power into a binding circle. Strahad needs three Rods of Channeling carried by renegade orcs of the Dragonmaw clan. They dwell among the ruins of Angerfang Encampment in the Wetlands, far from Horde lands. You must enter contested territory and face clan remnants who hate the modern Horde as much as they butcher Alliance explorers.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1805-c1b02c416d7902f9d3a8/1-0000.mp3", duration = 55.4579592, start = 0},
  },
}
P.transport["quest:1806"] = {
  hash = "5c690b",
  fullHash = "5c690b",
  text = "The Test of Righteousness. At Jordan Stilwell’s forge outside Ironforge, you bring the materials for a paladin’s warhammer. Gathered across the Eastern Kingdoms and Kalimdor, they help turn an apprentice into a recognized champion of the Light. Jordan Stilwell works at his forge outside Ironforge’s gates. He envies paladins who wander the land, yet takes pride in serving their cause. You bring him rare materials gathered from shadowy crypts, sunken ruins, and dangerous mines. With them, the master smith keeps his promise and forges a weapon worthy of a true defender. Jordan Stilwell names the finished warhammer Verigan's Fist, for Bosch Verigan, an honored dwarven paladin and his dear friend. On behalf of himself and his wife, he places the sacred weapon in a young champion's hands. Through it, his fallen friend's memory and valor endure against the darkness threatening Azeroth.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1806-40b328ac174676794977/1-0000.mp3", duration = 70.3738776, start = 0},
  },
}
P.transport["quest:181"] = {
  hash = "d17d88",
  fullHash = "d17d88",
  text = "Look To The Stars. In Darkshire, Viktori Prism'Antras seeks the last piece for his telescope. Its frame is ready, but no local glass is large enough for the lens his plans require. Viktori Prism'Antras is building a telescope in Darkshire from plans by Cog Glitzspinner, a gnome engineer. He has gathered brass tubes and sturdy mountings from local supplies. But the design calls for an unusually large focusing lens. Magnifying glasses and optical parts from Stormwind traders are too small, so Viktori searches beyond ordinary materials for the piece he needs.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_181-ccc295b0c90b59fa3c3c/1-0000.mp3", duration = 34.9257143, start = 0},
  },
}
P.transport["quest:1824"] = {
  hash = "c2d243",
  fullHash = "c2d243",
  text = "Trial at the Field of Giants. At Camp Taurajo, Ruga Ragetotem sends warrior aspirants south to face an unfamiliar foe. They have half an hour to slay silithid in the Field of Giants and return with several twitching antennae. Ruga Ragetotem tests growing warriors at Camp Taurajo against an unfamiliar foe. Horde warrior trainers demand more than skill in battle: aspirants must slay the creatures and bring fresh antennae back within half an hour. The run across the southern Barrens tests their speed and resolve. The antennae must still twitch when they reach Taurajo. Silithid hives rise in the Field of Giants beneath massive fossilized ribcages. These strange, crawling insects arrived in the Barrens recently, disturbing tauren hunters and shamans who watch the savannas. Ruga says their presence bodes ill for Kalimdor. The trial tests a young warrior's instincts in battle and gathers intelligence on a growing threat to the land.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1824-cc8221de6abaaabf0924/1-0000.mp3", duration = 61.9363265, start = 0},
  },
}
P.transport["quest:1825"] = {
  hash = "22166c",
  fullHash = "22166c",
  text = "Speak with Thun'grim. After the Trial at the Field of Giants, Thun'grim Firegaze calls warriors to his camp in the Barrens. The orc smith offers custom armor to those who have proved their valor, and sends them to gather materials for Brutal Armor. Word of the warriors’ trial reaches Thun'grim Firegaze after they prove their endurance and fighting skill to Ruga Ragetotem. His camp stands on a ridge east of the Crossroads. Thun'grim wants to forge them an exceptional suit of battle mail. Thun'grim Firegaze reserves his forge for warriors who meet his high standard. He expects steel to match the spirit of the one who bears it. Reaching his camp means a warrior has moved beyond basic militia drills and can take on the hard work of gathering rare materials across Kalimdor.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1825-829be418dd35d09e8cff/1-0000.mp3", duration = 47.4644898, start = 0},
  },
}
P.transport["quest:1838"] = {
  hash = "3279b9",
  fullHash = "3279b9",
  text = "Brutal Armor. In the northern Barrens, a warrior faces Thun'grim Firegaze's test. The near-blind smith sends seasoned Horde warriors across distant lands for rare ingredients and smelting agents. Bring him what his scroll calls for, and he can begin forging a full set of brutal battle gear. In the northern Barrens, Thun'grim Firegaze listens for news of war. The veteran orc smith's eyesight is failing, yet no hand at the forge is more skilled. Rumors tell him of a warrior whose strength and valor surpass those of ordinary soldiers. So Thun'grim sets out to forge mail fit for the fiercest battles across Kalimdor and the Eastern Kingdoms. Thun'grim's armor requires more than common ore. By firelight, his failing eyes guide him as he writes a precise scroll for the core chestpiece. It calls for refined iron, smoky iron ingots carried by burrowing kobolds, powdered azurite worked by miners across the sea, and a volatile vial of phlogiston. Only a warrior ready for trials across distant lands can gather all the required materials.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1838-c258119bd6014aac954f/1-0000.mp3", duration = 68.4146939, start = 0},
  },
}
P.transport["quest:1839"] = {
  hash = "8b0817",
  fullHash = "8b0817",
  text = "Ula'elek and the Brutal Gauntlets. In Sen'jin Village, Ula'elek waits to forge the Brutal Gauntlets for you. Thun'grim Firegaze sends you from the Barrens to Durotar's southern coast. Thun'grim Firegaze sends you east after you prove your valor in the Barrens and begin assembling the Brutal Armor set. The veteran orc smith trusts skilled artisans across Horde lands to forge its pieces. For the heavy mail gauntlets, he sends you to Durotar's rocky southern shore. In Sen'jin Village, troll armorsmith Ula'elek works among his Darkspear kin. Thun'grim has told him of your deeds, and Ula'elek says the spirits have watched your triumphs in battle. For a warrior seeking a place among the Horde's elite, fine craft goes hand in hand with spiritual recognition.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1839-a216ebf1ddd00e230ad8/1-0000.mp3", duration = 49.5804082, start = 0},
  },
}
P.transport["quest:1840"] = {
  hash = "06784e",
  fullHash = "06784e",
  text = "Orm Stonehoof and the Brutal Helm. In Thunder Bluff, Orm Stonehoof can forge the Brutal Helm. Thun'grim Firegaze sends warriors to him for the work. Warriors who prove their mettle and gather pieces of the Brutal Armor in the Barrens are sent to Thunder Bluff. Thun'grim Firegaze is a skilled armorsmith, but the work has grown beyond his craft. So he directs the warriors to Orm Stonehoof, whose skill is known across Kalimdor. Orm can shape sturdy helms from rare trophies taken from savage beasts. Orm Stonehoof lives and works on Mulgore's high bluffs, near the pool below Thunder Bluff's great central totem. When a warrior comes with Thun'grim Firegaze's word, Orm sets aside his usual work. He speaks with them about the demanding parts needed to forge a helm fit for the Horde's front lines.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1840-80edbf214ac19982cbb6/1-0000.mp3", duration = 52.244898, start = 0},
  },
}
P.transport["quest:1841"] = {
  hash = "dee499",
  fullHash = "dee499",
  text = "Velora Nitely and the Brutal Legguards. Across the Great Sea, Thun'grim Firegaze sends Horde warriors to seek Velora Nitely and the Brutal Legguards. In the Undercity, the Forsaken smith uses the craft she kept from her mortal life to forge the armor. Her work helps complete a durable suit for the Horde's warriors. Thun'grim Firegaze sends you east across the Great Sea to find a smith for the Brutal Legguards. You've proved your mettle to the veteran smith during his vigil in the Barrens, and now he points you toward the fabled Brutal Armor. Thun'grim cannot make the whole suit alone, so he depends on skilled allies across the Horde. The greaves call for an artisan whose work was revered before northern humanity fell, in the Forsaken's underground kingdom. Velora Nitely works in the Undercity's Trade Quarter, where her old craft still serves the Horde. Before the Scourging of the north ended her mortal life, she was one of the Kingdom of Lordaeron's foremost armorsmiths. Her homeland was corrupted, and she became one of the Forsaken. Death did not take her mastery of metal. Now she turns her human skill toward the Horde's warriors, with a dry, macabre wit about being undead.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1841-13ed5e8f717e656a78b2/1-0000.mp3", duration = 83.7746939, start = 0},
  },
}
P.transport["quest:1842"] = {
  hash = "cc54cb",
  fullHash = "cc54cb",
  text = "Satyr Hooves. In Sen'jin Village, Ula'elek sends warriors north to Ashenvale for Satyr Hooves. He needs their strange power to forge brutal gauntlets. Ula'elek sends you into Ashenvale's ancient woods to gather what his craft requires. Demonic corruption still clings to the satyr covens there. For armor meant to rival Kalimdor's fiercest forces, he needs more than iron and leather. In northeastern Ashenvale, satyrs feed on the forest's lingering purity and twist it into foul power. Those that take in the most grow swollen hooves without the usual cloven split. Ula'elek plans to draw out that concentrated magic and weave it into his gauntlets.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1842-f35002c1d5e34bbb5a88/1-0000.mp3", duration = 42.9191837, start = 0},
  },
}
P.transport["quest:1843"] = {
  hash = "c944ac",
  fullHash = "c944ac",
  text = "Brutal Gauntlets. In Durotar, Ula'elek has finished Brutal Gauntlets for a seasoned Horde warrior. Rare materials from distant lands went into the work, meant to honor both maker and bearer. In Durotar, Ula'elek brings his lineage and skill to armor for a seasoned frontline warrior. He shapes brutal gauntlets from hardened trophies taken from dangerous foes. The finished armor can withstand fierce blows and strengthen the wearer's attacks. Among orcs and trolls, fine arms and armor carry the forge's prestige and the maker's spirit into battle. When Ula'elek presents the finished gauntlets, he entrusts a warrior with his ancestors' legacy. He expects a champion who wears them to answer that craft with courage, martial discipline, and strength.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1843-8c5226006835a7fcc0cb/1-0000.mp3", duration = 52.2710204, start = 0},
  },
}
P.transport["quest:1844"] = {
  hash = "d1e7c9",
  fullHash = "d1e7c9",
  text = "Chimaeric Horn. In the Charred Vale, a suffering chimaera matriarch tests a Horde warrior’s strength and mercy. Orm Stonehoof needs her horn for the Brutal Helm, and the hunt will prove the warrior’s resolve. Orm Stonehoof will forge the Brutal Helm for Horde warriors, but custom asks for proof before he begins. Metal and coin are not enough. A warrior must show martial skill and face the scars left by devastating conflict. The Charred Vale lies in the southwestern Stonetalon Mountains, buried in ash. Once lush and green, the valley was burned into a smoking wasteland. Beasts still roam its soot-covered craters, twisted by pain and fury. Mighty chimaeras nest among dead trees and searing steam vents. To the tauren smith, the chimaera matriarch’s horn is needed for the helm and proves a warrior’s strength. Yet the hunt also ends her torment. By felling the matriarch, the warrior brings mercy to a wild spirit driven mad by the destruction of her home.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1844-1ddfe58a946ea5797b47/1-0000.mp3", duration = 67.2130612, start = 0},
  },
}
P.transport["quest:1845"] = {
  hash = "3d08a3",
  fullHash = "3d08a3",
  text = "Brutal Helm. In Thunder Bluff, Orm Stonehoof brings the warrior’s trial to its end with Brutal Helm. After gathering rare beast trophies across Kalimdor, an aspiring warrior earns recognition with a horned helm that honors their strength. Orm Stonehoof is a stern smith in Thunder Bluff who guides Horde warriors through hard rites of passage. The trials test their skill in battle. Initiates hunt dangerous creatures in treacherous lands and claim rare trophies. Only those who meet Orm’s high standards may come before him to complete their armor. The warrior proves their resolve in the wild by bringing Orm Stonehoof a rare chimaeric horn. In return, Orm presents Brutal Helm, heavy mail crafted to honor the beast and strengthen its wearer in the front line. As he gives the helm, Orm calls on the Earthmother’s blessing. He looks to the greater deeds the warrior is bound to undertake across Azeroth.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1845-7f7fa255fcb76b99b098/1-0000.mp3", duration = 60.1077551, start = 0},
  },
}
P.transport["quest:1846"] = {
  hash = "0e39c2",
  fullHash = "0e39c2",
  text = "Dragonmaw Shinbones. Velora Nitely sends Horde warriors from the Undercity into the southern Wetlands for Dragonmaw Shinbones. The thick bones will brace Brutal Legguards against the blows a seasoned warrior faces. Velora Nitely, a Forsaken armorer in the Undercity, needs a sturdy brace for Brutal Legguards. She sends Horde warriors to the Wetlands to gather thick bone from the Dragonmaw orcs. Their dense frames can bear the heavy blows that seasoned warriors face. Velora needs bones that can hold firm. Each must pass a hand test; any that snap are too brittle for the forge. So warriors scour renegade camps along the Wetlands' crags, breaking weak specimens until eight sturdy shinbones remain.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1846-372f66d04a8f26209c76/1-0000.mp3", duration = 48.4832653, start = 0},
  },
}
P.transport["quest:1848"] = {
  hash = "4f33cb",
  fullHash = "4f33cb",
  text = "Brutal Hauberk. Across the Barrens, Horde warriors face a trial before Thun'grim Firegaze will forge their mail. They gather rare materials and face dangerous foes across the lands, then bring their bounty to the reclusive smith. He hammers it into armor built for battle. In the northern Barrens, Thun'grim Firegaze, an orc, forges armor only for warriors who meet his demands. The reclusive smith sends them far and wide to gather tough beast parts, rare metal, and alchemical reagents before he lights his bellows. The finished hauberk protects its wearer and marks the endurance and grit they have shown. Veteran fighters throughout the Horde recognize that hard-won proof. Thun'grim makes his demands punishing by design. Horde arms and armor are expected to carry the sweat and blood of their wearer from the moment they are made. When you hand over the finished Brutal Hauberk, the smith offers no praise. He expects you to prove the armor in brutal combat and return with stories of blood and honor.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1848-611152a9c5b19b773e50/1-0000.mp3", duration = 65.3322449, start = 0},
  },
}
P.transport["quest:185"] = {
  hash = "53487d",
  fullHash = "53487d",
  text = "Tiger Mastery. At Nesingwary's Expedition, Ajeck Rouack trains hunters to track big cats. She begins with young tigers near the northern camp, testing a newcomer's hunting and tracking skills. Ajeck Rouack learned to hunt tigers from her father when she was a girl. Now she shares his craft with travelers who reach Nesingwary's Expedition after Welcome to the Jungle. Young tigers are the first quarry. Tracking and hunting them prepare you to pursue greater prey. Young Stranglethorn tigers prowl the jungle near the expedition camp. Ajeck Rouack asks you to hunt ten. She wants proof of your skill before she offers further training.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_185-006868dcb091e60e94b8/1-0000.mp3", duration = 39.7844898, start = 0},
  },
}
P.transport["quest:19"] = {
  hash = "3c137c",
  fullHash = "3c137c",
  text = "Tharil'zun. Near Stonewatch Keep, Marshal Marris targets Tharil'zun, whose outrunners harass the roads. His death is a critical step in breaking the Blackrock clan's hold over northern Redridge, and his severed head brought to Lakeshire marks a hard-fought victory for its watch. The road between Lakeshire and Stonewatch Keep has become perilous with sudden ambushes. Blackrock outrunners and renegades prowl the rocky ridges, cutting off scouts and threatening reinforcements bound for the fortress. Marshal Marris names Tharil'zun as the commander directing these strikes. He says Tharil'zun must be eliminated, or Lakeshire may be hemmed in entirely. Tharil'zun is a dangerous battlefield leader, vicious and crafty, who unites scattered orc raiders into an effective force. Reaching him in Stonewatch's shadow means cutting through entrenched Blackrock outposts. His death breaks the outrunner patrols' cohesion and clears a path for the Alliance to face the garrison inside the keep.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_19-43c4f9208606ca7b5592/1-0000.mp3", duration = 69.5902041, start = 0},
  },
}
P.transport["quest:190"] = {
  hash = "c1ece5",
  fullHash = "c1ece5",
  text = "Panther Mastery. At Nesingwary's Expedition, Sir S. J. Erlgadin tests those who seek a place in Hemet's hunt. They must bring down ten young panthers to prove their skill at tracking. Hemet Nesingwary has gathered seasoned big-game hunters in northern Stranglethorn Vale. Sir S. J. Erlgadin asks newcomers to prove they can hunt panthers before they join the party. Before trusting newcomers with larger game, Erlgadin sets them a test. They must find and slay ten young panthers. Finding the prowlers is only half the challenge.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_190-0a54b97f2812eccb36c2/1-0000.mp3", duration = 34.8473469, start = 0},
  },
}
P.transport["quest:1938"] = {
  hash = "9bcfcb",
  fullHash = "9bcfcb",
  text = "Ur's Treatise on Shadow Magic. High Sorcerer Andromath seeks Ur's Treatise on Shadow Magic in Stormwind. Morganth stole the forbidden tome and carried it to the Tower of Ilgalar in the Redridge Mountains. Three promising mages studied together in Stormwind's Wizard's Sanctum. Morganth turned to dark arts and shadow magic despite their desperate warnings. The city's magical order banished him. Before he left, he stole a dangerous work by Ur, an infamous archmage whose studies reached beyond orthodox arcana. Morganth seized the Tower of Ilgalar in the heights of the Redridge Mountains, beyond Stormwind's scrutiny. High Sorcerer Andromath fears the tome's knowledge in the hands of an outcast practicing forbidden sorcery. So he sends Alliance adventurers into the tower to recover it before its wards fall.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1938-b9e570b15bcbbb4bd880/1-0000.mp3", duration = 59.4546939, start = 0},
  },
}
P.transport["quest:1939"] = {
  hash = "622624",
  fullHash = "622624",
  text = "High Sorcerer Andromath. At Stormwind’s Wizard’s Sanctum, promising Alliance mages are summoned to the tower’s summit. Andromath works among the kingdom’s foremost archmages beyond ruined Dalaran. Jennea Cannon, the apprentice coordinator in Stormwind’s Mage Quarter, sends promising casters to the summit of the Wizard’s Sanctum. High Sorcerer Andromath, one of the southern kingdoms’ most senior active practitioners of the arcane, has asked to meet magi ready for greater responsibilities. Dalaran’s magocracy was ruined in the Third War, and its surviving wizards are busy rebuilding. Without easy access to the Violet Citadel’s libraries, the Alliance relies on senior archmages in Stormwind to study ancient threats and guide research into shadowy, forbidden arts.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1939-3daf91554a446cb69cdf/1-0000.mp3", duration = 55.4057143, start = 0},
  },
}
P.transport["quest:1940"] = {
  hash = "615965",
  fullHash = "615965",
  text = "Pristine Spider Silk. In Stormwind, High Sorcerer Andromath sends rising Alliance mages to Duskwood for pristine spider silk. They carry eight samples to Wynne Larson in the Mage Quarter, where she weaves an adept’s robe. High Sorcerer Andromath marks a mage’s passage beyond apprenticeship with vestments fit for an adept. In the Wizard’s Sanctum, a mage’s skill is seen in the robes they wear. So each mage must gather pristine silk from dangerous spiders and show both field skill and discernment. Carrion recluse spiders haunt Duskwood’s gloomy woods, and ordinary stalls do not sell their silk. You gather eight fine samples and carry them across Stormwind to Larson Clothiers in the Mage Quarter. There, Wynne Larson weaves the delicate threads into a robe with arcane significance.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1940-890637288ea9bf14fde2/1-0000.mp3", duration = 54.282449, start = 0},
  },
}
P.transport["quest:1942"] = {
  hash = "0d60c5",
  fullHash = "0d60c5",
  text = "Astral Knot Garment. In Stormwind City, Wynne Larson weaves pristine spider silk into a garment for dangerous journeys and high-society gatherings. An adventurer brings her rare silk from the wilds, and she shapes it into a magical weave. In Stormwind's Mage Quarter, tailors serve arcane elites and visiting nobles. Wynne Larson weaves pristine spider silk into garments both durable and enchanted. Her playful humor shows when she jokes about saving a few precious scraps for her own wardrobe before handing over her finished work. Spellcasters who wear cloth prize the Astral Knot Garment for its resilience and refinement. Its silk comes from dangerous spiders, and its weave is made to endure combat. It keeps the polished look expected at formal banquets in Stormwind Keep.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1942-78760ea8ab7239d21ad9/1-0000.mp3", duration = 52.6367347, start = 0},
  },
}
P.transport["quest:1943"] = {
  hash = "ac962f",
  fullHash = "ac962f",
  text = "Speak with Deino. In Orgrimmar, Deino calls promising Horde mages to aid their craft. The troll mage works from the Valley of Spirits and seeks an adept for important work. Her summons opens a path to deeper study and duties across Kalimdor. Horde mages sharpen their arcane skill under their instructors’ care. When a student is ready for harder work, a mentor such as Anastasia Hartwell in the Undercity points the way to Orgrimmar. There, in the troll quarter, specialized knowledge and dangerous work await. Deino lives in Darkbriar Lodge, in Orgrimmar’s Valley of Spirits. Few Darkspear study arcane magic beside the many witch doctors and priests, making Deino an authority in the capital. Her work reaches Horde mages beyond local concerns. She seeks ambitious spellcasters willing to face dangers far from home.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1943-9a42fdc9cbdaa193ec33/1-0000.mp3", duration = 55.7191837, start = 0},
  },
}
P.transport["quest:1944"] = {
  hash = "0dbe6b",
  fullHash = "0dbe6b",
  text = "Waters of Xavian. In Ashenvale, Deino seeks water from Xavian to study the city's lingering arcane power. She sends her apprentice to draw a sample from the pool beneath its highest waterfall. Deino, a troll mage in Orgrimmar's Valley of Spirits, searches Kalimdor for primal arcane traces. Now she has turned her attention to Xavian, an ancient night elf city beneath Ashenvale's eastern canopy. Scholars say the city held great magical knowledge before the Sundering. They believe its waters still hold arcane power that modern mages hope to understand. Xavian lies in ruins, overrun by feral, corrupt satyrs who defend their ground from outsiders. To reach the water, you pass Satyrnaar and cross dangerous waterways, steering clear of prowling beasts and demonic sentinels. Deino needs a sample from the pool at the base of the city's highest waterfall.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1944-4c3f670f6d19d1aa44d2/1-0000.mp3", duration = 63.4514286, start = 0},
  },
}
P.transport["quest:1945"] = {
  hash = "4de469",
  fullHash = "4de469",
  text = "Laughing Sisters. In Ashenvale, dryad hair is sought for an empowered robe. At the Crossroads, the experienced troll tailor Kil'hala needs the enchanted locks to weave a mage robe as Horde mages press against the woodland's native defenders. After you secure water from Xavian, Deino in Orgrimmar sends rising mages to craft their own enchanted vestments. These arcane garments need materials touched by raw magic. Dryad locks carry the forest's ancient vitality, giving mages what they need to weave intricate robes that shield and strengthen a caster. Near Raynewood Retreat in Ashenvale, mages seek the laughing sisters. These nimble dryads ally with the night elves and fiercely guard their groves from woodsmen and outsiders. They will not willingly give their hair to Horde spellcasters. So the locks are taken by force beneath the ancient trees. The locks travel south across the border to the dusty settlement of the Crossroads in the Barrens. There, troll tailor Kil'hala receives them without remorse. Kil'hala acknowledges the woodland creatures' loss with a touch of irony, then puts the enchanted strands to use. Horde power demands resolve.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1945-f1885f1a1a60e8e061f6/1-0000.mp3", duration = 78.8636735, start = 0},
  },
}
P.transport["quest:1946"] = {
  hash = "b9f787",
  fullHash = "b9f787",
  text = "Nether-lace Garment. At the Crossroads, Kil'hala weaves dryad hair into enchanted cloth for spellcasters. This garment completes his specialized work in the Barrens. At the Crossroads in the Barrens, Kil'hala weaves nether-lace from the locks of laughing sisters. The dryads live in Ashenvale, where their hair is gathered for his craft. He binds the woodland enchantment carried in those rare, resonant locks into cloth that is comfortable and durable. Kil'hala seeks more than fine work from his trade. He hopes to win favor with Deino, a respected troll mage in Orgrimmar's Valley of Spirits. By making exceptional garb for aspiring practitioners, he hopes to earn and keep Deino's good graces.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1946-2da0d8932dfa9afa1795/1-0000.mp3", duration = 43.7289796, start = 0},
  },
}
P.transport["quest:1950"] = {
  hash = "197c57",
  fullHash = "197c57",
  text = "Get the Scoop. Near the Mirage Raceway, Magus Tirth has forgotten the words to open his sealed strongbox. His apprentice, Johnson, is missing somewhere around the track, and Tirth needs the spellbook inside. Magus Tirth lives on the cracked salt bed of the Shimmering Flats in Thousand Needles. He is an eccentric spellcaster whose arcane knowledge and books draw mages seeking to advance. Patience helps when dealing with him. Tirth relies on an assistant for everyday details, even the spoken passwords guarding his arcane stores. Now a book of power is locked away, and the magic words have slipped from his mind entirely.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1950-eebac4c65ddb2990cbe0/1-0000.mp3", duration = 38.0865306, start = 0},
  },
}
P.transport["quest:1999"] = {
  hash = "3911c0",
  fullHash = "3911c0",
  text = "Tools of the Trade. In the Undercity, Horde rogues are sent to steal a report from Ambermill. Lord Varimathras orders them to obtain lockpicking tools and learn Dalaran’s condition from Kirin Tor intelligence. A prisoner’s interrogation leads the Deathstalkers to intelligence hidden in Ambermill. Silverpine Forest remains a precarious front line, and human mages guard the village’s communications fiercely. Lord Varimathras orders Mennet Carkad, a Deathstalker handler, to guide promising operatives past the Kirin Tor sentries and recover the Dalaran Status Report. Infiltration and lockpicking test skills beyond assassination. Before entering Kirin Tor territory, operatives collect specialized thieves’ tools from Estelle Gendry. Opening the secured chest in Ambermill shows an operative can move beyond street brutality and serve the Forsaken as an espionage asset.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1999-fbab43701e6a626b39d4/1-0000.mp3", duration = 64.2089796, start = 0},
  },
}
P.transport["quest:2"] = {
  hash = "a2169f",
  fullHash = "a2169f",
  text = "Sharptalon's Claw. In Ashenvale, Sharptalon's attacks put Horde supply lines at risk. Bring its claw to Senani Thunderheart at Splintertree Post as proof that the predator has fallen. Sharptalon hunts the paths to Splintertree Post while the Horde seeks resources in Ashenvale. The aggressive hippogryph strikes peons and couriers traveling between forward logging camps and the outpost. Its attacks hinder Horde work in the region. Night elven sentinels and dangerous wildlife threaten the newcomers as well. Senani Thunderheart, a tauren huntress, directs Horde hunters against Ashenvale's deadliest predators. Sharptalon's talon proves the hippogryph has fallen. Bring the trophy to Splintertree Post. The outpost's defenders honor the hunt, and frightened laborers can walk the woods with less fear.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2-c1a9e0e8168223704b05/1-0000.mp3", duration = 49.8677551, start = 0},
  },
}
P.transport["quest:20"] = {
  hash = "301d13",
  fullHash = "301d13",
  text = "Blackrock Menace. Redridge's Blackrock orcs press from the north and southeast, and Lakeshire is under siege. Marshal Marris asks you to thin their ranks and bring back their battleworn axes. Lakeshire faces threats from several sides, but the Blackrock orcs are the gravest danger. They came south from the fiery Burning Steppes and now roam Redridge's craggy passes. After taking strongholds, they have penned townspeople inside Lakeshire. Trade, foraging, and travel along the northern roads have all been cut off. Marshal Marris commands Lakeshire's beleaguered guard, but cannot spare soldiers to attack the orcs' positions. So he calls on you to strike their forward scouts and foot soldiers. Their crude, battleworn axes will prove they are dead. Marris hopes to thin the invaders near Stonewatch in the north and in the rugged pockets of southeastern Redridge.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_20-43f34fc51d07c1818964/1-0000.mp3", duration = 58.122449, start = 0},
  },
}
P.transport["quest:2040"] = {
  hash = "4ef13b",
  fullHash = "4ef13b",
  text = "Underground Assault. Shoni the Shilent sends Alliance adventurers into the Deadmines to seize a power core. The exiled gnomes need it to drive drills through the rock around Gnomeregan and reclaim their home. Gnomish tinkerers fled across Khaz Modan and Stormwind after primitive troggs brought Gnomeregan down. Shoni the Shilent is already planning how to break through the rock around their lost home. Her gyrodrillmatic excavationators need great power to bore through the underground stone. Human lands have no local power grids, so the gnomes have turned to heavy goblin machinery in the criminal underworld. In the Deadmines shafts in Westfall, Edwin VanCleef's Defias Brotherhood employs goblin engineers to build war machines. One machine is a working goblin shredder, a lumbering automaton. Shoni sends Alliance operatives to destroy or dismantle it and recover its specialized heart, the Gnoam Sprecklesprocket. The exiled gnomes need that goblin power supply to drive their drills through the underground rock and begin their counteroffensive to reclaim Gnomeregan.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2040-2e8fcb5c48e91c3979a1/1-0000.mp3", duration = 76.1208163, start = 0},
  },
}
P.transport["quest:2078"] = {
  hash = "66eca7",
  fullHash = "66eca7",
  text = "Gyromast's Revenge. Along Darkshore, Gelkak Gyromast seeks revenge on the murlocs who plundered his wrecked ship. He sends you to wind up his mechanical first mate, the Threshwackonator 4100. Gelkak Gyromast is stranded on Darkshore, but he will not yield to the murlocs along the shore. He has gathered the parts for his plan and seeks revenge on their tribe and its chief. Rather than wade into the surf with his cutlass, the eccentric captain turns to engineering. He gives you a winding key and asks you to tend to his mechanical subordinate.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2078-0c6f8c3d3b39f8eeb8ae/1-0000.mp3", duration = 33.3322449, start = 0},
  },
}
P.transport["quest:2098"] = {
  hash = "1805c3",
  fullHash = "1805c3",
  text = "Gyromast's Retrieval. Gelkak Gyromast needs your help on Darkshore's coast. His mechanical first mate cannot work without a winding key, shattered on the rocks. Wildlife and murlocs carried off its three pieces. On Darkshore, Gelkak Gyromast is a gnome pirate stranded far from the South Seas. He says aggressive threshadons attacked and sank his vessel just off the coast. The wreck cast him ashore among the flotsam, marooned and parted from his crew. Gelkak's first concern is his first mate, not provisions or gold. His companion needs a special key to operate, but the key broke into three pieces when Gelkak crashed on the rocky shoals. Reef crawlers on the beach, foreststriders near the woods, and Greymist murloc scavengers carried the shiny pieces away.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2098-10a501b337f2335fcd06/1-0000.mp3", duration = 48.5616327, start = 0},
  },
}
P.transport["quest:219"] = {
  hash = "b63c26",
  fullHash = "b63c26",
  text = "Missing In Action. Corporal Keeshan is missing in the Redridge Mountains after Blackrock orcs overran his regiment. They knocked him unconscious and carried him into a cave fortress. Now he needs an escort to Lakeshire, where the garrison awaits his return. Blackrock orcs come down from the northern peaks, making the Redridge Mountains more dangerous. Town guard patrols often meet ambushes, and Corporal Keeshan's regiment suffered the worst. Outnumbered and overwhelmed, most of its soldiers fell. Keeshan survived when a crushing blow knocked him unconscious before the orcs could execute him. They dragged him to their cave as a prisoner. Battered and concussed, Keeshan is held deep in enemy territory. He cannot make the trek down the mountain alone, so you escort him toward Lakeshire past the orc warbands on the ridgelines. Marshal Marris has been trying to learn what happened to the missing regiment. He is also preparing Lakeshire for further attacks, and Keeshan's safe return brings him sorely needed relief.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_219-3d74c7f867ace7cad96a/1-0000.mp3", duration = 69.877551, start = 0},
  },
}
P.transport["quest:220"] = {
  hash = "c8ac53",
  fullHash = "c8ac53",
  text = "Call of Water. The water Brine prepared now reaches Islen Waterseer on the eastern Barrens coast. There it begins the next part of the shamanic trial, and will form the base of a sapta that lets an initiate see water spirits in Silverpine Forest. After the trials in the southern Barrens, Brine gives you a Vial of Purest Water. It comes from pure springs and has been consecrated by Brine's rites. You carry it back to the eastern coast, where Islen Waterseer keeps watch. The water joins Brine's teachings to the rites of the totem. Islen explains that mortal eyes cannot easily see water spirits. To meet them, you drink a brew called a sapta. Brine's water forms the base of that draught and opens your senses to what ordinary sight cannot find. Seeing the spirits is only part of the journey. They will test you.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_220-332242b5fbd403c21ad5/1-0000.mp3", duration = 61.6228571, start = 0},
  },
}
P.transport["quest:221"] = {
  hash = "3e529c",
  fullHash = "3e529c",
  text = "Worgen in the Woods. Nightbane Dark Runners press toward Darkshire from the Rotting Orchard in Duskwood. Calor sends you to thin their ranks before the pack can surround the town. Calor's scouting has revealed a greater danger than the lone worgen first seen weaving shadowy magic at the forest's edge. Larger and swifter Nightbane Dark Runners have gathered in the Rotting Orchard, just southwest of Darkshire. They make up most of the pack and have made the orchard a staging ground within striking distance of the village gates.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_221-0812f5ee794162bb3f8a/1-0000.mp3", duration = 30.3020408, start = 0},
  },
}
P.transport["quest:222"] = {
  hash = "0bedb4",
  fullHash = "0bedb4",
  text = "Worgen in the Woods. Calor sends you into southern Duskwood against the Nightbane pack. Their dens and mines bring the worgen threat close to Darkshire. South of Darkshire, Nightbane worgen fortify caves and abandoned mine shafts as camps. Calor watches their bonfires and fears what their growing hold means for the town. Among the pack, the Vile Fangs and Tainted Ones are its fiercest breeds. Their savagery and stubbornness threaten Darkshire’s perimeter.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_222-836aa945240c6523ebb0/1-0000.mp3", duration = 28.7608163, start = 0},
  },
}
P.transport["quest:223"] = {
  hash = "59a6a3",
  fullHash = "59a6a3",
  text = "Worgen in the Woods. In Worgen in the Woods, Calor sends you to Darkshire with a letter for Jonathan Carevin. Your hunts against the worgen in Duskwood have earned his trust, and he believes your skill can aid Carevin. You drove the Nightbane pack from Roland's Doom and the shadowed glades, earning Calor's respect. He serves on the dark frontier of the woods and rarely offers praise or formal introductions. Now he gives you a faded scrap of parchment for Jonathan Carevin in Darkshire. Calor believes more fighters like you could help his small company outshine the town's beleaguered Night Watch. Jonathan Carevin works in Darkshire under heavy strain. Worgen, restless undead, demonic forces, and cultists who aid the corruption from within all threaten the town. Wary of outsiders and short on time, Carevin trusts Calor's recommendation. He sees you as a dependable fighter who can help preserve the Light against Duskwood's terrors.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_223-db45eb606f7a8f4ae2ce/1-0000.mp3", duration = 67.8138776, start = 0},
  },
}
P.transport["quest:226"] = {
  hash = "fc9b0d",
  fullHash = "fc9b0d",
  text = "Wolves at Our Heels. In western Duskwood, Lars faces hungry, rabid dire wolves. Hunting them gives him room to gather food while he and Sven Yorgen pursue their vendetta against the necromancer Morbent Fel. Sven Yorgen and Lars keep an isolated camp in Duskwood’s western hills, near the Westfall border. Far from Darkshire, they rely on hunting and foraging to survive. As Lars carries fresh game through the dark woods, ravenous predators prowl the riverbanks and underbrush. Starving, rabid dire wolves prowl north and east of the camp, toward the river. Killing the frenzied beasts makes Lars’s hunt safer. With less danger as they gather their daily food, Sven and Lars can focus on Morbent Fel, the necromancer farther east.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_226-d57988273ada5ac84c56/1-0000.mp3", duration = 47.6212245, start = 0},
  },
}
P.transport["quest:2282"] = {
  hash = "f97503",
  fullHash = "f97503",
  text = "Alther's Mill. Lucius sends Alliance rogues to test their skill at Alther's Mill. It lies northeast along the road from Lakeshire, where Blackrock orcs now draw near. Lucius sends you northeast from Lakeshire along the road to Alther's Mill, carrying your first set of thieves' tools. There, a locked chest puts your skill to the test. Open Lucius's personal lockbox and bring back the token inside to earn your Certificate of Thievery. Alther's Mill once served as a lumber outpost. Now Blackrock orcs press into Redridge and have drawn near, so Lucius makes their presence part of the trial. SI:7 expects its agents to pick locks unseen while moving through enemy-held ground.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2282-dca4f3276641d961901c/1-0000.mp3", duration = 40.8555102, start = 0},
  },
}
P.transport["quest:23"] = {
  hash = "6688b8",
  fullHash = "6688b8",
  text = "Ursangous's Paw. The Ashenvale Hunt has brought you Ursangous's Paw. Take it to Senani Thunderheart at Splintertree Post, and earn honor among the Horde's trackers. Trackers from Splintertree Post hunt the ancient beasts that rule Ashenvale's canopy. Ursangous is among the fiercest. He kills travelers and warriors who cross his path, so his paw proves the mighty beast has fallen to your hunt.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_23-58115c2f91feac5a78da/1-0000.mp3", duration = 27.0628571, start = 0},
  },
}
P.transport["quest:230"] = {
  hash = "3bcedb",
  fullHash = "3bcedb",
  text = "Sven's Camp. In Duskwood's western hills, Sven Yorgen still grieves for his slain family and seeks answers. A journal buried at his ruined farm may tell who saw the massacre. You find a small, dirt-stained book beneath freshly turned earth at the ruined Yorgen farm. Dark riders struck while Sven Yorgen was away, leaving his family dead and the farm in ruins. Grief and vengeance sent his allies to search the wreckage. Someone had hastily hidden the book there.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_230-6a55d4e6cc8854dd0cbd/1-0000.mp3", duration = 27.2979592, start = 0},
  },
}
P.transport["quest:235"] = {
  hash = "aa2d56",
  fullHash = "aa2d56",
  text = "The Ashenvale Hunt. Warcaller Gorlach sends the Horde north to Ashenvale, where its frontier presses into an ancient forest. You are to report to Senani Thunderheart at Splintertree Post and join the hunt. Orgrimmar needs timber, meat, and safe trade routes to keep growing. Warcaller Gorlach bears orders from the Horde's high command, sending seasoned wanderers and new adventurers to active campaigns. For those coming of age in Durotar and the Barrens, Ashenvale is the next test of skill and survival. North of the Barrens, the Horde holds two strongholds in Ashenvale. Splintertree Post lies in the eastern woods, while Zoram'gar Outpost stands on the western coast. Senani Thunderheart coordinates operations from Splintertree Post. She organizes trackers and hunters against the beasts beneath the canopy and the night elven sentinels who contest the Horde's claims.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_235-ec64ab1db57b943a2137/1-0000.mp3", duration = 68.884898, start = 0},
  },
}
P.transport["quest:2359"] = {
  hash = "c00da4",
  fullHash = "c00da4",
  text = "Klaven's Tower. From a camp in Westfall, Agent Kearnen watches Klaven's Tower. Strange shipments and altered guards point to danger within the Defias Brotherhood. At Westfall's southeastern edge, the river runs below Klaven's Tower, north of the Dagger Hills. The Defias Brotherhood holds the stone spire, though its human thieves and brigands are common across the plains. Agent Kearnen has watched the tower alone for weeks. Lately, she has seen strange things: a bizarre shipment came straight from Duskwood's shadowed woods, escorted by monstrous, deformed sentries unlike ordinary highwaymen.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2359-02afc1c8f74da4286314/1-0000.mp3", duration = 39.8889796, start = 0},
  },
}
P.transport["quest:24"] = {
  hash = "b6c1e1",
  fullHash = "b6c1e1",
  text = "Shadumbra's Head. At Splintertree Post, Shadumbra's Head proves a feared predator has fallen. Bringing it to Senani Thunderheart completes a trial of the Ashenvale Hunt and helps secure the western roads toward the Zoram Strand. Shadumbra hunted the woods west of Splintertree Post. Horde scouts and couriers used those paths to reach the Zoram Strand. Her speed and stealth made each journey perilous, and every westward patrol kept the post's defenders wary. Senani Thunderheart, a tauren huntress, challenges Horde champions to track and fell Ashenvale's great beasts. Shadumbra's head proves the hunter has slain one of Kalimdor's deadliest native stalkers. Now travelers can use the roads with less danger.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_24-abbc29ecb194ab7442f4/1-0000.mp3", duration = 48.2220408, start = 0},
  },
}
P.transport["quest:240"] = {
  hash = "1a8e60",
  fullHash = "1a8e60",
  text = "Return to Jitters. At Raven Hill, you bring Jitters a meal from Chef Grual. The cakes ease his hunger, though fear still holds him there. Chef Grual cooks at the Scarlet Raven Tavern in Darkshire. With little livestock or sea life in Duskwood, he makes use of what the blighted forest provides. His Dusky Crab Cakes contain no crab meat. Instead, gooey legs from venom web spiders make up his specialty. Grual calls it resourceful cooking, though delicate stomachs may disagree. At Raven Hill, Jitters cowers in fear, unable to face the horrors that drove him from the woods. Terror keeps him from hunting or foraging, and hunger only deepens his distress. The warm cakes bring him a rare moment of relief. Desperate for food, he eats without asking what kind of crab Grual used.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_240-4790b7783a4e3abe3e6b/1-0000.mp3", duration = 51.3306122, start = 0},
  },
}
P.transport["quest:245"] = {
  hash = "9d1c5e",
  fullHash = "9d1c5e",
  text = "Eight-Legged Menaces. In Duskwood, venom web spiders crowd the western border, and Watcher Dodds fears for the Night Watch. He asks travelers to thin their numbers before more guards fall into their webs. Pygmy venom web spiders swarm the brush beside the western road from Westfall into Duskwood. Beneath the dense canopy, their webs choke the thickets. Travelers and the Night Watch's already fragile defenses are in danger. Watcher Dodds keeps a small camp far from Darkshire, with too few troops to hold the border. Commander Althea Ebonlocke cannot send help while undead and worgen press against the township. Dodds has lost comrades to the spiders. He found them hanging upside down in the canopy, paralyzed by venom as it liquefied their flesh.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_245-29bfc1b98463d2269dd7/1-0000.mp3", duration = 47.0726531, start = 0},
  },
}
P.transport["quest:2458"] = {
  hash = "1a3ecd",
  fullHash = "1a3ecd",
  text = "Deep Cover. Shenthul sends a promising Horde rogue to Sludge Fen to meet an agent among the Venture Company. The Shattered Hand has spent a year placing Taskmaster Fizzule inside its drilling grounds, where he watches their plans. The Shattered Hand guards Orgrimmar’s interests with secret intelligence and assassination. For a year, its members worked to place an agent among the Venture Company. Taskmaster Fizzule won a place at their drilling outpost north of Sludge Fen, among the company’s mercenaries. Fizzule must keep his harsh reputation to satisfy the Venture Company’s overseers. An unexpected visitor could bring an attack. If you reach his tower, fire two flares from the signaling gun within sight, approach quietly, and give the Shattered Hand’s secret salute. Then Fizzule can share what he has learned about the company’s growing schemes.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2458-724e62eb8cfc11ce72ad/1-0000.mp3", duration = 59.5330612, start = 0},
  },
}
P.transport["quest:2460"] = {
  hash = "e4b79a",
  fullHash = "e4b79a",
  text = "The Shattered Salute. In Orgrimmar's Cleft of Shadow, Shenthul teaches newly inducted rogues a silent sign. The Shattered Hand uses it to recognize its agents safely in the field. The Shattered Hand works in secrecy as Thrall's Horde intelligence and assassination arm from Orgrimmar's Cleft of Shadow. On dangerous, secret assignments, its agents cannot use military signs. So Shenthul teaches newly inducted rogues the Shattered Salute, a silent gesture that lets allies recognize one another. For Shenthul's rogues, learning the salute is vital tradecraft, not ceremony. Agents sent into danger or to infiltrate rival factions need to verify contacts without alerting bystanders or targets. Before entrusting an agent with covert fieldwork, Shenthul expects them to recognize and mirror the gesture without hesitation.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2460-9c81177afb7fcc4ecdbc/1-0000.mp3", duration = 63.1118367, start = 0},
  },
}
P.transport["quest:247"] = {
  hash = "592c34",
  fullHash = "592c34",
  text = "The Hunt Completed. In Ashenvale, a Horde champion faces three legendary predators. Ursangous, Shadumbra, and Sharptalon test strength, tenacity, and a hunter's skill in the wild. Senani Thunderheart tests travelers among the Horde forces in Ashenvale. Her hunt tests loyalty to the warchief and asks whether a hunter understands survival in the wild. Three legendary predators are its quarry: Ursangous the bear, Shadumbra the cat, and Sharptalon the fierce hippogryph. A hunter must fell all three and secure their trophies to prove their blood runs true. For the tauren, hunting is sacred. It honors balance and respect, even in an active warfront. By overcoming Ashenvale's greatest terrors, a hunter honors the spirits of the land and earns Thunderheart's ancestral blessings. A formal commendation and token of favor mark the hunt's end, and the champion's reputation spreads through the forest.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_247-b554b1820141d0c9ce3d/1-0000.mp3", duration = 69.3812245, start = 0},
  },
}
P.transport["quest:2478"] = {
  hash = "35673d",
  fullHash = "35673d",
  text = "Mission: Possible But Not Probable. In the northern Barrens, Horde rogues infiltrate a Venture Company outpost to steal a potent brew for the Shattered Hand. Their work tests stealth, theft, and combat. North of the Sludge Fen oil rigs, the Venture Company keeps an isolated drilling tower. Taskmaster Fizzule, a Shattered Hand operative posing as a Venture Company supervisor, sends rogues to use underworld craft instead of attacking openly. He asks them to pick the key from Foreman Silixiz and keep it for him. Then they climb past workers and sentries changed by the tower’s experiments.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2478-34b87a7078b0053a16da/1-0000.mp3", duration = 44.2253061, start = 0},
  },
}
P.transport["quest:2479"] = {
  hash = "b2ad82",
  fullHash = "b2ad82",
  text = "Hinott's Assistance. In Orgrimmar, poisoned rogues seek help before Zanzil's mixture claims their lives. The toxin came from an infiltration in the Barrens. Serge Hinott in Tarren Mill can offer a cure and teach rogues to brew poisons. Your infiltration of the Venture Company's tower north of the Sludge Fen has left you poisoned by Zanzil's altered mixture. It dulls your reflexes and threatens your life. Shenthul, the rogue trainer in Orgrimmar, knows local remedies cannot help. So he sends you across the sea to the Eastern Kingdoms for care. Your search for a cure leads south through Lordaeron to Tarren Mill, a village in Hillsbrad Foothills. Serge Hinott lives there as an apothecary and is fascinated by virulent brews. Ordinary healers recoil from Zanzil's venom, but Hinott meets the deadly compound with professional glee. He can dissect the foul concoction and teach worthy rogues to brew their own venoms.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2479-b592e48d4b6dff40b8ab/1-0000.mp3", duration = 62.0930612, start = 0},
  },
}
P.transport["quest:248"] = {
  hash = "0edccb",
  fullHash = "0edccb",
  text = "Looking Further. Theocritus watches eastern Redridge from Elwynn through an enchanted conduit. He seeks the cause of the conflict between Morganth and the Blackrock orcs at Stonewatch Keep, and sends you to place the Glyph of Azora in the nearby watch tower. From his sanctum in Elwynn Forest, Theocritus watches eastern Redridge with scrying magic. As he studies the Tower of Ilgalar, he detects a clash between Morganth, a renegade human warlock, and the Blackrock orcs entrenched in Stonewatch Keep. Both hostile factions should be united against the Kingdom of Stormwind, yet they fight over an unknown prize. Theocritus intervenes before their conflict shifts the balance.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_248-41df91082c41d3f8aaf4/1-0000.mp3", duration = 40.9338776, start = 0},
  },
}
P.transport["quest:2480"] = {
  hash = "fca0ed",
  fullHash = "fca0ed",
  text = "Hinott's Assistance. In Tarren Mill, Serge Hinott studies the poison clouding a Horde rogue’s mind and prepares a cure. Your trouble began with an assignment in the Barrens. Now you are sent north to Tarren Mill with a toxin clouding your mind. Serge Hinott, a Forsaken chemist, studies the poison made by Zanzil, a jungle troll exile. The troll’s identity and kin matter little to Hinott. He admires the brew’s vicious effect and wants to learn how it works before making an antidote.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2480-4c2f54c0337bdcd50ec8/1-0000.mp3", duration = 37.3028571, start = 0},
  },
}
P.transport["quest:249"] = {
  hash = "38e59d",
  fullHash = "38e59d",
  text = "Morganth. Across Redridge, Morganth hunts the Scythe of Elune while Theocritus watches from afar. From the Tower of Azora in eastern Elwynn Forest, Theocritus uses scrying spells to watch the crags of Redridge. There he sees Morganth, a warlock in the Tower of Ilgalar, searching for the Scythe of Elune. Fearing Morganth is close to claiming it, Theocritus asks Alliance champions to stop him before Stormwind is threatened. The Tower of Ilgalar rises above the Redridge basin, where gnolls roam and arcane energies twist its halls. Morganth waits at the summit, wielding shadow magic and guarding his research. You climb through hostile ground to face him directly. Bring back his Pendant of Shadow as proof that the tower has fallen and the threat is broken.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_249-35a0a383448c57dedb83/1-0000.mp3", duration = 51.3306122, start = 0},
  },
}
P.transport["quest:25"] = {
  hash = "b7d6d5",
  fullHash = "b7d6d5",
  text = "Stonetalon Standstill. At Mystral Lake, befouled water spirits have halted Horde supply transports bound for Stonetalon. Mastok Wrilehiss at Splintertree Post sends you to clear the hostile elementals and scout a night elf gazebo overlooking Silverwind Refuge. The Horde needs lumber, supplies, and messengers to travel between Ashenvale and the Stonetalon Mountains. The Talondeep Path passes Mystral Lake’s western shore, where hostile water elementals have halted travel and battered supply caravans. Mastok Wrilehiss calls for action before the Horde’s supply lines collapse. The water elementals in Mystral Lake have grown befouled, aggressive, and unpredictable. They attack travelers on nearby trails, so you are sent to cull them and defeat the greater spirit Tideress. What tainted the lake’s spirits remains unknown amid the turmoil in Ashenvale’s sacred groves. A night elf gazebo stands on Mystral Lake’s central island, with a clear view across the water to Silverwind Refuge. Horde scouts are sent to judge whether it could serve as a forward observation post. From there, Splintertree’s commanders could watch nearby Alliance movements unseen.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_25-cdfbab8c29ed9dd6c702/1-0000.mp3", duration = 85.4204082, start = 0},
  },
}
P.transport["quest:251"] = {
  hash = "887f9d",
  fullHash = "887f9d",
  text = "Translate Abercrombie's Note. In Darkshire, a strange letter comes before the town's leaders for translation. Mayor Ello Ebonlocke turns to Sirra Von'Indi, the scholar who knows obscure scripts. Abercrombie sends Mayor Ello Ebonlocke a sealed letter from his home. Ebonlocke expects an eccentric plea or bitter ramblings from the cemetery hermit, but the parchment bears strange writing that ordinary Common cannot explain. The mayor cannot read ancient or obscure languages, so he will not dismiss it. Even a mad hermit may pose a danger in Duskwood. Ebonlocke sends you across the square to Sirra Von'Indi, Darkshire's scholar of esoteric lore. Sirra knows ancient arts and forgotten tongues. He scoffs at Abercrombie's sanity, saying anyone who lives beside a haunted graveyard must have a rotted brain. Still, he takes the parchment seriously and begins the slow work of transcription.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_251-1ff05f41d1292fa97838/1-0000.mp3", duration = 59.5591837, start = 0},
  },
}
P.transport["quest:252"] = {
  hash = "361032",
  fullHash = "361032",
  text = "Translation to Ello. In Duskwood, you carry Sirra Von'Indi's translation to Lord Ello Ebonlocke in Darkshire. It belongs to the Abercrombie story, and the letter bears news of the hermit's writings.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_252-7e013ed827d2998323fa/1-0000.mp3", duration = 13.2440816, start = 0},
  },
}
P.transport["quest:253"] = {
  hash = "33206d",
  fullHash = "33206d",
  text = "Bride of the Embalmer. In Darkshire, Lord Ello Ebonlocke sends you to find Eliza's grave. The town now knows the Embalmer is real, and you are to take his living heart from her cursed remains and strip him of his power. Duskwood's children grew up hearing tales of the Embalmer. They said he was a kindly alchemist driven mad by the death of his beloved wife, Eliza. Desperate to cheat death, he turned to sorcery, cut out his own beating heart, and placed it in her chest. Lord Ello Ebonlocke once dismissed the tale as village folklore. Recent discoveries prove the Embalmer walks among the living, and his work festers beneath the graveyard dirt.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_253-208759b41ccd565c3fb2/1-0000.mp3", duration = 46.5763265, start = 0},
  },
}
P.transport["quest:254"] = {
  hash = "6566df",
  fullHash = "6566df",
  text = "Digging Through the Dirt. At Raven Hill Cemetery, you search for the Embalmer’s missing heart. A mound marked Eliza may hold the answer, buried beneath the dirt. At Raven Hill Cemetery, one patch of loose soil bears the name Eliza. Other graves in Duskwood lie open to scavengers or feral ghouls, yet this earth was laid with care. Dig beneath the topsoil and you find splintered coffin boards. They cover the remnant the Embalmer meant to hide from daylight.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_254-4ace5b09e47f60f3c4b9/1-0000.mp3", duration = 28.5779592, start = 0},
  },
}
P.transport["quest:256"] = {
  hash = "b045fa",
  fullHash = "b045fa",
  text = "WANTED: Chok'sul. In northeastern Loch Modan, Chok'sul's ogres threaten the settlements and the works that sustain the valley. Magistrate Bluntnose wants the warlord dead before more lives are lost. Ogres now threaten northeastern Loch Modan, where troggs and wild beasts have long tested the valley's borders. They have made camps in the rugged hills and moved beyond simple scavenging. Local scouts and town authorities report raids that are focused, persistent, and dangerous. Magistrate Bluntnose believes Chok'sul directs attacks on Thelsamar, a nearby dwarven excavation site, and the Stonewrought Dam. Fearing for civilian lives and the valley's great engineering work, he offers a bounty for the ogre chieftain's death by any means. Chok'sul's severed head is required as proof.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_256-f338acc05bbcdfb751c3/1-0000.mp3", duration = 53.002449, start = 0},
  },
}
P.transport["quest:262"] = {
  hash = "1b45d3",
  fullHash = "1b45d3",
  text = "The Shadowy Figure. Near his ruined farm, Sven Yorgen seeks the stranger who watched his family die. He gives you a strange book found in the wreckage and asks you to learn who left it behind. In Duskwood’s western hills, Sven Yorgen still grieves for his slaughtered family. He once blamed the black riders who terrorize the woods. Yet he remembers a shadowy figure nearby on the night of the massacre. Sven gives you the strange book found at his ransacked farm, the only physical clue in the wreckage. With no clear trail through the perilous wilderness, you head east to Darkshire. Sven hopes one of the superstitious townsfolk will recognize the curious book. Madame Eva is among them, and her occult senses reach beyond ordinary sight. Her divinations may reveal impressions left on mysterious relics.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_262-66aff43b8cfc2f101c23/1-0000.mp3", duration = 53.0546939, start = 0},
  },
}
P.transport["quest:265"] = {
  hash = "320314",
  fullHash = "320314",
  text = "The Shadowy Search Continues. In Duskwood, you trace the journal from Madame Eva to Clerk Daltry in Darkshire. It came from the ruins of Sven Yorgen’s ransacked farmstead. Madame Eva found that the journal’s author was an outsider, though its binding came from Darkshire. Clerk Daltry sells blank ledgers and tomes to traveling scholars, spellcasters, and record-keepers. So you follow those local sales for a clue to the sinister trespasser in Duskwood’s groves.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_265-57edaf8e50469a5e7915/1-0000.mp3", duration = 28.3167347, start = 0},
  },
}
P.transport["quest:266"] = {
  hash = "e9e592",
  fullHash = "e9e592",
  text = "Inquire at the Inn. Clerk Daltry sends you from Darkshire to the Scarlet Raven Tavern with a journal from Sven Yorgen's ruined farm. He hopes someone there knows who owned it. Clerk Daltry has finished examining the tattered book from Sven Yorgen's farm. He believes any stranger who came to Darkshire would have passed through its tavern. The Scarlet Raven Tavern stands across town as Darkshire's only gathering hall and lodging house. There, you may learn who came through and where they went.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_266-7bf025bbd0c0114881eb/1-0000.mp3", duration = 29.1265306, start = 0},
  },
}
P.transport["quest:268"] = {
  hash = "350238",
  fullHash = "350238",
  text = "Return to Sven. You bring Jitters' finished journal to Sven Yorgen's camp near Westfall. Its pages may answer the questions that have haunted him since his family's murder. When Sven Yorgen's farm came under attack, Jitters fled into the woods and left an incomplete diary behind. Afraid of Sven's anger and haunted by what he had seen, he hid deep in Duskwood. When you find him, he willingly gives you his finished journal. He hopes the full account will spare him from facing Sven in person.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_268-b4f5ee5794dbc0d1d182/1-0000.mp3", duration = 29.9885714, start = 0},
  },
}
P.transport["quest:269"] = {
  hash = "902dc8",
  fullHash = "902dc8",
  text = "Seeking Wisdom. In Stormwind, Sven Yorgen asks Bishop Farthing for holy counsel on Duskwood. He sends Jitters' Completed Journal, hoping the bishop can reveal how to break Morbent Fel's shield. Duskwood suffers beneath old curses and ravenous undead. Stormwind's royal court has grown indifferent, and Sven Yorgen knows ordinary strength cannot pierce Morbent Fel's wards. Broken-hearted, he shelters at a camp near the borders and asks you to carry Jitters' assembled journal to the church. The road north leads to the Cathedral of Light.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_269-53f51183cb895a37ddb4/1-0000.mp3", duration = 36.1534694, start = 0},
  },
}
P.transport["quest:270"] = {
  hash = "4f229a",
  fullHash = "4f229a",
  text = "The Doomed Fleet. Bishop Farthing sends you north from Stormwind to find a way through Morbent Fel's wards. Your trail crosses Khaz Modan and ends at the wreck of Kul Tiras's Third Fleet off the Wetlands. Morbent Fel's wards turn ordinary steel aside at his retreat on the Forlorn Rowe. Bishop Farthing sends you to seek a weapon bound to the Holy Light. Its key is Lightforge Iron, a rare consecrated metal whose strikes carry holy truth and pierce sorcerous protections. Duskwood has no Lightforge Iron to hand. Bishop Farthing recalls that Kul Tiras's Third Fleet sank years ago along the dangerous Wetlands coast, north of Ironforge. One galleon carried a shipment of the precious ore. You travel to Menethil Harbor to meet Glorin Steelbrow, a dwarven contact who knows the marshes and their wrecks.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_270-c0ebb54723aca3b11f0b/1-0000.mp3", duration = 53.2636735, start = 0},
  },
}
P.transport["quest:2745"] = {
  hash = "c77b76",
  fullHash = "c77b76",
  text = "Infiltrating the Castle. At Stormwind Keep, Elling Trias sends you to meet his fellow operative Tyrion. Tyrion has watched Lord Gregor Lescovar from the royal gardens for weeks. At his cheese shop in the Trade District, Elling Trias sees the Defias threat reaching into the kingdom's rule. Ordinary law cannot expose or punish a nobleman as protected and entrenched as Lord Gregor Lescovar. So Trias offers a dangerous path: deliver justice within Stormwind Keep, outside the law, and sever the conspiracy for good. Elling Trias has an operative in the high halls: Tyrion, a clever gnome skilled at concealment. For weeks, Tyrion has watched the keep's courtyards and royal gardens. He has tracked Lescovar's movements, who enters his chambers, and when the traitor meets covert Defias contacts. You need to reach Tyrion without drawing the Royal Guard's suspicion.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2745-12871ba888e88c0eeb7f/1-0000.mp3", duration = 61.9363265, start = 0},
  },
}
P.transport["quest:2746"] = {
  hash = "442d58",
  fullHash = "442d58",
  text = "Items of Some Consequence. Tyrion needs silk and apples to prepare Spybot for a covert approach to Lord Lescovar in Stormwind Keep. The mechanical spy must pass the royal guards and listen to the noble. Elling Trias, the cheese merchant, has moved the operation against Lord Gregor Lescovar forward. He suspects Lescovar's schemes in Stormwind Keep threaten the realm. Tyrion agrees to the tighter schedule in the keep's gardens, but Spybot's disguise needs careful preparation. Tyrion plans to send Spybot, a small mechanical contraption, past the castle guards to reach Lescovar inside the keep. Its strange disguise as a woman should turn suspicion aside. You gather suitably sized apples from Clara's orchard just outside the city walls, along with bolts of silk for the puppet's clothes.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2746-85c81e44c3bf029a205e/1-0000.mp3", duration = 53.2636735, start = 0},
  },
}
P.transport["quest:275"] = {
  hash = "89b0ee",
  fullHash = "89b0ee",
  text = "Blisters on The Land. Across the eastern Wetlands, Rethiel senses sickness spreading through the marsh. The bog beast warden asks travelers to destroy Fen Creepers, hoping to ease the land’s rising fever. Rethiel the Greenwarden watches over the Wetlands from a grove among the marshes. The mire has always been harsh, but now an unnatural sickness spreads through it. Rethiel feels fever in the earth. It twists wild nature into mindless, shambling horrors. Fen Creepers are decaying masses of swamp plants that wander the waterways. Rethiel calls them diseased blisters swelling on the land. Their tormented presence agitates the marsh, so Rethiel asks passing allies to destroy them. Their tangled remains can then settle into the mud.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_275-8ddfc44e6f870eb6db77/1-0000.mp3", duration = 46.5502041, start = 0},
  },
}
P.transport["quest:276"] = {
  hash = "252e01",
  fullHash = "252e01",
  text = "Tramping Paws. At Greenwarden's Grove in the Wetlands, Rethiel sees the Mosshide numbers rise near the Gate of Algaz. Their fires and trampling threaten the bog, so Rethiel asks travelers to thin their ranks. Mosshide gnolls lived in the Wetlands for many years without overwhelming the natural order. Now their numbers have surged south toward the pass of Dun Algaz. Their heavy boots and paws crush rare fen plants, and their logging strips groves for campsite fires. If the packs keep growing, the fragile marsh will suffer. Rethiel the Greenwarden watches the marsh for signs of imbalance. The gnolls' existence is not the trouble; their numbers have grown beyond what the Wetlands can support. Thinning the Mosshide gnolls and mongrels helps preserve the fen and may earn the approval of its ancient guardian.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_276-5674b05159d1767d9f42/1-0000.mp3", duration = 49.5281633, start = 0},
  },
}
P.transport["quest:277"] = {
  hash = "d8beb0",
  fullHash = "d8beb0",
  text = "Fire Taboo. In the Wetlands, Rethiel turns concern for the forest into action. The bog beast asks travelers to take the crude flints Mosshide gnolls strike to set living trees alight, hoping to spare the ancient boughs. Rethiel the Greenwarden feels the Wetlands' trees as kin. Rot and renewal belong to the swamp, yet the Mosshide gnolls cut living timber and feed it to their hearthfires. The groans of those boughs weigh on Rethiel. The Greenwarden can no longer watch the trees suffer in silence. Rethiel hopes to curb the Mosshides without a long war, so the bog beast asks you to take the crude flints their stronger gnolls carry. Without those tools, the pack cannot burn the timber it fells.\n\nRethiel means to smash each stone and cast its dust into the sea, where it can never spark the forest again.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_277-3bc4c9900ceafc37d3bc/1-0000.mp3", duration = 55.3534694, start = 0},
  },
}
P.transport["quest:283"] = {
  hash = "940642",
  fullHash = "940642",
  text = "A Dark Threat Looms. Chief Engineer Hinderweir the Seventh needs you at Stonewrought Dam, where Dark Iron saboteurs have planted a charge. Disarm it before the valley below is in danger. The Stonewrought Dam holds back the waters of the Loch above the lowlands of the Wetlands. An explosive charge now sits inside it, a volatile keg left there by Dark Iron hands. If it goes off, the valley below and the lives downstream will pay for it. It falls to you to apply the Disarming Mixture before that happens, then bring word to Chief Engineer Hinderweir the Seventh.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_283-03678b2b1c229d14e23f/1-0000.mp3", duration = 38.8702041, start = 0},
  },
}
P.transport["quest:288"] = {
  hash = "d95e62",
  fullHash = "d95e62",
  text = "The Third Fleet. Outside the Deepwater Tavern, First Mate Fitzsimmons drinks through memories of the Third Fleet. He alone survived its burning off the Wetlands during the Second War. First Mate Fitzsimmons spends his days outside the Deepwater Tavern in Menethil Harbor. He nurses a hangover and memories that will not leave him. He once served aboard the Wave Mistress, a ship-of-the-line under Kul Tiras's maritime banner. Now he turns to dwarven mead, and another drink may bring his account of a terrible naval slaughter. During the Second War, the Third Fleet sailed along the shores of Khaz Modan when fire fell from the sky. The Dragonmaw clan had subdued the red dragonflight at Grim Batol and unleashed dragonfire upon the unsuspecting warships. Fitzsimmons remembers wooden hulls burning beneath towering flames as their crews were dragged into the deep. He alone survived and washed ashore. His fallen brothers lie in the watery graveyard known as the Doomed Fleet.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_288-fe4acf081d839e8ba294/1-0000.mp3", duration = 70.2955102, start = 0},
  },
}
P.transport["quest:289"] = {
  hash = "b8579b",
  fullHash = "b8579b",
  text = "The Cursed Crew. Off the Wetlands coast, The Cursed Crew haunts the ships where the Third Fleet of Kul Tiras sank. First Mate Fitzsimmons, the fleet's sole survivor, asks travelers to free his lost brethren. A dark relic aboard one wreck binds the drowned sailors and marines to their ships as restless undead. The Third Fleet of Kul Tiras wrecked along the jagged shores north of Menethil Harbor. First Mate Fitzsimmons alone reached land alive. His fellow sailors found no peace beneath the waves. As they died, sorcery from a mysterious treasure hidden deep in one hull bound their souls to the battered timbers and denied them rest.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_289-dd38645e2ce3a5beff29/1-0000.mp3", duration = 41.6130612, start = 0},
  },
}
P.transport["quest:290"] = {
  hash = "fce9b5",
  fullHash = "fce9b5",
  text = "Lifting the Curse. First Mate Fitzsimmons asks you to free his fallen crewmates from a restless curse. He believes an artifact aboard the wrecked Intrepid binds them, and Captain Halyndor’s ghost guards the strongbox key. First Mate Fitzsimmons survived the Third Fleet’s fate, yet memories of his comrades haunt him day and night. He believes an evil object locked in the Intrepid’s strongbox is tied to the undeath gripping his shipmates. Captain Halyndor’s ghost watches the wreck and guards the strongbox key.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_290-93b8c1dd820471cb39c7/1-0000.mp3", duration = 36.5714286, start = 0},
  },
}
P.transport["quest:2904"] = {
  hash = "45c4fd",
  fullHash = "45c4fd",
  text = "A Fine Mess. In Gnomeregan, you find Kernobee battered among the troggs after a Dark Iron ambush. His rescue brings word of a drilling rig beneath Dun Morogh, bound for Booty Bay. You find Kernobee in Gnomeregan’s dormitory, beaten and groggy. Dark Iron dwarves ambushed the goblin and left him among the feral troggs. You guide him through the contaminated corridors toward safety.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2904-86c51c4949ce4c7fcb27/1-0000.mp3", duration = 31.4514286, start = 0},
  },
}
P.transport["quest:292"] = {
  hash = "080407",
  fullHash = "080407",
  text = "The Eye of Paleth. Fitzsimmons asks you to recover The Eye of Paleth from the sunken Intrepid. Then carry the cursed gem to Glorin Steelbrow in Menethil Harbor, where the dwarven priest seeks a way to purge its blight. Beneath Baradin Bay, the Intrepid's locked strongbox holds a blackened orb. The Eye of Paleth pulses under the water, warped from sacred light into a source of suffering. Its corruption binds it to the restless spirits and doom that claimed the sailors of the Third Fleet.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_292-4681f86fcae4df9afd6c/1-0000.mp3", duration = 32.2873469, start = 0},
  },
}
P.transport["quest:2922"] = {
  hash = "512b84",
  fullHash = "512b84",
  text = "Save Techbot's Brain!. Tinkmaster Overspark sends you into Gnomeregan to save Techbot's Brain! and recover its memory core. The machine once aided researchers, but radiation filled the city and an electrical surge during its fall polarized its brain and made its behavior violent. Overspark hopes the core will help him reverse the damage and restore his creation. Before Gnomeregan fell, Techbot aided researchers with its devices and deep technical knowledge. Tinkmaster Overspark designed the mechanical assistant, and its built-in gizmos made it a marvel of gnomish ingenuity. Then the trogg invasion brought chaos, and toxic radiation filled the city. A stray electrical surge jolted Techbot's delicate workings and polarized its positronic brain into a volatile negatronic state. Tinkmaster Overspark needs you to recover Techbot's core, for the machine now wanders Gnomeregan's contaminated halls in a frenzy and attacks anyone in sight. Overspark refuses to abandon his prized assistant as scrap. He asks you to find the machine, remove its memory core from the metal chassis, and bring it to Ironforge. With the core, he hopes to understand the polarization and repair Techbot's mind.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2922-d3ff9046aaa723f874cf/1-0000.mp3", duration = 87.9804082, start = 0},
  },
}
P.transport["quest:2923"] = {
  hash = "603a00",
  fullHash = "603a00",
  text = "Tinkmaster Overspark. In Stormwind, Brother Sarno hears that Techbot has failed and that Tinkmaster Overspark grieves in Ironforge. He sends Alliance adventurers to Tinker Town, where Overspark asks for help recovering Techbot's memory core from Gnomeregan. Brother Sarno tends to travelers in Stormwind City and speaks of trouble among the gnomish refugees. Tinkmaster Overspark, one of the minds behind Gnomeregan's wonders, grieves over Techbot's corruption. The mechanical servant once aided the tinkerers faithfully. Then the city fell into ruin. You take the Deeprun Tram from Stormwind to Ironforge's Tinker Town. There, Overspark seeks adventurers willing to help in Gnomeregan's irradiated halls. He asks them to salvage what remains of Techbot's faculties before the construct causes irreparable harm.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2923-4e1e4dc0aa5d89f7d0eb/1-0000.mp3", duration = 61.0220408, start = 0},
  },
}
P.transport["quest:2924"] = {
  hash = "8ee567",
  fullHash = "8ee567",
  text = "Essential Artificials. In Ironforge, Klockmort Spannerspan lacks the components his experiments need. Exiled gnomes fled Gnomeregan during the trogg invasion and radiation disaster, leaving essential artificials in the city's lower halls. When troggs overran Gnomeregan and radiation filled its corridors, the gnomes fled with only what they could reach. Essential artificials remained behind. These specialized mechanical parts work in nearly any device, and tinkers and crafters prize them. Now in Ironforge's Tinker Town, master tinker Klockmort Spannerspan cannot continue his new experiments without a supply. Deep inside Gnomeregan, the components rest in heavy, steam-powered containers called artificial extrapolators. To reach them, you cross irradiated halls where mutated leper gnomes, malfunctioning defense automatons, and feral troggs roam. Klockmort needs twelve components to continue his work, keeping gnomish invention moving through exile.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2924-3e8fcfe89e7e90dba6b9/1-0000.mp3", duration = 72.6726531, start = 0},
  },
}
P.transport["quest:2925"] = {
  hash = "5a4452",
  fullHash = "5a4452",
  text = "Klockmort's Essentials. In Darnassus, Mathiel carries Klockmort Spannerspan's urgent plea across the sea. Bound to his post, he asks Alliance travelers to find his gnome friend in Ironforge. From the Warrior's Terrace in Darnassus, Mathiel sends word to Dun Morogh. Klockmort Spannerspan needs bold allies for a venture into Gnomeregan, but Mathiel cannot leave his post to travel there. So he asks capable Alliance travelers passing through Darnassus to make the journey in his place. Klockmort Spannerspan works in Tinkertown, Ironforge's district for gnomes driven from their underground city. He plans to recover vital machinery from Gnomeregan's contaminated corridors. Mathiel's referral brings you to Klockmort's workshop, where he needs help reclaiming what was left behind.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2925-5205b7eda4fd5a8afa46/1-0000.mp3", duration = 51.5134694, start = 0},
  },
}
P.transport["quest:2926"] = {
  hash = "a23761",
  fullHash = "a23761",
  text = "Gnogaine. In Kharanos, Ozzie Togglevolt sends adventurers toward Gnomeregan to gather radioactive fallout. He hopes to make a cure for the leper gnomes, though the brew may become potent drink. Since Gnomeregan fell, refugees such as Gnoarn have sought to kill the trogg invaders and reverse the sickness that changed their kin. Ozzie Togglevolt and his partner Razzle Sprysprocket have taken another path from their workshop in Kharanos. Ozzie says they are trying to make a cure for the leper gnomes. Their formula might instead become very strong rum. Ozzie and Razzle need toxic residue from the heart of the disaster. Ozzie gives adventurers a leaden collection phial and sends them toward Gnomeregan's breached tunnels. Irradiated Invaders and Irradiated Pillagers roam there, troggs saturated with leaking waste. The phial needs their green glow.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2926-6c803d376bfae114a394/1-0000.mp3", duration = 53.0808163, start = 0},
  },
}
P.transport["quest:2927"] = {
  hash = "5b9d32",
  fullHash = "5b9d32",
  text = "The Day After. In Ironforge and Kharanos, Gnomeregan's survivors search for an answer to their city's ruin. Gnoarn sends travelers to Ozzie Togglevolt, who studies the contamination and hopes to find a solution. In Ironforge's Tinker Town, Gnoarn mourns Gnomeregan and the loss of his gnomefro. Trogg invaders took the mechanical city, and toxic fallout stripped away his prized mane. Fury toward the troggs and hope of reclaiming the city move him to send sympathetic travelers to colleagues who can salvage what remains. In Kharanos, inventive gnomes have begun to face the fallout. Gnoarn sends travelers to Ozzie Togglevolt, who works with his partner Razzle Sprysprocket. Ozzie remembers the catastrophe, when Gnoarn's locks fell out in clumps and madness and thirst for vengeance took hold. Now Ozzie studies the contamination in the snowbound town, using his engineering skill to seek an antidote.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2927-44403efddbf3f930bdb6/1-0000.mp3", duration = 65.5673469, start = 0},
  },
}
P.transport["quest:2928"] = {
  hash = "691656",
  fullHash = "691656",
  text = "Gyrodrillmatic Excavationators. In Stormwind's Dwarven District, Shoni the Shilent readies tunneling machines for Dun Morogh. Short on parts, she sends you into Gnomeregan to salvage them from rogue automatons. Hundreds of gyrodrillmatic excavationators wait to be made ready in the Dwarven District. Gnomish engineers there aid their displaced kin. The machines will carry people and supplies underground, but these massive rigs cannot work without the mechanical parts Shoni lacks. Gnomeregan once supplied gnomish high technology. Its ruined halls and nearby tunnels still hold machines worth salvaging, though malfunctioning defense bots, mechanical sentries, and clockwork laborers roam unchecked. Shoni sends you into the fallen city for two dozen bundles of robo-mechanical guts, to bring back to human lands. Two dozen bundles of mechanical guts provide enough scrap to repair one excavationator. Shoni still has nearly four hundred machines to prepare, so mass transport underground remains a slow undertaking. Each working machine is a small step toward regaining ground lost in Gnomeregan's fall.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2928-f20e70028e9abb721cca/1-0000.mp3", duration = 74.4489796, start = 0},
  },
}
P.transport["quest:293"] = {
  hash = "e101dd",
  fullHash = "e101dd",
  text = "Cleansing the Eye. In the Wetlands, Cleansing the Eye sends adventurers south to Stormwind with a cursed orb in need of aid. After recovering the Eye of Paleth, they seek Archbishop Benedictus to purge its lingering taint. The Eye of Paleth recovered from the marshlands bears no holy light. Shadow clings to it, along with the sorrow and trauma of the tragedy where it was lost. Glorin Steelbrow, a dwarf, recognizes the orb's power. Yet he lacks the divine craft to lift so heavy a curse. Human priests of the Holy Light first fashioned the Eyes of Paleth, so their highest order alone knows how to undo the defilement. Glorin sends adventurers south to Stormwind with the darkened orb, to Archbishop Benedictus, leader of the Church of the Holy Light. Benedictus knows the danger of leaving such a relic unpurified. He takes on the work of restoring its sacred light.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_293-07a986e38b7e8531d688/1-0000.mp3", duration = 66.4816327, start = 0},
  },
}
P.transport["quest:2930"] = {
  hash = "c12a8c",
  fullHash = "c12a8c",
  text = "Data Rescue. Master Mechanic Castpipe sends you into Gnomeregan to recover its records. Troggs and radiation drove the gnomes from the city, but the punchograph terminals still guard its archives behind layers of clearance. Troggs and radiation drove Gnomeregan's people from the city, leaving centuries of research, schematics, and civic records behind. Matrix Punchograph terminals still line its technological corridors. They manage security clearance and store files. Master Mechanic Castpipe in Ironforge's Tinker Town wants you to recover those punch-encoded archives from the city's depths. Gnomish mainframes demand clearance in stages. First, find a White Punch Card among the wreckage outside the inner gates. Insert it into the Matrix Punchograph 3005-A in the Train Depot to make a Yellow card. Then take that to the 3005-B terminal in the Dormitory for a Blue card. Model 3005-C advances it to Red. The final terminal, 3005-D, waits in the Engineering Labs, where the Red card becomes a Prismatic Punch Card.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2930-3e76f5ec2fa89683d32d/1-0000.mp3", duration = 74.2661224, start = 0},
  },
}
P.transport["quest:2931"] = {
  hash = "e475c1",
  fullHash = "e475c1",
  text = "Castpipe's Task. In Ironforge, Master Mechanic Castpipe calls travelers to recover Gnomeregan's records. The ruined halls still hold vital mechanical and technical knowledge. After Gnomeregan fell and was sealed under radioactive quarantine, its surviving gnomes found refuge in Ironforge's Tinkertown. Troggs and irradiated constructs still overrun their old home. Deep within the city, computing arrays hold operational records and mechanical schematics. Castpipe seeks outsiders willing to brave the toxic halls and recover files that may explain what went wrong or help the gnomes return. Gaxim Rustfizzle of the Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences spreads word of Castpipe's effort. Castpipe belongs to no academic body, yet his fellow gnomes respect his skill and support his work. Rustfizzle puts the operation's strategic value at an eighty-four percent chance. Travelers can report to Tinkertown for orders.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2931-ed27c1af080176a39a38/1-0000.mp3", duration = 68.7542857, start = 0},
  },
}
P.transport["quest:294"] = {
  hash = "b42f2b",
  fullHash = "b42f2b",
  text = "Ormer's Revenge. At Whelgar Excavation Site, Ormer Ironbraid and his two companions cling to a bluff above the raptor-swarmed dig. Beneath the Wetlands, the dwarves uncovered massive prehistoric bones. Mottled raptors came in packs and killed most of the crew. The dwarves came to Whelgar Excavation Site to uncover massive prehistoric remains beneath the Wetlands muck. Their discovery drew the marsh’s native raptors to the dig. Packs of mottled predators swarmed the site, caught the excavators off guard, and tore through their ranks. Only a handful of dwarves survived. Ormer Ironbraid, Merrin Rockweaver, and Prospector Whelgar scrambled up a bluff above the pit, but aggressive packs still pin them there. Ormer grieves for his fallen comrades and burns with anger, yet stays to guard Merrin and the Prospector. He asks travelers to thin the Mottled Raptors and Mottled Screechers below. This is the first strike in his vengeance.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_294-525c15b38602aaf9157b/1-0000.mp3", duration = 63.477551, start = 0},
  },
}
P.transport["quest:295"] = {
  hash = "ded781",
  fullHash = "ded781",
  text = "Ormer's Revenge. At the ruined Whelgar Excavation Site, Ormer Ironbraid sends you after the raptors that drove out his expedition. Their smaller young are already thinned, and now he wants the Mottled Scytheclaws and Razormaws killed. Ormer Ironbraid sends you after the adult raptors in the lower dig. You have already thinned the juveniles that overran the upper camp, but Mottled Scytheclaws and Razormaws still threaten any hope of reclaiming the excavation. They tear through dwarven prospectors and leave the trenches strewn with shattered crates and abandoned picks. Raptors have made nests in the excavation pits. From the ridge above the dig, Ormer directs you into the mud to strike at the mature beasts. Prospector Whelgar and his crew hope to salvage ancient relics, but Ormer is consumed by vengeance. He demands a heavy toll of dead Scytheclaws and Razormaws before he turns to the site's apex terror.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_295-6ea54a8b4f09459af197/1-0000.mp3", duration = 55.6408163, start = 0},
  },
}
P.transport["quest:2951"] = {
  hash = "86cec1",
  fullHash = "86cec1",
  text = "The Sparklematic 5200!. In Gnomeregan, the Sparklematic 5200! keeps cleaning salvaged valuables for three silver coins. Gnomish ingenuity keeps it working amid the ruined city's chaos. A pocket of surviving gnomes holds a secure perimeter near the Sparklematic 5200! in Gnomeregan. The machine scrubs harsh subterranean filth from salvaged valuables. Troggs and other subterranean creatures pound on the bulkheads, yet it remains ready for what you bring. Place a grime-caked relic and three silver coins in the Sparklematic, and the cleaning begins. The iron machine groans and vibrates, lurching as it strips away toxic sludge, irradiated grease, and rock dust. Moments later, it expels what lay beneath the muck, from precious minerals to mechanical components.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2951-e5c74db4ee582be1f0ec/1-0000.mp3", duration = 52.2971429, start = 0},
  },
}
P.transport["quest:2952"] = {
  hash = "5f6177",
  fullHash = "5f6177",
  text = "The Sparklematic 5200!. In Gnomeregan, the Sparklematic 5200! takes in soiled salvaged objects and cleans them. Its cycles scour away toxic grime, then wrap whatever remains in a gift box. Feed toxic and contaminated refuse into the Sparklematic 5200!, and its cycles scour away grime and caustic residue. Once loaded and paid, the machine rattles through its routine. A cheerful ding follows, then a bow-tied present holds whatever remains. When Gnomeregan fell to the troggs, radiation and industrial mire buried personal effects and scraps of technology. Feed grime-encrusted objects into the machine, and it may recover gemstones, raw ores and other valuables swallowed when the city was vented.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2952-b4608606039ebf6bc6b4/1-0000.mp3", duration = 44.4081633, start = 0},
  },
}
P.transport["quest:2953"] = {
  hash = "c44a34",
  fullHash = "c44a34",
  text = "More Sparklematic Action. In Gnomeregan, the Sparklematic 5200 still cleans what can be saved. Left behind when the city was evacuated, it scrubs muck and radioactive sludge from curiosities for a small fee in silver. Before the trogg invasion and the fallout that followed, Gnomeregan's engineers installed automated devices throughout the city. Toxic waste and hostile automatons now fill its corridors. Yet the Sparklematic 5200 follows its exact programming: it needs three silver coins and an artifact caked in grime to begin. The Sparklematic lurches as it sprays an inserted relic with potent gnomish solvents and scrubs it clean. A cheerful chime marks the end of the cycle, and the machine dispenses a neatly packaged box. Inside is whatever salvage remained beneath corrosive trogg slime and toxic filth.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2953-16bb78ac9be0c3c7b8f4/1-0000.mp3", duration = 55.3273469, start = 0},
  },
}
P.transport["quest:296"] = {
  hash = "4b6167",
  fullHash = "4b6167",
  text = "Ormer's Revenge. Ormer Ironbraid seeks vengeance at Whelgar Excavation Site. He believes Sarltooth led the raptor attack that slaughtered dwarven excavators, and asks you to bring back one of its talons as proof. After the Explorer's League diggers were slaughtered at Whelgar Excavation Site, Ormer Ironbraid watched the raptors from his ridge. One beast stood larger than the rest. Sarltooth perched above the dig works, where Ormer saw it lead the pack that drove the dwarves out. To Ormer, Sarltooth was more than a wild beast. He believed it had led the attack on King Magni Bronzebeard's subjects. Ormer demands death for the massacre. He sends you up the high paths along the excavation walls to kill Sarltooth. Bring back one of the raptor's formidable talons, and the fallen workers will be avenged. Ormer wants the marshes to know that attacks on dwarven expeditions will not go unanswered.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_296-c8b17195f50cc1da8bee/1-0000.mp3", duration = 65.5934694, start = 0},
  },
}
P.transport["quest:2962"] = {
  hash = "5423ac",
  fullHash = "5423ac",
  text = "The Only Cure is More Green Glow. In Kharanos, Ozzie Togglevolt seeks a cure for the leper gnomes. He needs a pure sample of fallout from deep inside Gnomeregan. Ozzie Togglevolt's first tests outside Gnomeregan gave him no answers. The troggs in Dun Morogh carried too little residue, and what they bore was impure. Now, from his lab in Kharanos, Ozzie seeks a fresh, concentrated sample from deep inside the city. He hopes it will help him find a remedy for the leper gnomes. You need to gather potent fallout from inside Gnomeregan. Irradiated horrors, lurkers, and slimes fill the lower depths around the Hall of Gears and Clean Zone. Their unstable ooze must be carried in a heavy leaden phial, and the work is dangerous. The fallout quickly loses its potency, so you need to get it to Ozzie's lab in Kharanos in time.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2962-21711a7ecfb3d74d089b/1-0000.mp3", duration = 60.4995918, start = 0},
  },
}
P.transport["quest:2985"] = {
  hash = "bcec1e",
  fullHash = "bcec1e",
  text = "Call of Water. Swart sends an initiate from Razor Hill toward Islen Waterseer on the Barrens coast. Earth and fire have tested the shaman; water asks for another kind of understanding. Swart, the shaman trainer in Razor Hill, guides initiates through the elements. Earth teaches endurance, and fire tests their command. Once an initiate can wield flame without being consumed, Swart judges them ready to seek the teachings of water. Islen Waterseer lives on the Barrens coast beyond Ratchet. Travel south along the Southfury River into the Barrens, then east to the shore near a massive shark's carcass. Islen dwells where the waves meet the land, apart from the trainers in Durotar's towns. She guides the Horde in communion with water.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2985-3b8d83c0c3cc7053352b/1-0000.mp3", duration = 56.6334694, start = 0},
  },
}
P.transport["quest:299"] = {
  hash = "8f1f80",
  fullHash = "8f1f80",
  text = "Uncovering the Past. Prospector Whelgar needs the Goaz Stone's four missing pieces from his overrun dig in the Wetlands. Its inscriptions await translation. Before raptors overran the dig in the Wetlands, Prospector Whelgar unearthed the Goaz Stone. His first attempts to read its ancient script found broken references to a divine plan and a doomed prophecy. Four pieces had broken away, leaving passages scattered across the dig. To restore the stone, you search the raptor guarded excavation for four fragments: Ados, Modr, Golm, and Neru. The pieces lie among loose soil and half excavated relics, watched by aggressive Razormaws and Scytheclaws. Reaching them means facing the marsh's fiercest predators.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_299-f961a867dda10111839a/1-0000.mp3", duration = 47.5167347, start = 0},
  },
}
P.transport["quest:2996"] = {
  hash = "5fd34d",
  fullHash = "5fd34d",
  text = "Seeking Strahad. In Orgrimmar, Gan'rul Bloodeye sends warlocks south to Ratchet for harder lessons. A human summoner there teaches arts beyond basic summoning. In the Cleft of Shadow, Gan'rul Bloodeye has taught you to command the Nether. Now you have outgrown his lessons. The beings beyond them are more volatile, and they demand a tutor with deeper mastery of dark arcana than any within Orgrimmar's walls. So Gan'rul sends you south to Strahad Farsan, a human sorcerer whose tower stands above Ratchet's goblin port. Horde and humans may be enemies, but warlocks look past such loyalties: power, discipline and ritual knowledge matter more than ancestry. Strahad judges his students by the hatred within them and their will to subjugate, not by the color of their skin.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2996-85d3b12d354b584fd3e9/1-0000.mp3", duration = 53.0546939, start = 0},
  },
}
P.transport["quest:3001"] = {
  hash = "060505",
  fullHash = "060505",
  text = "Seeking Strahad. Carendin Halgar sends Horde warlocks across the Great Sea to seek Strahad Farsan. Above Ratchet, a human sorcerer offers them a path beyond basic instruction and toward the difficult art of summoning a felhunter. Carendin Halgar trains warlocks in the Undercity's Magic Quarter. When an initiate outgrows basic instruction, he sends them beyond Lordaeron's ruins to find Strahad Farsan. Halgar warns that Strahad is a living human, but no weakling, and says not to treat him as an enemy. The pursuit of demonic mastery can cross racial and factional lines. Strahad works from the bluffs above Ratchet, the goblin port in the Barrens. Near a stone watchtower, he looks down on the sailors, mercenaries, and merchants below, amused by their blissful ignorance of the Twisting Nether. Horde warlocks may reach him with distrust and simmering hatred in their eyes. Strahad accepts that raw malice as fuel to shape into dark authority.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3001-d8e7409ba1b68bf684f2/1-0000.mp3", duration = 60.6563265, start = 0},
  },
}
P.transport["quest:303"] = {
  hash = "4794f8",
  fullHash = "4794f8",
  text = "The Dark Iron War. At Dun Modr, Motley Garmason leads a desperate defense on the Wetlands' northern edge. The Dark Iron clan holds the town after saboteurs shattered the Thandol Span. The Ironforge Mountaineers keep a tenuous line as they wait for reinforcements that may never come. Dun Modr guarded the southern end of the colossal Thandol Span, the bridge linking Khaz Modan to Lordaeron. Dark Iron saboteurs and demolitionists shattered its archway, cutting off Alliance travel before they overran the stronghold. Motley Garmason and a handful of surviving defenders withdrew to an observation camp just outside town. Without a counterattack, the northern gateway may remain under Dark Iron rule. Dwarven regiments are fighting on distant Alliance battlefields, leaving Motley's small detachment largely to fend for itself. His scouts try to signal Ironforge for relief, but communications falter and promised reserves remain out of sight. To buy time and disrupt the enemy's defenses, Motley orders surgical strikes into Dun Modr's ruins. His aim is to thin the ranks of Dark Iron engineers, tunnelers, and front-line soldiers before they push farther south into the Wetlands.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_303-3f5fe09fca8c2ab08cc1/1-0000.mp3", duration = 83.6440816, start = 0},
  },
}
P.transport["quest:304"] = {
  hash = "fc25d5",
  fullHash = "fc25d5",
  text = "A Grim Task. In the Wetlands, Longbraid the Grim seeks vengeance for Dun Modr. The Dark Iron assault shattered the Thandol Span and killed his brother and many soldiers. Now he wants Balgaras the Foul slain, with the warlock's ear as proof. Fighting between Ironforge Mountaineers and Dark Iron infiltrators has scarred the northern Wetlands. Dun Modr fell during the siege, and the western bridge of the Thandol Span was shattered. Longbraid the Grim lost his brother and many loyal soldiers in the assault. He wants the Dark Iron clan to pay for those deaths. Scouts such as Roggo have found that Balgaras the Foul commands the Dark Iron force occupying Dun Modr. The warlock hides while his soldiers carry out his dark designs. Longbraid hopes Balgaras's death will break their resolve. Then Ironforge's survivors may secure the passage north.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_304-67fa01a94ee175cf1488/1-0000.mp3", duration = 56.9730612, start = 0},
  },
}
P.transport["quest:305"] = {
  hash = "a7c10a",
  fullHash = "a7c10a",
  text = "In Search of The Excavation Team. Tarrel Rockweaver waits in the Wetlands for news of Merrin at the Whelgar Excavation Site. Two weeks have passed without a letter, and he fears for the eastern dig. For two weeks, Tarrel Rockweaver has heard nothing from his wife, Merrin. From the Whelgar Excavation Site, she once sent weekly letters about the work. Now Tarrel fears disaster has struck the camp. With dwarf authorities stretched thin, he turns to passing scouts to learn whether the diggers are alive. East in the Wetlands, dwarves at the Whelgar Excavation Site seek ancient Titan relics and history. The crews work in the wild, where beasts and threats from below may find them. The site lies far from the main roads. Whatever stopped the letters has left the diggers beyond easy reach.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_305-c79ea52616588991202d/1-0000.mp3", duration = 48.404898, start = 0},
  },
}
P.transport["quest:306"] = {
  hash = "d97a1c",
  fullHash = "d97a1c",
  text = "In Search of The Excavation Team. At Whelgar's Excavation site, Merrin Rockweaver sends word after mottled raptors overrun the dig. Her letter tells Tarrel Rockweaver she survived, though most of the expedition did not. Merrin Rockweaver has news for you from the ridge above Whelgar's Excavation site. Her team was uncovering rare artifacts and massive prehistoric fossils when packs of mottled raptors swept through the dig. Most of the crew died in the attack. Merrin and the other survivors remain cut off from Menethil Harbor. At Menethil Harbor, Tarrel Rockweaver learns his wife survived with at least two companions. Ormer's courage helped them escape, and Tarrel's fear eases. Yet the deaths of so many colleagues still weigh on the town and its frontier spirit.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_306-5e50765649e933300145/1-0000.mp3", duration = 46.3412245, start = 0},
  },
}
P.transport["quest:321"] = {
  hash = "57613b",
  fullHash = "57613b",
  text = "Lightforge Iron. In Menethil Harbor, Glorin Steelbrow seeks cargo lost with an elven destroyer. The Flying Osprey carried rare Lightforge iron when it sank with the Third Fleet of Kul Tiras during the Second War. The Flying Osprey sailed from Lordaeron beside the Third Fleet of Kul Tiras. The elven destroyer carried a precious cargo of Lightforge iron and traveled with the fleet for safety. Then the Dragonmaw clan's enslaved red dragons swept down from the sky. They set the ships ablaze, sending sailors and sanctified metal beneath the waves.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_321-04b19a5401eb2b2846b5/1-0000.mp3", duration = 35.3436735, start = 0},
  },
}
P.transport["quest:322"] = {
  hash = "e6baf0",
  fullHash = "e6baf0",
  text = "Blessed Arm. In Stormwind, Glorin Steelbrow sends lightforge iron toward a weapon against Morbent Fel. You bring the rare metal from the wreck of the Flying Osprey in the Wetlands to master weaponsmith Grimand Elmore, who can forge it for the fight. Glorin Steelbrow packs the recovered lightforge iron for Stormwind. Rare and powerful against foul and unholy beings, the metal needs a smith who knows how to work it. The shipment came from the wreck of the Flying Osprey off the Wetlands coast. Glorin knows only one artisan in the southern kingdoms suited to the task: master weaponsmith Grimand Elmore. In Stormwind's Dwarven District, Grimand Elmore keeps one of the city's finest anvils. Years have passed since he last hammered lightforge iron, he says, when you bring him the recovered shipment. The veteran artisan welcomes the chance to strike at the necromancer Morbent Fel. He agrees to put his hammer to work.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_322-2155e151d033c628fbf1/1-0000.mp3", duration = 60.8914286, start = 0},
  },
}
P.transport["quest:323"] = {
  hash = "2f5a15",
  fullHash = "2f5a15",
  text = "Proving Your Worth. In Duskwood, Sven Yorgen tests your strength before you face Morbent Fel. The hermit wants revenge for his family and needs proof you can defeat the undead at Raven Hill Cemetery. Sven Yorgen grieves at a secluded camp north of the howling woods. Fury burns in him over the slaughter of his family. He has learned that the Dark Riders who destroyed his homestead were allied with the necromancer Morbent Fel. Sven wants revenge, but he will not send an untried ally into Fel's grasp. First, he asks you to prove your fighting skill against the skeletons at Raven Hill Cemetery. Raven Hill Cemetery lies south of Forlorn Rowe, and corpses bound by Fel's magic fill its grounds and mausoleum. Skeletal Raiders patrol among the tombstones with swords. Below, Skeletal Warders and Healers tend the chambers. To earn Sven's trust, you must press deep into the necropolis and clear this vanguard. Mor'Ladim, a vengeful phantom, prowls the cemetery paths.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_323-f49b9ed0286bbd25bfc2/1-0000.mp3", duration = 65.515102, start = 0},
  },
}
P.transport["quest:324"] = {
  hash = "9613d6",
  fullHash = "9613d6",
  text = "The Lost Ingots. Glorin Steelbrow seeks Lightforge iron from a shipwreck off the Wetlands. The chest holds only one ingot, and Bluegill murlocs have taken the rest. The Flying Osprey lies broken off the Wetlands shore. Glorin Steelbrow, a dwarven priest, sent you to recover its Lightforge iron. Yet the waterlogged chest in the cargo hold holds only one ingot. Bluegill murlocs near the wreck scavenged the rest of the shipment. Lightforge iron is rare metal, fit for sacred smithing. Glorin Steelbrow needs it for a weapon, so the bars cannot remain in Bluegill camps. The Bluegill raiders hunt the shallows near the broken hull. Reclaim the scattered ingots for Glorin.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_324-5b1cb26dbb6320a4f08d/1-0000.mp3", duration = 43.6506122, start = 0},
  },
}
P.transport["quest:325"] = {
  hash = "a6751b",
  fullHash = "a6751b",
  text = "Armed and Ready. You carry Morbent's Bane back to Sven Yorgen, a weapon made to break Morbent Fel's unholy defenses. Ordinary steel cannot break Morbent Fel's hold over Raven Hill cemetery. Blades shatter or glance from the dark wards around him. Grimand Elmore shaped the metal in Stormwind's Dwarven District, and sacred power consecrated it. Now Morbent's Bane can sever Fel's tie to unlife.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_325-ac2afa8acd4a41392acd/1-0000.mp3", duration = 27.637551, start = 0},
  },
}
P.transport["quest:335"] = {
  hash = "a41939",
  fullHash = "a41939",
  text = "A Noble Brew. Beneath Stormwind, Zardeth of the Black Claw schemes against the city's nobles. Lord Wishock's call for an investigation threatens the hidden warlock coven. Warlocks gather beneath the Mage Quarter in the Slaughtered Lamb, keeping their coven hidden. Lord Wishock, a member of the House of Nobles, has heard of the dark magic below the city. Now he urges his peers to begin a full investigation. The city guard and royal scrutiny could soon fall upon the coven.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_335-158dafb0b9d1e0ec2676/1-0000.mp3", duration = 34.6383673, start = 0},
  },
}
P.transport["quest:336"] = {
  hash = "55081f",
  fullHash = "55081f",
  text = "A Noble Brew. Zardeth of the Black Claw sends you to the Royal Keep with Black Claw Stout for Lord Baurles K. Wishock. The brew must reach him in the Hall of Petitioners. In Stormwind Keep, Lord Baurles K. Wishock speaks of his importance and the kingdom’s future. Yet patrons of the Slaughtered Lamb know he drinks in the tavern’s upper rooms at night and leaves large bills unpaid. By day, he petitions to have the tavern shut down.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_336-68e3ea3ece3d5f0329fd/1-0000.mp3", duration = 30.8244898, start = 0},
  },
}
P.transport["quest:3369"] = {
  hash = "bc9f13",
  fullHash = "bc9f13",
  text = "In Nightmares. A shard from the Wailing Caverns brings a troubling vision to Thunder Bluff. You carry the glowing Nightmare Shard to Arch Druid Hamuul Runetotem on Elder Rise, where it reveals corruption within the Emerald Dream. Falla Sagewind sees the Emerald Dream's pure essence in a strange crystal from the Wailing Caverns. Within it lies a dark, chaotic vision, more waking nightmare than peaceful slumber. Unwilling to speak openly of the omen, she entrusts the shard to you. Then she sends you to Arch Druid Hamuul Runetotem, Thunder Bluff's most venerated elder druid.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3369-52b1d127c22b302f7333/1-0000.mp3", duration = 44.564898, start = 0},
  },
}
P.transport["quest:337"] = {
  hash = "76af69",
  fullHash = "76af69",
  text = "An Old History Book. Milton Sheaf awaits a lost Stormwind chronicle at the Royal Library. The book, The History of Stormwind, bears the library’s seal and vanished before the kingdom rose again after the First War. Its return may help preserve the history of the southern human lands. You find the mud-caked book among the ruins of Duskwood, where undead and ogres roam. Its first page bears Stormwind’s formal library seal, marking it as a rare relic from before the city’s destruction. It was checked out decades ago, before the Horde razed the capital, and was thought lost when the south fell. Milton Sheaf recognizes the book when you bring it to the Royal Library in Stormwind Keep. He plans to place it in the rare books archive, though years in the haunted wilds have badly damaged its pages. The discovery sends Sheaf seeking more lost knowledge in Southshore, the nearest town to Alterac’s ruined kingdom and abandoned libraries.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_337-2b2beaf8ed26e76ef002/1-0000.mp3", duration = 66.56, start = 0},
  },
}
P.transport["quest:3370"] = {
  hash = "4f4a12",
  fullHash = "4f4a12",
  text = "In Nightmares. Falla Sagewind sends a glowing shard to the elder druids in Darnassus. It holds the essence of the Emerald Dream, clouded by dark visions. Falla Sagewind sees more than a crystal in the glowing shard recovered from the depths of Wailing Caverns. Within it lies the pure essence of the Emerald Dream. Yet the shard shows fearful visions where nature should be in harmony. Shaken, Falla will study it no further. She sends you to carry the shard to the senior druids of the Cenarion Circle.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3370-6b8a706b6141835993ee/1-0000.mp3", duration = 37.3028571, start = 0},
  },
}
P.transport["quest:34"] = {
  hash = "95a000",
  fullHash = "95a000",
  text = "An Unwelcome Guest. In Lakeshire, Martie Jainrose asks you to stop Bellygrub for good. The wild boar wrecked her garden and trampled her daffodils, and she offers a bounty for his tusk. Martie Jainrose lives in Lakeshire, a town by the lake beneath the gathering shadows over the Redridge Mountains. A wild boar keeps breaking into her garden and ruining the peace of her home. Bellygrub has trampled her daffodils beyond recovery for the season. Now Martie asks travelers to end the animal's rampage. Marshal Marris, who leads Lakeshire's town guard, gave the boar his name: Bellygrub. He spends most of his time rooting through the fields southwest of town. His hunger and boldness bring him close to homes, where he ruined Martie's flower beds. The damage has left her wanting him gone.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_34-5aea1aed4736588330c6/1-0000.mp3", duration = 49.6065306, start = 0},
  },
}
P.transport["quest:343"] = {
  hash = "f50f0c",
  fullHash = "f50f0c",
  text = "Speaking of Fortitude. Brother Kristoff has sent Head Librarian Milton Sheaf searching the Royal Library for an exact volume. Brother Kristoff is preparing a sermon on the Fortitude of the Spirit. To give his congregation a clear picture of spiritual strength, he turns to metalworking alongside scripture. He hopes a treatise on iron enduring pressure will serve as his example. Head Librarian Milton Sheaf knows the Royal Library's archive by heart. Still, he must check whether it holds the exact title Kristoff seeks. Its centuries of histories, civic writings, and craft works give him plenty to search.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_343-b8f3d324e062110c3a86/1-0000.mp3", duration = 41.2473469, start = 0},
  },
}
P.transport["quest:344"] = {
  hash = "32625f",
  fullHash = "32625f",
  text = "Brother Paxton. At Stormwind's royal archives, Milton Sheaf sends you to Northshire Abbey for a missing dwarven treatise. The book went there months ago for copying, but it has not returned to the city's shelves. Stormwind's head librarian, Milton Sheaf, is searching for a book missing from the capital's shelves. 'The Stresses of Iron,' a treatise on metallurgical techniques by dwarven prospector Margulf Blaggon, was loaned months ago to the clerics of Northshire Abbey for copying. It was not misplaced in Stormwind. At Northshire Abbey, Brother Paxton tends the library and its books. The Holy Order of Northshire Clerics values knowledge, but copying a long technical manuscript by hand takes time. Paxton admits he has not finished duplicating Blaggon's work. So the original has not yet returned to Stormwind.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_344-21716f22e942da50b31a/1-0000.mp3", duration = 61.8579592, start = 0},
  },
}
P.transport["quest:345"] = {
  hash = "a60ef3",
  fullHash = "a60ef3",
  text = "Ink Supplies. Brother Paxton at Northshire Abbey has run short of the ink his writings need. He sends you east to Lakeshire for Rethban ore. Brother Paxton uses his special ink for important writings, including The Stresses of Iron. The ink dries quickly and resists smearing. Yet its recipe has a flaw: left too long, it hardens in the pot. To make a fresh batch, Paxton needs raw Rethban iron ore from the rocky Redridge Mountains. Foreman Oslow has no workers to spare for mining. His laborers are strengthening Lakeshire’s barricades, rebuilding ruined structures, and defending the town from Blackrock orc raids. So you must brave the perilous Rethban Caverns yourself to find the ore Paxton needs.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_345-bbdfa35e954c4e48b481/1-0000.mp3", duration = 46.3412245, start = 0},
  },
}
P.transport["quest:346"] = {
  hash = "c6b27d",
  fullHash = "c6b27d",
  text = "Return to Kristoff. In Cathedral Square, Brother Kristoff waits for the return of The Stresses of Iron. After a long search in Northshire, you bring the borrowed book back to the Cathedral of Light. Brother Kristoff waits in Cathedral Square for The Stresses of Iron, a book on metallurgy. Its path led from Stormwind Keep's Royal Library to Northshire Abbey, where Brother Paxton copied it by hand. The work stalled when Paxton ran short of Rethban ore for his ink. Now the ore has been found and the copy is complete. You bring the original book back to Stormwind. Brother Paxton asks you to apologize to Librarian Milton Sheaf for the delay. Northshire's copyists preserve civic and spiritual lore, though their supplies are scarce. Valuable books must be copied stroke by stroke with mineral-rich ink. Only then can they leave the abbey and return to Stormwind's care.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_346-55cd2cc845ec450810ba/1-0000.mp3", duration = 57.4955102, start = 0},
  },
}
P.transport["quest:347"] = {
  hash = "530f51",
  fullHash = "530f51",
  text = "Rethban Ore. In Redridge, Rethban Ore is needed at Northshire Abbey for its dark color. Foreman Oslow sends you into Rethban Caverns to gather the soft mineral, which cannot make strong weapons or armor. Scribes at Northshire Abbey prize Rethban Ore for its dark, flat color. Bart Rethban discovered it, but the mineral has little use at an armorer’s anvil. Smelted metal from the ore is too weak for sturdy weapons or plate. Its raw color instead makes a valued base for manuscript dyes. The main ore deposits lie in Redridge’s northern mountains, inside Rethban Caverns. Lakeshire’s stoneworkers have left, driven out by a fierce band of Redridge gnolls. The gnolls force drudgers to chip ore from the rocky veins for their own crude purposes. Brother Paxton, a monk at Northshire Abbey, needs the pigment to copy historic texts. His work on The Stresses of Iron has stopped without the proper dye. Messengers and adventurers now travel into gnoll-held territory to bring him the raw stone.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_347-6c71f0bd4f3a43a8c732/1-0000.mp3", duration = 64.0783673, start = 0},
  },
}
P.transport["quest:350"] = {
  hash = "ce24e3",
  fullHash = "ce24e3",
  text = "Look to an Old Friend. Master Mathias Shaw sends you to find an unusual ally in Stormwind's Trade District. Noble corruption shields traitors from ordinary justice, so Shaw turns to the city's finest cheesemonger and his intelligence network.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_350-f76ff0b7573ac054b24b/1-0000.mp3", duration = 15.4122449, start = 0},
  },
}
P.transport["quest:3513"] = {
  hash = "4e052e",
  fullHash = "4e052e",
  text = "The Runed Scroll. Found in Kalimdor's wilds, The Runed Scroll bears a formal message from across the border. Its discovery sends Horde scouts to warn the guards at Mor'shan Rampart of activity to the north. A silvery ribbon binds the scroll, unlike the rough leathers and parchment common in the Barrens. Its craft and script point north, to the night elves beneath Ashenvale's canopies. The ridges and roads are contested, so a message taken from the enemy could matter greatly to the Horde's front lines. The scroll belongs with local command, not in the Warchief's hall in Orgrimmar. Kadrak, an orc warrior, watches the border from Mor'shan Rampart, where the Barrens' red earth meets Ashenvale's forests. Bring the scroll to this outpost, and its guards will learn of night elf troop movements.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3513-25cf3039eae8efcc902a/1-0000.mp3", duration = 51.6440816, start = 0},
  },
}
P.transport["quest:3514"] = {
  hash = "a1cc1d",
  fullHash = "a1cc1d",
  text = "Horde Presence. At the Barrens border, Kadrak sends a Horde champion into Stonetalon Peak after a missive is intercepted. The champion is to kill the dryad Rynthariel and plant a Horde banner inside the Talon Den. Kadrak watches the Barrens’ northern boundary for Alliance and night elf incursions. A messenger carrying a runed scroll is cut down, and Kadrak decodes the missive. It leads him to Rynthariel the Keymaster, an influential dryad in Stonetalon Peak. Rather than merely guard the mountain passes, Kadrak strikes first, hoping to deter future scouts from probing Horde territory. Horde warriors enter the Talon Den, a cavern overlooking Stonetalon Peak. Killing Rynthariel strikes at the night elves’ local coordination. Kadrak’s banner is planted inside the cave. Its red standard marks the heart of dryad territory with a warning: incursions into the Barrens will meet decisive violence.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3514-39b6caac83cda809f493/1-0000.mp3", duration = 64.3395918, start = 0},
  },
}
P.transport["quest:3567"] = {
  hash = "563c03",
  fullHash = "563c03",
  text = "To the Top. Marli Wishrunner offers you a view from one of Feralas's twin colossals, with one warning: the way up is one way. Marli Wishrunner can send you to the top of one of Feralas's twin colossals for a view. She warns you to think about how you will get down. The journey goes only one way.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3567-3a5b3d202f8739bbb31f/1-0000.mp3", duration = 18.677551, start = 0},
  },
}
P.transport["quest:373"] = {
  hash = "6c57b3",
  fullHash = "6c57b3",
  text = "The Unsent Letter. A sealed letter from Edwin VanCleef awaits Baros Alexston, Stormwind's City Architect. Its delivery brings their shared past to light. A sealed letter rests in Edwin VanCleef's clothing aboard his juggernaut beneath Moonbrook. Newly penned, it bears Baros Alexston's name. VanCleef chose the City Architect, not a criminal lieutenant or financier.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_373-0505ee20cc39bbd63083/1-0000.mp3", duration = 26.5404082, start = 0},
  },
}
P.transport["quest:3765"] = {
  hash = "d04957",
  fullHash = "d04957",
  text = "The Corruption Abroad. In Stormwind, Argos Nightwhisper seeks adventurers to aid his brother in northern Kalimdor. Gershala studies a spreading decay in Darkshore, where he needs fresh hands. Stormwind faces internal turmoil and unrest in its surrounding regions. Even so, envoys from distant kaldorei lands walk its stone streets. Argos Nightwhisper seeks seasoned champions willing to look beyond human borders. The kaldorei are relatively new allies to the Eastern Kingdoms, and formal military aid is scarce. So families and researchers recruit independent champions who will answer the call. Argos points you toward auberdine, a misty port on Darkshore’s fog-shrouded coast. His brother Gershala studies an ominous malaise afflicting the local wildlife and flora. Reaching him means a long voyage from stormwind harbor across the Great Sea. It is a traveler’s first true passage into Kalimdor’s ancient wilderness.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3765-b97c428a58e04548f066/1-0000.mp3", duration = 62.4587755, start = 0},
  },
}
P.transport["quest:377"] = {
  hash = "341c1f",
  fullHash = "341c1f",
  text = "Crime and Punishment. In Darkshire, Crime and Punishment begins with a sentence the capital has overturned. Councilman Millstipe seeks Dextren Ward, held in the Stormwind Stockade, after the House of Nobles spared him from Darkshire's death sentence. Ward had been caught robbing graves for the necromancer Morbent Fel. Duskwood already suffers beneath creeping horrors and indifference from the capital. Dextren Ward was caught digging fresh corpses from Darkshire's cemetery. He sold them to Morbent Fel, a necromancer.\n\nLord Ello Ebonlocke sentenced Ward to beheading. Before the axe could fall, the House of Nobles claimed him as an imperial prisoner. They transferred him to the high-security cells of the Stormwind Stockade. To Councilman Millstipe and Darkshire's grieving citizens, sparing Ward was an intolerable insult. The nobles in their secure city showed complete disregard for frontier families whose dead relatives had been fed into Fel's dark craft.\n\nFrustrated by Stormwind's meddling, Millstipe recruits daring mercenaries to infiltrate the riotous Stockade. They are to assassinate Ward in his cell and sever his hand as proof of execution.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_377-f284412e5b071fa26ca5/1-0000.mp3", duration = 78.5502041, start = 0},
  },
}
P.transport["quest:378"] = {
  hash = "9f176c",
  fullHash = "9f176c",
  text = "The Fury Runs Deep. Motley Garmason seeks vengeance against Kam Deepfury, held in Stormwind's Stockade. Deepfury planned the assault on the Thandol Span, where Bronzebeard defenders died, including Longbraid the Grim's brother. Stormwind keeps Deepfury as a political prisoner, so Motley asks an adventurer to carry out dwarven justice. The Wetlands' northern reaches remain troubled by clashes between Bronzebeard defenders at Dun Modr and Dark Iron insurgents. When the Thandol Span came under attack, sabotage killed several dwarves, among them Longbraid the Grim's brother. Roggo uncovered intelligence showing Kam Deepfury planned the strike. Rather than face execution on the front lines, Deepfury was taken to Stormwind's Stockade as a political prisoner, not executed for murder. Motley Garmason is stationed at Dun Modr, and he will not let Stormwind's political calculations shield a war criminal. To him, human law puts decorum before blood debts. Bound to remain beside Longbraid in the Wetlands, Motley sends trusted champions into the rioting Stockade beneath the human capital. They are to take Deepfury's head and settle the clan's score.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_378-835d52bd8df67a5a62fe/1-0000.mp3", duration = 86.1779592, start = 0},
  },
}
P.transport["quest:386"] = {
  hash = "07d82d",
  fullHash = "07d82d",
  text = "What Comes Around.... In Lakeshire, Guard Berton presses for Targorr the Dread's execution. The Blackrock orc remains in Stormwind Stockade despite his sentence, while political delays keep justice out of reach. Targorr the Dread earned his name in the Redridge Mountains. He served as supreme executioner under General Gath'Ilzogg, chieftain of the Blackrock orcs at Stonewatch Keep. Even among the invaders, his cruelty was notorious. He oversaw the torture and execution of many Redridge defenders. After his capture, Stormwind sent him to its high-security prison, the Stormwind Stockade, and condemned him to die for his crimes against the realm.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_386-47bd299dcb5d75927541/1-0000.mp3", duration = 45.1657143, start = 0},
  },
}
P.transport["quest:387"] = {
  hash = "aae623",
  fullHash = "aae623",
  text = "Quell The Uprising. Beneath Stormwind, Warden Thelwater calls for help as the Stockade erupts in riot. Defias prisoners have seized the cell blocks, and he wants the uprising crushed before the city's leaders learn how badly the prison has failed. The Stockade holds criminals, conspirators, and outlaws who threaten the Kingdom of Stormwind. Now Defias operatives have risen in sudden violence and seized the cell blocks from the guards. Armed prisoners crowd the corridors, and order has broken down. The guards depend on visiting champions to fight through the riot and retake the prison. Warden Thelwater orders Defias prisoners killed on sight. Desperate and afraid for his position, he suspects foul play behind the coordinated mutiny. He fears losing his post if the House of Nobles or the wider nobility learns the Stockade is out of control. He hopes a death sentence for insurgency will break the inmates' resolve and crush the rebellion before word passes the canal gates.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_387-ccdb495968f26726bb20/1-0000.mp3", duration = 71.7844898, start = 0},
  },
}
P.transport["quest:388"] = {
  hash = "041484",
  fullHash = "041484",
  text = "The Color of Blood. Nikova Raskol grieves for Mac, her young grandson, killed inside Stormwind City's prison. Anger consumes her, and she sends adventurers into The Stockade to take the Defias gang's red bandanas in retribution. Mac Raskol was fourteen when he took up arms as a guard in The Stockade. Stormwind's regular soldiers had gone to distant fronts, so volunteers and the city's youth took on local defense. Mac watched hardened criminals and mutinous members of the Defias Brotherhood. The prison was far more dangerous than his experience could prepare him for. The Defias inmates tore apart their wool prison blankets and fashioned red bandanas from the scraps. The color marked their loyalty to the Brotherhood, even behind prison walls. Mac rebuked them and tried to enforce discipline. The prisoners stabbed him in the back, and he died on the stone floor. After Mac's pointless death, Nikova Raskol turns from official channels to cold revenge. She sends you into The Stockade to quell the rioting prisoners and bring back ten of their cherished red bandanas. Dyed the color of her grandson's spilled blood, the tokens offer a broken family a grim sense of closure.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_388-b498f3d31912af0473b7/1-0000.mp3", duration = 86.8310204, start = 0},
  },
}
P.transport["quest:389"] = {
  hash = "19a4a9",
  fullHash = "19a4a9",
  text = "Bazil Thredd. Beneath Stormwind, a Defias prisoner may know what the Brotherhood still intends. After an unsent letter is found in the Deadmines, City Architect Baros Alexston sends you to the Stockade for answers. Baros Alexston and Edwin VanCleef once led the Stonemasons Guild. The masons rebuilt Stormwind after the First and Second Wars. Yet when the white walls and towers were complete, the nobility refused to pay the wages they had promised. Some senior masons received government posts to quiet them. VanCleef would not leave the rank-and-file laborers behind. He led a violent riot out of the city and founded the Defias Brotherhood.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_389-28e2b5ff68200e24c43b/1-0000.mp3", duration = 46.8897959, start = 0},
  },
}
P.transport["quest:391"] = {
  hash = "b08d8a",
  fullHash = "b08d8a",
  text = "The Stockade Riots. At Stormwind's prison gates, Warden Thelwater sends you into the Stockade Riots to prove your loyalty to the city guards. The uprising has seized the prison, and he orders you to find and execute its ringleader, Bazil Thredd. Beneath the Mage Quarter's cobblestones, the Stockade has fallen into lawlessness. Criminals, Defias insurgents, and violent cutthroats have broken containment and seized the cell blocks. The prison is now an impenetrable war zone. Warden Thelwater and his guards hold desperately to the entrance, unable to push inside and restore order by ordinary means.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_391-3adc2280c82ea7051e0e/1-0000.mp3", duration = 41.2995918, start = 0},
  },
}
P.transport["quest:392"] = {
  hash = "69d227",
  fullHash = "69d227",
  text = "The Curious Visitor. After the Stockade uprising, Warden Thelwater has found a troubling link to Bazil Thredd. For months before the riot, a man called Maelik visited Thredd with papers that passed inspection. After the riot, Warden Thelwater learned that Bazil Thredd’s former comrades had not abandoned him. For months, a quiet visitor met with Thredd once or twice a week. He passed every inspection, carried authorized papers, and gave his name as Maelik. Thelwater suspects those visits helped coordinate the bloody uprising. He sends you to City Architect Baros Alexston with a description, hoping to learn who the visitor was.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_392-4f142ab2d4b8253de674/1-0000.mp3", duration = 45.6881633, start = 0},
  },
}
P.transport["quest:393"] = {
  hash = "08e1be",
  fullHash = "08e1be",
  text = "Shadow of the Past. The trail from a Stockade prisoner leads into Stormwind’s hidden dealings in Shadow of the Past. Baros Alexston sends you to Mathias Shaw after a mysterious visitor spoke with Bazil Thredd. Baros Alexston cannot name the visitor who spoke with Bazil Thredd, the Stockade’s chief prisoner. Warden Thelwater’s account brought investigators to Stormwind’s city architect, but he has no name to give. So Baros points you to Master Mathias Shaw. Shaw leads SI:7 and makes it his business to know Stormwind’s secrets.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_393-3ec99c047860c567d3d6/1-0000.mp3", duration = 37.12, start = 0},
  },
}
P.transport["quest:394"] = {
  hash = "2348b6",
  fullHash = "2348b6",
  text = "The Head of the Beast. In Stormwind, The Head of the Beast takes you from Elling Trias to Master Mathias Shaw in Old Town. Your report of Lord Gregor Lescovar’s death confirms your place in Stormwind’s covert intelligence network. Master Mathias Shaw directs Stormwind’s covert apparatus through SI:7 from hidden chambers in Old Town. When you report Lescovar’s death, Shaw recognizes your skill and ruthlessness. He praises your efficiency and thanks you for serving the people of Stormwind.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_394-bb73ae5ddeb6438f87fb/1-0000.mp3", duration = 34.5077551, start = 0},
  },
}
P.transport["quest:395"] = {
  hash = "89f43d",
  fullHash = "89f43d",
  text = "Brotherhood's End. In Stormwind Keep, questions remain after Lord Gregor Lescovar is killed. Master Mathias Shaw sends you to City Architect Baros Alexston and warns you to keep the killer's identity quiet. Baros Alexston, the City Architect who helped rebuild Stormwind as a stonemason, is relieved that Lescovar is dead. Edwin VanCleef had marked Alexston and other prominent figures in the rebuilding effort for vengeance after the Stonemasons were cast out without pay. With Lescovar silenced and the conspiracy disrupted, Alexston believes the immediate threat to the kingdom's architects and nobility has passed.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_395-f061e1f04378ad50a064/1-0000.mp3", duration = 45.9493878, start = 0},
  },
}
P.transport["quest:396"] = {
  hash = "215be5",
  fullHash = "215be5",
  text = "An Audience with the King. At Stormwind Keep, the Defias report comes before the Crown. After a long inquiry through Westfall and the Deadmines, you bring City Architect Baros Alexston's findings to the capital. Edwin VanCleef has fallen, and the conspiracy beneath Moonbrook is broken. City Architect Baros Alexston prepares an official report for the Crown. He believes you should be honored for ending the guild's criminal enterprise. So you carry the findings across Stormwind's grand canals to Stormwind Keep, expecting to meet the realm's ruler.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_396-8c76a719d97efa87f437/1-0000.mp3", duration = 38.0342857, start = 0},
  },
}
P.transport["quest:397"] = {
  hash = "e14e06",
  fullHash = "e14e06",
  text = "You Have Served Us Well. Beneath the Slaughtered Lamb, Stormwind's warlocks have secured a refuge. They report to Zardeth of the Black Claw, whose cabal has kept the city guard and curious nobles at bay. Beneath the Slaughtered Lamb, Stormwind's warlocks practice their dark arts, tolerated so far by the authorities. Lord Wishock threatens to expose their hidden studies or bring them to an end. So the coven gives him a tainted draught, and his death preserves their refuge beneath the inn.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_397-24b3cb287a754a249755/1-0000.mp3", duration = 28.4734694, start = 0},
  },
}
P.transport["quest:401"] = {
  hash = "7de648",
  fullHash = "7de648",
  text = "Wait for Sirra to Finish. In Darkshire's Town Hall, Sirra Von'Indi writes as he deciphers Abercrombie's cryptic note. Dread settles over the room, and the hermit's words hint at danger. Sirra Von'Indi has the note Abercrombie sent from his seclusion. He aids the Night Watch and Darkshire's leaders, and needs only a short time to decipher the message. He does not yet know what horrors the words conceal.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_401-94ce6bbb4c7272773302/1-0000.mp3", duration = 26.6710204, start = 0},
  },
}
P.transport["quest:4021"] = {
  hash = "b3d6aa",
  fullHash = "b3d6aa",
  text = "Counterattack!. At Regthar Deathgate’s outpost west of the Crossroads, Kolkar warriors strike back for their fallen leaders. Reinforcements have crossed from Desolace under Warlord Krom'zar. The Kolkar have been humiliated in the Barrens. Barak Kodobane, Verog the Dervish, and Hezrul Bloodmark are dead, leaving the remaining centaur shattered and without direction. News of their defeat crosses the mountains to Desolace, their ancestral homeland. There, hardened Kolkar warriors rally instead of scattering into the scrubland. Burning for blood and retribution, they enter the Barrens and march against the young Horde encampments.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4021-ada4d3ce7a88b8b323dc/1-0000.mp3", duration = 44.3820408, start = 0},
  },
}
P.transport["quest:434"] = {
  hash = "df2342",
  fullHash = "df2342",
  text = "The Attack!. Tyrion and Elling Trias draw a traitor into a garden meeting inside Stormwind Keep. Their plan puts his Defias contact within reach. Inside Stormwind Keep, an automaton disguised as Priestess Tyriona brings word to the library: Lescovar’s guest has arrived. Lord Gregor Lescovar sends his guards away and leaves for the quiet garden. The guest is Marzon the Silent Blade, an assassin tied to the Defias Brotherhood. But Tyrion, a spy working with the cheese merchant Elling Trias, has fed Marzon false information, and it has drawn him within their reach.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_434-4a2c7f32bb8789f91d04/1-0000.mp3", duration = 38.8963265, start = 0},
  },
}
P.transport["quest:442"] = {
  hash = "00b110",
  fullHash = "00b110",
  text = "Assault on Fenris Isle. High Executor Hadrec sends Forsaken agents to Fenris Isle. They are to storm Fenris Keep and take the head of Thule Ravenclaw, the necromancer commanding the island stronghold in Lake Lordamere. The Forsaken hold the western roads and have made their presence known at the Sepulcher. Yet the Scourge remain entrenched in Fenris Keep, on an island in Lake Lordamere east of Silverpine Forest. Their forces threaten the forest and the southern waterways that lead toward the Undercity. High Executor Hadrec sees Thule Ravenclaw’s experiments as a danger to Forsaken control of Silverpine. From the keep, Thule commands the Scourge close to the Forsaken shore.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_442-a01d04686f872671c834/1-0000.mp3", duration = 48.9273469, start = 0},
  },
}
P.transport["quest:453"] = {
  hash = "af4264",
  fullHash = "af4264",
  text = "Finding the Shadowy Figure. Sven Yorgen's farm has been devastated, and Finding the Shadowy Figure turns toward the stranger who fled it. Tavernkeep Smitts points the search west from Darkshire into Duskwood's haunted woods. Sven Yorgen pleads for help identifying the figure who fled his devastated homestead. The trail leads to the Scarlet Raven Tavern, where Tavernkeep Smitts offers several clues. The fugitive was a complete stranger to Darkshire, nervous and jittery, and left the faint lamps at the town's edge in haste. He vanished into the wilderness to the west.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_453-459e9471dc0522fade17/1-0000.mp3", duration = 35.7093878, start = 0},
  },
}
P.transport["quest:4542"] = {
  hash = "361b96",
  fullHash = "361b96",
  text = "Message to Freewind Post. At Thousand Needles' western approaches, Brave Moonhorn sends an urgent warning to Freewind Post. Centaur raids are rising, and he reports strange behavior among the Grimtotem. Brave Moonhorn watches Thousand Needles' western approaches. Centaur attacks have risen sharply, and the border sentries need to alert their leaders. So Moonhorn asks you to carry a dispatch southeast to Cliffwatcher Longhorn, commander of the mesa settlement at Freewind Post. Cliffwatcher Longhorn confirms that centaur recently intercepted and slaughtered a supply caravan. Freewind Post must defend itself and answer the attack. Moonhorn also warns you to avoid the nearby Grimtotem tauren. Their strange, hostile behavior points to growing divisions across the arid flats.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4542-0fa928900f2ac7f67c7b/1-0000.mp3", duration = 49.5281633, start = 0},
  },
}
P.transport["quest:455"] = {
  hash = "a69a60",
  fullHash = "a69a60",
  text = "The Algaz Gauntlet. At Dun Algaz, orcs have seized the pass between Loch Modan and the Wetlands. The Dragonmaw threaten Ironforge's route to Menethil Harbor, so Mountaineer Rockgar sends Alliance travelers to strike them and carry word to Valstag Ironjaw. Crags divide Loch Modan from the Wetlands, and Dun Algaz is the way across. It is the only overland mountain pass between them, and Ironforge depends on it for trade, troop movements, and supplies bound for Menethil Harbor, the Alliance's main coastal port in the region.\n\nIf the pass falls, Ironforge loses its route to the western seas. Isolated outposts would also lose access to dwarven reinforcements. Dragonmaw remnants have haunted the hills and ruins of the Wetlands since the Second War. Now they have pushed into Dun Algaz in an organized assault, seizing the tunnels and fortifying the pass with their scouts and grunts.\n\nMountaineer Rockgar asks Alliance travelers to slay the orcs and carry word of the attack to Valstag Ironjaw in Menethil Harbor.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_455-9947549044190167549b/1-0000.mp3", duration = 70.5828571, start = 0},
  },
}
P.transport["quest:4581"] = {
  hash = "c3aff5",
  fullHash = "c3aff5",
  text = "Kayneth Stillwind. In Ashenvale, Sentinel Shindrell Swiftfire sends a scouting report east from Astranaar. Druid Kayneth Stillwind needs help watching corruption spread through the ancient woods. In Astranaar, Sentinel Shindrell Swiftfire watches over western Ashenvale. Kayneth Stillwind, a druid at Forest Song in the eastern forest, has asked her to judge the region's security. Shifting wildlife and dark omens along the coasts and through the woods trouble him. So Swiftfire seals her observations in a note and entrusts it to a traveler crossing the dangerous central forest. The road to Forest Song crosses Nightsong Woods, where satyrs encroach, wildlife turns hostile, and the Horde ventures from the south. At the shrine, Kayneth Stillwind studies the balance of Ashenvale's natural spirits. Swiftfire's report confirms his fear: corruption spreads through the forest, neither confined to one place nor passing quickly. The druids need more help to confront the wickedness taking root.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4581-fad55a1de5812e18112c/1-0000.mp3", duration = 65.1232653, start = 0},
  },
}
P.transport["quest:463"] = {
  hash = "351d91",
  fullHash = "351d91",
  text = "The Greenwarden. From Menethil Harbor, First Mate Fitzsimmons sends Alliance travelers northeast into the Wetlands marshes. They seek a mysterious being rumored to dwell among the beasts. At Menethil Harbor, sailors and wanderers trade stories of a beast lurking in the swamp. First Mate Fitzsimmons calls the Greenwarden an appetite with legs and those who seek it gullible. Leave the dry road, he warns, and ol’ Greenie will bite you in two. To the folk on the docks, anything huge in the murky waters is another man-eating danger in the marsh.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_463-99c7d317d7ecd3c9ded8/1-0000.mp3", duration = 32.7836735, start = 0},
  },
}
P.transport["quest:464"] = {
  hash = "efa7d5",
  fullHash = "efa7d5",
  text = "War Banners. At Menethil Harbor, Captain Stoutfist sends Alliance champions against Dragonmaw orcs gathering strength in the Wetlands. He wants their banners taken from a camp northeast of town. During the Second War, the Dragonmaw clan held the red dragonflight captive at Grim Batol. When their control broke, the freed dragons hunted their captors nearly to extinction. The few orcs who survived fled Grim Batol into the high mountains east of Whelgar's Excavation, hiding from the red flight's wrath. Dragonmaw survivors have gathered again northeast of Menethil Harbor. They have raised a war camp and planted crimson standards in the marsh. Captain Stoutfist sees danger in an armed orc force so near the harbor town. He wants their ranks thinned and their banners torn down as proof of defeat.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_464-7c3f44f5937af4d4ce58/1-0000.mp3", duration = 51.8530612, start = 0},
  },
}
P.transport["quest:465"] = {
  hash = "9c92ec",
  fullHash = "9c92ec",
  text = "Nek'rosh's Gambit. At Menethil Harbor, Captain Stoutfist braces for Nek'rosh's assault. The Dragonmaw chieftain has built catapults to batter the port, while fighting at Dun Algaz blocks reinforcements. You are sent into the marshes to destroy the engines before they reach the town. Dwarven scouts uncovered the plan while Alliance fighters clashed with Dragonmaw raiders. Chieftain Nek'rosh has overseen the building of full-scale siege catapults in the Wetlands encampments. He means to bring them to Menethil Harbor and batter its fortress walls. The attack threatens the Alliance's main shipping hub on the western coast. Fighting and greenskin activity clog the mountain passes at Dun Algaz. The lowlands are cut off from Ironforge's main garrisons, so Captain Stoutfist cannot spare troops to guard the harbor's perimeter. Without aid from Khaz Modan, Menethil's survival depends on sabotaging the catapults before they can be brought against the town. Scouts carry Dwarven Tinder into the heart of the Dragonmaw encampment. There, they must set the timber catapults ablaze and destroy them. This will strip Nek'rosh of his artillery and deny his warriors the firepower to break Menethil's defenses. The engines must be ruined before the warlord can be confronted.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_465-8fe1ee4077199bd1278d/1-0000.mp3", duration = 92.3428571, start = 0},
  },
}
P.transport["quest:466"] = {
  hash = "5ccdef",
  fullHash = "5ccdef",
  text = "Search for Incendicite. At Steelgrill's Depot, Pilot Stonegear seeks samples of volatile incendicite ore from the Wetlands. He believes its explosive force could change dwarven artillery, and needs you to reach a secluded cave and bring back the dangerous mineral. Siege engine pilots and mechanics at Steelgrill's Depot have heard of rare, unstable ore. Rich veins are rumored in a cavern northwest of Algaz Gate, in the Wetlands. Careless miners there risk having the reactive mineral detonate in their faces. Pilot Stonegear sees military promise in the ore. Refined correctly, it could power dwarven artillery or serve as its payload. Cannon shells might gain enough force to break fortified defenses. He wants raw samples so researchers can test smelting methods without blowing up the depot.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_466-a561076b10341c4dc0f5/1-0000.mp3", duration = 58.4881633, start = 0},
  },
}
P.transport["quest:467"] = {
  hash = "5542e8",
  fullHash = "5542e8",
  text = "Stonegear's Search. At Steelgrill's Depot, Pilot Stonegear seeks rare ore to strengthen his tank's weapons. He asks you to find fresh fuel for its firepower. Pilot Longbeard or Mountaineer Kadrell may send you to hear Stonegear's proposal. The ambitious pilot wants his siege engine to hit harder, and word of his plans has spread through Ironforge and Loch Modan. At the proving ground and staging yard just east of Kharanos, Stonegear seeks prospectors to search for rare, volatile ore. He believes it can greatly increase his tank's firepower.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_467-2ea7e1d33b49df35c6a1/1-0000.mp3", duration = 37.642449, start = 0},
  },
}
P.transport["quest:468"] = {
  hash = "47f94e",
  fullHash = "47f94e",
  text = "Report to Mountaineer Rockgar. At Dun Algaz, Mountaineer Rockgar is preparing an expedition into the Wetlands. Mountaineer Kadrell sends you north from Loch Modan to join him in the sodden lowlands along the pass between the dwarven homeland and the northern territories. Dun Algaz cuts through the northern ridge between Loch Modan and the marshy Wetlands. Trade, messengers, and military detachments pass through this fortified route between Ironforge and Alliance settlements farther north. As tensions rise along the borders, Mountaineer Kadrell watches the road and seeks hardy volunteers for the northern outposts.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_468-dbb9a859a20f396d57f4/1-0000.mp3", duration = 38.4, start = 0},
  },
}
P.transport["quest:469"] = {
  hash = "9c493f",
  fullHash = "9c493f",
  text = "Daily Delivery. In the Wetlands, Daily Delivery takes cured crocolisk hides toward Menethil Harbor. Einar Stonegrip asks travelers bound for town to carry them to a local tanner. Einar Stonegrip hunts the Wetlands, especially the aggressive crocolisks along its waterways. Their skins are valuable, but bringing them to Menethil Harbor means going home. His marriage to Sida is going through a rough patch, so Einar would rather stay in the field than face her. He gives his parcels to travelers heading toward town. James Halloran tans hides in Menethil Harbor. Local hunters bring him leather for boots and goods suited to merchants and sailors passing through the port. Einar has been away for a week, and Halloran guesses that a quarrel with Sida explains the delivery by proxy. He wonders whether his own wife should step in and make peace with her.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_469-b135ad4bf9cd29e4063a/1-0000.mp3", duration = 52.1926531, start = 0},
  },
}
P.transport["quest:470"] = {
  hash = "40417a",
  fullHash = "40417a",
  text = "Digging Through the Ooze. In Menethil Harbor, Sida needs her bag back from the ooze that swallowed it. She fled Ironbeard's Tomb when foul oozes filled the barrows. Sida lives in Menethil Harbor and often travels northeast into the Wetlands to pay homage at Ironbeard's Tomb. On her latest visit, foul, dripping oozes filled the ancient barrow. In panic, she hurled her satchel at one of them. The ooze swallowed the bag whole, giving Sida just enough time to flee back to the port town. Now she asks travelers to search for it. Near Dun Modr, the contested stronghold, Ironbeard's Tomb holds the remains of a storied dwarven hero. Corruption in the surrounding marshland draws amorphous, acidic slimes that consume anything in their path. Sida cannot remember which creature swallowed her belongings. Search the tomb grounds and cut through the creeping blight to find her drenched satchel.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_470-6df060102bc0da03a640/1-0000.mp3", duration = 55.9281633, start = 0},
  },
}
P.transport["quest:471"] = {
  hash = "17f817",
  fullHash = "17f817",
  text = "Apprentice's Duties. In Menethil Harbor, James Halloran needs giant crocolisk hides for his trade. His apprentice has been mauled in the marshes, so Halloran asks travelers to take up the dangerous hunt. James Halloran sent his young apprentice into the Wetlands marshes to skin giant crocolisks. When the boy failed to return, Halloran went looking and found him badly mauled. Menethil Harbor's tradesmen rely on materials from the surrounding country, though the bogs make such work dangerous. The town midwife believes Halloran's apprentice will live, though the attack cost him a leg. Halloran needs hides for his trade, and he wants vengeance on the beasts that tore into the boy he loves like a son. He asks you to go north along the coast, past the murloc hovels, and hunt the giant crocolisks.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_471-e5f3a470015026ff4f57/1-0000.mp3", duration = 49.7371429, start = 0},
  },
}
P.transport["quest:472"] = {
  hash = "54c7ba",
  fullHash = "54c7ba",
  text = "Fall of Dun Modr. At Dun Modr, Dark Iron forces have broken the northern fortress and its garrison. In Menethil Harbor, a badly wounded survivor asks an Alliance adventurer to go north and learn whether Longbraid the Grim or any defenders lived. For generations, Dun Modr guards northern Khaz Modan and the vital road and bridge across the Thandol Span. They link the Wetlands to the Arathi Highlands. After an ambush at the bridge, the garrison falls back to regroup inside the fortress. Before the defenders can restore their defenses, overwhelming Dark Iron forces strike and drive them into a desperate flight. Harlo Barnaby, a young defender, is gravely wounded when a stray axe strikes his back during the retreat. Believing him doomed, Longbraid the Grim and the remaining troops strap Barnaby to their last surviving horse and send him south to Menethil Harbor. He survives and wakes in the harbor tavern, burdened by survivor's guilt. He has no idea whether any of his comrades escaped alive.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_472-0fdbdf4ebd43953c8d2c/1-0000.mp3", duration = 70.8963265, start = 0},
  },
}
P.transport["quest:473"] = {
  hash = "043476",
  fullHash = "043476",
  text = "Report to Captain Stoutfist. In Menethil Harbor, Valstag Ironjaw sends proven fighters to Captain Stoutfist as the Dragonmaw threat spreads across the Wetlands. The harbor is an Alliance military post, and the captain directs its defense from the keep. For years, dwarven mountaineers have watched Dun Algaz's narrow passes. Now the Dragonmaw clan has returned beyond Loch Modan. The orcs push outward, raise encampments, and threaten the marshlands. Valstag Ironjaw knows the pass is only the first part of keeping the road to Ironforge safe. Captain Stoutfist directs Menethil Harbor's defenses from the war room inside Menethil Keep. Dark Iron saboteurs, local beasts, and marsh murlocs threaten the port. So the captain relies on capable volunteers to meet dangers beyond the walls. Valstag sends you to carry out direct orders against the Dragonmaw war machine.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_473-f9d2256e172dd8c594bf/1-0000.mp3", duration = 58.9322449, start = 0},
  },
}
P.transport["quest:4736"] = {
  hash = "7cb5ec",
  fullHash = "7cb5ec",
  text = "In Search of Menara Voidrender. Alliance warlocks cross the sea to find Menara Voidrender in the Barrens. From Strahad Farsan's tower above Ratchet, she teaches seasoned practitioners to craft tools and garments that strengthen their hold over demons. Briarthorn can tell when a warlock has moved beyond basic demonology and resisted corruption. He sends those pupils beyond Ironforge, across the sea to Kalimdor, rather than keeping them beneath the mountain. There, an artisan of greater skill can teach them practical felcraft. Strahad Farsan keeps a solitary tower on the bluffs above Ratchet. Warlocks often set aside racial and political borders to survive in a world wary of dark magic. Menara Voidrender stays at Strahad's sanctuary and works with warlocks of every allegiance. She helps them sharpen their craft and keep their summoned fiends bound.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4736-93b70b9b58645537fe58/1-0000.mp3", duration = 56.555102, start = 0},
  },
}
P.transport["quest:4737"] = {
  hash = "1e51d9",
  fullHash = "1e51d9",
  text = "In Search of Menara Voidrender. Zevrost sends warlocks from Orgrimmar to find Menara Voidrender in the Barrens. He fears fel magic will enslave them, yet directs them to a mentor who can help shape powerful arcane vestments. Beneath Orgrimmar, warlocks gather in the Cleft of Shadow, where others tolerate them uneasily. Zevrost, one of their bitter tutors, scorns acolytes who seek mastery of the dark arts. He believes each step deeper into fel magic brings them closer to enslavement. To Zevrost, demonic addiction will claim every practitioner in time. Even the most disciplined scholar will become a thrall of the Twisting Nether. Zevrost knows that other warlocks see a different path. Word has reached Orgrimmar of Menara Voidrender, a skilled warlock on the bluffs above Ratchet, the neutral goblin port. Menara seeks promising disciples to help craft special implements for their arcane might. For warlocks eager to advance their craft, her summons begins the making of the legendary Enchanted Gold Bloodrobe. Menara waits high above Ratchet, where warlocks face the hard truths of their order. They must set aside racial and cultural rivalries and support one another. The demons they bargain with show neither prejudice nor mercy to anyone who falters. Sharing knowledge and crafting protective vestments is practical, not charitable. Warlocks need both to survive the hostile beings they bind to their service.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4737-4b0beaba0fa2fd607601/1-0000.mp3", duration = 101.32898, start = 0},
  },
}
P.transport["quest:4738"] = {
  hash = "3d1af1",
  fullHash = "3d1af1",
  text = "In Search of Menara Voidrender. An Alliance warlock is sent across the Great Sea to seek Menara Voidrender. From a tower above Ratchet, she trains warlocks of every faction in binding and artifact making. Beneath the Slaughtered Lamb in Stormwind, Demisette Cloyce trains warlocks with strict standards. When a student is ready to make powerful items, Demisette seldom believes they are prepared. Yet the cabal's higher authorities order the student onward, far from the capital, to prove their mettle. Menara Voidrender keeps her laboratory in a stone tower above Ratchet, the goblin port in the arid hills of the Barrens. There she takes apprentices of every race and allegiance, beyond Stormwind's laws and Orgrimmar's watch. The fiends and demons warlocks face bear the same malice toward every mortal soul.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4738-65cde18f5457e802ea94/1-0000.mp3", duration = 58.2791837, start = 0},
  },
}
P.transport["quest:4739"] = {
  hash = "c3e5b5",
  fullHash = "c3e5b5",
  text = "In Search of Menara Voidrender. Menara Voidrender awaits Horde warlocks seeking deeper study in Ratchet. From the Undercity, they cross the Great Sea to her refuge above the port. Kaal Soulreaper watches warlocks grow more skilled in the Undercity. When one outgrows simple hexes and impish thralls, he sends them across the Great Sea for specialized instruction. Demonic control leaves little room for error. A skilled mentor can help a warlock survive the Nether’s volatile powers. Strahad Farsan’s tower rises from a high bluff above Ratchet. There, away from the scrutiny of city guards, practitioners such as Menara Voidrender teach younger initiates. Warlocks from different backgrounds set tribal and political rivalries aside. The demons they bargain with will consume human, orc, or Forsaken alike if their summoner’s will falters.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4739-0aacad406df5e34e28c1/1-0000.mp3", duration = 58.6187755, start = 0},
  },
}
P.transport["quest:474"] = {
  hash = "542a05",
  fullHash = "542a05",
  text = "Defeat Nek'rosh. In the Wetlands, the Alliance closes in on Nek'rosh and his Dragonmaw warband. Their catapults are burning, but Menethil Harbor remains under threat until the chieftain falls. The Dragonmaw have long plagued the marshlands of Khaz Modan. They hold fortified camps and threaten Menethil Harbor's sea lanes. After the clan's catapults are found and burned, the marsh's defenders strike at the warband's leader. Chieftain Nek'rosh commands the local orcs and remains the last obstacle to breaking the siege. Without him, the remaining raiders lose their leader's direction. Bring Nek'rosh's severed head to Captain Stoutfist in Menethil Harbor, and Ironforge's garrison will claim a major victory. The Dragonmaw have lost their heavy siege weapons and their chieftain, a blow they are unlikely to recover from quickly.\n\nMenethil Harbor is the Alliance's main lifeline between Lordaeron and Khaz Modan. With Nek'rosh fallen, its docks and trade vessels are safer from sudden attack.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_474-187f1a363b09723e5d34/1-0000.mp3", duration = 71.8106122, start = 0},
  },
}
P.transport["quest:4767"] = {
  hash = "b8d4fa",
  fullHash = "b8d4fa",
  text = "Wind Rider. At Freewind Post, Elu hopes to join the Horde’s wind riders. He asks you to gather wild wyvern eggs at Highperch, where the Horde needs more mounts. Across Kalimdor, wind riders carry Horde couriers, scouts, and warriors over long distances. At Freewind Post, young tauren Elu hopes to join their ranks. The Horde needs more mounts, so Elu has been asked to help find new wyverns for its master wind riders. He asks travelers for help. Highperch rises above the Thousand Needles mesas and is a prime nesting ground for wild wyverns. To gather viable eggs, you climb the cliffs and face adults guarding their roosts. Elu hopes the eggs will prove his dedication. Then he can begin raising and training wyverns for the Horde’s flight masters.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4767-31f9519b7c02d9609a81/1-0000.mp3", duration = 43.0236735, start = 0},
  },
}
P.transport["quest:4770"] = {
  hash = "4f5836",
  fullHash = "4f5836",
  text = "Homeward Bound. Pao'ka Swiftmountain is stranded among the wyverns of Highperch. You are helping the young tauren naturalist reach the canyon floor and return toward Whitereach Post after he wandered into their nesting grounds. Pao'ka Swiftmountain came to Thousand Needles with the elder Motega Firemane. They meant to study the canyon floor's wildlife and towering stone pillars. Curious and too sure of himself, Pao'ka went alone into Highperch to watch its wyverns up close. The territorial beasts drove him off. Now the young scholar has spent days frightened and stranded among the crags. Aggressive wyverns guard their clutches and high roosts throughout Highperch. You clear a way through the nesting predators so Pao'ka can reach level ground. The panicked youth cannot defend himself in the open, and relies on passing Horde travelers to fend off the wyverns. He needs to reach the safer canyon path leading east.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4770-1d0a19af984fa12cf497/1-0000.mp3", duration = 56.5812245, start = 0},
  },
}
P.transport["quest:480"] = {
  hash = "73a340",
  fullHash = "73a340",
  text = "The Weaver. In Silverpine Forest, Ataeric works to wake a dormant ley node for Dalaran. At the Sepulcher, Shadow Priest Allister sends you to stop the archmage and take his staff, lest Dalaran’s magic threaten Forsaken control of southern Lordaeron. After your earlier inquiries into Ambermill and Dalaran’s movements, the Forsaken learned that its wizards seek to wake a dormant ley energy node in Silverpine Forest. Dalaran could draw on that concentrated arcane power to strengthen its position and threaten the Undercity’s hold over southern Lordaeron.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_480-172993c561cc670fe4f4/1-0000.mp3", duration = 39.6538776, start = 0},
  },
}
P.transport["quest:4821"] = {
  hash = "b8d22a",
  fullHash = "b8d22a",
  text = "Alien Egg. At Freewind Post, Hagar Lightninghoof sends you after an egg guarded by serpents beneath the stone needles. He wants it brought back before anything inside can break free. Hagar Lightninghoof hears of an unusual egg in the serpent dens below the stone needles. The canyon serpents guard it as though it were their own brood, striking at travelers who draw near. Concerned for the hunting grounds, Hagar asks you to find the nest, pass its sentries, and bring the strange egg back for study.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4821-74f8fe54cf96853b6a09/1-0000.mp3", duration = 31.7126531, start = 0},
  },
}
P.transport["quest:484"] = {
  hash = "6f94ff",
  fullHash = "6f94ff",
  text = "Young Crocolisk Skins. In Menethil Harbor, James Halloran needs fresh skins from young marsh crocolisks. Their cured hides are wanted across the sea, keeping his trade supplied. Bring him the softer skins, and you earn his trust for more leatherworking work. Menethil Harbor links the Eastern Kingdoms with distant continents. Its trade draws on the surrounding marsh, where James Halloran tans and cures hides from the region's reptilian predators. Merchants and ships carry his leather goods to far ports, so his workshop needs a steady supply. Einar brings Halloran regular hauls of mature hides, but those are too firm for some luxury goods. Halloran turns to travelers to find softer leather in the shallow bogs just outside Menethil's palisades. The young crocolisks' skins must stay intact for his careful curing.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_484-0b70964b91d5260138a4/1-0000.mp3", duration = 50.9387755, start = 0},
  },
}
P.transport["quest:4841"] = {
  hash = "9f4f70",
  fullHash = "9f4f70",
  text = "Pacify The Centaur. At Freewind Post, you face the Galak camp below. Cliffwatcher Longhorn wants the threat at Splithoof Crag cut down before it reaches the tauren post. Freewind Post stands on a desert mesa above Thousand Needles. From there, the tauren watch the canyon floor, where enemies gather beneath the ropes and lifts. The Galak centaur have built a war camp at Splithoof Crag, directly north along the canyon wall. Their camp threatens the supply lines and tauren movement through the needles. Cliffwatcher Longhorn sends Horde travelers to weaken the Galak ranks. The tauren believe Freewind Post will be safe only when the centaur vanguard is broken in its own camp. Galak Scouts, Galak Wranglers, and Galak Windchasers all face the fight. Their deaths may blunt an attack before it reaches the post.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4841-35f120d15f92184e5e37/1-0000.mp3", duration = 50.2857143, start = 0},
  },
}
P.transport["quest:4865"] = {
  hash = "9d0eee",
  fullHash = "9d0eee",
  text = "Serpent Wild. At Freewind Post, Hagar Lightninghoof sends you northwest after signs of Arikara emerge in Thousand Needles. Strange eggs point to a vengeance spirit from tauren legend, and Hagar seeks Motega Firemane's counsel at Whitereach Post. Strange eggs have appeared across Thousand Needles, and local tauren fear an ecological disaster. Their signs point beyond ordinary predators to Arikara, a vengeance spirit from old tauren tales. The evidence shakes Hagar Lightninghoof. A threat he knew only from fireside lore now faces the canyon. Hagar Lightninghoof seeks Motega Firemane's counsel because this danger reaches beyond physical defense. Motega watches over the canyon floor from Whitereach Post, northwest of Freewind Post. As a spiritual guide versed in the Needles' traditional omens, he may help the Horde understand the rising spirit and decide whether to appease or destroy it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4865-4d190bfef8977a77eeb7/1-0000.mp3", duration = 59.2195918, start = 0},
  },
}
P.transport["quest:4881"] = {
  hash = "33d128",
  fullHash = "33d128",
  text = "Assassination Plot. In Thousand Needles, centaur move against Kanati Greycloud at Whitereach Post. Intercepted orders reveal their plan to attack the tauren hunter. Kanati Greycloud is a tauren hunter camped at Whitereach Post in contested Thousand Needles. The small post lies southwest of the Great Lift, amid warring centaur clans and dangerous wildlife. The local centaur see his camp as a bold intrusion into their territory. They mean to kill Greycloud and discourage further Horde expansion through the canyon.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4881-58be2a87babd4b44ef6b/1-0000.mp3", duration = 36.0228571, start = 0},
  },
}
P.transport["quest:4904"] = {
  hash = "037a41",
  fullHash = "037a41",
  text = "Free At Last. Lakota Windsong is making her way back to Thalia Amberhide at Freewind Post. After refusing Arnak Grimtotem, she was taken to his stronghold above Thousand Needles and now needs protection on the journey home. Arnak Grimtotem wanted Lakota Windsong for his bride. When she refused, he returned by night and attacked her home. Lakota's brother tried to defend her, but Arnak struck him down. Then he dragged Lakota to Darkcloud Pinnacle. Darkcloud Pinnacle rises above Thousand Needles, with high wooden bridges linking its spires. Grimtotem warriors guard the heights. As Lakota makes her way down, you fight off bandits who mean to seize her before she reaches the canyon floor. Lakota reaches the canyon floor and makes her way to safety at Freewind Post. There, Thalia Amberhide welcomes her with relief, though she grieves for Lakota's brother. Thalia gives his remaining belongings to those who brought Lakota home alive.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4904-805b2d361008d756d670/1-0000.mp3", duration = 71.8628571, start = 0},
  },
}
P.transport["quest:4921"] = {
  hash = "107e3f",
  fullHash = "107e3f",
  text = "Lost in Battle. At the Crossroads, Mankrik searches for his wife, lost in a Bristleback ambush at a tauren camp. Wounded and unable to look for her himself, he asks travelers to search the Barrens for any sign of her. Mankrik, an orc warrior at the Crossroads, fought beside his wife at a small tauren camp. Bristleback quilboar suddenly swarmed them. His wife held off three attackers alone, but fresh reinforcements cut her off from Mankrik in the fight. Mankrik faced the advancing quilboar in a blind rage, but their numbers soon brought him down. A passing tauren druid found him near death on the Gold Road and tended his wounds. Still too injured to search for his wife, Mankrik asks travelers passing through the Crossroads to look across the Barrens and bring back any sign of her.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4921-035de2c0838070e5d8bc/1-0000.mp3", duration = 49.2408163, start = 0},
  },
}
P.transport["quest:493"] = {
  hash = "fc00bc",
  fullHash = "fc00bc",
  text = "Journey to Hillsbrad Foothills. Renferrel sends his research south to Tarren Mill, where Forsaken apothecaries press on with their plague studies. You carry his notes from Silverpine Forest to Apothecary Lydon in Hillsbrad Foothills. Since breaking free of the Lich King's control, Lady Sylvanas Windrunner has pursued a New Plague that could destroy both the living and the Scourge. The Royal Apothecary Society works under the Banshee Queen's relentless pressure to create it. Its researchers are spread across Lordaeron, so they share chemical data and test findings to hasten their work. Apothecary Renferrel works from the Sepulcher in Silverpine Forest. He sends you south with his recent findings for Apothecary Lydon. Your road leaves the pine woods and crosses open pastures in Hillsbrad Foothills. Tarren Mill lies beneath the Alterac Mountains, an outpost where the Forsaken stage their research.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_493-abcdd109117a4d4d7a0d/1-0000.mp3", duration = 64.1567347, start = 0},
  },
}
P.transport["quest:494"] = {
  hash = "322b03",
  fullHash = "322b03",
  text = "Time to Strike. At Hillsbrad's border, Lesh sends a warning east to Tarren Mill. Her coded words carry word from a quiet watch to Forsaken plans against the human settlers. Deathstalker Lesh watches the valley from high ground near the border of Silverpine Forest and the Hillsbrad Foothills. Below her, human settlers and militia move through the valley. The Deathstalkers watch enemy settlements for the Undercity before its troops deploy. Lesh holds her post and asks passing Horde travelers to carry her gathered intelligence down the road to Tarren Mill.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_494-c1ea6da57994a29511cb/1-0000.mp3", duration = 36.1012245, start = 0},
  },
}
P.transport["quest:496"] = {
  hash = "e41e91",
  fullHash = "e41e91",
  text = "Elixir of Suffering. In Tarren Mill, Apothecary Lydon prepares a brew meant to kill the living. He needs animal reagents from the surrounding foothills. Tarren Mill is a Forsaken stronghold in the Hillsbrad Foothills and a research station for the Royal Apothecary Society. Apothecary Lydon works there, surrounded by green countryside he despises. He longs to see human settlements poisoned and conquered. For his experimental Elixir of Suffering, he needs potent, virulent ingredients from nearby creatures. Apothecary Lydon sends hunters into the wilds around Tarren Mill for Gray Bear tongues and the rare ichor of Moss Creepers. Unholy alchemy refines these animal substances into the base of a lethal mixture. He means it to kill living trespassers across Hillsbrad.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_496-ede50cee78317651fdc6/1-0000.mp3", duration = 60.1077551, start = 0},
  },
}
P.transport["quest:4966"] = {
  hash = "66d15c",
  fullHash = "66d15c",
  text = "Protect Kanati Greycloud. At Whitereach Post in Thousand Needles, you join Kanati Greycloud as Galak assassins close in. Their orders name the tauren for death. At Whitereach Post, Kanati Greycloud finds centaur orders naming him as a target. The Galak centaur have long fought the nomadic tauren and their Horde allies. Raiding supply paths is not enough for them. They also seek to kill those who settle in their canyons. Kanati suspects the Galak will strike soon, and their numbers may be greater than he first thought. So he asks travelers at the post to stand with him. When the assassins attack, Kanati holds his ground beside his allies. Their blades and spells can break the ambush before the centaur kill him.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4966-91997a20a4c82ce2da4c/1-0000.mp3", duration = 47.124898, start = 0},
  },
}
P.transport["quest:498"] = {
  hash = "0afa1f",
  fullHash = "0afa1f",
  text = "The Rescue. In Tarren Mill, Krusk needs your help after Syndicate bandits seize the orc scouts sent to Durnholde Keep. Thrall sent them to investigate the growing threat and retrieve an object from the keep. Warchief Thrall sent orc warriors to Hillsbrad Foothills to investigate the growing Syndicate threat and retrieve an object from Durnholde Keep. Gol'dir led them toward the fortress ruins, but the Syndicate overwhelmed the scouts in an ambush. Krusk broke free and limped back across the river to Tarren Mill. The human bandits captured Drull, Tog'thar, and Gol'dir.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_498-42badfa4887f43444375/1-0000.mp3", duration = 37.3812245, start = 0},
  },
}
P.transport["quest:499"] = {
  hash = "d6cc49",
  fullHash = "d6cc49",
  text = "Elixir of Suffering. In Tarren Mill, Apothecary Lydon tests a poison for the Royal Apothecary Society. He wants to learn how quickly it kills before it is used more widely. Apothecary Lydon works in Tarren Mill, making chemical weapons for the Dark Lady's ambitions. His blight is meant to destroy the Alliance's living humans and the Scourge's undead horrors. Once he has the needed reagents, Lydon mixes them into a foul brew called the Elixir of Suffering. He wants to see its power before the Society uses it more widely.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_499-bba44ed52c21129d6b6c/1-0000.mp3", duration = 37.1722449, start = 0},
  },
}
P.transport["quest:5"] = {
  hash = "b8614a",
  fullHash = "b8614a",
  text = "Jitters' Growling Gut. In Raven Hill, Jitters is starving and afraid, with only weeds and insects to eat. He asks you to travel east to Darkshire for Chef Grual’s famous Dusky Crab Cakes. Raven Hill shelters ravenous undead and lurking beasts among its ruined streets. Jitters has hidden there for weeks, moving through crumbling shanties beneath a sky that never seems to brighten. He has found only grubs in the dirt and wild weeds to eat. Hunger and fear wear him down, far from ordinary comforts. Jitters longs for a taste of safety: the seasoned patties made at the Scarlet Raven Tavern in Darkshire. He asks you to cross the haunted road and speak with Chef Grual. If the chef agrees to make Dusky Crab Cakes, a hot meal may quiet Jitters’ growling gut.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5-4cd8b3722197d6004a63/1-0000.mp3", duration = 48.9795918, start = 0},
  },
}
P.transport["quest:501"] = {
  hash = "b31bdd",
  fullHash = "b31bdd",
  text = "Elixir of Pain. In Tarren Mill, Apothecary Lydon seeks mountain lion blood for a lethal brew. His work serves the Royal Apothecary Society’s drive to perfect the New Plague. Apothecary Lydon takes little comfort in Tarren Mill. Hillsbrad’s blooming meadows and brisk mountain air offend him. Like many in the Royal Apothecary Society, he gives himself to Lady Sylvanas Windrunner and the New Plague. The Society works to perfect this engineered scourge, made to kill the living and bring retribution to its enemies. Apothecary Lydon seeks ingredients for a poisonous mixture among animals that prowl the foothills and slopes toward the Alterac Mountains. He believes mountain lion blood holds what he needs for an Elixir of Pain. So he sends agents into the wilds for ten vials. The blood will support the Society’s continuing chemical trials along the contested southern front.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_501-246b67c89701bbda0c78/1-0000.mp3", duration = 66.7428571, start = 0},
  },
}
P.transport["quest:502"] = {
  hash = "8ba8a7",
  fullHash = "8ba8a7",
  text = "Elixir of Pain. In Tarren Mill, the Elixir of Pain is ready for a trial on Farmer Ray’s dog, Stanley. Apothecary Lydon prepares the draught for the Royal Apothecary Society. Apothecary Lydon serves the Royal Apothecary Society and Lady Sylvanas Windrunner from Tarren Mill. He gathers fresh blood from local wildlife and brews it into the volatile Elixir of Pain. The Society seeks proof in the field of how its experimental poisons and mutagens affect living bodies. Lydon sends his agents to the northern farm in Hillsbrad Fields, beyond the human defenders. Farmer Ray keeps his dog Stanley there. An agent pours the draught into an open hand and offers it as an ordinary treat. Stanley does not know what he is being given.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_502-feeafb4a3265e0c65170/1-0000.mp3", duration = 52.6367347, start = 0},
  },
}
P.transport["quest:5042"] = {
  hash = "4df610",
  fullHash = "4df610",
  text = "Agamaggan's Strength. In Camp Taurajo, Mangletooth offers Horde travelers strength drawn from Blood Shards. The captive Razormane shaman honors the ancient boar demigod Agamaggan and hates the rival Bristleback tribe. Quilboar honor Agamaggan, an ancient boar demigod. They say his spilled blood formed the red Blood Shards scattered across the Barrens. The crystals are sacred to them, and their power strengthens the fighters who stand at the front. Mangletooth, an elder Razormane shaman held captive in Camp Taurajo, offers that strength to Horde champions. He says your foes will cower before you as they do before the mightiest Razormane champions. Mangletooth offers his strength out of spite. Orcs and tauren captured and caged the old quilboar, whose Razormane tribe is at war with the rival Bristleback. He cannot break his chains and slaughter them himself, so he trades Agamaggan's gifts for help against them. Those who destroy Bristleback tribes and take the sacred Blood Shards from their lands earn his blessing.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5042-e9a515be264794374252/1-0000.mp3", duration = 72.5420408, start = 0},
  },
}
P.transport["quest:5043"] = {
  hash = "619574",
  fullHash = "619574",
  text = "Agamaggan's Agility. In Camp Taurajo, Mangletooth offers a blood shard ritual. The captive quilboar channels his ancient boar god's power, blessing those who bring him shards from the Barrens with swift movement and sure aim. Crimson blood shards jut from the Barrens soil, especially near quilboar camps and great brambles. Quilboar tradition says the crystals formed from Agamaggan's spilled blood. The Great Boar Ancient fell fighting the Burning Legion in the War of the Ancients. Though caged in Camp Taurajo, elder quilboar Mangletooth can channel the stones' divine power for anyone who brings him shards. Quilboar hunters and scouts prize ruthless accuracy and blinding quickness in the scrublands. For four blood shards, Mangletooth calls on the fallen demi-god's power. He lends the petitioner the instincts and supple grace of his people's finest stalkers. Mangletooth grunts at outsiders, yet honors his pact and weaves Agamaggan's power into a temporary mantle of agility.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5043-364321adfc523c47e9a4/1-0000.mp3", duration = 71.8889796, start = 0},
  },
}
P.transport["quest:5044"] = {
  hash = "67a358",
  fullHash = "67a358",
  text = "Wisdom of Agamaggan. At Camp Taurajo, Mangletooth offers Horde spellcasters a way to draw on Agamaggan’s power. The captive quilboar asks for blood shards in return. At Camp Taurajo, the Horde holds Mangletooth prisoner. The quilboar trades his people’s magical secrets for blood shards, crimson crystals said to have formed from Agamaggan’s spilled blood. The towering boar Demigod fell in the War of the Ancients. Mangletooth says his tribes’ geomancers and shaman use the shards to channel divine power in their rituals. Some shard offerings bring physical resilience or swiftness. Mangletooth’s Wisdom ritual instead sharpens the mind and arcane ability. For four blood shards, he calls on Agamaggan’s spirit to grant you cunning in your confrontations. Then he reminds you that you are mortal.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5044-28aa44b1f89aed9208ad/1-0000.mp3", duration = 60.6563265, start = 0},
  },
}
P.transport["quest:5045"] = {
  hash = "48b0df",
  fullHash = "48b0df",
  text = "Rising Spirit. At Camp Taurajo, Mangletooth offers you an old blessing drawn from Agamaggan's power. Bring blood shards taken from his Bristleback rivals, and he will strengthen your will and spirit. In a cage at Camp Taurajo, Mangletooth knows the geomancy and ancestral magic of the quilboar. He takes pride in his people's devotion to their creator, the Great Boar Agamaggan. To Mangletooth, an unbroken spirit carries a warrior onward when strength fails and defeat draws near. Mangletooth asks you for blood shards to raise your spirit. These crystals hold Agamaggan's ancient blood, which seeped into the red earth ten thousand years ago. Bring shards gathered across the Barrens, especially from his Bristleback enemies. Then Mangletooth can channel their power into a blessing that strengthens your will.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5045-3c19f899f1c6ade9b61c/1-0000.mp3", duration = 59.7942857, start = 0},
  },
}
P.transport["quest:5046"] = {
  hash = "4573a3",
  fullHash = "4573a3",
  text = "Razorhide. In Camp Taurajo, Mangletooth offers a rite to those who bring him blood shards. The captive quilboar trades Agamaggan’s life essence for a blessing that hardens the skin before battle. The quilboar trace their power to Agamaggan, the Great Boar who died fighting the Burning Legion thousands of years ago. His blood sank into the Barrens and hardened into crystalline shards, still alive with ancient power. The Horde and quilboar remain sworn enemies. Yet Mangletooth, held in a cage at Camp Taurajo, may share sacred knowledge in exchange for these fragments. Quilboar are born with thick hides and protective quills. Their warriors call on Agamaggan to harden their skin against blades and claws. Mangletooth can perform the rite for outsiders, channeling four blood shards to strengthen their defenses and help keep their bones unbroken in the wilds.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5046-66e887df599895c7602e/1-0000.mp3", duration = 63.4253061, start = 0},
  },
}
P.transport["quest:5052"] = {
  hash = "a6db06",
  fullHash = "a6db06",
  text = "Blood Shards of Agamaggan. Across the Barrens, the Blood Shards of Agamaggan still hold the power of a fallen boar god. Quilboar say his blood sank into the earth and hardened into red stones. At Camp Taurajo, captive Mangletooth trades that power to the Horde for his own reasons. Quilboar lore tells how Agamaggan fell ten thousand years ago in the War of the Ancients. His blood raised giant thorn mazes across the plains, then sank into the soil and seeped into minerals. In time, it hardened into blood-red stones.\n\nThe quilboar honor the shards as sacred remnants of their creator. They gather them from mineral seams and holy grounds, then use them as totems in battle and sorcery. The tauren hold Mangletooth in a cage at Camp Taurajo. He bears a bitter grudge against his own kind, saying his tribe betrayed him and cast him out.\n\nWithout freedom or his people's magic, he bargains with you for blood shards. Their power lets him reach Agamaggan's magic despite his captivity, then channel it to Horde champions. He takes pleasure in turning that power against the quilboar who rejected him. Mangletooth speaks with reverence of Razorfen, the quilboar's holiest sanctuary to the south. The tribes say the vast briars of Razorfen Kraul and Razorfen Downs grew from Agamaggan's colossal skeleton and tusks.\n\nThey believe Razorfen Downs lies within the demigod's gaping maw. It is a holy threshold that devours and crushes any who enter without the Boar God's favor.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5052-7bd8caca1664a0e24194/1-0000.mp3", duration = 94.6155102, start = 0},
  },
}
P.transport["quest:5062"] = {
  hash = "2ec53c",
  fullHash = "2ec53c",
  text = "Sacred Fire. At the Boiling Pool, hunters seek Incendia Agave for a sacred flame meant to call Arikara from the canyons of Thousand Needles. Motega Firemane asks you to prepare the sacred fire of life, an ancient flame that calls Arikara. The monstrous wind serpent cannot be tracked across the canyon floor. You must draw her to the fire instead. Ordinary kindling will not feed the flame. It needs rare Incendia Agave, which grows around the scalding waters of Thousand Needles. Incendia Agave grows near the Boiling Pool, below Darkcloud Pinnacle. You brave blistering waters and steam elementals drifting through the mists to gather its spiky leaves. Many bushels lie beneath the surface. The hot lake water tests every hunter sent to collect them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5062-747479e81511bcd6a845/1-0000.mp3", duration = 58.9061224, start = 0},
  },
}
P.transport["quest:5064"] = {
  hash = "e0cf13",
  fullHash = "e0cf13",
  text = "Grimtotem Spying. At Freewind Post, Cliffwatcher Longhorn sends you to learn what the Grimtotem are planning. Three unknown couriers visited Darkcloud Pinnacle, and guarded notes lie scattered through their village. Their words may threaten the tauren settlements of Thousand Needles. Freewind Post clings to high spires, where its defenders watch their hostile cousins. The Grimtotem have long resented the Horde and kept to strongholds atop Darkcloud Pinnacle. Then Cliffwatcher Longhorn noticed a change. Three unknown agents arrived over several weeks and met secretly with clan leaders. He suspects they brought orders or proposed alliances against Thunder Bluff's presence in the canyon. Darkcloud Pinnacle is a fortified village of sheer mesas joined by wooden rope bridges. Dense patrols of hostile Grimtotem warriors and shamans guard the way in. Longhorn's scouts found the agents' messages locked in separate chests among the central dwellings and outer bluffs. You cross the settlement to recover all three notes and take the clan's private words under its watchful eyes.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5064-9df3cb8ca94d0cd24af8/1-0000.mp3", duration = 64.1044898, start = 0},
  },
}
P.transport["quest:5088"] = {
  hash = "97b1bf",
  fullHash = "97b1bf",
  text = "Arikara. From Thunder Bluff, Magatha Grimtotem warns that Arikara may be hunting High Chieftain Cairne Bloodhoof. She sends Horde adventurers to summon and slay the ancient wind serpent at the burial spires of Thousand Needles. Magatha Grimtotem enchants refined Incendia powder to call Arikara. She warns that ancient tauren traditions have changed too quickly under the new Horde alliance. Those changes, she says, stirred the vengeance of the ferocious wind serpent spirit. So she sends you south to the canyon of Thousand Needles. There, among the elevated burial sites of Darkcloud Pinnacle, you are to cast the powder onto a ritual pyre.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5088-ef742febee0d11cc22d3/1-0000.mp3", duration = 47.7257143, start = 0},
  },
}
P.transport["quest:509"] = {
  hash = "147a4c",
  fullHash = "147a4c",
  text = "Elixir of Agony. In Hillsbrad, the Elixir of Agony is part of Lydon's work against the living and the Scourge. In Tarren Mill, you gather Mudsnout Blossoms for the Royal Apothecary Society's experiments under Lady Sylvanas. The Scourge ravages the north, while the Alliance clings to towns such as Southshore. In Tarren Mill, Apothecary Lydon works under the Dark Lady's command to develop a plague against both. He finds alchemy tedious, yet gathers potent organic toxins from the countryside. With them, he brews elixirs meant to hasten the destruction of Sylvanas's enemies. Nethander Stead lies south of Tarren Mill and east of the river. The abandoned human farmstead is overrun by vicious Mudsnout gnolls, and Mudsnout Blossoms grow among its filth and neglected soil. These foul-smelling mushrooms hold concentrated organic poisons prized by the Royal Apothecary Society. You can cut through the gnoll packs or weave quietly past their ramshackle camps to gather them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_509-f3d4f324cd4819a28f39/1-0000.mp3", duration = 71.4187755, start = 0},
  },
}
P.transport["quest:513"] = {
  hash = "3b99a6",
  fullHash = "3b99a6",
  text = "Elixir of Agony. In the Undercity, the Elixir of Agony awaits its final treatment. Apothecary Lydon sends his freshly mashed Mudsnout Composite from Tarren Mill to Master Apothecary Faranell, who must add a colloid of decay. The Royal Apothecary Society is developing a new plague for the Forsaken. The Royal Apothecary Society sends discoveries from regional researchers to the Undercity for refinement. In Tarren Mill, Apothecary Lydon has mashed local Mudsnout Blossoms into a composite. Only the capital's laboratory has the advanced reagents needed to make his work lethal. Master Apothecary Faranell works under pressure in the Apothecarium. The Scourge threatens from the north, while aggressive human populations press from the south. Lady Sylvanas Windrunner has demanded a potent new plague to defend the Forsaken. Lydon's composite may give Faranell the toxic breakthrough the Dark Lady expects.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_513-aa46f11b7b0576ebcd0e/1-0000.mp3", duration = 70.8179592, start = 0},
  },
}
P.transport["quest:5147"] = {
  hash = "5d7703",
  fullHash = "5d7703",
  text = "Wanted - Arnak Grimtotem. At Freewind Post, a Horde bounty calls for Arnak Grimtotem’s death. The authorities seek the violent Grimtotem exile for murder and kidnapping on the mesas above the canyon. Tauren of the Horde and the reclusive Grimtotem have long been at odds. Arnak worsened that strife by murdering a tauren and abducting the victim’s sister, Lakota Windsong. Branded an outcast, he drew the notice of Cliffwatcher Longhorn at Freewind Post. Longhorn sanctioned an open bounty calling for Arnak’s death. Arnak has taken refuge on the high northern cliff mesas of Darkcloud Pinnacle. Grimtotem encampments spread across the high crags near the entrance to Razorfen Downs, linked by rope bridges. Lakota Windsong is held captive there and waits for rescue. Anyone who reaches her must cross the Grimtotem bridges.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5147-1185744be356b4587e1a/1-0000.mp3", duration = 51.2, start = 0},
  },
}
P.transport["quest:515"] = {
  hash = "2e4c79",
  fullHash = "2e4c79",
  text = "Elixir of Agony. In the Undercity, Faranell prepares Lydon's mixture for a deadly purpose. The Royal Apothecary Society needs reagents from the coast and alchemical draughts to make its new plague ready. Apothecary Lydon sent his Mudsnout Blossom mixture from gnoll-held Nethander Stead to the Apothecarium in the Undercity. Master Apothecary Faranell leads the Royal Apothecary Society, and he saw the mixture's grim potential at once. Its toxic properties pleased him, so he added his own colloid of decay. Then he named the catalysts that could turn it into a weapon. To activate the mixture's contaminating agents, Lydon needs exact reagents in Tarren Mill. Faranell calls for a restorative draught of Strong Troll's Blood to feed and steady the chemical reaction. He also needs organic parts from Hillsbrad's southern shore: scales from the serpentine Daggerspine naga and eyes from the coastal Torn Fin murlocs.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_515-c1561bf149d70f8c5aa1/1-0000.mp3", duration = 69.7730612, start = 0},
  },
}
P.transport["quest:5151"] = {
  hash = "0bf643",
  fullHash = "0bf643",
  text = "Hypercapacitor Gizmo. In Thousand Needles, Wizlo Bearingshiner waits at Whitereach Post after a centaur ambush. He needs his invention back from the wreckage, where a caged panther wears it around its neck. Beneath Thousand Needles' sandstone spires, centaur guard the canyon floor. Just north of Whitereach Post, they overran a trade caravan, killed its travelers and plundered the wagons. Only Wizlo Bearingshiner, a goblin tinkerer, escaped. He limped back to safety. The centaur left one ruined wagon untouched, though they looted nearly every other valuable scrap. Inside its transport cage, a ferocious, enraged panther remains bound with Wizlo's prized hypercapacitor gizmo fastened around its neck. The centaur feared the beast and left the cage closed. Now Wizlo entrusts its key to mercenaries willing to face the predator and reclaim his invention.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5151-d176cd4678551a72d3d1/1-0000.mp3", duration = 54.9355102, start = 0},
  },
}
P.transport["quest:516"] = {
  hash = "0e0d5c",
  fullHash = "0e0d5c",
  text = "Beren's Peril. In southern Silverpine Forest, Shadow Priest Allister moves against Scourge gathering in a hidden cave. The Forsaken hope to strike before the undead begin their offensive. Shadow Priest Allister has heard that servants of the Lich King gather deep in southern Silverpine Forest. Their growing numbers threaten Forsaken operations across the region. So Allister sends scouts to strike first and destroy the Scourge in their secluded lair before they can mobilize. South of Ambermill, the Dalaran-aligned settlement, a hidden cave cuts into the hills. Its rough slopes make the cavern easy to miss, and the approach runs around the hills’ southern face. Ravenclaw drudgers and guardians dwell within. Destroying these Scourge remnants helps the Forsaken hold their ground in the forest.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_516-d20daf00b3be63831ac5/1-0000.mp3", duration = 52.0097959, start = 0},
  },
}
P.transport["quest:517"] = {
  hash = "fef067",
  fullHash = "fef067",
  text = "Elixir of Agony. In Tarren Mill, Apothecary Lydon puts his Elixir of Agony to a deadly test. He sends Horde champions to Dun Garok for a keg of Shindigger Stout. Apothecary Lydon serves the Royal Apothecary Society and Lady Sylvanas from Tarren Mill. He has gathered lethal ingredients across Hillsbrad and finished a new concoction. Frogs and stray dogs cannot test its strength. Lydon wants to see what it does to living adversaries. Lydon needs a quiet way to carry his experiment. South of Hillsbrad, Ironforge dwarves hold the fortified stronghold of Dun Garok. He sends Horde agents into its underground barracks and mess halls. There, they must slip past dwarven rifles and axes to steal a keg of Shindigger Stout.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_517-883f72b356ebf1ce769f/1-0000.mp3", duration = 50.6514286, start = 0},
  },
}
P.transport["quest:524"] = {
  hash = "5be774",
  fullHash = "5be774",
  text = "Elixir of Agony. In Tarren Mill, Apothecary Lydon prepares a deadly poison for a cruel test. He plans to disguise it as stolen dwarven ale and use it on human prisoners. Apothecary Lydon gathers foul ingredients across the Hillsbrad Foothills and steals dwarven ale from Dun Garok. The Royal Apothecary Society has charged him with making a deadly brew called Elixir of Agony. Once mixed, the poison waits inside a keg that appears to hold ordinary mountain stout.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_524-06384e90a7f7472ee1c0/1-0000.mp3", duration = 38.164898, start = 0},
  },
}
P.transport["quest:527"] = {
  hash = "82fa84",
  fullHash = "82fa84",
  text = "Battle of Hillsbrad. Across Hillsbrad, the Forsaken strike at the farms that feed the human town. High Executor Darthalia directs the attack from Tarren Mill under Varimathras's command. High Executor Darthalia directs the Forsaken campaign from Tarren Mill. Varimathras in the Undercity has ordered her to break the human resistance in Hillsbrad Foothills. So Darthalia targets the northern fields before attacking the defended town. Those farms feed the town. Disrupting them cuts provisions to the human militia and brings disorder to the homesteads. The Forsaken press the human defenders while the Royal Apothecary Society prepares a plague meant to destroy the living and the Scourge. Darthalia uses the fighting to hold the humans down until the plague is ready. Farmer Ray and Farmer Getz are among the landowners killed in these early attacks.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_527-0988630e420cbe0ca3c3/1-0000.mp3", duration = 59.6897959, start = 0},
  },
}
P.transport["quest:528"] = {
  hash = "b166aa",
  fullHash = "b166aa",
  text = "Battle of Hillsbrad. In Hillsbrad, Forsaken forces press south after strikes on the northern farms. Horde operatives now hunt the peasants who fled to the orchards. Hillsbrad's human farms have come under attack, driving laborers south into the fields. After strikes on the northern farms, many flee to the orchards and pastures of Hillsbrad Fields. They hope to escape the advancing undead. High Executor Darthalia sees their flight as a chance to break the township's remaining labor force and morale. From Tarren Mill, High Executor Darthalia orders Horde forces to hunt the displaced laborers in the fields. The peasants have no protection. Their deaths choke Hillsbrad's food supply and weaken civilian resolve. For Darthalia and the Forsaken, each human killed tightens their hold over the surviving township and helps keep Lordaeron in Forsaken hands.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_528-76d3dfb0c7ee823b2f62/1-0000.mp3", duration = 57.0514286, start = 0},
  },
}
P.transport["quest:529"] = {
  hash = "e97512",
  fullHash = "e97512",
  text = "Battle of Hillsbrad. At Hillsbrad, the Forsaken press their advance against the humans who resist them. High Executor Darthalia orders the smithy in Hillsbrad Fields destroyed, hoping to cut off the weapons arming the local people. In the Hillsbrad Foothills, the Forsaken face fiercer resistance than High Executor Darthalia expected. Rural humans refuse to scatter or yield to the Deathstalkers and soldiers sent from Tarren Mill. The Forsaken learn that the peasantry fight with more than pitchforks and scythes. In the fields, they are being armed for war. At the southwestern edge of Hillsbrad Fields, Blacksmith Verringtan and his apprentices forge blades and armor for the militia from raw ore. Darthalia sends an operative to kill Verringtan, butcher his apprentices, and seize their stockpiled iron. She aims to weaken the settlement's defenses and use the metal in the eventual assault on Southshore.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_529-12a20c0465154e26eadd/1-0000.mp3", duration = 61.6228571, start = 0},
  },
}
P.transport["quest:530"] = {
  hash = "fa24ff",
  fullHash = "fa24ff",
  text = "A Husband's Revenge. In the Undercity, Raleigh Andrean sends you to hunt the man who murdered his wife. An engraved ring from Silverpine Forest stirs Raleigh Andrean's mortal memories. He recalls his close friend Valdred Moray, who murdered Raleigh's wife, Deliah. The Scourge's chill and undeath have dulled his grief and love. Yet his thirst for revenge remains, and you are sent to find Valdred.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_530-a8e45fbec9386553b718/1-0000.mp3", duration = 26.2530612, start = 0},
  },
}
P.transport["quest:532"] = {
  hash = "b0c24d",
  fullHash = "b0c24d",
  text = "Battle of Hillsbrad. In Hillsbrad town, Forsaken forces strike to break human rule. High Executor Darthalia directs the assault from Tarren Mill. Hillsbrad’s human defenders hold to their authority despite heavy losses in the fields and among the patrols. High Executor Darthalia knows the peasants and militia rally behind the town’s leaders. So she sends Forsaken operatives into the Town Hall to kill Magistrate Burnside and five councilmen. Without them, the town loses its command. Darthalia seeks to break Hillsbrad’s civic life as well as its leadership. She orders operatives to burn the Hillsbrad Proclamation, a political document bound to the settlement’s charter and pride. They also seize the town registry from surviving Alliance loyalists. Its official records and citizen rolls give Undercity’s intelligence a detailed view of the local people.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_532-363289eae7d3d8483a31/1-0000.mp3", duration = 61.1004082, start = 0},
  },
}
P.transport["quest:5321"] = {
  hash = "519d26",
  fullHash = "519d26",
  text = "The Sleeper Has Awakened. Kerlonian Evershade struggles to stay awake on the road from Darkshore to Maestra's Post in Ashenvale. Newly roused from a long sleep, he carries the Horn of Awakening and needs help past furbolgs and cultists. Kerlonian Evershade is a Druid of the Claw, newly awakened from sleep in the barrows. For millennia, druids communed with wild spirits through the Emerald Dream. The Third War called them to wake, but centuries of hibernation left Kerlonian struggling to stay conscious.\n\nHe set out south from Darkshore to meet Liladris Moonriver in Ashenvale, yet exhaustion soon overtook him. Sudden naps leave him helpless in the wilds, so he relies on a brass Horn of Awakening and passing allies to keep moving. The road from Darkshore into Ashenvale is dangerous for Kerlonian. In Twilight Vale, corrupted Blackwood furbolgs stalk the road. Farther south in Ashenvale, members of the Dark Strand cult lie in ambush. Sleep may lay Kerlonian down wherever he stands, so you need to keep watch and rouse him with the horn.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5321-d79467e5101626d7408c/1-0000.mp3", duration = 66.8473469, start = 0},
  },
}
P.transport["quest:536"] = {
  hash = "179183",
  fullHash = "179183",
  text = "Down the Coast. Along Hillsbrad's coast, Lieutenant Farren Orinelle leaves Southshore's defense to passing adventurers. Sent from Stormwind, he would rather drink ale than patrol while Torn Fin murlocs gather along the Western Strand. Lieutenant Farren Orinelle left Stormwind's city guard for a post in Southshore. The port feels dreary to him, and the harbor's fishy odor is more than he can bear. So he spends his days drinking at the inn instead of patrolling the frontlines. Marshal Redpath has ordered him to protect Southshore from nearby dangers, but Orinelle hires passing sellswords to do the work. The Western Strand runs along the coast west of Southshore. Orinelle scoffs at the murlocs as overgrown fish, yet the Torn Fin tribe threatens coastal travel and local shipping. Its tidehunters and oracles gather in camps along the breakers. There, they ambush anyone who strays too far from town walls, so clearing the shoreline means facing them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_536-96331554d69624be8a9b/1-0000.mp3", duration = 61.7534694, start = 0},
  },
}
P.transport["quest:539"] = {
  hash = "eb7b11",
  fullHash = "eb7b11",
  text = "Battle of Hillsbrad. At Azurelode Mine, Horde forces strike to cut iron shipments to Alliance armories. High Executor Darthalia has ordered Foreman Bonds and his crew killed. High Executor Darthalia marked Azurelode Mine as vital to human strength after the Horde seized the Hillsbrad Town Registry in earlier raids. The mine lies just south of Hillsbrad Fields. There, workers keep drawing rich iron ore for Alliance weaponsmiths and armories. If the mine stays open, Southshore can rearm and strengthen its garrisons, undoing Tarren Mill’s earlier victories. Darthalia orders Horde forces to kill Foreman Bonds, the human overseer, and a large part of his workforce. The attack reaches into the mine’s dark shafts to halt production. Southshore receives a clear warning: the Forsaken can strike its supply lines and isolated labor camps.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_539-6fc33a1ecc2d68e0884e/1-0000.mp3", duration = 56.5028571, start = 0},
  },
}
P.transport["quest:540"] = {
  hash = "e3a0b5",
  fullHash = "e3a0b5",
  text = "Preserving Knowledge. In Southshore, Loremaster Dibbs sends you into the Ruins of Alterac to save books from the ogres who have settled there. One worn leather volume matters most: it holds The Arm of Gri'lek, a work of ancient troll lore. Loremaster Dibbs fears for the books left in the Ruins of Alterac, now home to ogres. You search for the tomes they have looted and recover what you can. Dibbs would climb into the mountains to search too, but fears old bones would not survive the journey. Among the tomes, Loremaster Dibbs most wants a worn leather book containing The Arm of Gri'lek. Dibbs is bent on learning its ancient troll lore. The Ruins of Alterac were the last known home of an intact copy.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_540-fc2eeca476f5f4eefb32/1-0000.mp3", duration = 53.9428571, start = 0},
  },
}
P.transport["quest:541"] = {
  hash = "b95c87",
  fullHash = "b95c87",
  text = "Battle of Hillsbrad. In Hillsbrad, the Forsaken's campaign now turns on Dun Garok. High Executor Darthalia sends Horde champions to break the dwarven garrison aiding local humans and kill its commander, Captain Ironhill. High Executor Darthalia has already pressed the human farmers and town militia across the foothills. Now she directs Tarren Mill's fury at Ironforge's troops. Dwarven soldiers have taken up arms for Southshore, strengthening the human presence in Lordaeron. Darthalia sees that bond as an obstacle. She means to show the Alliance that aid for the human survivors will bring devastation. Dun Garok clings to Thoradin's Wall in southeastern Hillsbrad. Disciplined mountaineers hold the fortified stronghold, joined by skilled riflemen and battle-hardened priests. Horde forces must break through those defenders and kill Captain Ironhill. His death breaks Ironforge's forward command in the region, leaving the remaining human enclaves isolated.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_541-e0a108b4478744c8ed17/1-0000.mp3", duration = 63.2163265, start = 0},
  },
}
P.transport["quest:5421"] = {
  hash = "a01ac2",
  fullHash = "a01ac2",
  text = "Fish in a Bucket. In Shadowprey Village, Jinar'Zillen leaves the shellfish gathering to others. The traps lie below the docks, and he offers a Bloodbelly fish for every five shellfish. Jinar'Zillen keeps many shellfish traps below the docks of Shadowprey Village. He would rather someone else gather from them, and offers a fine Bloodbelly fish for every five shellfish brought in.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5421-802adbeb555b7c646b47/1-0000.mp3", duration = 22.8832653, start = 0},
  },
}
P.transport["quest:546"] = {
  hash = "e68128",
  fullHash = "e68128",
  text = "Souvenirs of Death. At Tarren Mill, Deathguard Samsa watches others march against Hillsbrad's human settlements and longs to join them. He asks for thirty human skulls taken in battle for his collection. High Executor Darthalia directs the Forsaken campaign against Hillsbrad's human settlements. Deathguard Samsa keeps watch in Tarren Mill while others are sent to raid, burn, and pillage. He envies their chance to slaughter the living, denied to a guard held at his post. Samsa hates the humans of Hillsbrad and collects the skulls of those slain in the campaign. He asks for thirty as trophies from a war he longs to fight himself. No arcane rite or military plan lies behind his request.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_546-a4a1b41bc1e276250571/1-0000.mp3", duration = 49.1363265, start = 0},
  },
}
P.transport["quest:547"] = {
  hash = "cdd407",
  fullHash = "cdd407",
  text = "Humbert's Sword. Near Dun Garok, Humbert's Sword is missing from the camp where its owner left it. Deathguard Humbert had gone for firewood while watching the dwarven stronghold on High Executor Darthalia's orders. Ironforge scouts took his weapon, and now he fears Darthalia will learn he failed. Deathguard Humbert watches Dun Garok for High Executor Darthalia. His hidden post lies near the dwarven fortress. One morning, he leaves camp to gather firewood for boiling water. Ironforge scouts find the post unguarded and loot it. When Humbert returns, his sword is gone, carried into the heavily defended bunker. Humbert knows losing his weapon to the enemy he was sent to watch could cost him his life under Forsaken command. If High Executor Darthalia learns what happened, he fears she will hang him from the rafters in Tarren Mill. He cannot storm Dun Garok alone. So he turns to passing Horde adventurers to recover his blade before his commander notices anything amiss.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_547-c1c7845ff42022e17ea5/1-0000.mp3", duration = 72.1763265, start = 0},
  },
}
P.transport["quest:549"] = {
  hash = "83d541",
  fullHash = "83d541",
  text = "WANTED: Syndicate Personnel. At Tarren Mill, Lady Sylvanas Windrunner's bounty calls for every Syndicate member's death. The Forsaken want the brigands driven from Durnholde Keep before they threaten Horde operations in the foothills. The Syndicate's sudden arrival southeast of Tarren Mill has drawn the Forsaken's attention. Lady Sylvanas Windrunner and her commanders see the Syndicate as a plague, not displaced nobles to bargain with. Her bounty orders their immediate death. Any prisoners brought in will be executed without trial. Durnholde Keep was once an infamous internment fortress. Now it lies shattered and lawless. Syndicate Rogues and Watchmen have taken its crumbling ramparts and towers as an operations hub. High Executor Darthalia needs the armed bandits driven out to secure the road and protect Tarren Mill's southeastern approach.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_549-62027e222310cbb1affb/1-0000.mp3", duration = 59.0889796, start = 0},
  },
}
P.transport["quest:555"] = {
  hash = "78e159",
  fullHash = "78e159",
  text = "Soothing Turtle Bisque. Chef Jessen wants Soothing Turtle Bisque back on Southshore's tavern menu. Unrest has cut off his snapjaw turtle meat, so he asks cooks to brave the northern waters near Dalaran and Lake Lordamere. Southshore is one of Lordaeron's last intact coastal towns held by the Alliance. Civilian life continues there amid growing strife. Chef Jessen says his cooking rivals any tavern north of Stormwind. Patrons supposedly come from Darkshire in Duskwood to taste his bisque. The rich soup calls for fresh meat from snapjaw turtles native to the rivers and lakes of the northern mountains. In calmer years, Jessen gathered turtle meat himself. He traveled past Dalaran to the eastern shore of Lordamere Lake. Now rising tensions, hostile wildlife, the Syndicate, and Forsaken incursions make the lands beyond town deadly for ordinary townsfolk. To keep the bisque on his menu, Jessen relies on armed travelers to gather meat from snapjaws along the riverbanks and northern shores.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_555-82be14811935cc3a8738/1-0000.mp3", duration = 65.5412245, start = 0},
  },
}
P.transport["quest:56"] = {
  hash = "77c347",
  fullHash = "77c347",
  text = "The Night Watch. In Darkshire, The Night Watch holds the line against the dead rising nearby. Stormwind has withdrawn its garrison, leaving the town’s local militia to rely on travelers at Tranquil Gardens Cemetery. Stormwind once guarded Duskwood, but its royal resources dwindled as political discord took hold in the capital. Then the crown withdrew its commissioned soldiers, leaving Darkshire with little defense against the forest’s encroaching shadows. The people formed a local militia called the Night Watch, led by Commander Althea Ebonlocke. It stands between the cursed forest and the town’s remaining residents. South of Darkshire, Tranquil Gardens Cemetery was once a peaceful resting place. Now restless skeletons and reanimated spellcasters roam its graves. The Night Watch is stretched thin along Duskwood’s borders, so Commander Ebonlocke sends arriving travelers to strike down Skeletal Warriors and Skeletal Mages before the dead reach the roads.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_56-7aa432ff0b437e465cbe/1-0000.mp3", duration = 72.5420408, start = 0},
  },
}
P.transport["quest:5643"] = {
  hash = "89aeb5",
  fullHash = "89aeb5",
  text = "Shadowguard. In the Undercity, Aelthalyste sends a Darkspear priest across the Great Sea to Orgrimmar. She has seen the young troll grow ready for the tribe’s sacred rites, and Ur'kyo awaits in the Valley of Spirits. In the Undercity, Aelthalyste watches the troll priests who come to learn. When an initiate grows strong enough for the tribe’s trials, she sends them across the Great Sea to their own elders. She does not press Forsaken teachings upon them. Their faith follows the traditions of their people. In Orgrimmar’s Valley of Spirits, Ur'kyo tends to the Darkspear tribe’s spiritual needs and ancient rites. He welcomes the returning initiate and prepares them for a rite of passage. The rite deepens the priest’s bond with the loa and uses spells to ward off harm.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5643-42ed57d1eee40e817789/1-0000.mp3", duration = 57.1297959, start = 0},
  },
}
P.transport["quest:5644"] = {
  hash = "9236f1",
  fullHash = "9236f1",
  text = "Devouring Plague. Across the sea from Lordaeron, Devouring Plague awaits Forsaken priests ready to learn its dark art. Miles Welsh in Thunder Bluff sends the adept to Aelthalyste in the Ruins of Lordaeron for this signature Shadow magic. In Thunder Bluff, Miles Welsh trains Forsaken priests among the tauren. He watches their divine and shadowy studies, and knows when an acolyte is ready for higher mysteries. Rather than teach those secrets himself in Kalimdor, Miles sends the worthy back to the Ruins of Lordaeron. Aelthalyste waits beneath the city ruins in the Undercity's War Quarter. She is one of the foremost mentors of the Forsaken priesthood, guiding acolytes who weave shadow. Devouring Plague drains its victim and carries a corruptive force. Aelthalyste teaches it only to those able to wield that force without succumbing.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5644-725b03982e2d5612ac85/1-0000.mp3", duration = 65.4106122, start = 0},
  },
}
P.transport["quest:5645"] = {
  hash = "8ef146",
  fullHash = "8ef146",
  text = "A Lack of Fear. In Ironforge, High Priest Rohan tests promising dwarven disciples. In the Mystic Ward, he teaches them as their strength of spirit grows. Local mentors send priests serving the Alliance abroad to senior clergy of their order. For dwarven disciples, that summons brings you to High Priest Rohan in Ironforge's Mystic Ward. There, basic spiritual practice gives way to deeper uses of holy magic, tested through trials. Dwarven tradition teaches that the Light is a shield in physical conflict. When you report to High Priest Rohan, you show that you have endured trials in the wider world. Now you must prove your mettle and master fear on the front lines.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5645-7c526274836ce6dfd037/1-0000.mp3", duration = 46.2367347, start = 0},
  },
}
P.transport["quest:5646"] = {
  hash = "48f4eb",
  fullHash = "48f4eb",
  text = "Devouring Plague. In Orgrimmar, Ur'kyo sends Forsaken priests home to learn Devouring Plague. They came to Kalimdor to learn from the Darkspear, but Aelthalyste waits in Undercity to teach them their people's shadow arts. Ur'kyo guides those drawn to spiritual power in Orgrimmar. Darkspear trolls and Forsaken share a curious bond in matters of faith, while orcs and tauren show little desire for priestly worship. Ur'kyo knows Forsaken initiates must master the shadow arts tied to their own condition. Out of respect between their peoples, he sends wandering Forsaken back to Lordaeron to finish their training. Beneath Lordaeron's ruins, Priestess Aelthalyste tends her flock in Undercity's War Quarter. Forsaken priests follow a solitary, grueling path shaped by their turn to shadow. They endure the painful touch of the Holy Light and learn to wield the devastating affliction of Shadow magic.\n\nWhen an initiate gains enough skill, Aelthalyste gathers them close. There, she teaches the affliction her kind calls Devouring Plague.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5646-a8b0209e28970af3b729/1-0000.mp3", duration = 70.2432653, start = 0},
  },
}
P.transport["quest:567"] = {
  hash = "04b945",
  fullHash = "04b945",
  text = "Dangerous!. At Tarren Mill, High Executor Darthalia names four Hillsbrad humans for execution. She says they killed Forsaken and struck at supplies. Across Hillsbrad Foothills, the fighting is brutal and personal. High Executor Darthalia and the Forsaken garrison at Tarren Mill see ordinary Hillsbrad citizens as deadly foes. A wanted notice names four people whose resistance has killed Forsaken and cost them valuable shipments from the Undercity. The bounty names Clerk Horrace Whitesteed, who killed Deathguard Toma; Citizen Wilkes, who murdered Apothecary Eli; Miner Hackett, who killed Deathstalker Fry; and Farmer Kalaba, who sabotaged supply convoys from the Undercity. Each works from a different pocket of Hillsbrad resistance and remains elusive amid the wider conflict.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_567-00e0ff35a0f45766f7be/1-0000.mp3", duration = 61.2310204, start = 0},
  },
}
P.transport["quest:5672"] = {
  hash = "533a21",
  fullHash = "533a21",
  text = "Elune's Grace. In Darnassus, young night elf priests answer the Sisterhood of Elune's call. Their first journeys prepare them for deeper teaching from Priestess Alathea. In the Temple of the Moon, the Sisterhood guides young acolytes from their first prayers toward mastery of lunar magic. Night elves trust the Mother Moon, Elune. Humans and dwarves instead follow the Holy Light. When a novice reaches a milestone in devotion, senior mentors take notice and judge the disciple ready to bear greater divine power. Priestess Alathea brings the Sisterhood's summons to the acolyte. She honors their devotion and welcomes them into traditions kept through millennia. By accepting the rite, the novice seals a bond with Elune. From then on, protective wards and lunar invocations of the kaldorei faith are within reach.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5672-388feac3b0f93c7dc4cb/1-0000.mp3", duration = 62.7461224, start = 0},
  },
}
P.transport["quest:5674"] = {
  hash = "76db0c",
  fullHash = "76db0c",
  text = "Elune's Grace. Night elf priests leave Dolanaar for Darnassus to receive Elune's Grace. The rite marks their readiness for a divine talent reserved for the kaldorei. A priest of the Sisterhood of Elune needs more than skill in prayers of mending and smiting. With experience, an acolyte reaches the point where blessings reserved for the kaldorei may be bestowed. Local mentors such as Laurna Morninglight in Dolanaar cannot teach these deeper arts, so they send promising disciples to the spiritual heart of their order. Initiates cross Teldrassil to the Temple of the Moon in Darnassus. There, beneath the gaze of the high priesthood, Priestess Alathea judges whether each petitioner is ready to bear the goddess's defensive mantle. She teaches Elune's Grace there, a divine talent reserved for the kaldorei.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5674-54b20a8a0f9a68d5f075/1-0000.mp3", duration = 59.4285714, start = 0},
  },
}
P.transport["quest:5676"] = {
  hash = "00be90",
  fullHash = "00be90",
  text = "Arcane Feedback. In Stormwind, High Priestess Laurena teaches Arcane Feedback to priests bound for dangerous roads. At the Cathedral of Light, faith becomes a defense against hostile spellcasters. At the Cathedral of Light, High Priestess Laurena warns the acolytes that arcane magic remains dangerous. The Holy Light brings healing, warmth, and divine order. Raw magic can turn volatile and lead to corruption or catastrophe. Warlocks, renegade sorcerers, and magical beasts threaten the faithful, so priests learn to make their faith an active ward against spells. Arcane Feedback turns a hostile spellcaster's power back against them. The ward does more than deflect spells; it burns through the caster's mana and brings agony. Laurena teaches the rite to human priests preparing to travel beyond Stormwind. Thus the Cathedral's emissaries can face sorcery with a defense of their own.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5676-658df381fadc39cbf10b/1-0000.mp3", duration = 60.9697959, start = 0},
  },
}
P.transport["quest:5677"] = {
  hash = "0dca7b",
  fullHash = "0dca7b",
  text = "Arcane Feedback. In Ironforge, human acolytes seeking deeper teaching are sent back to Stormwind. There, the Cathedral of Light holds the traditions of their people. High Priest Rohan welcomes a human priest who seeks deeper spiritual teaching in Ironforge’s Mystic Ward. Dwarven and human priests both serve the Holy Light, yet each people keeps its own rites, disciplines, and prayers of defense. Rohan reserves Ironforge’s teachings for his own clergy. So he sends human priests back to Elwynn to learn the traditions of humankind. After reaching Stormwind City, the acolyte finds High Priestess Laurena in the Cathedral of Light. Laurena is relieved that Rohan’s guidance has brought the traveler to her, and welcomes them as their powers begin to grow. In the Cathedral, human priests can keep learning Stormwind’s spiritual practices. There they prepare to wield the Holy Light against the threats around the kingdom.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5677-19e6a7847a0a4f733b7d/1-0000.mp3", duration = 64.9404082, start = 0},
  },
}
P.transport["quest:5678"] = {
  hash = "2f1d74",
  fullHash = "2f1d74",
  text = "Arcane Feedback. Human priests are being called from Darnassus to Stormwind. At the Temple of the Moon, Priestess Alathea reluctantly honors the Alliance summons. High Priestess Laurena waits at the Cathedral of Light to prepare the acolyte for deeper instruction. Priestess Alathea oversees visiting priests at Darnassus's Temple of the Moon. She honors the formal alliance between the kaldorei and Stormwind, yet distrusts human ways of magic and faith. For ten millennia, grief from the War of the Ancients has shaped the night elves' fear of arcane power. Even human divine rites trouble the clergy when radiant faith blurs with arcane workings. Alathea honors the bond between the Alliance races and sends you to answer a recall from the Cathedral of Light. High Priestess Laurena has sent couriers across the seas to gather human priests for advanced training. In Stormwind, you leave Elune's moonlit groves for grand stone sanctuaries and the golden radiance of the Holy Light.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5678-8042dd648cc90f7a9889/1-0000.mp3", duration = 69.9820408, start = 0},
  },
}
P.transport["quest:5679"] = {
  hash = "8fdaa4",
  fullHash = "8fdaa4",
  text = "Devouring Plague. In the Undercity, Devouring Plague marks the shadow path of Forsaken priests. Priestess Aelthalyste teaches the rite to those who have proven their dedication to shadow magic. In the Undercity’s War Quarter, Priestess Aelthalyste teaches Forsaken priests the grim arts of the Shadow. Priests of other races draw on the Holy Light or ancestral spirits, while the Forsaken have shaped their own spiritual doctrines. Devouring Plague gives that path a fearsome form. It torments foes and drains their stolen vitality to sustain the caster’s decaying body. Priestess Aelthalyste shares the plague’s power with care. This potent weapon is meant to turn the tide against the Scourge and the Scarlet Crusade. She warns her disciples to practice until their command is sure. Greater trials await those who seek mastery of the dark arts.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5679-6ba01afb6dc612a96428/1-0000.mp3", duration = 57.1559184, start = 0},
  },
}
P.transport["quest:57"] = {
  hash = "feec8e",
  fullHash = "feec8e",
  text = "The Night Watch. Across Duskwood, restless dead rise from their graves, and The Night Watch struggles to hold them back. Commander Althea Ebonlocke sends travelers into the haunted barrows to defend Darkshire. Their fight may keep the town from falling to darkness. Duskwood’s graveyards stir beneath the forest’s twilight. Commander Althea Ebonlocke leads Darkshire’s volunteer militia, The Night Watch, against the rising dead. Stormwind sends no aid, and her forces are stretched thin. Skeletons and other horrors threaten the eastern settlements, so the militia calls on able travelers to enter the deadlands. Two places hold the militia’s attention: Tranquil Gardens Cemetery, just south of town, and Raven Hill Graveyard, far to the west. Skeletons rise from forgotten tombs and shallow graves beside the roads, stirred by dark magic in the forest’s shadows. Cutting them down gives Darkshire’s beleaguered citizens room to breathe. Yet the battle against this entrenched evil never ends.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_57-4ae067c0c2197962dcfb/1-0000.mp3", duration = 67.1869388, start = 0},
  },
}
P.transport["quest:575"] = {
  hash = "890608",
  fullHash = "890608",
  text = "Supply and Demand. In Booty Bay, Drizzlik is preparing an order for Director Riddlevox, chief inventor of the Tinkers' Union. The leathercrafter claims to be the finest in the South Seas and beyond. Drizzlik calls his leatherwork exquisite and famed everywhere. Director Riddlevox has ordered twelve Excelsior-line boots, among Drizzlik's best sellers and the boots Riddlevox favors. To begin shaping them, Drizzlik needs skins from crocolisks by the northern Stranglethorn river. His equipment is ready, and leaving so important a customer unsatisfied would be a poor idea.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_575-6cb6fdac30ec65299b07/1-0000.mp3", duration = 38.1126531, start = 0},
  },
}
P.transport["quest:5762"] = {
  hash = "9fe933",
  fullHash = "9fe933",
  text = "Hemet Nesingwary. A crate delayed on the road from Kalimdor reaches the jungles of Stranglethorn Vale by sea. At the Mirage Raceway, Kravel Koalbeard sends special supplies to Hemet Nesingwary, the renowned big-game hunter. At the Mirage Raceway in the Shimmering Flats, Kravel Koalbeard receives a long-overdue crate for one of his wealthy patrons. Hemet Nesingwary had already left Thousand Needles, but he paid to have the crate sent on to his hunting camp in Stranglethorn Vale. Kravel stays behind rather than face the arduous journey himself. So he hires passing adventurers to carry the crate across the sea. North of Grom'gol Base Camp, Hemet Nesingwary's expedition receives the heavy crate. It holds specialized heavy-gauge ammunition for bringing down the jungle's dangerous predators. Hemet recognizes the white salt crust on the courier's gear. His old dealings with Kravel have brought the firepower his safari needed.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5762-3a336a6b558ae46c99e4/1-0000.mp3", duration = 58.1485714, start = 0},
  },
}
P.transport["quest:5763"] = {
  hash = "6df9a7",
  fullHash = "6df9a7",
  text = "Hunting in Stranglethorn. You carry Roon Wildmane's token north of Grom'gol Base Camp to Hemet Nesingwary in Stranglethorn. The tauren and dwarf once hunted together in Desolace. Roon Wildmane remembers hunting beside Hemet, a dwarf who came to Desolace to hunt great beasts. Hemet wielded a rifle with uncanny skill. For many days, the two hunted together and set aside the old enmity between their peoples.\n\nWhen Hemet left for Stranglethorn, Roon vowed to welcome him back for another hunt. Now Roon sends you with his kodo horn, a token Hemet will recognize. Find Hemet in Stranglethorn, north of Grom'gol Base Camp.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5763-959867d3951821a7ebe1/1-0000.mp3", duration = 40.1502041, start = 0},
  },
}
P.transport["quest:58"] = {
  hash = "7ea91a",
  fullHash = "7ea91a",
  text = "The Night Watch. In eastern Raven Hill, The Night Watch sends for help as Darkshire faces the undead. Commander Althea Ebonlocke calls on travelers to enter the crypts and destroy the plague spreaders while her guards defend the town. This is the last chapter in the guard’s direct fight against the undead overrun. Darkshire stands nearly alone, with no soldiers from Stormwind to rely on. Its civilian militia, The Night Watch, must hold the town. Commander Althea Ebonlocke has few guards to spare, and she uses them to protect the crossroads, the town’s edge, and the supply lines. As the restless dead multiply across Duskwood, she calls on wandering champions to carry the fight into Raven Hill’s depths. The eastern mausoleum in Raven Hill Cemetery holds one of the region’s largest concentrations of undead. Unlike the open barrows, its stone crypts teem with plague spreaders. These ghouls carry afflictions that can sicken the living. Destroying twenty gives The Night Watch room to breathe and helps keep Darkshire from facing a united undead surge from the west.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_58-17003c7cf235ba6337c8/1-0000.mp3", duration = 69.5902041, start = 0},
  },
}
P.transport["quest:583"] = {
  hash = "007692",
  fullHash = "007692",
  text = "Welcome to the Jungle. In Stranglethorn Vale, Barnil Stonepot welcomes newcomers to the hunting camp and spots a seasoned wanderer. He offers to introduce you to Hemet Nesingwary, the expedition's leader. Barnil Stonepot greets newcomers at the camp in Stranglethorn Vale. He spots seasoned fighters and points out Hemet Nesingwary, an Alliance war hero and peerless tracker. Nesingwary keeps company with veterans who have proved themselves. Barnil thinks the old marksman may share his hunting wisdom with someone who has endured battle.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_583-ae2f5efd311785ec7d44/1-0000.mp3", duration = 35.6832653, start = 0},
  },
}
P.transport["quest:5881"] = {
  hash = "e7eea3",
  fullHash = "e7eea3",
  text = "Calling in the Reserves. At Sun Rock Retreat, Maggran Earthbinder sends you south to relieve a weary sentry at the Great Lift. He gives you a letter for Grish Longrunner, who has stood watch far from home. Maggran Earthbinder keeps troop welfare and supplies in hand at Sun Rock Retreat in the Stonetalon Mountains. Across Kalimdor, the Horde strains to keep its garrisons staffed, even after the Third War. Maggran knows that endless watch duty wears seasoned soldiers down. So he sends a reassignment letter south to the Great Lift, where Grish Longrunner has stood guard far from home. The Great Lift joins the southern Barrens to the canyons of Thousand Needles. With Maggran's letter in hand, Grish can leave his lonely watch over the lift mechanisms and return to his family. Fresh reserves can take his place.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5881-76d5f4c5147eec3a8ac2/1-0000.mp3", duration = 50.0506122, start = 0},
  },
}
P.transport["quest:6282"] = {
  hash = "fff3b6",
  fullHash = "fff3b6",
  text = "Harpies Threaten. In the Charred Vale, Bloodfury harpies threaten the roads west of Sun Rock Retreat. Maggran Earthbinder calls Horde warriors to thin their growing ranks and keep travel through Stonetalon open. Tauren at Sun Rock Retreat guard Stonetalon and its peaceful travelers. Maggran Earthbinder, the retreat’s elder leader, has watched the harpy ranks grow. The Bloodfury coven has spread through the scorched Charred Vale, harrying beasts and blocking routes. If the flocks grow further, Sun Rock Retreat could be cut off. West of Sun Rock Retreat, the Charred Vale is a wasteland of ash, scorched earth, and smoldering trees left by catastrophic fires. Bloodfury harpies nest high in the charred remains of ancient woods, and the vale is their stronghold. Maggran sends Horde warriors into the hostile caldera to cull dozens of harpies: Bloodfury ambushers, slayers, and roguefeathers. Thinning their ranks weakens the coven’s grip on the vale and clears the way to confront its matriarchal lineage.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6282-49fa090014a1837fb5dc/1-0000.mp3", duration = 72.2546939, start = 0},
  },
}
P.transport["quest:6283"] = {
  hash = "dff25d",
  fullHash = "dff25d",
  text = "Bloodfury Bloodline. Maggran Earthbinder sends you into the Charred Vale to break the harpies’ hold and bring back proof. Harpies from the edge of the Charred Vale threaten Sun Rock Retreat. Maggran Earthbinder believes their attacks will end only when Bloodfury Ripper, their matriarch, is dead. The flock treats her like a queen. Under her lead, they move as one and grow bold along the craggy western ridge. Maggran asks you to bring back Bloodfury Ripper’s remains as proof. Without their brood queen, the harpies lose their order and become easier to keep at bay. Sun Rock Retreat faces less danger, and Maggran can set aside his anger and constant watchfulness. Then he is free to seek the harmony and balance the tauren value.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6283-6cb5a6caf98760454eff/1-0000.mp3", duration = 48.6138776, start = 0},
  },
}
P.transport["quest:6284"] = {
  hash = "dad136",
  fullHash = "dad136",
  text = "Arachnophobia. A Horde bounty sends you west of Windshear Crag after Besseleth, the ancient spider haunting southern Stonetalon Mountains. Bring her fang to Maggran Earthbinder at Sun Rock Retreat, and travelers may find the mountain roads safer after dark. A weathered wanted poster warns travelers on the main road south of Windshear Crag to beware the lands west of it. Sishir Canyon and Webwinder Path swarm with spiders. Besseleth, an unusually large orange spider, commands her brood. After sunset, she ambushes anyone who strays from the path. Maggran Earthbinder, a tauren at Sun Rock Retreat, has posted the bounty on Besseleth. In an earlier encounter, her massive two-foot fang struck him and nearly killed him. Maggran fought her off and limped to safety, but the wound still reminds him of the danger in the canyon shadows. He hopes you will bring him Besseleth's Fang and secure the passes, so trade and travel to Sun Rock Retreat can continue without fear.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6284-29ebeb02cba78f5935cb/1-0000.mp3", duration = 72.4636735, start = 0},
  },
}
P.transport["quest:63"] = {
  hash = "43588d",
  fullHash = "43588d",
  text = "Call of Water. Across the sea, Call of Water sends Barrens shamans to a blighted shore in Silverpine Forest. There, an initiate faces the sickness at an ancient shrine to earn communion with water spirits. You gather pure water with help from the hermit Brine, then return to Islen Waterseer on the Barrens coast. She sends you across the sea with the purified essence to Silverpine Forest's haunted shore. The shrine lies just west of the Forsaken refuge called the Sepulcher.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_63-2d531cb8f0ab6a4b6cde/1-0000.mp3", duration = 35.7616327, start = 0},
  },
}
P.transport["quest:6301"] = {
  hash = "57a46c",
  fullHash = "57a46c",
  text = "Cycle of Rebirth. At Sun Rock Retreat, Tammra Windfield seeks Gaea seeds to heal Stonetalon. She asks the Horde to gather them from Mirkfallon Lake, so she can bless them and restore the mountain’s damaged soil. Logging and clashes between rival factions have scarred Stonetalon’s peaks. Forests have been scorched, cut down, or reduced to ash. For the tauren at Sun Rock Retreat, the swift ruin of the natural world is a grievous wound. Shamans such as Tammra Windfield turn to the Earthmother’s renewing cycle as they work to mend the land. Tammra seeks rare Gaea seeds along Mirkfallon Lake, north of Sun Rock Retreat. Sturdy seed pods grow on the banks by the water, holding a resilience found only in Stonetalon. Once gathered, Tammra gives each kernel an ancestral shamanistic blessing. The blessing awakens its power and hastens its growth.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6301-ee5b54fddfd05d38e38e/1-0000.mp3", duration = 64.9404082, start = 0},
  },
}
P.transport["quest:631"] = {
  hash = "15a641",
  fullHash = "15a641",
  text = "The Thandol Span. At the Thandol Span, Rhag Garmason seeks a missing dwarf scout after a blast destroys the northern crossing. The Dark Iron clan has attacked Dun Modr, cutting off word and leaving its defenders without reinforcements. Ol' Rustlocke may know what caused the blast. A blast has torn through the bridge between Wetlands and the Arathi Highlands. Bronzebeard soldiers at the border were caught in the destruction when Dark Iron dwarves attacked Dun Modr. Their ranks are thin, and their strongholds are under siege. Longbraid the Grim leads the survivors as they hold their ground against the attackers. Longbraid sent veteran scout Ebenezer Rustlocke to inspect the eastern span. He was to learn whether a crossing or northern route remained usable. Days have passed without word from him. Dun Modr is under siege, and Rhag Garmason and the garrison have too few soldiers to search the enemy-held rubble.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_631-a73b28da5d209bc56f88/1-0000.mp3", duration = 59.7681633, start = 0},
  },
}
P.transport["quest:632"] = {
  hash = "fac2dc",
  fullHash = "fac2dc",
  text = "The Thandol Span. At the Thandol Span, Rhag Garmason waits for word from a missing scout. He sent adventurers to check on Ol' Ebenezer Rustlocke after the dwarf stopped reporting from the great stone crossing. The search beneath its arches may reveal a threat to northern supply lines. Longbraid the Grim sent Ebenezer Rustlocke to watch over the Thandol Span's structure and security. When the scout stopped reporting, foul play was feared.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_632-0ae3808005b28684f95c/1-0000.mp3", duration = 28.8130612, start = 0},
  },
}
P.transport["quest:633"] = {
  hash = "c8b0a8",
  fullHash = "c8b0a8",
  text = "The Thandol Span. On the Thandol Span, a murder puts Ironforge’s northern road at risk. Ebenezer Rustlocke is dead, and Rhag Garmason has found explosives hidden by Kam Deepfury. A recovered document lays bare the crime beneath the Thandol Span. Ebenezer Rustlocke was murdered in the bridge’s substructure. The papers reveal more: Kam Deepfury, the Dark Iron agitator who first destroyed part of the bridge, has not stopped. His network planted another cache of heavy munitions just across the northern border in the Arathi Highlands, ready to finish the destruction.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_633-145ef55a5bd9ee9b3a4f/1-0000.mp3", duration = 39.9412245, start = 0},
  },
}
P.transport["quest:634"] = {
  hash = "bcfeca",
  fullHash = "bcfeca",
  text = "Plea To The Alliance. At the shattered Thandol Span, Plea To The Alliance carries Dun Modr's desperate call for aid. Dark Iron infiltrators slaughtered the garrison, and its dwarven survivors appeal to human forces at Refuge Pointe, though the Alliance is stretched thin. Dun Modr lies in ruins, and Dark Iron dwarves have sabotaged the Thandol Span. The survivors cling to a foothold on the Wetlands' northern rim. Ironforge's main reserves have not arrived, so Rhag Garmason and Longbraid the Grim look north to the Arathi Highlands. There they learn that Alliance forces have camped at Refuge Pointe. Garmason sends an emissary across the shattered bridge to ask Captain Nials for urgent military aid. At Refuge Pointe, Captain Nials offers sympathy to Longbraid's soldiers but cannot spare a single fighter. Stromgarde has fallen into ruin, overrun by Syndicate rogues, Boulderfist ogres and Witherbark trolls. Its surviving defenders are committed to reclaiming their ancestral capital. Bound by honor and pressed by their own desperate struggle, Nials sends word that the dwarves at the Span must stand alone.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_634-a09d3c91d57c9a7b0fda/1-0000.mp3", duration = 78.9681633, start = 0},
  },
}
P.transport["quest:637"] = {
  hash = "1d6a42",
  fullHash = "1d6a42",
  text = "Sully Balloo's Letter. At the Thandol Span, Sully Balloo's Letter carries a dwarf's last words to his wife in Ironforge. Found beneath the bridge, it tells where he died. Beneath the stone pilings of the Thandol Span, the land bridge between the Wetlands and the Arathi Highlands, a drowned skeleton still clutches an envelope. Its water-damaged pages begin, “My dear Sara,” and preserve the tenderness of Sully Balloo's careful writing. Alliance forces and their enemies have fought fiercely for the Thandol Span. Dark Iron saboteurs and warbands contesting the borderlands have threatened the crossing. Sully Balloo was among the dwarven soldiers sent north to defend it. His family in the mountains knew nothing of his fate until a diver brought his farewell letter up from beneath the waves.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_637-c9c336b51805e4b6b0a3/1-0000.mp3", duration = 52.3755102, start = 0},
  },
}
P.transport["quest:6381"] = {
  hash = "8d9483",
  fullHash = "8d9483",
  text = "New Life. Tammra Windfield sends travelers west from Sun Rock Retreat to begin healing the Charred Vale. She hopes Gaea seeds can help the scorched land recover. Tammra Windfield asks you to enter the Charred Vale, where soot, fire elementals, and harpies haunt the ruined ground. She trusts the Earth Mother's resilience. Find the Gaea Dirt Mounds, where fertile soil survived the fire. Gaea seeds can take root despite the lingering elemental corruption. Their roots hold back decay and give plants a place to return to the valley. Tammra hopes new growth will calm the fire spirits and drive the harpies from their desolate roost. She also hopes the Venture Company's logging will eventually be driven out.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6381-2a921ab68c7ccf272d92/1-0000.mp3", duration = 44.3036735, start = 0},
  },
}
P.transport["quest:6382"] = {
  hash = "d7c813",
  fullHash = "d7c813",
  text = "The Ashenvale Hunt. In Ashenvale, the Horde's proven hunters face a new test beneath ancient trees. Jorn Skyseer sends you north from Camp Taurajo to Splintertree Post, where Senani Thunderheart awaits. After proving yourself in the Barrens, you are sent toward Ashenvale. Jorn Skyseer sees when a hunter has outgrown the local game and points the way north. For the young Horde, these old forests offer resources and mark a political and spiritual frontier to understand and claim. The road north passes the Mor'shan Rampart before reaching Splintertree Post, a fortified Horde camp deep among the trees. Senani Thunderheart, a tauren huntress, welcomes experienced hunters seeking harder tests of survival. The Horde needs skilled trackers to face Ashenvale's native predators and the forest's watchful defenders.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6382-e93ab99d9edaec7e95b5/1-0000.mp3", duration = 62.1191837, start = 0},
  },
}
P.transport["quest:6383"] = {
  hash = "27c86d",
  fullHash = "27c86d",
  text = "The Ashenvale Hunt. In Ashenvale, Horde hunters face three great predators in Senani Thunderheart's trial at Splintertree Post. Track Ursangous, Shadumbra, and Sharptalon to prove your skill. Senani Thunderheart gives the Horde's presence in Ashenvale a different kind of test. While Orcs gather lumber, she sends hunters into the shadowed forest to face its strongest predators. Strength alone will not serve; hunters need cunning and respect for the wilderness. They must learn what they can endure. Three solitary beasts test those who take up the hunt. Ursangous, an immense elder bear, roams near the Talondeep Path. Shadumbra, a cunning nightsaber, stalks the eastern borders near Raynewood Retreat and the Laughing Sisters. South of Splintertree Post, Sharptalon, a fierce hippogryph, wheels above the forest canopy.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6383-41c80faedc4a3db5013d/1-0000.mp3", duration = 57.5477551, start = 0},
  },
}
P.transport["quest:6393"] = {
  hash = "0769e1",
  fullHash = "0769e1",
  text = "Elemental War. In Stonetalon Mountains, Tsunaman sends you against fire elementals in Neptulon’s name. The water envoy at Sun Rock Retreat asks you to enter the Charred Vale and gather Incendrite cores from the blazing elementals you destroy. Their struggle reaches beyond mortal borders, bound to the ancient rivalry between elemental forces. At Sun Rock Retreat in Stonetalon Mountains, Tsunaman speaks for the Tribunal of the Tides. You carry out Neptulon the Tidehunter’s will against the fiery kin of his water elementals. Their enmity reaches far beyond mortal borders. It is an ancient struggle between the primal forces of Azeroth. Southern Stonetalon Mountains hold the Charred Vale, where ash and smoke mark the land. Fire elementals gather there and threaten the surrounding regions. Tsunaman sends you to destroy them and gather the Incendrites they leave behind. These blazing cores prove to the Tribunal that the elementals are gone.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6393-08a7755e73101b354b09/1-0000.mp3", duration = 73.9526531, start = 0},
  },
}
P.transport["quest:647"] = {
  hash = "1c8776",
  fullHash = "1c8776",
  text = "MacKreel's Moonshine. Foggy MacKreel needs his moonshine carried from the broken Thandol Span to Southshore. He drank too much while on watch and now has little time to deliver a fresh batch to Brewmeister Bilger and settle his debt. On the shattered Thandol Span, Foggy MacKreel keeps watch through wet, cold, and dull hours. He drinks his homemade moonshine to bear the damp chill. The brew hits hard enough that he compares its aftereffects to siege engines pounding across his skull. One drink too many leaves him asleep through his shift. Longbraid the Grim commands the dwarves defending the Span, and Foggy cannot afford another lapse in discipline. Foggy owes Brewmeister Bilger in Southshore a longstanding debt. He promised a batch of his personal brew to settle the account, but his hangover and watch duties have left him minutes from missing the deadline. You race across the Arathi Highlands with the jug, by gryphon and swift feet. Reach Southshore before Bilger decides Foggy has skipped out on his tab again.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_647-c3cb7f2c314d8a543674/1-0000.mp3", duration = 61.8579592, start = 0},
  },
}
P.transport["quest:6481"] = {
  hash = "fd2163",
  fullHash = "fd2163",
  text = "Earthen Arise. In Boulderslide Ravine, Mor'rogal finds Goggeroc asleep inside a Resonite cask. The tauren shaman fears the ancient Earthen could threaten all Kalimdor, so he sends a champion to break the cask and slay Goggeroc before its strength returns. Scouts searching Boulderslide Ravine for vermin found a strange relic among the kobolds. A Resonite cask held unearthly force. Mor'rogal, a tauren shaman in the Stonetalon Mountains, knew it was both prison and sanctuary for Goggeroc, a dormant Earthen. These ancient beings of stone can outmatch mortal warriors, and Goggeroc's freedom could endanger the whole region.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6481-c149d8bda14c6c46424b/1-0000.mp3", duration = 45.6097959, start = 0},
  },
}
P.transport["quest:6503"] = {
  hash = "a56a95",
  fullHash = "a56a95",
  text = "Ashenvale Outrunners. In Ashenvale, Kuray'bin sends the Horde against night elf scouts slipping out from Silverwing Outpost. They are gathering word of Horde encampments and defenses before they can report back. Night elf scouts from Silverwing Outpost move through the woods east of their base and south of nearby Horde holdings. They watch the paths and ridges, mapping fortifications and tracking troop movements.\n\nKuray'bin has learned that these scouts, called Ashenvale Outrunners, have slipped into the wilderness to gather intelligence. The Horde strikes at enemy scouts before they can return to Silverwing Outpost. Hunting down the outrunners keeps their commanders from learning the Horde's troop strength and outpost defenses.\n\nWithout their forward eyes, the night elves are disoriented and less willing to risk aggressive moves through the contested woods.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6503-b3bc0d26efe1b658641f/1-0000.mp3", duration = 56.2155102, start = 0},
  },
}
P.transport["quest:6504"] = {
  hash = "279ebf",
  fullHash = "279ebf",
  text = "The Lost Pages. A gust has scattered The Lost Pages across Ashenvale, leaving Gurda Ragescar stranded near Splintertree Post. She cannot run the shredder she is carrying from Ratchet to the Warsong Lumber Camp without its manual. The Warsong Clan buys steam-powered shredders in Ratchet to clear lumber across Ashenvale. Their delicate workings can be hard for an orc warrior to master. As Gurda Ragescar carried a newly bought shredder north, a sudden gust tore the instruction booklet from her hands. Twelve parchment leaves scattered across the forest floor. The wind carried the manual pages across Ashenvale. Wandering creatures, cultists, and forest denizens have taken them. The shredder cannot run without all three chapters. Gurda is stranded on the road to Splintertree Post, unable to report for logging duty.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6504-6b15a932c624fd0655c8/1-0000.mp3", duration = 50.5208163, start = 0},
  },
}
P.transport["quest:6546"] = {
  hash = "54740a",
  fullHash = "54740a",
  text = "Warsong Outrider Update. Along eastern Ashenvale, the Warsong Outrider Update carries word of danger closing in on the Horde. Its report names Alliance forces, satyr entrenched in the forest, and naga moving through neighboring Azshara. A lone Warsong Outrider watches Ashenvale’s contested eastern edge. Horde supply lines face constant harassment, so outriders track enemy movements before raiding parties can strike Mor'shan Rampart or Splintertree Post. Meet one on patrol and you know the forest is under watch. His report may decide whether a Horde fortification holds or falls to ambush. A Warsong Outrider’s report tells of danger across Kalimdor’s central forests. Night elves and the wider Alliance remain a threat, while cunning, demonic satyr haunt eastern Ashenvale. Scouts have also found a massive naga presence spreading through the ruined coastal lands of neighboring Azshara. The Horde faces hostile powers from nearly every direction.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6546-2f2dcfb463de96c51028/1-0000.mp3", duration = 61.6228571, start = 0},
  },
}
P.transport["quest:6547"] = {
  hash = "32681d",
  fullHash = "32681d",
  text = "Warsong Scout Update. Kadrak's orders reach Warsong Scout Update as scouts watch the contested woods. The Horde relies on their reports to guard its positions in Ashenvale from night elf attacks. Kadrak relies on scattered Warsong scouts to watch Ashenvale's border. Night elf sentinels use the forest for cover, and the scouts risk being cut off. Couriers carry written updates between them, keeping isolated outposts connected to Horde command and able to report what they see. Warsong scouts watch for night elf raids meant to reclaim the forest. The clan has paid in lives for every stretch of Ashenvale it cleared or occupied. Kadrak's orders keep forward scouts in touch with the Horde and let them report whether their defenses are holding against elven resistance.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6547-3e2665109904fd132987/1-0000.mp3", duration = 47.4383673, start = 0},
  },
}
P.transport["quest:6561"] = {
  hash = "24b995",
  fullHash = "24b995",
  text = "Blackfathom Villainy. In Blackfathom Deeps, a wounded scout calls for help against the cult serving Aku'mai. Argent Dawn scout Thaelrid asks passing Horde champions to end Twilight Lord Kelris's blood sacrifices in the sunken ruins. Argent Dawn scout Thaelrid lies wounded in the underground temple along the Ashenvale coast. His reconnaissance uncovered horrors beyond the naga incursions, but he has spent his strength and cannot finish his mission alone. So he calls on passing Horde champions to strike at the cult's leaders in the sunken halls. Twilight Lord Kelris leads the Twilight's Hammer cultists in the ruined Temple of the Moon. Alongside the local naga, he performs dark rites over the defiled Moon Well. Captives are fed alive to Aku'mai, a ravenous hydra and beast of the Old Gods. Kelris seeks cosmic power and primordial chaos.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6561-7164fdb8e48b7093990b/1-0000.mp3", duration = 56.6595918, start = 0},
  },
}
P.transport["quest:6562"] = {
  hash = "a31871",
  fullHash = "a31871",
  text = "Trouble in the Deeps. From Stonetalon Mountains, Tsunaman sends Horde travelers to aid Je'neu Sancrea on Ashenvale's remote coast. The troll scholar waits at Zoram'gar Outpost, where danger gathers along the shore. Tsunaman hears troubling reports from the north and calls Horde travelers to aid Je'neu Sancrea. The troll scholar waits at Zoram'gar Outpost on Ashenvale's far western shore, along the Zoram Strand. Danger is growing there, and Je'neu needs help from beyond the outpost. The road to Ashenvale's western shore is dangerous for Horde travelers. You can pass through Windshear Crag, where goblins have stirred trouble, or travel north from the Barrens. Either way, you enter a forest watched by night elf sentinels.\n\nFar beneath Ashenvale's dense canopy, Zoram'gar Outpost holds on along the storm-washed Zoram Strand. The outpost faces the shadowed waters.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6562-eeaab376ca8d44536d22/1-0000.mp3", duration = 52.1665306, start = 0},
  },
}
P.transport["quest:6563"] = {
  hash = "f849e1",
  fullHash = "f849e1",
  text = "The Essence of Aku'Mai. At Zoram'gar Outpost, Je'neu Sancrea asks Horde adventurers to stop the naga's sapphire harvest in Blackfathom Deeps. He fears they will misuse the gems' power. From the Zoram Strand, Je'neu Sancrea watches over the Kaldorei ruins. Naga now mine sapphire clusters in the submerged chambers of Blackfathom Deeps, where the gems grow along damp cavern walls. Sancrea senses the serpentine invaders mean to harness their power, so he seeks to stop the harvest before they can use it. The Sapphires of Aku'mai carry elemental water energy and hold clinging water spirits. Adept sorcerers could fuel dangerous arcane rituals with them or strengthen Aku'mai, the shadowy hydra whose presence fills the subterranean temple. Recovering the clusters keeps this potent reagent from the naga and helps guard the coastline against unchecked elemental magic.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6563-e90a397b6626fa3d1fd9/1-0000.mp3", duration = 56.7902041, start = 0},
  },
}
P.transport["quest:6564"] = {
  hash = "a1fa0d",
  fullHash = "a1fa0d",
  text = "Allegiance to the Old Gods. At Zoram'gar Outpost, you bring Je'neu Sancrea a naga message from Blackfathom Deeps. Its orders point to a ritual plot in the flooded ruins. Horde scouts find a damp, crumpled note while fighting the naga in Blackfathom Deeps. Its frantic words order naga priestesses to gather elemental water crystals. These crystals are meant to fuel the summonings of naga aquamancers. The aquamancers are gathering elemental forces for a darker purpose.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6564-804eae77be53b84299b0/1-0000.mp3", duration = 35.4220408, start = 0},
  },
}
P.transport["quest:6565"] = {
  hash = "39c535",
  fullHash = "39c535",
  text = "Allegiance to the Old Gods. At Zoram'gar, the Horde moves against the Twilight's Hammer cult in Blackfathom Deeps. Je'neu Sancrea sends champions after Lorgus Jett, hoping to disrupt cultists who seek to awaken ancient forces of destruction beneath Ashenvale's coast. From the Ashenvale shore, Zoram'gar Outpost watches Blackfathom Deeps. Naga, corrupted beasts, and Twilight's Hammer fanatics overrun its submerged temple complex. Je'neu Sancrea is an Earthen Ring seer stationed on the coast. He sees the cultists serving the Old Gods rather than the land's natural balance and spirits. These monstrous beings of chaos were defeated in ancient times, yet their malign touch lingers in Azeroth's forgotten places. Je'neu sends Horde champions into the underground ruins to hunt Lorgus Jett, an established leader among the cultists in Blackfathom Deeps. Lorgus works deep in the stone passages between Ghamoo-ra's chamber and Baron Aquanis's chamber. Je'neu is too frail to enter the damp darkness himself. Lorgus's defeat is vital to severing the dark rituals he sought to orchestrate beneath Ashenvale's waves.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6565-7083958eb9d62d0f6ad3/1-0000.mp3", duration = 80.5355102, start = 0},
  },
}
P.transport["quest:6571"] = {
  hash = "e4b659",
  fullHash = "e4b659",
  text = "Warsong Supplies. At Splintertree Post, Locke Okarr needs Warsong Supplies to keep the lumber camp working. Some wait in town, some in Booty Bay, and others lie in enemy hands across Ashenvale. From Splintertree Post, Locke Okarr works to keep the Warsong Lumber Camp supplied. The Warsong Clan needs a steady flow of heavy tools to harvest Ashenvale's ancient timber. Furbolg and satyr raids have scattered or seized local supplies, leaving the camp short of vital gear. You gather equipment from across Kalimdor and beyond. Pixel, the goblin courier at Splintertree Post, has circular saw blades. In Booty Bay, Wharfmaster Lozgil holds a crate of heavy axes. Foulweald and Thistlefur furbolgs have taken logging ropes, while satyrs at Night Run, Satyrnaar, and Xavian stole barrels of Warsong machinery oil for their profane rites.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6571-e14dec951f65e02b456a/1-0000.mp3", duration = 56.3983673, start = 0},
  },
}
P.transport["quest:6581"] = {
  hash = "10ed45",
  fullHash = "10ed45",
  text = "Warsong Saw Blades. At Splintertree Post, the Warsong loggers wait for blades brought from Ratchet. Their courier Pixel will trade the shipment for a weapon to guard herself on Ashenvale's dangerous roads. The blades keep the Horde's lumber camps at work. Pixel has brought heavy saw blades from Ratchet to Splintertree Post, but she will not give them away. In Ashenvale's wilds, safety matters more to her than coin. She asks to trade them for a Deadly Blunderbuss, so she can defend herself on the dangerous roads through hostile territory. The Horde needs Ashenvale timber to ease shortages across Durotar and the Barrens. Axes dull quickly against the ancient groves, so the Warsong loggers rely on goblin-forged blades. Pixel's shipment supplies the lumber camps, where the Horde cuts timber for outposts and war machines despite fierce resistance from the night elves.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6581-8f6817801e7d800d521a/1-0000.mp3", duration = 54.2040816, start = 0},
  },
}
P.transport["quest:66"] = {
  hash = "8a05b8",
  fullHash = "8a05b8",
  text = "The Legend of Stalvan. Madame Eva's vision in Darkshire names Stalvan and warns of death for her granddaughter, Alyssa. She sends you to the Darkshire Town Hall to search the records. In Darkshire, Madame Eva reads cards and portents for troubled locals. A terrible disturbance jolts her awake, and she draws the Death card for her young granddaughter, Alyssa. Eva enters a deep trance to learn what the omen means. One clue comes to her: the name Stalvan. Fearing for her family and the town, she asks you to follow that name before tragedy strikes. Madame Eva sends you across the square to the Darkshire Town Hall. Search its records for Stalvan, and speak with Clerk Daltry, who keeps the town's ledgers and public archives. He can help determine whether Stalvan once lived in Darkshire, passed through as a traveler, or belongs to Duskwood's past.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_66-17dcaa4484c5a451f728/1-0000.mp3", duration = 58.3314286, start = 0},
  },
}
P.transport["quest:6621"] = {
  hash = "0f53e0",
  fullHash = "0f53e0",
  text = "King of the Foulweald. At Zoram'gar Outpost, Karang Amakkar orders a strike against the Foulweald. Horde champions plant a war banner on the tribe’s sacred totem mound, drawing out Chief Murgut and killing him. Karang Amakkar sees the corrupted Foulweald as a danger to the Horde from his post at Zoram'gar Outpost. The tribe is smaller than the northern Thistlefur, but its members are fierce. So Karang orders a show of force to break their will before they can ambush Horde patrols. Greenpaw Village lies northeast of Mystral Lake. Karang prepares a tribal war banner for the center of the Foulweald totem mound, insulting the tribe’s ancestral spirits and pride. The defenders rush to tear it down, and Chief Murgut emerges to defend his honor in open combat. Taking his personal totem breaks the tribe’s leadership and establishes Horde supremacy in the area.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6621-c5a3e4b4a8911ef29b43/1-0000.mp3", duration = 55.9542857, start = 0},
  },
}
P.transport["quest:6627"] = {
  hash = "634599",
  fullHash = "634599",
  text = "Test of Lore. At Braug Dimspirit’s perch in Stonetalon, you face a test of ancient history. Having retrieved the tome Legacy of the Aspects, you must show what its lessons taught you. A wrong answer sends you far across Kalimdor. Braug Dimspirit’s trial follows the tests Dorn Plainstalker began at the Weathered Nook. It calls for understanding, not martial survival or blind trust. Braug lives among the crags of the Stonetalon Mountains. He expects seekers to recover ancient texts and learn from their pages. The lesson concerns how the Dragon Aspects were created and divided, and the pact they made long before the Great Sundering. Braug asks what the tome says about the Earth Warder, Neltharion. His madness and betrayal reshaped Azeroth’s surface. You must understand this history before continuing along the path of wisdom.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6627-8a9df976743fe0e2e483/1-0000.mp3", duration = 62.3542857, start = 0},
  },
}
P.transport["quest:6628"] = {
  hash = "c4f86c",
  fullHash = "c4f86c",
  text = "Test of Lore. In the Undercity, initiates face a test of history with Parqual Fintallas. They have scoured the world for historical texts, and this examination is part of spiritual trials begun in Thousand Needles. The Test of Lore is one of the spiritual trials begun in Thousand Needles. Dorn Plainstalker set the trials at the Weathered Nook. This examination carries candidates from the wind-carved canyons of Thousand Needles to the Undercity, where Parqual Fintallas tests their knowledge of history and holds each seeker to a high standard.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6628-0997933d1d84747b307d/1-0000.mp3", duration = 44.3297959, start = 0},
  },
}
P.transport["quest:67"] = {
  hash = "1e2afc",
  fullHash = "1e2afc",
  text = "The Legend of Stalvan. In Darkshire, Clerk Daltry searches the town records for Stalvan Mistmantle. An old address points west to Moonbrook in Westfall, where the search for Stalvan’s past begins. After your inquiries in Darkshire, Clerk Daltry searches the town registry for Stalvan Mistmantle. The ledger has gone years without an update, and lists Stalvan’s last known home as the schoolhouse in Moonbrook, far to the west. Daltry takes the old address as routine record keeping. He asks you to investigate and bring back any records that could bring Darkshire’s archives up to date. The trail runs from Duskwood into Westfall, where the Defias Brotherhood holds Moonbrook. Once a thriving farming settlement, the town is now under outlaw control. Near its center stands the abandoned schoolhouse. Inside, an old footlocker holds the first clear clues to Stalvan’s former life as an educator. A sorrow still lingers around the chest.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_67-78b777088fa2dbdea1e9/1-0000.mp3", duration = 62.8506122, start = 0},
  },
}
P.transport["quest:68"] = {
  hash = "098396",
  fullHash = "098396",
  text = "The Legend of Stalvan. In Moonbrook, The Legend of Stalvan leads you back to Darkshire's records. A dusty, unsent letter from an old footlocker proves Stalvan Mistmantle stayed there before his trail went cold. You find a dusty, unsent letter in an old footlocker while tracing Stalvan Mistmantle's past. Moonbrook was once an agricultural settlement, but now lies in ruin, crowded with outlaws and restless specters. Few remember his brief stay, yet the letter places him in the hamlet. You carry the letter across the border to Darkshire, where Clerk Daltry keeps the town records. He finds it strange that the letter was never mailed, but the evidence confirms Stalvan's connection to Moonbrook. The records can now point toward where Stalvan fled next.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_68-32492c6cd904525a3bdb/1-0000.mp3", duration = 46.6546939, start = 0},
  },
}
P.transport["quest:681"] = {
  hash = "1b8d2b",
  fullHash = "1b8d2b",
  text = "Northfold Manor. At Refuge Pointe, Captain Nials seeks your help against the Syndicate at Northfold Manor. Their hold between Stromgarde's defenders and Southshore slows supplies. Ogres, the Syndicate and the Alliance divide Stromgarde, and the factions fight to a bloody stalemate. The Alliance's forces dwindle as their enemies grow. The defenders need help from Southshore, but supplies arrive slowly. The Syndicate holds the ground between the defenders and Southshore. Captain Nials asks you to go to Northfold Manor, the Syndicate's base, and cut down their highwaymen and mercenaries. He hopes easing their pressure will let more supply trains through.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_681-f7f1decbfa19dfd84d8b/1-0000.mp3", duration = 44.1730612, start = 0},
  },
}
P.transport["quest:683"] = {
  hash = "ec0716",
  fullHash = "ec0716",
  text = "Sara Balloo's Plea. In Ironforge, Sara Balloo grieves for Sully and asks you to carry her plea to King Magni Bronzebeard. Sara has received Sully’s final letter, recovered from the waters of the Thandol Span. She wants the king to remember his sacrifice, so she writes him a plea. Grief keeps her from appearing before the throne herself. She entrusts the sealed letter to you, a champion of the Alliance, to carry to King Magni Bronzebeard.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_683-bf765b8e48b2a84c588d/1-0000.mp3", duration = 32.6269388, start = 0},
  },
}
P.transport["quest:686"] = {
  hash = "d23de5",
  fullHash = "d23de5",
  text = "A King's Tribute. King Magni Bronzebeard answers Sara Balloo with a lasting tribute to her fallen husband, Sully. He sends you across Ironforge with a royal commission for Grand Mason Marblesten. Sara Balloo's plea weighs on King Magni Bronzebeard. War's harsh needs can be hard for common folk to understand, yet every soldier beneath the Alliance banner weighs on his conscience. He cannot undo a death on the front lines. He can see that Sully Balloo's sacrifice is remembered. King Magni chooses a stone memorial for Sully, not empty words. He entrusts you with his royal commission and sends you across Ironforge to Grand Mason Marblesten. The master stonemason receives the king's personal charge and prepares to carve the fallen defender's memory into stone.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_686-3cb936c0c63b7dbf1b30/1-0000.mp3", duration = 51.9836735, start = 0},
  },
}
P.transport["quest:689"] = {
  hash = "22b832",
  fullHash = "22b832",
  text = "A King's Tribute. King Magni Bronzebeard has ordered a memorial for Sully Balloo, who died defending the Thandol Span. Grand Mason Marblesten sends you north to Hillsbrad for stone worthy of the fallen soldier. Grand Mason Marblesten carries King Magni Bronzebeard’s commission to honor Sully Balloo. Sully died in the disaster at the Thandol Span. Dark Iron saboteurs have attacked the span, a vital artery between the dwarven lands and the northern kingdoms. Marblesten will shape a sculpture to withstand time and war, so the Great Forge remembers the dwarven sacrifice. For Sully Balloo’s likeness, Marblesten requires Alterac Granite. Its dense, resilient stone and clean texture make it prized by masons. The finest deposits lie around Darrow Hill in Hillsbrad’s contested foothills. The journey into the troubled north is dangerous, but Marblesten seeks stone worthy of the heroism it will honor.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_689-701015765556d8f821ae/1-0000.mp3", duration = 67.3697959, start = 0},
  },
}
P.transport["quest:69"] = {
  hash = "d888b1",
  fullHash = "d888b1",
  text = "The Legend of Stalvan. In Darkshire, a scratched registry entry sends the search for Stalvan Mistmantle toward Goldshire. Clerk Daltry finds another destination beneath Stalvan Mistmantle's earlier entry in Darkshire's town registry. The hurried note is partly scratched out. Someone meant to hide the route or changed their mind. It points northwest toward the Lion's Pride Inn in Elwynn Forest. You leave Duskwood's shadowed groves for Goldshire's sunny roads, where Stalvan's trail reaches too. The Lion's Pride Inn stands at Elwynn Forest's crossroads, where travelers, merchants, and soldiers gather. Innkeeper Farley runs the busy taproom and may know of an educated wanderer looking for a room.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_69-88174e0c06cdeb03231a/1-0000.mp3", duration = 38.8702041, start = 0},
  },
}
P.transport["quest:6921"] = {
  hash = "7986a1",
  fullHash = "7986a1",
  text = "Amongst the Ruins. At Zoram'gar Outpost, Je'neu Sancrea sends Horde champions beneath the waters of Blackfathom Deeps. The Earthen Ring hopes a fathom core will show what the Twilight's Hammer is doing to the elements. The Twilight's Hammer has seized Blackfathom Deeps, an ancient night elven temple once sacred to Elune. Its cultists now command the submerged passages. At Zoram'gar Outpost on Ashenvale's shore, Darkspear shaman Je'neu Sancrea watches the corruption spread. He fears the cult will turn the local elements against the land and its defenders. Je'neu Sancrea sends Horde champions to recover a fathom core from the fathom stone beneath the waters of the Moonshrine Ruins. Shamans who can read the core will find a detailed record of elemental currents and disturbances. The Earthen Ring hopes that record will reveal the Twilight's Hammer's work and help guard the region against elemental disaster.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6921-3e7831a1226a565595a4/1-0000.mp3", duration = 59.3502041, start = 0},
  },
}
P.transport["quest:6922"] = {
  hash = "62b8a0",
  fullHash = "62b8a0",
  text = "Baron Aquanis. Beneath Ashenvale, Baron Aquanis leaves a strange globe filled with tainted fluid. Je'neu Sancrea of the Earthen Ring suspects the Twilight's Hammer cultists in the submerged ruins and hopes the globe will reveal what corrupted the elemental. In Blackfathom Deeps, foul sorcery has twisted Baron Aquanis into a water spirit. When the elemental is destroyed, a Strange Water Globe remains. The impervious orb holds putrid fluid that seems to have sustained and warped Aquanis's natural essence. Physical force cannot harm it. Its energies unsettle those attuned to the balance of the elements.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6922-a6400ef2c36b43e69fa7/1-0000.mp3", duration = 41.6653061, start = 0},
  },
}
P.transport["quest:6981"] = {
  hash = "079f50",
  fullHash = "079f50",
  text = "The Glowing Shard. Deep in the Wailing Caverns, you find a green shard whose smoky depths stir unease. Its mystery draws you to Ratchet and onward. You carry a green crystal from deep within the Wailing Caverns. Beneath its bright, solid face, shadowy wisps seem to churn. Those who touch it feel uneasy, and its strange presence hints at the corruption around the sleeping druids and their nightmare-haunted sanctuary.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6981-54cd53d08606285605a8/1-0000.mp3", duration = 27.7681633, start = 0},
  },
}
P.transport["quest:70"] = {
  hash = "e0702a",
  fullHash = "e0702a",
  text = "The Legend of Stalvan. In Goldshire, an old letter renews the search for Stalvan Mistmantle. Its trail runs from Elwynn Forest to Stormwind's Canal District. At the Lion's Pride Inn, Innkeeper Farley recalls a stormy night years ago. A traveling courier came in from the rain to find shelter. Around midnight, he rushed downstairs in a panic, wearing only his sleepwear. He vanished into the storm, and no one saw him again. The courier left his satchel and personal chest in the upstairs room. Among the forgotten cargo was an unsent letter bearing the name Stalvan, addressed to someone in Stormwind City's Canal District. The chest remained untouched at the foot of the bed until Farley allowed it to be opened.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_70-9d41e8cb7211544eb9b5/1-0000.mp3", duration = 44.4865306, start = 0},
  },
}
P.transport["quest:700"] = {
  hash = "3661b0",
  fullHash = "3661b0",
  text = "A King's Tribute. Magni Bronzebeard gives Sully Balloo a memorial in Ironforge. Granite from Lordaeron keeps the fallen dwarf in his people's memory. King Magni Bronzebeard commissioned a monument for Sully Balloo, a dwarf who died serving his people. Grand Mason Marblesten carved it from fine granite brought from Lordaeron's war-torn lands. The monument stands in Ironforge, honoring soldiers whose sacrifices help preserve the dwarven kingdom. When told the monument is complete, Magni considers stone and mortality. Carved rock can never equal a brave dwarf's life, he knows, yet he hopes the memorial endures. Then generations walking Azeroth may remember the heroes who bled to secure their tomorrow.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_700-bae7d662936f3bbbfd4d/1-0000.mp3", duration = 49.5804082, start = 0},
  },
}
P.transport["quest:72"] = {
  hash = "6eb548",
  fullHash = "6eb548",
  text = "The Legend of Stalvan. In Stormwind, you search for Stalvan Mistmantle among the Flintridge belongings. By the canals, sealed crates hold what remains of the household, watched over by restless spirits tied to the massacre. You follow Stalvan’s path from Duskwood to Stormwind. Beside the city canals, Caretaker Folsom guards what remains of the Flintridge household. His father served the estate before him and had to mop up blood after a massacre claimed the household. Somehow, Stalvan’s name is tied to that slaughter. The Flintridge trust funds are gone, and royal tax collectors press the estate. Surviving heirlooms and packed belongings wait inside sealed shipping crates along the canal embankment, awaiting auction. You search them for Stalvan’s trail before the family’s remaining goods scatter to collectors across the kingdom.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_72-d4865a3300b53d985a93/1-0000.mp3", duration = 60.2644898, start = 0},
  },
}
P.transport["quest:729"] = {
  hash = "cb0244",
  fullHash = "cb0244",
  text = "The Absent Minded Prospector. In southern Darkshore, hostile stone golems overrun a dig site, and Archaeologist Hollee seeks help in Auberdine. She fears for Prospector Remtravel, her senior colleague, whose research often blinds him to mortal danger. Archaeologist Hollee came across the sea with the Explorers' League. Master Greywhisker sent her to apprentice under Prospector Remtravel, whose discoveries had made him renowned in Ironforge's academic circles. The League sent them to study ancient ruins along Darkshore's untamed coast. As they dug through what seemed to be the remains of a great civilization, violent stone golems burst from the earth and overran the site. In panic, Hollee fled through the night to Auberdine, the night elf port, to seek help. Remtravel barely noticed the danger. Absorbed in his relics, the elderly prospector stayed among the rubble as lumbering constructs surrounded his camp. South of Auberdine, anyone who reaches him finds him grumbling about missing stone brushes and misplaced fossils.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_729-4f293312080e6ab67b1b/1-0000.mp3", duration = 63.3208163, start = 0},
  },
}
P.transport["quest:731"] = {
  hash = "030bd0",
  fullHash = "030bd0",
  text = "The Absent Minded Prospector. At Darkshore's southern ruins, Prospector Remtravel presses on with his dig, hoping to find a prize for the Explorers' League. Hostile troggs and his forgetfulness make the search perilous, and word of his safety must reach his assistant in Auberdine. Far south in Darkshore, Remtravel's Dig lies among ancient ruins. Dwarven excavators searching there uncovered troggs, who drove out the workers and besieged their camp. Remtravel will not return to Auberdine empty-handed. He wanders into danger to recover a fossil, hoping to justify the expedition's costs to the Explorers' League.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_731-9fe94dd2b1ced367adb6/1-0000.mp3", duration = 38.4, start = 0},
  },
}
P.transport["quest:7321"] = {
  hash = "3c2500",
  fullHash = "3c2500",
  text = "Soothing Turtle Bisque. In Tarren Mill, Christoph Jeffcoat hopes Soothing Turtle Bisque will prove the Forsaken can cook with care. He needs snapjaw meat from Hillsbrad's waterways and the shores of Lordamere Lake. Many think the Forsaken have given up the comforts of life, fine cooking among them. Christoph Jeffcoat in Tarren Mill holds otherwise. He boasts that his rich turtle bisque could tempt souls back from beyond the grave. With care in the cooking, he means to show that undead hands can still make a warming dish in a land marked by plague and war. Jeffcoat once gathered ingredients from Hillsbrad's waterways and Lordamere Lake's eastern shores in neighboring Alterac. Now his duties in Tarren Mill and nearby Alliance forces keep him from hunting. So he relies on passing Horde cooks to hunt snapjaws and bring back their meat. Their help keeps his recipe alive.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7321-7fdee2d8a5f2922f821a/1-0000.mp3", duration = 53.2114286, start = 0},
  },
}
P.transport["quest:74"] = {
  hash = "8c4289",
  fullHash = "8c4289",
  text = "The Legend of Stalvan. Beside Stormwind City's canals, you find a clue to Stalvan Mistmantle's past in the Flintridge crate. Its torn journal page points toward Marshal Haggard in Elwynn Forest. Beneath a ceramic vase in the sealed crate lies a torn page from Stalvan Mistmantle's journal. Musty Flintridge heirlooms, old hunting trophies, and family portraits fill the crate. Stalvan's own hand offers a glimpse of the reclusive scholar before tragedy struck.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_74-0dd92fef736cb9d045fd/1-0000.mp3", duration = 31.1902041, start = 0},
  },
}
P.transport["quest:741"] = {
  hash = "36012a",
  fullHash = "36012a",
  text = "The Absent Minded Prospector. From Darkshore, Hollee sends Remtravel’s fossil to Darnassus while she stays to watch the wandering prospector. Chief Archaeologist Greywhisker takes a keen interest in the find. Prospector Remtravel has found a curious fossil on Darkshore’s coast. He would rather keep digging than follow protocol. So Archaeologist Hollee stays with him among the shore’s dangerous beasts and hostile cultists. She asks you to carry the specimen to Darnassus, where a dwarven scholarly delegation is kept. Dwarves from Ironforge have crossed the Great Sea under the Explorers’ League banner. They seek ancient relics and lost history in Kalimdor’s soil. In Darnassus, Chief Archaeologist Greywhisker marvels at Remtravel’s knack for finding ancient treasures. Night elves see their forests as living sanctuaries, while the League sees ancient lands as ground to study and decipher.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_741-63e370c6688c098757f1/1-0000.mp3", duration = 64.6008163, start = 0},
  },
}
P.transport["quest:742"] = {
  hash = "192eb3",
  fullHash = "192eb3",
  text = "The Ashenvale Hunt. In Thunder Bluff, The Ashenvale Hunt sends young Horde champions north to serve at the forest outposts. Heralds direct them to report to Senani Thunderheart at Splintertree Post for a proving hunt. Bluff Runner Windstrider carries an open invitation through Thunder Bluff for proven adventurers. North of the Barrens, the Horde has footholds in an ancient forest, and its outposts need young warriors. Those who answer will face harsher country and test their survival skills beyond Mulgore. Ashenvale offers the Horde rich resources and severe peril. Splintertree Post lies along the main road, while a remote outpost stands on the western coast at Zoram Strand. At Splintertree Post, Senani Thunderheart is a veteran outdoorswoman who organizes a great hunt. There, recruits tame the wilderness and win glory for the Horde.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_742-eb6a7768490050ee285e/1-0000.mp3", duration = 58.2269388, start = 0},
  },
}
P.transport["quest:75"] = {
  hash = "edc04e",
  fullHash = "edc04e",
  text = "The Legend of Stalvan. In Elwynn, your search for The Legend of Stalvan leads you to Marshal Haggard's home. The veteran's failing eyesight left an upstairs chest of papers unread. Marshal Haggard lives near Elwynn Forest's southeastern edge, close to Duskwood and Redridge. Upstairs, an old chest holds parchments he found when he moved into his secluded home. His failing eyesight kept him from reading them, and they have remained untouched until you ask about Stalvan.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_75-96e1da1337d2345f6c16/1-0000.mp3", duration = 28.16, start = 0},
  },
}
P.transport["quest:78"] = {
  hash = "e259eb",
  fullHash = "e259eb",
  text = "The Legend of Stalvan. Marshal Haggard sends you to find Tavernkeep Smitts, who may know the hand behind a page from Stalvan's journal. Marshal Haggard cannot read the faded writing on the torn journal page you recovered from his chest in Elwynn Forest. His failing eyesight leaves the words beyond him. He recalls serving with the Stormwind Guard and spending evenings at the Scarlet Raven Tavern in Darkshire. So he sends you across the river to Tavernkeep Smitts, whose years behind the bar have made him a keeper of local history and rumors.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_78-e78253c5f325bfddfd32/1-0000.mp3", duration = 32.2089796, start = 0},
  },
}
P.transport["quest:78124"] = {
  hash = "c51a65",
  fullHash = "c51a65",
  text = "Nar'thalas Almanac. Scholars seek the Nar'thalas Almanac to preserve ancient magical study. Its recovery brings forgotten lore into a library where researchers can study it. A rare work of arcane study, the Nar'thalas Almanac comes from the ancient traditions of pre-Sundering night elven scholarship. For caretakers of great archives, securing the volume rescues centuries-old lore from obscurity and adds an important piece of history to their shelves. Those who uncover neglected works help bridge forgotten antiquity and modern scholarship. Across Azeroth, archivists and researchers seek lost treatises, field notes, and chronicles. Bringing the Nar'thalas Almanac to a dedicated library lets its keepers safeguard, catalog, and study it, rather than leave it to rot in ruins or fall into careless hands. Each recovered volume offers fresh insight into the arcane arts of past eras.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_78124-919eff01845a36e1c4f9/1-0000.mp3", duration = 68.8587755, start = 0},
  },
}
P.transport["quest:78143"] = {
  hash = "346c8c",
  fullHash = "346c8c",
  text = "Secrets of the Dreamers. A library's scholars seek writings tied to the Dreamers and other magical lore. Travelers bring forgotten works from across the realm, where they can be studied and kept in the archives. Scholars across the realm depend on travelers to recover rare magical texts and historical treatises. These works lie in ancient ruins or private hoards, far from the archives. So adventurers carry them safely to those who study Azeroth's arcane mysteries and preserve its lore. When travelers bring in treatises, archivists add them to the library's permanent collection. Researchers seek obscure writings on the Emerald Dream and arcane theory. Their work continues, and they welcome further magical texts found in the field.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_78143-bd0fca5bb1c0f2c92328/1-0000.mp3", duration = 53.8644898, start = 0},
  },
}
P.transport["quest:79"] = {
  hash = "26fff2",
  fullHash = "26fff2",
  text = "The Legend of Stalvan. In Darkshire, The Legend of Stalvan rests on muddy pages and new proof. Tavernkeep Smitts gives you the pages and sends you to Commander Althea Ebonlocke. Tavernkeep Smitts and Marshal Haggard once investigated the slaughter of a visiting noble family in Duskwood. Haggard then led the Stormwind Guard. At the scene, they found torn, muddy journal pages, but had no handwriting samples or other papers to confirm who wrote them. So the notes could not formally implicate the recluse rumored to live in the wilderness.\n\nNow evidence gathered across Elwynn, Westfall, and Duskwood links the handwriting to Stalvan Mistmantle. The old rumors have become proof of murder.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_79-0578491c27417e51e63a/1-0000.mp3", duration = 50.3902041, start = 0},
  },
}
P.transport["quest:79007"] = {
  hash = "aee90a",
  fullHash = "aee90a",
  text = "... and that note you found. At a recent campsite, cooling embers and scattered supplies are all that remain. A scorched parchment bears a riddle about finding a twin land, the only clue left behind. A recent campfire is dying beside scattered provisions and a blistered piece of paper. Whoever stayed here left recently, and the parchment narrowly escaped the flames. The supplies remain exposed, as though the traveler departed in haste or was interrupted. The surviving scrap bears one instruction: “Not all that burns is lost. Find the twin land, find the place.” No signature, coordinates, or further context survived the fire. The riddle is the only trail left for whoever finds it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_79007-0748d1a3c9b1fd9f7675/1-0000.mp3", duration = 42.3444898, start = 0},
  },
}
P.transport["quest:79008"] = {
  hash = "1efe22",
  fullHash = "1efe22",
  text = "... and that note you found. A scorched note lies beside a dying campfire in Westfall. Its brief message points to a place called the twin land. Travelers crossing Westfall’s abandoned fields and wind-scoured plains find camps left by vagrants, outlaws, or desperate wanderers. This small camp was left in haste or secrecy. Its provisions lie abandoned, embers still glow, and a scorched slip of parchment rests among the scattered debris. The blistered note bears two short sentences: “Not all that burns is lost. Find the twin land, find the place.” Its words point away from Westfall but give no clear direction. What place shares a name, geography, or fate with this land?",
  ["1"] = {
    {file = "Audio/Transport/full_quest_79008-018430af5972884259af/1-0000.mp3", duration = 39.8367347, start = 0},
  },
}
P.transport["quest:79091"] = {
  hash = "d6771d",
  fullHash = "d6771d",
  text = "Archmage Antonidas: The Unabridged Autobiography. In Ironforge, you seek Archmage Antonidas: The Unabridged Autobiography. The rare volume holds the late Kirin Tor leader's own account and offers insight into Dalaran's history and high arcane scholarship. Archmage Antonidas led the Kirin Tor for decades and ruled Dalaran. One of Azeroth's most brilliant minds, he rose through the ranks of the Violet Citadel and mastered the arcane. His unabridged autobiography records his leadership during the Second and Third Wars. For scholars and practitioners of magic, it offers a firsthand view of Dalaran's inner workings and the arcane arts. Before reaching its new home, the rare manuscript rested in Ironforge's grand library. In the Hall of Explorers, dwarven archivists kept it beside ancient titan relics and dwarven histories. Their vast collections hold texts gathered from ruins and foreign kingdoms across Azeroth. Yet arcane scholars elsewhere seek such works for their own collections, sure the busy archivists will never notice one missing volume.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_79091-0fa67b2d618ea0b0c694/1-0000.mp3", duration = 71.8367347, start = 0},
  },
}
P.transport["quest:79092"] = {
  hash = "736c38",
  fullHash = "736c38",
  text = "Archmage Theocritus' Research Journal. At the Tower of Azora, Archmage Theocritus keeps a journal of his investigations. Now you carry its magical insights to the scholars of the Ironforge Library, where they can join the dwarven archive. Archmage Theocritus is an esteemed spellcaster known throughout the Alliance. He is stationed at the Tower of Azora in eastern Elwynn Forest, where he has studied alone for years. His investigations range from curious artifacts and ley line anomalies to nearby magical threats.\n\nHe records his findings in detailed journals. This volume offers a rare chance to study the personal observations of a senior Kirin Tor archmage. The Explorers' League and the caretakers of the Ironforge Library maintain one of the continent's greatest archives. You bring Archmage Theocritus' Research Journal to them, helping preserve and catalog its arcane insights beside the historic volumes of Khaz Modan. The librarians welcome further magical discoveries that can broaden their shared wisdom.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_79092-2202f3f067344038ce53/1-0000.mp3", duration = 77.322449, start = 0},
  },
}
P.transport["quest:79093"] = {
  hash = "f37d93",
  fullHash = "f37d93",
  text = "Rumi of Gnomeregan: The Collected Works. A compiled work by Rumi of Gnomeregan is sought for a library’s collection. Its pages preserve gnomish writings and knowledge that might otherwise be lost. Gnomish writings were scattered, buried, or left in danger when troggs overran Gnomeregan. Now scholars and archivists seek surviving manuscripts, treatises, and compiled works. They hope to keep the wisdom and ingenuity of gnomish thinkers alive. When travelers find collected works in the field and bring them to the archives, curators add them to their growing collections. Each recovered manuscript widens what scholars can study. Archivists welcome more magical and historical texts, keeping them within reach of scholars, mages, and historians who guard Azeroth’s learning.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_79093-4ea79493af2477149481/1-0000.mp3", duration = 54.3085714, start = 0},
  },
}
P.transport["quest:79095"] = {
  hash = "68ba2a",
  fullHash = "68ba2a",
  text = "The Apothecary's Metaphysical Primer. Curators seek The Apothecary's Metaphysical Primer to enrich their archives. Its delivery helps preserve rare alchemical and arcane theory for researchers and spellcasters. Curators welcome The Apothecary's Metaphysical Primer for its study of esoteric and magical principles. Owen Thadd adds the text directly to his working collection of magical references. Owen Thadd's collection in Undercity preserves specialized treatises. By bringing him rare primers on arcane and alchemical theory, you help keep metaphysical insights safe in the archives and accessible to researchers instead of leaving them lost in the wilderness.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_79095-67be20c949bbddec2665/1-0000.mp3", duration = 49.1885714, start = 0},
  },
}
P.transport["quest:79097"] = {
  hash = "cc5cd2",
  fullHash = "cc5cd2",
  text = "Baxtan: On Destructive Magics. At the library, Baxtan: On Destructive Magics joins the works scholars gather to understand dangerous arcane power. Scholars seek to preserve what is known of arcane lore. When you find a text on destructive magic, its place is in careful academic keeping. There, its power and peril can be understood instead of lost. The library holds works on history, science, and the arcane. Its scholar welcomes travelers who recover forgotten treatises from dangerous corners of the world. Each volume adds to the library's knowledge.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_79097-85a53f73284841326134/1-0000.mp3", duration = 42.1093878, start = 0},
  },
}
P.transport["quest:79192"] = {
  hash = "b09875",
  fullHash = "b09875",
  text = "Stepping Stones. At a backcountry camp in the Barrens, a weathered note points toward Stepping Stones, a mountain refuge near Desolace. It says two couriers made deliveries for the New Plague, and calls their sudden ends simple apothecary accidents. A torn message hangs from a wooden plank at a backcountry camp in the Barrens. Mercenaries, cutthroats, and drifters stop at such camps for brief shelter, far from the eyes of the Crossroads or Ratchet. Among the ordinary signs of the wilds, the note gives you reason to look beyond the camp toward the mountains.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_79192-a8c5b81d542c0c19bb6d/1-0000.mp3", duration = 36.7281633, start = 0},
  },
}
P.transport["quest:79980"] = {
  hash = "0d07f1",
  fullHash = "0d07f1",
  text = "Scramble. A scavenger's note sends travelers down a steep cliff in search of Scramble's hidden supplies. One hundred paces north, they find provisions and a dirty parchment. A note points the way to a hidden supply cache. Its writer offers a few informal words of encouragement, then gives precise directions: go one hundred paces due north down the treacherous cliffside. Provisions wait there to keep a traveler going.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_79980-c7c94af57f3a669c6361/1-0000.mp3", duration = 26.8538776, start = 0},
  },
}
P.transport["quest:80"] = {
  hash = "8f0f6b",
  fullHash = "8f0f6b",
  text = "The Legend of Stalvan. In Darkshire, the search for Stalvan Mistmantle brings a bloodstained journal page to the Night Watch. Commander Althea Ebonlocke sends you to Clerk Daltry to compare its writing with the town records. The Night Watch has gathered journal pages from across Duskwood and the surrounding human territories. Together, they seem to condemn Stalvan Mistmantle, the elusive tutor. Commander Althea Ebonlocke has suspected him for some time, but she needs proof before passing judgment. The bloodstained page alone cannot show who wrote it. Its hand must be matched to Stalvan’s.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_80-71d141cf31b5dc7496ce/1-0000.mp3", duration = 43.2326531, start = 0},
  },
}
P.transport["quest:822"] = {
  hash = "d9b731",
  fullHash = "d9b731",
  text = "Chen's Empty Keg. In Ratchet, Brewmaster Drohn turns to another recipe Chen Stormstout shared with him. Trogg ale calls for rare organs and glands from the Barrens' beasts. You helped Brewmaster Drohn recreate Chen Stormstout's first draught. Now you learn the wandering pandaren shared more brewing secrets. Drohn has the formula for trogg ale, a strange brew made from potent parts of the wild beasts of central Kalimdor, not grain. Trogg ale calls for lightning glands from stormhides, a saliva gland from greater thunderhawks, and a hearty liver from the roaming kodos of the plains. Distilled together, these ingredients make a fiercely stimulating drink for life in the wilderness.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_822-8fe8461c2ec5b1807358/1-0000.mp3", duration = 39.3665306, start = 0},
  },
}
P.transport["quest:824"] = {
  hash = "ca0909",
  fullHash = "ca0909",
  text = "Je'neu of the Earthen Ring. At Zoram'gar Outpost, Je'neu of the Earthen Ring studies a corruption spreading through the region. Horde travelers bring him a corrupted water globe taken from Ashenvale's elementals. He seeks to understand the blight along the Zoram Strand and in Blackfathom Deeps, hoping to halt the poison in the waters. Mastok Wrilehiss sends you to Je'neu Sancrea with a corrupted water globe recovered from Ashenvale's elementals. Strange elementals have appeared across the region, driven by power the scouts cannot explain. Among their remains, one intact globe pulses with corrupted magic.\n\nMastok knows soldiers and scouts lack the spiritual insight to understand it. So he directs Horde travelers to someone versed in ancient legends and elemental lore. Je'neu Sancrea serves the Earthen Ring, an order of shamans devoted to balance among Azeroth's primal forces. Horde forces guard the Zoram Strand frontier while he studies the spiritual wound in the nearby temple ruins of Blackfathom Deeps.\n\nTo Je'neu, an elemental drawing strength from a tainted vessel is no isolated threat. It is an alarming omen: unseen ancient powers are perverting the natural order.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_824-f6c2857d2f6ee8b52af3/1-0000.mp3", duration = 88.5028571, start = 0},
  },
}
P.transport["quest:843"] = {
  hash = "165224",
  fullHash = "165224",
  text = "Gann's Reclamation. In the southern Barrens, Gann's Reclamation turns toward Bael Modan. Gann Stonespire, a tauren exile, asks you to strike at the dig after it drove him from his clan's ancestral home and hunting grounds. Gann Stonespire walks alone along the southern road, seeking justice for his fallen kin. His clan lived among the red bluffs south of the Barrens. Dwarves from Ironforge built Bael Modan there, driving the tauren out or killing them to make room for quarries and trenches. Gann says peaceful protests and diplomacy failed. Now he seeks vengeance for his displaced and slain clan. At Bael Modan, dwarven excavators tear into the hills with steam engines and explosives. Prospector Khazgorm leads the dig deep underground. Gann asks you to thin the ranks of Bael'dun excavators and foremen, kill Khazgorm, and bring back the prospector's personal excavation notes. He wants to learn what the Alliance expedition seeks in the sacred soil.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_843-4085e4c51cc562fa1a0a/1-0000.mp3", duration = 65.8285714, start = 0},
  },
}
P.transport["quest:846"] = {
  hash = "ff4678",
  fullHash = "ff4678",
  text = "Revenge of Gann. In the southern Barrens, Gann Stonespire prepares to strike back at the Bael Modan dwarves. After Prospector Khazgorm's death, he sends Horde allies into the fortress to seize volatile munitions for his attack. Gann Stonespire knows Prospector Khazgorm's death has only slowed the Bael Modan dig site. The dwarves will return to work, and another foreman will soon direct the machines cutting through Gann's ancestral land. He will not watch the earth suffer more excavation. So Gann means to turn the invaders' demolitions gear against them and rupture their stronghold from within. Bael Modan's fortress guards an excavation base and a garrison of soldiers, riflemen, and officers who protect dwarven interests in the Barrens. Its defenders carry nitroglycerin, wood pulp, and sodium nitrate for industrial demolition. Gann sends Horde allies past the perimeter to take these volatile supplies. With enough in hand, he can assemble a powerful satchel charge.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_846-57eab98ae54db71fb5c8/1-0000.mp3", duration = 69.2244898, start = 0},
  },
}
P.transport["quest:849"] = {
  hash = "471d53",
  fullHash = "471d53",
  text = "Revenge of Gann. At Bael Modan, Gann Stonespire turns the dwarves’ plans against their flying machine. The Horde agent seeks revenge for his fallen tribe. Bael Modan’s dwarven excavation covers ancestral grounds of the displaced Stonespire tauren. The Prospectors depend on a gyrocopter for reach and military strength. It waits on a watchtower above the dig, surveying the Barrens and guarding the dwarves’ supply lines. To Gann, the machine also marks the Alliance’s intrusion into kalimdorian soil.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_849-67fcd4ff431cdf46e65c/1-0000.mp3", duration = 33.3061224, start = 0},
  },
}
P.transport["quest:857"] = {
  hash = "8e4094",
  fullHash = "8e4094",
  text = "The Tear of the Moons. At Bael Modan, Feegly the Exiled still begs for the Tear of the Moons, the relic that drove him mad. Dwarves found the Tear of the Moons while cutting into the southern Kalimdor hills for Bael Modan. It was the expedition’s first major discovery. Its strange influence fell at once on Feegly, one of the workers. Feegly claimed the Tear gave him immense power. He turned violently on his comrades to protect it. General Twinbraid saw the relic’s corrupting hold, called it cursed, took it from Feegly, and locked it in the keep. Banished from the excavation camp, Feegly took refuge among the cliffs. Bitter and obsessed, he begs passing travelers to steal the Tear back.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_857-a8367370388ce3484e03/1-0000.mp3", duration = 44.0946939, start = 0},
  },
}
P.transport["quest:862"] = {
  hash = "19ef19",
  fullHash = "19ef19",
  text = "Dig Rat Stew. Grub waits east of the Crossroads, hungry for dig rat stew. He sends travelers to Bael Modan in the southern Barrens for the rodents his recipe needs. Hunters cross the dry Barrens in search of zhevras, plainstriders, and raptors. Grub, an orc camping east of the Crossroads, wants something else: dig rats. Hungry all day, he offers his recipe to any traveler willing to catch the burrowing rodents. Deep in the southern Barrens, dwarven prospectors dig into the red earth at Bael Modan. Their work has disturbed nests of dig rats. The dwarves see an infestation; Grub sees a feast near the excavation. Grub says dig rats taste best after rotting for several weeks. For a hungry traveler who wants food now, he accepts fresher meat. His recipe shows how forgiving roadside cooking can be on Kalimdor's frontier.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_862-ffe002e1c19308142947/1-0000.mp3", duration = 54.3608163, start = 0},
  },
}
P.transport["quest:86614"] = {
  hash = "5ab21d",
  fullHash = "5ab21d",
  text = "Silver of the Waves. A lost silver hair clip waits among fishing debris, and its owner is caught up in daily chores. Its return brings relief and restores a keepsake thought lost to the water. Among discarded fishing debris, you find an ornate silver hair clip marked with the initials K.D. Rusted hooks and broken wire spools lie nearby. Moisture has tarnished the clip, but its fine work still shows beneath the corrosion. The clip belongs to a hardworking local, busy with daily chores. You return the keepsake, which its owner had thought lost to the water for good. A little polishing will restore its shine, and the grateful owner welcomes its return.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_86614-2708cad7e99524c56012/1-0000.mp3", duration = 41.6653061, start = 0},
  },
}
P.transport["quest:86776"] = {
  hash = "eea765",
  fullHash = "eea765",
  text = "Ingredients for the Forge. In Thelsamar, Morhan Coppertongue needs bronze bars to fill his dwindling workshop stores. Far from Ironforge's steady trade, the settlement depends on travelers to bring the metals its forge needs. Thelsamar keeps a quieter pace than Ironforge's Great Forge. Far from the capital, supplies can be hard to come by. Morhan Coppertongue, the local blacksmith, makes the hardware, pots, and tools the township needs. Yet bronze and other raw metals often run short. Without regular shipments from the city, passing travelers and prospectors help keep the local anvils at work. Bronze bars let Morhan resume making goods for daily use. But the forge still faces shortages, and Loch Modan has no reliable merchant route bringing coal to town.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_86776-6b335fdb113bbe87b564/1-0000.mp3", duration = 44.4081633, start = 0},
  },
}
P.transport["quest:868"] = {
  hash = "2540f8",
  fullHash = "2540f8",
  text = "Egg Hunt. Across the Barrens, Korran seeks silithid eggs for study. The Horde scholar at the Crossroads has heard of clever insect creatures in the south and wants their intact eggs brought to Orgrimmar. From the Crossroads, Korran watches the Barrens and sends reports to Orgrimmar. The Horde faces tribal conflicts and Alliance incursions, yet the land itself is changing. In the southern Barrens, intelligent insects have begun to burrow. They move as one mind. Korran needs samples to learn where the silithid come from and what drives them. With an excavation claw, you travel to the Field of Giants and lift intact eggs from the dirt mounds. Disturb one mound and the nearby brood comes to defend it. Their coordination is uncanny.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_868-3929d1844921d6fca965/1-0000.mp3", duration = 47.124898, start = 0},
  },
}
P.transport["quest:873"] = {
  hash = "3a830f",
  fullHash = "3a830f",
  text = "Isha Awak. Along the Merchant Coast, Mahren Skyseer sends you hunting in the Great Sea. Slay Isha Awak, the Deep Doom, and bring back its heart for a rite of spirit and respect. South of Ratchet, Isha Awak prowls beneath the waves. The immense sea creature is known as the Deep Doom and holds the coastal waters by force. Human forces camped along the shore fear those waters. They have lost many scouts and soldiers to the predator. Mahren Skyseer reveres the leviathan, while the humans fear it. To the tauren mystic, Isha Awak is no curse or mere pest. It is a worthy foe whose might tests a hunter's resolve. Slaying the beast brings spiritual communion. Its heart holds the beast's essence, and claiming it lets the hunter carry that untamed spirit forward.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_873-1599fdf1f8fde6dd8325/1-0000.mp3", duration = 46.9159184, start = 0},
  },
}
P.transport["quest:874"] = {
  hash = "68a6d3",
  fullHash = "68a6d3",
  text = "Mahren Skyseer. At Camp Taurajo, proven hunters are sent east to Mahren Skyseer. Jorn Skyseer sends them to his sister to learn how to track along the Barrens shore. At Camp Taurajo, Jorn Skyseer tests hunters against the dangerous beasts of the southern Barrens. Once they prove themselves on the red plains, he sends them beyond dry earth and open savanna. A tracker must learn to follow prey through swamps, over sheer crags, and beside the crashing waves of the Great Sea. Mahren Skyseer keeps a camp far east along the coast. Jorn studies thunderhawks and plains stalkers, while his sister follows creatures that live in the salt spray. Reaching her means crossing dangerous ground. Kul Tiras marines and Theramore expedition forces hold fortified outposts and watchtowers across the coastal lowlands.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_874-3f3c7660967d5d8db7fc/1-0000.mp3", duration = 49.8416327, start = 0},
  },
}
P.transport["quest:876"] = {
  hash = "de3396",
  fullHash = "de3396",
  text = "Serena Bloodfeather. Across the northern Barrens, harpy attacks threaten the Crossroads supply lines. Serena Bloodfeather leads the Witchwing flock against the Horde, driven by vengeance for her sister, whom Rexxar slew during Durotar’s founding. Breaking the flock’s coordination could open the trails again. Witchwing harpies strike the trails northwest of the Crossroads under Serena Bloodfeather’s command. Hunger is not their only cause. Serena seeks vengeance against the Horde for her sister, the notorious matriarch Bloodfeather, whom the beastmaster Rexxar slew during Durotar’s founding. Now Serena rallies her flock against supply trains, scouts, and merchants on the arid trails.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_876-f14f8124558a6a3388f0/1-0000.mp3", duration = 40.9861224, start = 0},
  },
}
P.transport["quest:878"] = {
  hash = "85716d",
  fullHash = "85716d",
  text = "Tribes at War. From his cage in Camp Taurajo, Mangletooth bargains for help against the Bristleback. The Razormane captive offers intelligence about quilboar attacks in exchange for the deaths of rival spiritual leaders. The tauren hold Mangletooth, a Razormane quilboar, in Camp Taurajo. For years, the Razormane and Bristleback have contested the Barrens. Their sudden ambushes make it hard for the Horde to secure its settlements and supply lines. Mangletooth offers to explain who is tormenting Thork's outpost, but first he asks a Horde champion to kill the Bristleback's most revered casters. Mangletooth sends you north to strike at the Bristleback's spiritual heart: its Water Seekers, Thornweavers, and Geomancers. Both tribes revere the earth and draw power from ancient magic tied to their demigod progenitor, Agamaggan. Killing these casters weakens Bristleback rituals and leaves the tribe open to Razormane rivals. It also eases pressure on nearby trails.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_878-8c5aae12d4278a65d1ff/1-0000.mp3", duration = 58.0702041, start = 0},
  },
}
P.transport["quest:879"] = {
  hash = "185c36",
  fullHash = "185c36",
  text = "Betrayal from Within. At Camp Taurajo, Mangletooth offers Horde travelers a path to vengeance. His Razormane kin left him for dead, and he names three warlords from Razorfen Kraul who direct attacks across the Barrens. Mangletooth sits in a cage at Camp Taurajo, abandoned by his Razormane kin after their defeat. He has lost all loyalty to them and now faces execution. He offers Horde travelers knowledge of the leaders behind the ruthless raids across the plains, hoping to see those leaders fall before his own end. Razormane attacks trouble the Horde, while Thork at the Crossroads struggles to curb them. Mangletooth names three commanders from deep within Razorfen Kraul: Lok Orcbane, a formidable warrior, and his companions Nak, a tracker, and Kuz, a spellcaster. They direct raiders from encampments far to the south. Mangletooth demands their severed skulls as proof that his betrayers have fallen before his own end arrives.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_879-17084610eed377d08542/1-0000.mp3", duration = 54.4130612, start = 0},
  },
}
P.transport["quest:883"] = {
  hash = "91fb5b",
  fullHash = "91fb5b",
  text = "Lakota'mani. At Camp Taurajo, hunters bring Lakota'mani's hoof to Jorn Skyseer after the hunt. The offering honors the kodo's spirit and marks the hunter as an equal to its strength. Across the Barrens, Lakota'mani moves among the kodo herds, famed for great size and endurance. In Taur-ahe, the tauren tongue, his name means “Earthshaker.” Each step rumbles across the plains. Tauren hunters track and defeat such a beast not for slaughter, but to meet the raw vigor of Kalimdor's wildlife in a sacred hunt. When you bring Lakota'mani's hoof to Jorn Skyseer at Camp Taurajo, the hunt reaches its close. Jorn sees new power and a stronger stride in hunters who return from the encounter. The trophy earns his blessing. It honors Lakota'mani's courage and primal spirit as companions on your path.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_883-b9d8d01a2f4f30954521/1-0000.mp3", duration = 47.882449, start = 0},
  },
}
P.transport["quest:884"] = {
  hash = "f83edd",
  fullHash = "f83edd",
  text = "Owatanka. In the southern Barrens, Owatanka roams as a swift thunder lizard the tauren call Bluebolt. Bring his crackling tailspike to Jorn Skyseer at Camp Taurajo. The gift honors the elders’ tradition of learning from Kalimdor’s primordial beasts. Tauren hunters speak of Owatanka with reverence. Unlike his massive, plodding kin, he moves with blinding speed. They call him Bluebolt, for the storm changed him. Tauren lore says lightning struck Owatanka long ago. The thunder lizard survived, filled with unending energy and fury. Even after his death, his tailspike crackles with stray sparks when handled, a remnant of the storm’s power. Take Owatanka's Tailspike to Jorn Skyseer at Camp Taurajo. It marks a hunter’s prowess and spirit. Jorn recognizes the encounter in the eyes of any hunter who has outmatched the beast’s speed. Presenting the trophy honors Bluebolt’s enduring swiftness.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_884-8d5e38589f6b355444c4/1-0000.mp3", duration = 54.9877551, start = 0},
  },
}
P.transport["quest:885"] = {
  hash = "5a918e",
  fullHash = "5a918e",
  text = "Washte Pawne. Across the southern Barrens, Washte Pawne's feather leaves hunters with a pain they carry to Jorn Skyseer at Camp Taurajo. For the tauren, the hunt becomes a trial of regret. Thunderhawks are hard to find in the Barrens, and the nomadic tribes honor them. In Taurahe, Washte Pawne means “Spirit Biter.” Its death is no ordinary hunt. Shamans whisper that striking down a thunderhawk may bring triumph or misfortune. After Washte Pawne falls, its feather burns against the skin with a pain that lingers. At Camp Taurajo, Jorn Skyseer explains that the ache is regret, not poison. Taking a magnificent life carries a burden. The hunter must face that sorrow and turn it into lasting wisdom.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_885-dcc664fdf801f0fa7d3f/1-0000.mp3", duration = 43.8073469, start = 0},
  },
}
P.transport["quest:8852"] = {
  hash = "377e0c",
  fullHash = "377e0c",
  text = "Ten Signets for War Supplies. Warlord Gorchuk trades Horde Commendation Signets for war supplies in Orgrimmar. Champions exchange formal recognition for equipment to help keep soldiers supplied at the front. Warlord Gorchuk oversees the Horde's supplies in the Valley of Spirits. As the Horde gathers its legions, weapons, rations, and armor must reach the front. Champions who have proved their dedication can trade commendation signets for useful equipment from the army's reserves. Horde Commendation Signets prove a soldier's service and bring prestige with the leadership. Trading them for gear gives up that recognition for a better chance to survive the fighting. Gorchuk knows a satchel of supplies or a sturdy weapon can mean the difference between life and death when armies clash.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8852-792258a156445c43091e/1-0000.mp3", duration = 43.8595918, start = 0},
  },
}
P.transport["quest:889"] = {
  hash = "d56275",
  fullHash = "d56275",
  text = "Spirit of the Wind. At Camp Taurajo, Mangletooth offers travelers a swift crossing of the Barrens through Agamaggan’s blood shards. His ritual lends them the speed to pass through the plains. The Barrens are easier to cross quickly, before its beasts and centaur warbands find you. At Camp Taurajo, the captive quilboar Mangletooth draws on red crystalline blood shards scattered across the region. Bring him ten, and he channels their lingering power into a burst of swiftness called the Spirit of the Wind. Quilboar honor Agamaggan, the Great Boar whose blood spilled across central Kalimdor during the ancient War of the Ancients. Though held captive, Mangletooth knows the rites that channel that blood. His ritual stirs wild vigor, lending a runner speed to match the zhevra herds. The quilboar are bitter enemies of the Horde, yet Mangletooth shares Agamaggan's boons with travelers who bring him fresh shards.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_889-9461f9ed3b7f47841d20/1-0000.mp3", duration = 52.7673469, start = 0},
  },
}
P.transport["quest:89"] = {
  hash = "6c6561",
  fullHash = "6c6561",
  text = "The Everstill Bridge. In Lakeshire, The Everstill Bridge waits unfinished while its iron goes to war. The town forged its construction iron into weapons during the last orc invasion, and Redridge gnolls ambushed the replacement caravan from Stormwind. Across Lake Everstill, Lakeshire's stone bridge still lacks its final work. It links the western roads toward Elwynn Forest with the far bank and the northern passes. Recent orc incursions nearly ruined the town. To survive, Lakeshire melted the bridge's iron into munitions, blades, and plate armor against the Blackrock invaders. The bridge remained unfinished and exposed. Foreman Oslow sought fresh materials from the House of Nobles and Stormwind. A caravan bearing iron set out, but Redridge gnolls ambushed it on the road. They carried iron pikes and rivets to their camps in the northern hills. You can help recover the stolen supplies. Without them, repairs remain stalled as gnolls and orcs tighten their hold on the mountains.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_89-786177756b3d460a6eed/1-0000.mp3", duration = 62.3281633, start = 0},
  },
}
P.transport["quest:891"] = {
  hash = "25382f",
  fullHash = "25382f",
  text = "The Guns of Northwatch. Captain Thalo'thas Brightsun in Ratchet wants Northwatch Hold's guns silenced. Its gunners have been firing on merchant vessels, so he sends you down the Merchant Coast to strike the artillery officers and bring back badges from fallen infantry. Northwatch Hold guards the southern Barrens coast for the humans of Theramore. Its soldiers watch Horde activity in Kalimdor. Yet fear makes them see every unfamiliar sail as a threat. Their guns fire without warning at passing ships, putting Ratchet's merchant traffic and privateering vessels in danger. Captain Brightsun wants an answer for the attacks on his ships. Captain Fairmount commands Northwatch, while Whessan and Smythe direct its guns. Defeat them and take Theramore medals from the garrison. The artillery will fall into disarray, giving Ratchet's ships room to travel along the Merchant Coast.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_891-b59b4cf0a3a80b36d8bd/1-0000.mp3", duration = 51.4089796, start = 0},
  },
}
P.transport["quest:893"] = {
  hash = "1a669d",
  fullHash = "1a669d",
  text = "Weapons of Choice. At Camp Taurajo, Tatternack Steelforge studies reports of sturdy Razormane weapons. He sends travelers past the Field of Giants to recover them, so the Horde can judge the danger. In the southern Barrens, the Razormane are making unusually durable weapons. The Horde has taken notice, for most quilboar are thought to fight crudely with wood, bone, and stone. Tatternack Steelforge, an orc smith at Camp Taurajo, investigates under orders from Warchief Thrall. He doubts the quilboar know proper metalwork and seeks proof: have they learned new techniques, or found better supplies? Tatternack needs weapons from different parts of the Razormane arsenal to study their craft. South of the Field of Giants, scouts face Razormane war camps and seize weapons from their fighters. Razormane Stalkers carry backstabber daggers, Razormane Seers wield charred wands, and frenzied shock troops bear heavy war shields. Together, these arms reveal something of the martial and mystic arts behind the Razormane push against Horde territory.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_893-e8be0202c7afdd064e63/1-0000.mp3", duration = 58.88, start = 0},
  },
}
P.transport["quest:897"] = {
  hash = "29dd14",
  fullHash = "29dd14",
  text = "The Harvester. In the southern Barrens, a severed head brings The Harvester’s strange presence to Camp Taurajo. Jorn Skyseer examines the remains, and the creature’s arrival threatens the land’s spiritual and natural balance. You find the severed head of a silithid called the Harvester in the southern Barrens. Lions, raptors, and kodos roam these grasslands, but this chitinous insect is unlike the native wildlife. Its presence suggests an alien ecology has reached Kalimdor’s open plains.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_897-86760ac8f8055e6c1675/1-0000.mp3", duration = 29.2571429, start = 0},
  },
}
P.transport["quest:898"] = {
  hash = "819401",
  fullHash = "819401",
  text = "Free From the Hold. At Northwatch Hold, Gilthares Firebough waits in a dungeon after Alliance forces sink his ship off the Barrens coast. The elf deckhand longs to reach his captain in Ratchet. Gilthares Firebough is held in the dungeons of Northwatch Hold. Theramore keeps this fortress on the Barrens coast as its military foothold, with a garrison watching for threats. Gilthares was aboard a ship carrying moonshine between Ratchet and Booty Bay when Alliance forces bombarded it and sent it beneath the sea. He alone survived. The soldiers brought him to Northwatch and accused him of conspiring against the Alliance as an enemy agent. Gilthares says he is only a deckhand who carried illicit liquor. With help from Horde forces, he fights his way out of Northwatch Hold and flees north along the shore toward Ratchet. There, Captain Thalo'thas Brightsun welcomes him back to the crew of the Thalo'dan Privateers.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_898-0a7b6b802ad077030aad/1-0000.mp3", duration = 53.2636735, start = 0},
  },
}
P.transport["quest:899"] = {
  hash = "7d183a",
  fullHash = "7d183a",
  text = "Consumed by Hatred. At the Crossroads, Mankrik turns his grief into a campaign against the Bristleback quilboar. Separated from his wife in a violent ambush, the orc calls on Horde travelers to kill the creatures and bring back their tusks. Mankrik still bears the grief of the quilboar ambush that battered him and left his wife missing. At the Crossroads, he looks toward the arid horizon and thirsts for Bristleback blood, though he has killed many himself. Now he calls on fellow Horde travelers to help him carry on the fight. Mankrik demands sixty Bristleback quilboar tusks. Each one marks suffering returned to the creatures that tore his life apart. The trophies cannot heal his grief or end his desire for revenge. Yet seeing the Bristlebacks bleed brings the wounded warrior a fleeting, bitter satisfaction.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_899-51d2049574e4547a178d/1-0000.mp3", duration = 49.2669388, start = 0},
  },
}
P.transport["quest:90"] = {
  hash = "7056d5",
  fullHash = "7056d5",
  text = "Seasoned Wolf Kabobs. At the Scarlet Raven Tavern, Chef Grual prepares his signature dish for Darkshire. He asks you to hunt Duskwood wolves for meat while his herbs arrive from Stormwind City. Darkshire stands isolated among the horrors creeping through Duskwood. Trade caravans seldom reach town, farming has failed, and undead lurk nearby, yet people still need food. At the Scarlet Raven Tavern, Chef Grual turns dangerous forest wolves into hearty skewers. The local soil and timber cannot support delicate crops, so he relies on spices from the capital to make the gamey meat palatable. Grual has just received a shipment of Stormwind Seasoning Herbs. Now he needs lean meat from the ferocious wolves stalking Duskwood. The delivery shows how Darkshire remains tied to the wider kingdom. Royal military aid has dwindled, while supply lines between city merchants and outer hamlets barely endure.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_90-6acedc29657d1bdcf122/1-0000.mp3", duration = 54.0734694, start = 0},
  },
}
P.transport["quest:906"] = {
  hash = "4cef7b",
  fullHash = "4cef7b",
  text = "Betrayal from Within. In the central Barrens, Betrayal from Within brings the hunt for Lok Orcbane to its end. His fall will weaken the Razormane raids, and you carry his severed head to Thork at the Crossroads. At Camp Taurajo, Mangletooth is a captured Razormane quilboar held in a cage. He names Lok Orcbane as the chieftain directing attacks on Horde caravans. After you slay Lok deep in the southern thorn mazes, Mangletooth gives you the chieftain's skull. He finds it amusing that the orcs will benefit from betrayal within the tribe without knowing a captive quilboar helped them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_906-54214840b41b99aeb397/1-0000.mp3", duration = 32.0261224, start = 0},
  },
}
P.transport["quest:91"] = {
  hash = "7dac59",
  fullHash = "7dac59",
  text = "Solomon's Law. In Lakeshire, Bailiff Conacher seeks proof that the sentence against the Shadowhide gnolls has been carried out. They aided Morganth, an enemy of Stormwind, and the town hall has decreed their deaths. Lakeshire governs Redridge with little military help from Stormwind. Magistrate Solomon and the town officials rely on strict frontier authority to keep order. Bailiff Conacher works from the town hall as the magistrate court's arm. When threats reach the township, the court places bounties on offenders. It depends on hired mercenaries and traveling defenders to uphold the kingdom's laws. The Shadowhide clan faces execution for aiding Morganth, a rogue spellcaster in the eastern hills. Lakeshire and Stormwind law calls for death when someone directly helps a declared enemy of the realm. The gnolls carry out Morganth's bidding. So the court treats them as treasonous fighters, not wild scavengers.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_91-48020bfe532a9955779b/1-0000.mp3", duration = 54.7265306, start = 0},
  },
}
P.transport["quest:913"] = {
  hash = "acf822",
  fullHash = "acf822",
  text = "Cry of the Thunderhawk. In the southern Barrens, Cry of the Thunderhawk brings a hunter to the final trial. Entrusted by Camp Taurajo's elders, you seek a winged serpent in the scrublands and return with its wings to prove mastery of the savanna's fiercest beasts. After hunters prove themselves against prowling plainstriders, prowlers, and agitated thunder lizards, Jorn Skyseer directs them toward their final challenge. The thunderhawk is one of the fiercest aerial predators around Camp Taurajo. Slaying one takes patience, sharp aim, and an awareness of the sky that few landbound predators possess. Bringing back the thunderhawk's wings ends a novice's tutelage under Camp Taurajo's watch. To the tauren, hunting is no mere slaughter. It is a spiritual walk in harmony with the Earthmother and the wild's natural order. Besting this proud creature shows strength, courage, and honor, virtues needed before entering the harsher wilderness beyond the central plains.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_913-c10029b715ffe7db5833/1-0000.mp3", duration = 53.3420408, start = 0},
  },
}
P.transport["quest:914"] = {
  hash = "5b5970",
  fullHash = "5b5970",
  text = "Leaders of the Fang. In the Wailing Caverns, four leaders of the Druids of the Fang threaten the Barrens. Nara Wildmane sends Horde champions from Thunder Bluff to slay them and take their twisted dream gems. If the druids are not stopped, their serpentine nightmare may claim the land. Naralex, a night elf druid, entered the Wailing Caverns' underground springs. He hoped the Emerald Dream would bring life back to the dry Barrens. But when he fell asleep, his dream became a nightmare. The acolytes who came with him abandoned nature's harmony and fell under its corruption. They became the Druids of the Fang. Four leaders of the Druids of the Fang carry dream gems that channel warped dream energy. They hope to reshape the Barrens into their own viperous Eden. Lord Cobrahn, Lady Anacondra, Lord Pythas, and Lord Serpentis each carry one gem. While the gems remain with them, corruption spreads through Kalimdor's soil and waters.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_914-c3287f381b47b84b27e5/1-0000.mp3", duration = 57.8089796, start = 0},
  },
}
P.transport["quest:91859"] = {
  hash = "7595ff",
  fullHash = "7595ff",
  text = "A Curious Pair. In the Sepulcher, Trevan Rol watches a rare pair travel through Silverpine Forest. The tauren and high elf carry the Earthen Ring's banner, and their presence draws the Forsaken's suspicion. Trevan Rol sees two travelers claiming to represent the Earthen Ring on the road by the Sepulcher. The outpost is a grim waystation where strangers receive close scrutiny, especially when they come on diplomatic business. A tauren beneath the shamanic order's banner draws little surprise. His cloaked companion is another matter. The scout recognizes an unmistakable high elf, a sight the Forsaken find exceedingly strange. A high elf openly traveling beside a member of the Horde's shamanic circles raises questions among the Forsaken sentries. The Earthen Ring attends to the balance of the elements, and high elves are rarely seen in Lordaeron, much less beside tauren envoys. To learn where the pair went and what brought them to the forest, you are directed to Deathguard Baldren at the edge of town.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_91859-a22f2d3c9e5e415d9e4d/1-0000.mp3", duration = 59.3240816, start = 0},
  },
}
P.transport["quest:92401"] = {
  hash = "c84a64",
  fullHash = "c84a64",
  text = "A Frightened Request. Edward Heartweaver’s wife waits in fear after he vanishes in the Ruins of Lordaeron. Since their son was lost when the capital fell, Edward has gone each week to search the graveyard for his remains. Now his usual journey has lasted several days. When the Scourge destroyed Lordaeron during the Third War, the Heartweavers lost their young son. His body was never found in the ruin. So Edward Heartweaver went each week to the capital’s graveyard, still hoping to find some trace of his child.\n\nGrief and guilt kept Edward from letting go. The graveyard lay within the ruined capital, where the search was perilous. The surface ruins of Lordaeron are overrun by hostile creatures and lurking horrors. They are no place for ordinary citizens. Edward’s frightened wife warned him and begged him to stop going, but he kept to his weekly search.\n\nThen Edward failed to return for several days. His wife turned to capable adventurers and asked them to brave the ruins and learn what had become of him.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92401-e7311d3bfb368c971483/1-0000.mp3", duration = 58.4097959, start = 0},
  },
}
P.transport["quest:92415"] = {
  hash = "c73861",
  fullHash = "c73861",
  text = "Remember That I Love You. In the Ruins of Lordaeron, a stained letter calls for a missing child. Torn from parchment among the graves, it speaks of a child from the Heartweaver family. You carry it south to the orphanage in Stormwind City, hoping to learn what became of them. The ruined graveyard bears the marks of the Third War. Among grounds haunted by the undead, someone found a torn, blood-stained letter. It speaks of a missing child from the Heartweaver family. Prince Arthas and the Scourge swept through the kingdom and shattered their lives. Lordaeron fell, and the Undercity now fills the catacombs below. Refugees who escaped south scattered across the Alliance kingdoms. In Stormwind City, Orphan Matron Nightingale cares for children left without parents by the wars. You bring her the blood-stained letter, hoping she can identify a surviving Heartweaver child and give the family some closure.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92415-c63e341a3f6737d052c3/1-0000.mp3", duration = 51.5395918, start = 0},
  },
}
P.transport["quest:92421"] = {
  hash = "30daa9",
  fullHash = "30daa9",
  text = "Light's Justice. In the Undercity, Morbin Lightbane sends warriors above to gather what the Forsaken need. Intact limbs from the Scourge in the Ruins of Lordaeron help repair wounded Forsaken and sustain their ranks. Above the Undercity, Scourge remnants still prowl the ruined streets of Lordaeron's former capital. Though the Dark Lady has defeated the dreadlords and founded the Forsaken kingdom, clearing the surface remains costly work. The undead threaten the gateway below and drain the forces sent to reclaim the fallen kingdom. Forsaken bodies do not mend on their own. Rotting tissue and shattered sinew cannot knit again, so Morbin Lightbane sends warriors to gather intact limbs from destroyed Scourge in the ruins above. Those parts can repair wounded Forsaken and help them endure and fight again. Morbin Lightbane honors his late commander, Captain Garek Bandarion, by carrying on this work. Bandarion pledged to heal their people and free Lordaeron from Scourge occupation. To Morbin, destroying their mindless enemies and restoring their kin is justice in the service of the Banshee Queen.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92421-ba0de77a92d3a346bd44/1-0000.mp3", duration = 61.8318367, start = 0},
  },
}
P.transport["quest:92422"] = {
  hash = "7ebafb",
  fullHash = "7ebafb",
  text = "The Wrath of Rath'mael. In the Ruins of Lordaeron, a fog hides Scourge movements above the Undercity. Rath'mael, a Scourge necromancer, has shrouded the ruined streets and graveyard. Deathguard Kristof in Brill calls for you to strike him down. Scout reports from Lordamere Overlook tell of a sinister presence in the Ruins of Lordaeron. An unholy fog now covers the ruined streets and nearby graveyard, hiding lingering Scourge forces. Rath'mael cast the shroud. His spells conceal the undead above the heart of Forsaken territory. Deathguard Kristof in Brill sends you to rally your allies and strike Rath'mael down. The Forsaken cannot let this menace take root unchecked. The Scourge may replace him, but his fall will disrupt their coordination, disperse the fog, and give Tirisfal Glades room to breathe.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92422-9c58330a076ba48198c1/1-0000.mp3", duration = 46.08, start = 0},
  },
}
P.transport["quest:92706"] = {
  hash = "c481db",
  fullHash = "c481db",
  text = "WANTED: Bruuz. Bruuz threatens the ships that keep Ratchet busy. Gazlowe has posted a bounty for the huge shark prowling the docks and disrupting coastal trade. Ratchet is Kalimdor's main neutral gateway to the Eastern Kingdoms. Its trade depends on merchant ships. Lately, a huge shark named Bruuz has prowled the bay. Dockworkers gave it that name after it began attacking small skiffs, sailors, and cargo unloaded near the docks. The shark disrupts the port and puts the ships that supply Ratchet at risk. Gazlowe has posted a public bounty so ships will not avoid his port for fear of the shark. The notice calls on anglers and promises a hefty reward. To claim it, you need to slay Bruuz and bring back the shark's dorsal fin as proof.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92706-912a1cf349f81b97f21f/1-0000.mp3", duration = 44.5126531, start = 0},
  },
}
P.transport["quest:93"] = {
  hash = "59a883",
  fullHash = "59a883",
  text = "Dusky Crab Cakes. In Darkshire, Dusky Crab Cakes are a favorite snack with no crab in them. Chef Grual sends you to gather spider legs for Jitters, who is hungry and nervous. Chef Grual cooks at the Scarlet Raven Tavern in Darkshire. Isolation, dark magic, and severed supply routes have left Duskwood short of food, so locals have changed what they eat. Grual says the cakes get their tangy flavor from the gooey legs of local giant spiders, not seafood from distant shores. Chef Grual sends you north to the foothills and riverbanks, where Venom Web Spiders spin their snares. Undead and feral beasts make the gloomy forest dangerous, but fresh spider meat is one of the few ready sources of protein in the blighted woods. Grual fries the seasoned limbs on a hot skillet until crisp.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_93-99be5043d63a4ea6a2db/1-0000.mp3", duration = 46.7069388, start = 0},
  },
}
P.transport["quest:94"] = {
  hash = "17e7ca",
  fullHash = "17e7ca",
  text = "A Watchful Eye. At the Tower of Azora, Theocritus watches Morganth from afar. He sends travelers east into Redridge Mountains to place an enchanted glyph at an old lion statue near the Tower of Ilgalar. From his tower in eastern Elwynn Forest, Theocritus watches the hills. His rival, Morganth, is a powerful sorcerer who has claimed the Tower of Ilgalar in Redridge Mountains. Fearing Morganth's dark magic may cross the border, Theocritus made the Eye of Azora to watch the rogue wizard from afar. A distant view cannot show Theocritus what Morganth plans. So he gives travelers the Glyph of Azora and sends them to the Old Lion Statue near the Tower of Ilgalar. The statue has kept watch there for decades.\n\nSet the glyph into the worn hollow at its base. An arcane link then reaches back to Azora, letting Theocritus look into his rival's mind.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_94-fdcccc7748a4919ed786/1-0000.mp3", duration = 73.6130612, start = 0},
  },
}
P.transport["quest:942"] = {
  hash = "6e994a",
  fullHash = "6e994a",
  text = "The Absent Minded Prospector. In Darkshore, a strange fossil draws you across the Great Sea to the Wetlands. Chief Archaeologist Greywhisker sends you to Archaeologist Flagongut in Menethil Harbor, hoping he can unlock its secrets. Chief Archaeologist Greywhisker sees a likeness between the strange fossil from Darkshore and a relic shown at an Explorers' League conference in Ironforge. Archaeologist Flagongut presented that relic and believed such fossils held powers waiting to be unlocked. Greywhisker thinks Flagongut is the only dwarf who can discern what makes this Kalimdor find so extraordinary. You carry the mysterious fossil from Kalimdor to the Eastern Kingdoms. Flagongut was last seen lodging at the Deepwater Tavern in Menethil Harbor, waiting for an armed escort to the Whelgar Excavation Site. When you bring him the fossil, the Darkshore survey reaches across continents as part of a wider archaeological inquiry.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_942-a80968e1b5fa72a5a72e/1-0000.mp3", duration = 53.002449, start = 0},
  },
}
P.transport["quest:943"] = {
  hash = "adba58",
  fullHash = "adba58",
  text = "The Absent Minded Prospector. In Darkshore, Remtravel's dig sends his search across the Great Sea. In Menethil Harbor, Archaeologist Flagongut hopes to join Remtravel's finds with his own fossil and the lost Stone of Relu, revealing the relics' hidden powers. You once helped the distracted Prospector Remtravel during an escort through northern Darkshore. Now the search crosses the Great Sea to the Wetlands marshes. Prospector Whelgar keeps Flagongut's original fossil at his excavation site. After reviewing the finds, Archaeologist Flagongut believes the Stone of Relu can unlock the mysterious powers within the fossils.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_943-87915a9d4085e6cd127c/1-0000.mp3", duration = 37.6163265, start = 0},
  },
}
P.transport["quest:94494"] = {
  hash = "79783b",
  fullHash = "79783b",
  text = "Call of Water. In Loch Modan, Norric Lochthane calls a shaman toward water's purity. Having found harmony with wind, earth, and flame, the initiate is ready to commune with water. A shaman who has found balance with earth, wind, and flame now turns to water. Its lesson reaches beyond a force to wield. Water offers a spiritual image of purity and resilience. Norric Lochthane urges the initiate onward without delay. Communion with the elements demands effort and endurance, and the way climbs through rugged country. The mountain waits for no one. Understanding begins with the ascent.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_94494-bc2b2dc496f9ed0ad44a/1-0000.mp3", duration = 35.9183673, start = 0},
  },
}
P.transport["quest:94495"] = {
  hash = "93cec2",
  fullHash = "93cec2",
  text = "Call of Water. In the Wetlands, seekers learn what pure water can do and search for the water sapta. Beneath the southern falls, Hervdana Saegrund welcomes those who brave the wilderness. Pure water gives life anew, carves stone, and washes away impurities. Tainted water brings the threat of ruin. Those who seek communion with water are sent into the wild to obtain a water sapta from those who dwell beside the element. Hervdana Saegrund and her family make their home in a secluded cave directly beneath the southern waterfalls of the Wetlands. Ironforge guards are far away, and Dark Iron dwarves lurk in the surrounding swamps. Still, Hervdana and her kin keep their isolated home by the falls.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_94495-86ebfe3ba9dd12053b56/1-0000.mp3", duration = 44.0163265, start = 0},
  },
}
P.transport["quest:94497"] = {
  hash = "a7bbdc",
  fullHash = "a7bbdc",
  text = "Call of Water. In the Wetlands, an initiate gathers water to earn the sapta through Call of Water. The marsh is dangerous, but its waters show how water's energies shape and sustain the land. Hervdana guides initiates through the search for water in its many forms. They learn how it moves, changes lives, and sustains the land. Their path toward the sapta and communion with the spirits begins at an estuary, where ocean tides meet fresh runoff from the highlands. Below Hervdana's cave, waterfalls carry highland springwater into the marsh. There it meets saltwater pushed inland by the coastal tides. The ocean brings sediment, minerals, and energies unlike those in clear mountain snowmelt. An initiate can find wisdom in the land's natural ways where these waters meet. Dangerous marsh creatures make gathering water risky. Dark Iron dwarves have also pushed far north into the Wetlands. Hervdana regrets the hostility between the dwarven clans. She sees how much dwarfkind might achieve if they set aside their feuds.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_94497-eb9e6adbfe3da772608d/1-0000.mp3", duration = 63.0073469, start = 0},
  },
}
P.transport["quest:94499"] = {
  hash = "a0b1f5",
  fullHash = "a0b1f5",
  text = "Call of Water. Hervdana Saegrund sends you from the Wetlands to test the waters at Stonewatch Falls in Redridge. What you bring back will serve in your spiritual trials. Hervdana Saegrund sends you south from the Wetlands to examine the waters at Stonewatch Falls in Redridge. Lake Everstill supplies clean water to Lakeshire, but murlocs lurk beneath the cascade. They have grown unusually large and twisted. Hervdana suspects venom, foul sorcery, or seepage from the old fortress above. She asks you to gather a sample in an Empty Red Waterskin.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_94499-1d921b770a34818cb17a/1-0000.mp3", duration = 32.6008163, start = 0},
  },
}
P.transport["quest:94500"] = {
  hash = "4cbbe6",
  fullHash = "4cbbe6",
  text = "Call of Water. In Ashenvale, you gather pure water from the lake beside Astranaar. It is the last sample you need before returning to Norric. You are sent to fill a waterskin with Ashenvale's uncorrupted water. Astranaar is a haven beside the lake, whose ancient waters lap against sunken ruins. This is the last liquid sample the giver needs before sending you on to Norric. To reach Ashenvale from the Eastern Kingdoms, cross the sea by ship from Menethil Harbor toward Auberdine. The ship puts in at Southshore along the way. From Auberdine's docks, follow the road inland beneath Ashenvale's green boughs. Stay alert among the watchful shadows of the trees.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_94500-a4c20ee0e3b313e96fea/1-0000.mp3", duration = 39.6538776, start = 0},
  },
}
P.transport["quest:94501"] = {
  hash = "69e48e",
  fullHash = "69e48e",
  text = "Call of Water. At Loch Modan, seekers prepare to commune with water spirits. Hervdana blesses pure water for Norric Lochthane as aspiring shamans draw nearer to the water totem rites. You seek harmony with water through patience and reverence. Hervdana blesses the water you gather, and you carry it to Norric Lochthane in Loch Modan.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_94501-937a6e67c234759b0b97/1-0000.mp3", duration = 20.244898, start = 0},
  },
}
P.transport["quest:94502"] = {
  hash = "609491",
  fullHash = "609491",
  text = "Call of Water. You travel from Loch Modan to Westfall, where a corrupted spring has silenced the water spirits. At Stendel's Pond, you can cleanse the corruption and awaken an old shrine to seek their favor and the Water Totem. Near Moonbrook, Stendel's Pond lies under a dark taint spreading across Westfall. Its waters were once clear, but now the local water spirits are silent. An old shrine stands neglected along the shore, covered in dust and cobwebs. You can seek to awaken the powers sleeping within it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_94502-927286639b7ee9c10583/1-0000.mp3", duration = 30.7722449, start = 0},
  },
}
P.transport["quest:94503"] = {
  hash = "f93057",
  fullHash = "f93057",
  text = "Call of Water. In Westfall, you drive restless spirits from the waters before a Minor Manifestation of Water can speak with you. Corrupt spirits disturb Westfall's waters and their natural balance. You speak sacred words, and radiant light scatters the restless essences into ash and quiet mist. Once the corrupt spirits are driven back, a Minor Manifestation of Water can emerge. It warns that the land's vital energies still wane, and that preserving life demands constant care.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_94503-8066eb601e8b147c0f22/1-0000.mp3", duration = 29.8318367, start = 0},
  },
}
P.transport["quest:94505"] = {
  hash = "cd44e3",
  fullHash = "cd44e3",
  text = "Call of Water. In Westfall, you learn what water can give and what corruption can take. Bring a Shard of Water to Norric Lochthane in Loch Modan, and he grants you a water totem. You travel to Westfall and return to Norric Lochthane in Loch Modan with a Shard of Water. The journey tests your dedication to water and your understanding of its power to give life and purge corruption. Those who prove themselves receive a water totem and take an essential step on their elemental path. Water gives life, and corruption brings it to an end. Norric Lochthane teaches you to use water's restorative strength to protect the vulnerable and preserve living things. Its gifts reach beyond mending the body. They bring endurance, renewal, and spiritual balance.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_94505-e0d762efc4d0ba2d5320/1-0000.mp3", duration = 44.0946939, start = 0},
  },
}
P.transport["quest:94616"] = {
  hash = "6206dd",
  fullHash = "6206dd",
  text = "Water Sapta. In Westfall, you take the Water Sapta to seek a troubled pond. The ceremonial draught sharpens your sight to water spirits and hidden corruption, so you can investigate the imbalance. Shamans prepare a sapta to let them see beyond the physical world. The Water Sapta attunes your senses to water, revealing disturbances and spirits hidden from ordinary travelers. Without that changed sight, an elemental presence might seem like no more than ripples. The Water Sapta leads you to Westfall, an arid Alliance realm troubled by unrest and neglect. A pond there holds spiritually polluted water. With the sapta's sight, you seek the corrupted water, uncover the disturbance, and restore harmony to the local water spirits.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_94616-a6753557824b8ff60c0b/1-0000.mp3", duration = 43.7812245, start = 0},
  },
}
P.transport["quest:95"] = {
  hash = "345cbf",
  fullHash = "345cbf",
  text = "Sven's Revenge. In Sven's Revenge, grief drives Sven Yorgen from his ruined farm in southern Duskwood to hunt its killers. Now camped in the western hills, he asks travelers to return to the farmstead, where a stranger buried something near the barn. Hooded Dark Riders came from Deadwind Pass and attacked Sven Yorgen's farm in southeastern Duskwood. Sven was away, and they killed his family. When he returned to the slaughter, he saw an unknown figure skulking near the barn and hurriedly burying something. Sven left the object hidden and set out to hunt the killers. Sven Yorgen is camped in the western hills, consumed by wrath and seeking help at his farmstead. Between the farmhouse and ruined barn, a mound of loose dirt behind an old tree stump marks where something was hastily buried. Recovering it may explain why the shadowy riders targeted a quiet Duskwood farmer.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_95-a87ed8db97eae25a9fa3/1-0000.mp3", duration = 51.3044898, start = 0},
  },
}
P.transport["quest:95036"] = {
  hash = "f71951",
  fullHash = "f71951",
  text = "A Moon-Kissed Blade. Trevan warns you that worgen threaten Silverpine Forest. Old Fire-Eye resists death through unknown magic, and Trevan asks you to learn what a special blade will require. Old Fire-Eye is the worgen who attacked Trevan and his companions. Trevan will give you a list of materials for a weapon against him. The materials are gathered, and Trevan believes he knows a smith who can craft the blade.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_95036-9f97d7a99dd6923788b0/1-0000.mp3", duration = 23.7714286, start = 0},
  },
}
P.transport["quest:951"] = {
  hash = "d285e0",
  fullHash = "d285e0",
  text = "Mathystra Relics. Along Darkshore's northeastern coast, Mathystra Relics may reveal how the Twilight's Hammer bends ancient elven magic. Onu, an Ancient of Lore in the Grove of the Ancients, seeks them to learn what the cult intends. Onu sends you to the Ruins of Mathystra on Darkshore's northeastern shore. Before the Sundering, Mathystra was a shining bastion of highborne civilization. The city fell to rubble, weeds and naga, yet its old enchantments endure in shattered urns and relics scattered among the stone foundations.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_951-2b4d81a965804c50ed63/1-0000.mp3", duration = 32.2873469, start = 0},
  },
}
P.transport["quest:95161"] = {
  hash = "ac2a2d",
  fullHash = "ac2a2d",
  text = "Remember That I Love You. In Stormwind, a blood-stained letter is bound for Jeremy Heartweaver, now living with his adoptive mother, Avette Fellwood, in Duskwood. War, hardship, and the kingdom's turmoil have left many children at the Stormwind Orphanage without families. Jeremy Heartweaver was among them until Avette Fellwood adopted him and brought him to live in Duskwood. There, gloomy woods bring peril and hard labor. The caretakers believed a family could offer him more than life in the city orphanage.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_95161-4832b2b22fea451904da/1-0000.mp3", duration = 29.5706122, start = 0},
  },
}
P.transport["quest:95189"] = {
  hash = "0d723e",
  fullHash = "0d723e",
  text = "Crest of Lordaeron. In the ruins of Capital City, a weathered Crest of Lordaeron survives from the fallen northern kingdom. Relics like it are scarce, and Lady Dena Kennedy in Stormwind City is eager to claim one. The Scourge left Lordaeron's palaces and archives in ruins beneath the shadow of the Undercity. Its proud insignias were destroyed or left to decay, so few relics bearing the royal crest remain. A weathered crest from the northern ruins keeps a piece of human history. After the Third War, thousands of refugees fled south from Lordaeron toward the Kingdom of Stormwind. They carried memories of home. In Stormwind City, Lady Dena Kennedy seeks remnants of their homeland. For those who left the north behind, a crest like this is a cherished link to Lordaeron.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_95189-f5cb9e585753d7d6097e/1-0000.mp3", duration = 46.08, start = 0},
  },
}
P.transport["quest:95195"] = {
  hash = "5f530f",
  fullHash = "5f530f",
  text = "Bloodied Insignia. In Lordaeron's blighted ruins, Bloodied Insignias bear the old Alliance crests of fallen defenders. Many soldiers' families fled south to Stormwind during the Third War. Prince Arthas returned with the Scourge and laid waste to Lordaeron. Its great army was overwhelmed, and countless soldiers died defending the capital and the lands around it. Rusted armor and bloodstained brass are all that remain of many who fought.\n\nThe old Alliance insignias belonged to those who stood against the undead. Trampled into soil and rubble, the medals recall Lordaeron's last defense. Many survivors fled south across the sea and settled in Stormwind City. Alliance and kinship bind the two human realms, and families in the south still seek news of loved ones lost in the north.\n\nGeneral Marcus Jonathan commands Stormwind's city guard and takes custody of the bloodied insignias. He preserves the defenders' memory and helps their surviving families learn their fate.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_95195-7c766bb1560a0d998f90/1-0000.mp3", duration = 54.0995918, start = 0},
  },
}
P.transport["quest:95204"] = {
  hash = "0e1c13",
  fullHash = "0e1c13",
  text = "Crest of Lordaeron. The Forsaken preserve what little remains of Lordaeron in Undercity. A weathered crest bears the fallen kingdom’s emblem, a rare link to its past. The Third War shattered Lordaeron. Ash, ruins, and Scourge desolation swallowed much of the kingdom, leaving few emblems behind. To the Forsaken beneath the ruins of the Capital City, those that survive are precious links to the civilization they once belonged to. The weathered crest is brought from the wider world to Oran Snakewrithe in Undercity. Oran tests the metal with a bite, then confirms it is genuine and mostly intact. For Oran and the Forsaken archivists, each recovered piece helps restore a history the Scourge sought to erase.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_95204-8614b73cca26661391d9/1-0000.mp3", duration = 42.3444898, start = 0},
  },
}
P.transport["quest:95216"] = {
  hash = "56d855",
  fullHash = "56d855",
  text = "The New Plague. In the Undercity, Theodore Griffs studies reports of a lethal creature in the ruins above. Its venom consumes even undead flesh, and he seeks to learn how its toxins work. The Royal Apothecary Society gathers dangerous substances from across Azeroth. Theodore Griffs is one of its researchers. He tracks strange beasts and deadly contaminants to advance Forsaken alchemy. Now rumors tell of a venomous creature in the shattered stone above, so Griffs sends you to bring back a sample before the chance is lost. Witherfang is the venomous arthropod stalking the surface ruins of Lordaeron. Its venom breaks down living tissue and dead, preserved flesh alike. Griffs wants to learn how it overcomes the resistance of dead flesh, knowledge that could help refine biological weapons and protect the Forsaken kingdom.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_95216-f9c8e65d8f4cbb244f97/1-0000.mp3", duration = 48.875102, start = 0},
  },
}
P.transport["quest:95250"] = {
  hash = "0e3705",
  fullHash = "0e3705",
  text = "Abominable Creatures. At Lordaeron's fallen capital, Captain Truman waits anxiously for reinforcements and news of his missing commander. He believes the revered Grand Marshal still fights in the nearby ruins, and asks a capable traveler to find him. The search reveals the defenders' grim fate and deep hostility among the loyalists. Captain Truman keeps watch outside Lordaeron, anxious for long-overdue reinforcements. He calls his superior a renowned Grand Marshal, tall and statuesque, and believes him a formidable fighter. Ordered to hold the line while his commander charged into battle, Truman remains bound by duty.\n\nHe distrusts outsiders and scorns those he calls lesser breeds, refusing to rely on local irregulars. When a capable traveler arrives, he asks you to enter the ruins, check on his master's well-being, and learn how the battle fares. The search takes you into the Ruins of Lordaeron, the shattered capital that fell to the Scourge during the Third War. Captain Truman expects his glorious leader to stand triumphant over the fallen, but the blighted city tells a grimmer story.\n\nHorrors, undead remnants, and abominations roam its broken stone plazas. The ruined streets show what became of the defenders who entered the city. No immaculate knight holds the line; the commander has met a tragic, twisted end among the monstrosities in the courtyards.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_95250-2778844033fd7075e336/1-0000.mp3", duration = 78.3673469, start = 0},
  },
}
P.transport["quest:95697"] = {
  hash = "3230a9",
  fullHash = "3230a9",
  text = "Changing Tastes. At Borstan's Firepit, a new dish may bring travelers to Orgrimmar. Zamja's advice and tales of giant raptor talons lead Borstan to seek thicket raptor meat from the Wetlands across the sea. Borstan's Firepit in Orgrimmar hopes to widen its menu. Zamja suggests homestyle raptor cooking for travelers who miss the familiar meals of their birth villages. Borstan likes the thought of drawing new patrons with raptor, but simple village fare seems too modest for the Horde's great capital. He wants a bolder version of the old staple. A hunter returns to Orgrimmar with a massive talon from a thicket raptor of the Wetlands excavation sites. The beast's size and quality catch Borstan's interest. He arranges for adventurers to cross the sea to the Eastern Kingdoms, brave the excavation grounds, and bring back prime thicket raptor meat for his fires.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_95697-71f5ac61576626911d66/1-0000.mp3", duration = 51.8791837, start = 0},
  },
}
P.transport["quest:95795"] = {
  hash = "e42cf2",
  fullHash = "e42cf2",
  text = "Fallen in the Fen. At the excavation, a fallen dwarf leaves grim news for his brother in Lakeshire. Dorin Songblade learns what became of his kin and faces the gifts he could not finish in time. At the excavation sites, an adventurous dwarf lies dead. You cover his remains with his own cloak, then carry the grim news to Lakeshire and seek out his kin.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_95795-a9c9abc51947371f4021/1-0000.mp3", duration = 21.76, start = 0},
  },
}
P.transport["quest:95809"] = {
  hash = "f91cc0",
  fullHash = "f91cc0",
  text = "Heartwoven. In the Wetlands, Ardin Grassman has survived the marsh’s dangers and sends word to Menethil Harbor. A traveler carries a reed heart to Caitlin Grassman. Ardin Grassman went to see the strange grasses at the Wetlands excavation sites, but became stranded among the marsh’s dangers. You clear a path through the wilderness, giving him room to rest and gather his harvest. Tired but determined, Ardin prepares to return toward the safety of the port. Before setting out for home, Ardin takes marsh reeds from his pack and braids them into a heart. He gives you the token to carry to Caitlin Grassman in Menethil Harbor. She has been waiting in worry. Word that Ardin survived and will soon return brings relief, along with the reed heart and the promise of a warm meal.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_95809-801c52d21faa8480f424/1-0000.mp3", duration = 45.4269388, start = 0},
  },
}
P.transport["quest:95810"] = {
  hash = "2e4e62",
  fullHash = "2e4e62",
  text = "Lost Relic Carry. You carry a broken rock-mech relic through the Wetlands toward Prospector Whelgar. Its strange material draws the eye of dwarven researchers. A rock-mech has left behind a fractured piece of its ancient craft. Its unfamiliar composite marks it as part of a sophisticated mechanism tied to the Titans. Prospector Whelgar studies ancient remains at the Wetlands excavation site. Bring the relic safely to him, and dwarven scholars will have physical evidence for their study of their ancient heritage.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_95810-f82f1c16888e4f1f32b9/1-0000.mp3", duration = 29.6228571, start = 0},
  },
}
P.transport["quest:95883"] = {
  hash = "21eb9a",
  fullHash = "21eb9a",
  text = "The Tortured Soul. At Beren's Peril in Silverpine Forest, a dark rite waits unfinished. An abandoned note names the last offerings still needed: blood and a soul marked by suffering. At Beren's Peril in Silverpine Forest, an altar bears the remains of a hastily assembled dark rite. A scrawled note lies among the scattered materials. Most of the ingredients are already gathered, but the rite still calls for blood and a Tortured Soul.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_95883-cfe91e043b04ac9b4354/1-0000.mp3", duration = 26.88, start = 0},
  },
}
P.transport["quest:95884"] = {
  hash = "af6690",
  fullHash = "af6690",
  text = "The Offering Stone. In Beren's Peril, a ritual offering is being prepared at the Offering Stone. Fragments of a weathered note point travelers to the altar in Silverpine Forest. A weathered scrap found in Silverpine Forest holds fragments about a ritual and an offering stone nearby. Time and moisture have worn away most of its words. Follow the clues into Beren's Peril, and you can find the crude altar in the wilderness. At Beren's Peril, strange implements and bizarre items lie scattered across the rough stone. Someone has been using the site to prepare an offering or dark rite, far from prying eyes.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_95884-eca62fd531247a1b31e1/1-0000.mp3", duration = 34.8212245, start = 0},
  },
}
P.transport["quest:95885"] = {
  hash = "5d6d13",
  fullHash = "5d6d13",
  text = "The Offering of Blood. At Beren's Peril, the scrap of note calls for blood at the Offering Stone. You bring a Tortured Soul to answer it. Deep in Beren's Peril, the Offering Stone waits for a final offering. Scraps of note call for a willing sacrifice, and lead you to bring blood to the altar. As you approach with the restless essence, dread closes in.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_95885-ad7a4b3f5d16fba38f65/1-0000.mp3", duration = 21.1591837, start = 0},
  },
}
P.transport["quest:95981"] = {
  hash = "2b795f",
  fullHash = "2b795f",
  text = "Watching the Roads. Shadow Priest Allister sends the Forsaken against Kirin Tor patrols near Ambermill. With Dalaran's barrier down, their wizards and watchers guard the roads into Silverpine Forest while carrying magical goods into Forsaken lands. Near Ambermill, Kirin Tor wizards and sentries watch the roads into Silverpine Forest. Since the barrier around Dalaran fell, they have tightened their hold on travel across the border. From the Sepulcher, the Forsaken see the human magi using these roads to carry dangerous relics and enchanted pendants into contested lands. Shadow Priest Allister wants to stop the flow of Dalaran's magical goods at its source. He sends agents after the Kirin Tor escorts on the roads near Ambermill. By striking Dalaran Wizards and Dalaran Watchers, the Forsaken aim to break the Kirin Tor's hold on regional travel and guard their eastern frontier from outside arcane meddling.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_95981-9e9155a1d45e7c47be6c/1-0000.mp3", duration = 54.0734694, start = 0},
  },
}
P.transport["quest:95999"] = {
  hash = "d562db",
  fullHash = "d562db",
  text = "WANTED: Incinerator Gar'im. In Lakeshire, Magistrate Solomon offers a bounty for Incinerator Gar'im, whose forces threaten the town. The hostile orc commander holds Render's Valley with shadowcasters and is said to work with the Blackrock clan at Stonewatch Keep. Blackrock orcs press out from their mountain strongholds, making the Redridge Mountains more dangerous. In Render's Valley, Gar'im leads an incursion with loyal shadowcasters and dark sorcery. Lakeshire's guard is stretched thin, and the crown's armies are largely absent. So Magistrate Solomon calls on independent fighters to eliminate Gar'im, who is said to work with the Blackrock at Stonewatch Keep. Gar'im is known for destructive magic and command over shadow-weaving casters. To claim the township's reward, hunters enter enemy-held territory and defeat him. They must return his shattered staff to Lakeshire's town hall as proof that the threat has ended.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_95999-34055297bee255cab71c/1-0000.mp3", duration = 54.8571429, start = 0},
  },
}
P.transport["quest:96"] = {
  hash = "0e12e8",
  fullHash = "0e12e8",
  text = "Call of Water. You bring the Shard of Water to Islen Waterseer on the Barrens coast. This return shows your harmony with restorative energies and earns you a Water Totem. You carry a gift from the Minor Manifestation of Water back across the sea. To earn it, you crossed continents to the tainted shores of Silverpine Forest and faced the corruption there. Water gives life, adapts, and heals, yet its pliant nature leaves it open to blight and dark magic.\n\nBefore the Minor Manifestation, you witnessed pure elemental will and received the Shard of Water. Now you return to the sun-scorched Barrens, where the shard reminds you that water joins distant corners of the world. When you give Islen Waterseer the shard, she weighs more than proof of your journey. She tests whether you have learned the balance between preservation and renewal. Lordaeron's spreading rot can hide small victories, yet cleansing even one wellspring matters to the spirits. Islen accepts your offering and gives you a Water Totem. Through it, you can channel cleansing, healing, and mana-restoring streams into the mortal realm, binding you to the tide.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_96-59c949bbbdbd1234aef3/1-0000.mp3", duration = 64.2612245, start = 0},
  },
}
P.transport["quest:97"] = {
  hash = "029346",
  fullHash = "029346",
  text = "The Legend of Stalvan. In Darkshire, Clerk Daltry matches the recovered handwriting to Stalvan Mistmantle. His report makes the Night Watch's suspicion certain. Back in Darkshire's town hall, Clerk Daltry compares the bloodstained journal page with signatures in the Town Registry. The handwriting matches Stalvan Mistmantle exactly. After the trail led through manors, inns, and civic records across the human kingdoms, the Night Watch now has proof that the danger is close at hand.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_97-53613806ef921d94ad04/1-0000.mp3", duration = 28.6040816, start = 0},
  },
}
P.transport["quest:970"] = {
  hash = "29d15b",
  fullHash = "29d15b",
  text = "The Tower of Althalaxx. At Maestra's Post, Delgren the Purifier sends you south to stop the Cult of the Dark Strand. Its threat reaches from the Tower of Althalaxx into Ashenvale, and you are to recover a Glowing Soul Gem from the ruins of Ordil'Aran. Reports from the Tower of Althalaxx in northern Darkshore have led you south to Delgren the Purifier at Maestra's Post. He has fought the Cult of the Dark Strand for a long time, but the cult now presses into Ashenvale's ancient elven woods. Its reach crosses both territories, so Delgren seeks to strike at the source of its sorcery. Northeast of Maestra's Post, the ruins of Ordil'Aran are overrun by Dark Strand cultists. Delgren says their operatives carry glowing soul gems, vessels enchanted with magic that sustains the cult's power. Hunt among the ruins and recover a gem. Delgren can break its enchantment and uncover the source of the cult's rite.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_970-8387473e80b357ee04ab/1-0000.mp3", duration = 53.9689796, start = 0},
  },
}
P.transport["quest:97003"] = {
  hash = "c0c619",
  fullHash = "c0c619",
  text = "Chol'aruk the Ravener. In the Barrens, Gur'ak sends travelers after a colossal quilboar called Chol'aruk the Ravener. He believes the tales and asks them to return with its head. Razormane quilboar whisper of Chol'aruk, an enormous terror they call The Ravener. They say it lairs deep in a cavern at Thorn Hill, northeast of the local trails. By their account, it is roughly five times the size of an ordinary quilboar and driven by an unquenchable thirst for blood. Many dismiss the tales as campfire exaggeration. Gur'ak knows better from past battles with similar beasts. Gur'ak knows a beast of such size poses a real danger. He directs capable travelers to track Chol'aruk to its lair in Thorn Hill, end its threat, and bring back its head as proof. The Ravener is said to be ferocious and colossal. Gur'ak warns that only well-prepared groups should enter the cave to face it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_97003-b9bd38a8054855a3528f/1-0000.mp3", duration = 53.9167347, start = 0},
  },
}
P.transport["quest:97005"] = {
  hash = "eb6ade",
  fullHash = "eb6ade",
  text = "Chol'aruk the Ravener. On Thorn Hill in the Barrens, Chol'aruk the Ravener haunts a cave. Bainham seeks its severed head to avenge comrades slain by beasts like it. Northwest of Bainham's camp, Thorn Hill rises above the Barrens Savannah. The Razormane tribes have long fought over its plateau. Now a monstrous abomination is said to lurk in one of its caves. The Razormane call it Chol'aruk or the Ravener. Some travelers doubt the tale that it can swallow an armored orc whole. Those who have seen the carnage know the danger is real. Bainham knows Chol'aruk is no campfire tale. He has fought similar horrors and carries scars from those encounters. His comrades fell to such beasts, and he still mourns them. He fears the abomination threatens everyone crossing the Savannah. Bainham asks seasoned champions to climb Thorn Hill, enter its underground lair, slay Chol'aruk, and bring back its massive head.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_97005-eea06e5f7ab07bcbccfb/1-0000.mp3", duration = 55.7714286, start = 0},
  },
}
P.transport["quest:971"] = {
  hash = "8f715e",
  fullHash = "8f715e",
  text = "Knowledge in the Deeps. In Ironforge, Gerrig Bonegrip sends you across the sea to seek an ancient manuscript. He wants the Lorgalis Manuscript from the sunken ruins of Blackfathom Deeps in Ashenvale. In Ironforge's Forlorn Cavern, Gerrig Bonegrip gathers ancient texts. His interests reach beyond ordinary histories and civic records. He seeks forgotten lore that can open doorways and awaken 'Those Who Sleep.'\n\nBonegrip speaks of surviving beyond 'the end days.' Such words make him seem either an eccentric scholar or a devotee of powers that slumber in shadow. Bonegrip sends you to Ashenvale's shadowed shores, where the night elven sanctuary of Blackfathom Deeps lies drowned. Before the Great Sundering tore Kalimdor apart, night elven scholars gathered great magical knowledge in coastal temples.\n\nNow naga, satyrs, and Twilight's Hammer cultists crawl through the flooded halls. Among them lies the Lorgalis Manuscript, forbidden lore kept in a Pitted Iron Chest.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_971-f95b5ac73919b32c3e95/1-0000.mp3", duration = 60.7869388, start = 0},
  },
}
P.transport["quest:972"] = {
  hash = "dca536",
  fullHash = "dca536",
  text = "Water Sapta. At Islen Waterseer's shore, a young Horde shaman receives Water Sapta for a journey across the Great Sea. The trial leads from the Barrens to Silverpine Forest, where a spring has been corrupted. Among Horde shaman, a sapta is a draught that opens the senses to the world's spirits. A stream may look calm and a pond still to ordinary eyes. Drink a sapta, and the veil of the physical world parts. Then the elementals dwelling in the water come into view. After the shaman proves devotion to the spirits, Islen Waterseer gives them the draught. She lives alone on the barren shore south of Ratchet. Then she sends the initiate across the Great Sea, from Kalimdor's dry valleys to Silverpine Forest. There, an elemental corruption poisons Lordaeron's streams, and the shaman must face it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_972-133496bdf580ada561ac/1-0000.mp3", duration = 49.0579592, start = 0},
  },
}
P.transport["quest:97250"] = {
  hash = "232a30",
  fullHash = "232a30",
  text = "Wrongly Blamed, Justly Corrected. Along the eastern coast, Wrongly Blamed, Justly Corrected follows rising Horde and Alliance tensions after a roadside tavern is destroyed. The incident warns Alliance forces, while the question of who threatened a vital civilian trade route remains open. Along the eastern coast, Horde and Alliance skirmishes are reaching contested ground. Then a tavern on a major thoroughfare is destroyed. Ordinary travelers now face danger, and the region's stability is at risk. The affair ends in victory for Horde forces in the area, though questions about the tavern remain. The result warns the Alliance that any move into Horde territory along the coast will meet immediate resistance.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_97250-ccfa010c1f00be63e3cf/1-0000.mp3", duration = 42.6840816, start = 0},
  },
}
P.transport["quest:97288"] = {
  hash = "c85745",
  fullHash = "c85745",
  text = "Unending Torment. The head of a fallen abomination sets Unending Torment in motion. Its repeated stitching points toward deliberate dark experimentation in the Forsaken capital, and you bring it to Master Apothecary Faranell in the Undercity. When the towering abomination falls in battle, its head topples from its shoulders. The neck was severed, stitched, torn away, and reattached many times. Each repair left the seam more fragile, until the head barely clung to its shoulders.\n\nSuch persistent patchwork is unusual even for undead constructs. The repeated destruction and reassembly suggest this abomination was rebuilt again and again. Ordinary scavengers could not explain its craftsmanship. Only the skilled flesh-crafters of the Undercity could identify the creature's origins.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_97288-98e16452069b247fdb73/1-0000.mp3", duration = 48.0653061, start = 0},
  },
}
P.transport["quest:97289"] = {
  hash = "2189af",
  fullHash = "2189af",
  text = "Unending Torment. In the Undercity, the Forsaken prepare to question a fallen Alliance commander. They mean to give Grand Marshal Othmar Garithos a new body, and learn what he carried to his grave. Deep in the Undercity, Forsaken practitioners stitch abominations from discarded pieces of the dead. Among the preserved skulls lies one with a bitter history: the severed head of Grand Marshal Othmar Garithos. He led the surviving Alliance forces across Lordaeron, until the Dark Lady killed him.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_97289-9befc927f5b7529c6392/1-0000.mp3", duration = 28.1861224, start = 0},
  },
}
P.transport["quest:97290"] = {
  hash = "d9b3c5",
  fullHash = "d9b3c5",
  text = "Unending Torment. At the Undercity, a defiant subject refuses the Royal Apothecary Society's demands. Master Apothecary Faranell welcomes the news, eager to break a difficult captive. A subject under the Royal Apothecary Society's scrutiny despises you. The captive calls you an abomination and refuses to help. Such hatred is familiar to the Forsaken, for many living beings and captives recoil from Lordaeron's undead. You bring the subject's refusal to Master Apothecary Faranell in the Undercity. The head of the Royal Apothecary Society greets the news with wicked delight. To him, resistance makes the subject a challenge, fit for the cruel experiments of the Apothecarium.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_97290-5b99c9f14b9c4da55af0/1-0000.mp3", duration = 42.4228571, start = 0},
  },
}
P.transport["quest:97291"] = {
  hash = "99e496",
  fullHash = "99e496",
  text = "Unending Torment. In the Undercity, Master Apothecary Faranell prepares a brew to bind a captive to the Dark Lady's will. He needs lethal reagents from across the Forsaken capital to finish it. Deep in the Undercity's Apothecarium, Master Apothecary Faranell conducts experiments to strengthen the Forsaken. He has reattached the severed head of a battered captive. Now he needs a special alchemical mixture to crush the creature's remaining resistance and bind its will to Lady Sylvanas Windrunner. Faranell sends his agent across the Undercity to gather potent ingredients for his brew. A Toxic Skullcap comes from Tawny Grisette in the Trade Quarter. Blisterweed is held by nearby herbalist trainers who owe him a debt, and a poison vendor in the Rogues' Quarter sells Essence of Agony.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_97291-328823be26005dd44435/1-0000.mp3", duration = 47.8040816, start = 0},
  },
}
P.transport["quest:97292"] = {
  hash = "b20296",
  fullHash = "b20296",
  text = "Unending Torment. Master Apothecary Faranell sets a punishment in motion beneath the Undercity. In the Apothecarium, the Royal Apothecary Society turns Hissing Serum against Othmar’s remains, seeking lasting retribution for crimes against the Dark Lady. In the Undercity’s Apothecarium, Master Apothecary Faranell conducts harsh experiments against the Forsaken’s enemies. He has prepared Hissing Serum, a caustic substance meant to drip without end onto a captive beneath an alchemical apparatus.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_97292-d5af75f61c38d9a57f76/1-0000.mp3", duration = 29.6489796, start = 0},
  },
}
P.transport["quest:973"] = {
  hash = "a74817",
  fullHash = "a74817",
  text = "The Tower of Althalaxx. At the Tower of Althalaxx, dark cultists lead Delgren the Purifier to Ilkrud Magthrull. He sends you south through Darkshore into Ashenvale to slay the orc warlock at Fire Scar Shrine and recover his tome. Delgren the Purifier traces the dark cultists at the Tower of Althalaxx to Ilkrud Magthrull, an orc warlock. Ilkrud works from Fire Scar Shrine in southwestern Ashenvale. Delgren fears his magic could spread through the elven woodlands, so he sends you to kill the warlock and take his tome. He hopes its contents will reveal his master's designs.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_973-5fae7bb2ec4c9b244748/1-0000.mp3", duration = 34.8473469, start = 0},
  },
}
P.transport["quest:97538"] = {
  hash = "f7c470",
  fullHash = "f7c470",
  text = "Pigments for Paints. Tah Winterhoof needs red pigment for his paints, and you can help him replenish it. The color comes from mirkweed pods gathered in Mirkfallon Lake in the Stonetalon Mountains. Tah Winterhoof has run out of red pigment and cannot continue his work. He lives in Thunder Bluff, and his traveling days are behind him. So he asks you to make the long journey north into the Stonetalon Mountains and gather more coloring. Mirkfallon Lake lies in a mountain pass in the Stonetalon Mountains. Mirkweed grows beneath its waters, and its seed pods turn red when harvested and dried. Gather thirty pods, and Tah will have the raw material he needs to return to his work.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_97538-de2f2ec3d8d634a9c8f1/1-0000.mp3", duration = 39.68, start = 0},
  },
}
P.transport["quest:976"] = {
  hash = "cfec7c",
  fullHash = "cfec7c",
  text = "Supplies to Auberdine. Feero Ironhand carries provisions and messages from Maestra's Post to Auberdine, and the road north needs guards. Trouble near the Tower of Althalaxx and hostile infiltrators make the journey unsafe. Maestra's Post stands on Ashenvale's western frontier, between the forest and Darkshore. After investigations into sinister activity near the Tower of Althalaxx, Delgren the Purifier sends supplies and intelligence to Sentinel Starbreeze in Auberdine. The outpost trusts armed escorts over lone couriers, so Feero Ironhand travels the forest road with guards.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_976-0c903e3ef51b4a5cffff/1-0000.mp3", duration = 34.037551, start = 0},
  },
}
P.transport["quest:98013"] = {
  hash = "4a162a",
  fullHash = "4a162a",
  text = "Swelling Forces. At the Grove of the Ancients, Arbal sends defenders against the Stormscale naga in the northeast ruins. These cursed former Highborne threaten the surrounding woodlands as their numbers grow. Arbal watches the northeast ruins from the Grove of the Ancients with grave concern. Cursed Highborne have become the serpent-like naga of the Stormscale tribe. They now occupy the remains of their old civilization, and their growing army could spread beyond the ruins into the wider forest. Arbal sends defenders there to cut down their numbers before that happens.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98013-5d244ea99e416d9c0ac2/1-0000.mp3", duration = 32.235102, start = 0},
  },
}
P.transport["quest:98071"] = {
  hash = "2129b7",
  fullHash = "2129b7",
  text = "Brewer's Trade. In Hillsbrad, you carry Fallrook Varietal to Dun Garok, where the brew-kin trade for Homebrew Hops. They miss the Fallrook family's vineyards, and cases of wine remain in the cellars. Fallrook wine still waits in the cellars, though most of the family's best bottled years are long gone. The brew-kin at Dun Garok miss those vineyards, so a trade has been arranged. You carry a case southeast to Dun Garok. The brew-kin gather beside the fireplace at the base of their fort. In return, you bring back a sack of their Homebrew Hops.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98071-b24cc08cdd0c6b0e7dfc/1-0000.mp3", duration = 32.6269388, start = 0},
  },
}
P.transport["quest:981"] = {
  hash = "a54cbb",
  fullHash = "a54cbb",
  text = "The Tower of Althalaxx. Beneath the tower's shadow, the Cult of the Dark Strand has been broken. Word of victory travels south to Delgren the Purifier in Ashenvale, closing the campaign against the cult in Darkshore. For weeks, the Cult of the Dark Strand held the Tower of Althalaxx in northern Darkshore. Tracking its movements, gathering intelligence, and meeting it in violent skirmishes dismantled its work. The cult's sorcerers are slain, and its dark rituals are broken. The immediate danger of demonic infiltration in Darkshore has ended. After the cult leader's death, Balthule Shadowstrike sends you south to Maestra's Post beneath the Ashenvale canopy. Delgren the Purifier waits there. A devoted warrior of the Holy Light, he oversaw the fight against the tower's wicked occupants. Your report of the cult's collapse eases the regional defenders' minds. Delgren gives you his lasting blessing and gratitude.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_981-6cdfa3ccc2a622ab9339/1-0000.mp3", duration = 56.0587755, start = 0},
  },
}
P.transport["quest:98155"] = {
  hash = "097941",
  fullHash = "097941",
  text = "Pristine Pesterhide Pelts. In Thousand Needles, Kristy Grant hopes to send Pesterhide pelts to her sisters in Stormwind. They can make the hides into garments and goods, while Kristy relies on travelers to gather them. As Kristy Grant crosses the canyon floor of Thousand Needles, the Pesterhide hyenas catch her eye. Their pelts are little known in the Eastern Kingdoms, and she hopes to send some home to her sisters in Stormwind. Skilled hands in her family can turn the hides into fine garments and goods. Kristy Grant knows craft and trade, but she has no combat experience. Pesterhide hyenas roam beneath the mesas in vicious packs, so gathering their hides alone is dangerous. She relies on seasoned travelers to bring her five undamaged pelts for her sisters to work with back home.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98155-5ecc6c855a9a4c13efb4/1-0000.mp3", duration = 46.5502041, start = 0},
  },
}
P.transport["quest:98190"] = {
  hash = "0a31ad",
  fullHash = "0a31ad",
  text = "A Friend of the Family. In Menethil Harbor, leaders fear their relics will fall into enemy hands. They send the Menethil Statuette to Highlord Bolvar Fordragon in Stormwind Keep for safekeeping. Menethil Harbor links the northern Eastern Kingdoms with the south. It bears the name of the late King Terenas Menethil II of Lordaeron. Yet treacherous marshes and enemies surround the port. With danger growing, its leaders fear the outpost cannot guard relics from the fallen northern kingdom. Dragonmaw orcs still infest the Wetlands. Their clan has a dark past and favors ruthless advantage. Harbor defenders fear the orcs will seize the Menethil Statuette for conquest. They might defile it or turn it to their own ends. The courier takes the relic straight to Stormwind Keep, past the usual military and bureaucratic channels. There, Highlord Bolvar Fordragon receives it as regent to the young King Anduin Wrynn. The capital's leaders are trusted to guard a piece of Lordaeron's heritage.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98190-f967a6b452c0b2b04ee8/1-0000.mp3", duration = 58.4097959, start = 0},
  },
}
P.transport["quest:98191"] = {
  hash = "84f347",
  fullHash = "84f347",
  text = "A Friend of the Family. Highlord Bolvar Fordragon sends a rare likeness of King Terenas to the Cathedral of Light. Lord Grayson Shadowbreaker will keep the Menethil Statuette safe. King Terenas Menethil II helped shape the Grand Alliance during the Second War. He lived with deep personal devotion, yet held great standing among humanity's kingdoms. Humble by nature, he disliked monuments made in his honor. Few likenesses were commissioned, and fewer survived Lordaeron's ruin and the Scourge's devastation. Highlord Bolvar Fordragon sees more than fine carving in the surviving Menethil Statuette. The Holy Light has begun to gather within it, lending the figure a quiet spiritual presence. Bolvar decides Stormwind Keep is no place for so sacred a piece. He sends it across the city to the Cathedral of Light, into the care of Lord Grayson Shadowbreaker, who trains paladins.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98191-34f5582bc9b930d76b36/1-0000.mp3", duration = 53.995102, start = 0},
  },
}
P.transport["quest:98197"] = {
  hash = "4eeddb",
  fullHash = "4eeddb",
  text = "Spoils of War. As the Dragonmaw move, Valstag Ironjaw seeks timber and iron from Menethil Harbor. He needs them to strengthen the town’s defenses. Menethil Harbor once served the Old Horde as a staging ground for an invasion of Hillsbrad. The fleet built there drew on resources stolen from Khaz Modan. Some supplies remain in the harbor, and Valstag asks you to bring him the timber and iron for the town’s defenses.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98197-a8e2952a6152f56cda0c/1-0000.mp3", duration = 23.6930612, start = 0},
  },
}
P.transport["quest:98208"] = {
  hash = "376b40",
  fullHash = "376b40",
  text = "Bloom of the Heavens. Sylessa Duskwhisper searches the waters south of Menethil Harbor for Bloom of the Heavens. The sacred flower Nord'el was lost when the night elf vessel Flying Osprey wrecked alongside ships of the Kul Tiran Third Fleet. Murlocs now occupy the wreck, where Nord'el lies among the ruins. Sylessa Duskwhisper has come from Auberdine to Menethil Harbor to recover Nord'el. The flower was gathered beneath a full moon atop Mount Hyjal, and holds deep meaning for the night elves. Those who now live in Teldrassil treasure relics from their ancestral mountain as reminders of their heritage. Many moons ago, the night elf vessel Flying Osprey wrecked on the rocky coast south of Menethil Harbor while sailing with the Kul Tiran Third Fleet. Its ruined hull rests in the shallows. Fierce murloc raiders have made the wreck their home and defend it from anyone seeking the night elf cargo.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98208-2b43e77fd9540a8ecdc3/1-0000.mp3", duration = 53.2897959, start = 0},
  },
}
P.transport["quest:98209"] = {
  hash = "86412e",
  fullHash = "86412e",
  text = "Bloom of the Heavens. Across the Great Sea, Nord'el is bound for Auberdine after its recovery in the Wetlands. For night elves still grieving the loss of their immortality, the flower carries the grace of Elune. In the Wetlands, Sylessa recovers Nord'el, the legendary flower, despite an attack by local murlocs. Worn out by her escape, she entrusts the plant to you for its voyage across the Great Sea to Auberdine. From Menethil Harbor, a boat sails directly to Darkshore, linking the Eastern Kingdoms with northern Kalimdor. When Nord'el reaches Auberdine, Elder Thundris Windweaver is astonished. He believed the sacred bloom had vanished forever. Night elves still bear the cost of surrendering their immortality after the Battle of Mount Hyjal, and Nord'el's survival feels like a blessing from Elune. Thundris prepares to send the delicate plant to Darnassus, where it can be cultivated and preserved for future generations.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98209-cb5412aa7e751ecb6a58/1-0000.mp3", duration = 57.4432653, start = 0},
  },
}
P.transport["quest:98245"] = {
  hash = "6202ff",
  fullHash = "6202ff",
  text = "Razormaw Needling. In the Wetlands, Howin Kindfeather seeks Razormaw teeth for dragon whelp armor. He plans to make awls that can stitch the scales together against dragonfire. Howin Kindfeather means to strike back at the foes who have plagued the Wetlands: the Dark Iron dwarves, the Dragonmaw orcs, and the drakes they brought into battle. He is making armor from dragon whelp scales to guard against dragonfire. Their hides are too tough for ordinary tools to sew. Howin needs sharp, sturdy tools to pierce the whelp hide. He looks to the Razormaw raptors that stalk Raptor Ridge in the northeast and Saltspray Glen in the northwest. Their needle-sharp incisors make strong awls. These can pierce dragon scales without shattering under pressure.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98245-5def8bd43bb35a8ba57e/1-0000.mp3", duration = 44.0685714, start = 0},
  },
}
P.transport["quest:98246"] = {
  hash = "f8684c",
  fullHash = "f8684c",
  text = "Trying Times. Before Howin Kindfeather can fly through the Wetlands, Bassbeak needs a meal. He seeks a dozen intact eggs from the fierce Razormaw raptors. Howin Kindfeather tends Bassbeak in the Wetlands. The dwarf will not fly with his gryphon until her hunger is eased. A hungry gryphon can be stubborn and unpredictable. She may lash out, so a proper meal must come before any flight through the marshes. Howin seeks food for Bassbeak among the Razormaw raptors. Their nests lie at Raptor Ridge to the northeast and Saltspray Glen to the northwest. Razormaw eggs have yolks as large as a gnome's head. Howin wants those substantial meals to satisfy Bassbeak before she faces the dangers of the Wetlands.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98246-ef1cb61eea425940f5cd/1-0000.mp3", duration = 43.6767347, start = 0},
  },
}
P.transport["quest:98283"] = {
  hash = "0f6110",
  fullHash = "0f6110",
  text = "Carnage. In the Wetlands, Rethiel the Greenwarden asks you to draw Carnage from its lair. The Razormaw alpha's plague-driven frenzy has thrown the marshes out of balance. The Razormaw raptors once kept wild growth in check across the Wetlands. Now a bloodthirsty alpha named Carnage rules the pack. It slaughters without restraint and terrorizes its own kind. The marshes are in turmoil. Rethiel the Greenwarden watches over the Green Belt and believes corruption has taken hold of Carnage. Diseased Rotclaw bears came down from Loch Modan. You gather their malignant entrails and place the foul meat in Carnage's cave below Raptor Ridge. The frenzied alpha attacks, and its suffering can end.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98283-a4d086abae4671be62e4/1-0000.mp3", duration = 41.0644898, start = 0},
  },
}
P.transport["quest:98291"] = {
  hash = "ef18bf",
  fullHash = "ef18bf",
  text = "Death to the Dragonmaw. At Dragonmaw Retreat, Howin Kindfeather asks you to thin the Dragonmaw ranks. He hopes to reach Grim Batol and reclaim it for the Wildhammers, or learn more about it. Dragonmaw orcs have gathered along the retreat, where red dragons routed them before. Howin needs their numbers reduced before he can approach Grim Batol. He points you east along the road to find them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98291-0e183a2d2201879cf4e5/1-0000.mp3", duration = 22.4653061, start = 0},
  },
}
P.transport["quest:98293"] = {
  hash = "6478ec",
  fullHash = "6478ec",
  text = "Forced Disarmament. At Dragonmaw Retreat, you seize thirty bundles of weapons from hostile orcs for Captain Stoutfist. Their loss keeps the clan from arming more soldiers for future raids. You carry the gear to Captain Stoutfist at Menethil Keep, helping protect the region’s vital harbor. In the Wetlands, the Dragonmaw clan has stored a troubling number of weapons at Dragonmaw Retreat. Left there, they could arm fresh bands of warriors for raids on nearby settlements. Taking the weapons weakens the orcs’ preparations before their warbands can take the field. Menethil Harbor links Khaz Modan and Stormwind to the sea, making it a vital port. Nearby military buildup puts it in danger. Captain Stoutfist directs the harbor’s defenses from Menethil Keep and watches hostile clans and beasts draw near. Recovering thirty sets of Dragonmaw armaments deprives the orcs of weapons and gives the dwarven garrison a measure of their readiness.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98293-7c2511afad69be43a3f0/1-0000.mp3", duration = 55.797551, start = 0},
  },
}
P.transport["quest:98299"] = {
  hash = "f01caa",
  fullHash = "f01caa",
  text = "Stop the Spread. At Silverpine Forest's southern border, refugees gather by the Greymane Wall as Arugal's worgen spread. Researchers seek a way to halt the affliction, while orders aim to keep the living refugees from becoming his servants. In Silverpine Forest, worgen spread under renegade Archmage Arugal's hand. Researchers do not yet know exactly how the feral affliction passes from one victim to another. Its danger to the territory is plain. They study the magic while trying to keep Arugal from gathering an overwhelming host of savage followers.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98299-e2339d2f10ed768896b8/1-0000.mp3", duration = 32.5746939, start = 0},
  },
}
P.transport["quest:98310"] = {
  hash = "a4ca28",
  fullHash = "a4ca28",
  text = "Gleaning Our Future. Prospector Whelgar sees a way to learn more from the Goaz Stone. Four larger golems bear names that match its missing pieces. You've found missing pieces of the Goaz Stone. Prospector Whelgar points to four larger golems named Ados, Modr, Golm, and Neru. He asks you to use the stone near each one, then bring their hearts back. He hopes they will reveal more of its markings.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98310-55a0db43e58000ac7883/1-0000.mp3", duration = 23.8236735, start = 0},
  },
}
P.transport["quest:98341"] = {
  hash = "103bc2",
  fullHash = "103bc2",
  text = "The Great Windborne Cat Spirit. In Moonglade, the Avatar of Saeyleenan guides young shen'dorei druids through a spiritual trial. The spirit comes from Zephras and helps them embody the windborne feline form of their homeland. South of Moonglade's twin bridges, a spirit from distant Zephras has appeared in the sacred sanctuary. Calling itself the Avatar of Saeyleenan, this windborne cat spirit has crossed into Azeroth to guide young shen'dorei druids ready to unlock their feline form. Druids seek wisdom in the feline form, but those from Zephras follow a different tradition from Azeroth's native peoples. The shen'dorei embody the windborne predator of their homeland instead of an Azerothian wildcat. So Saeyleenan oversees their trial in Moonglade, to teach them the spirit's nature.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98341-d221063e5e1a434c93cf/1-0000.mp3", duration = 46.8897959, start = 0},
  },
}
P.transport["quest:98362"] = {
  hash = "fbb518",
  fullHash = "fbb518",
  text = "To Thunder Bluff. Back in Thunder Bluff, a young tauren druid returns in triumph after communion in Moonglade. The Great Cat Spirit has favored the initiate, who now seeks Turak Runetotem on the Elder Rise to master feline shapeshifting. You return to Mulgore after meeting dendrite starblaze and the great cat spirit in Moonglade's sacred groves. The communion joins ancient night elven teachings with the tauren's earthen heritage. It marks a pivotal milestone in a druid's training. Turak Runetotem awaits you atop the Elder Rise in Thunder Bluff. dendrite starblaze guided your communion with the great cat spirit, and Turak now teaches the physical change. With the spirit's blessing acknowledged, the elder trainer shows you how to take the cat's swift, predatory shape.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98362-832ebf96fae0177909e2/1-0000.mp3", duration = 47.2555102, start = 0},
  },
}
P.transport["quest:98387"] = {
  hash = "5c6038",
  fullHash = "5c6038",
  text = "Blackrock Blockade. Marshal Marris presses the Blackrock Blockade east of Lake Everstill. Lakeshire's guard means to starve out the Blackrock orcs and seize their weapons. Blackrock raiders in Redridge have driven the Alliance forces to their limits. Their forward parties are cut off from regular supply trains and live off the hills. Marshal Marris knows even fierce orcs cannot fight for long without food and steel. South of Stonewatch Keep, Blackrock camps mark the clan's advance. Lakeshire's defenders strike those camps for supplies and stolen weapons. Each seizure weakens the orcs' strength and morale.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98387-4a0169065c3c648e658d/1-0000.mp3", duration = 36.8587755, start = 0},
  },
}
P.transport["quest:98393"] = {
  hash = "fd298c",
  fullHash = "fd298c",
  text = "The Great Cat Spirit. In Nighthaven, druids gather at Dendrite Starblaze's call to learn the cat's ways. They have mastered the bear and now turn to another aspect of the wild under Father Cenarius's blessing. Druids who have mastered the enduring bear are summoned to Moonglade again. Elder Dendrite Starblaze calls them to Nighthaven, where they can deepen their communion with nature. Their spiritual gifts carry them across the distance to this haven of Cenarion wisdom. When you reach Nighthaven, Dendrite Starblaze invokes Father Cenarius and greets you with a faint aura of power. He says it is time to embrace the cat's perspective: swift, agile, and predatory. As before, Dendrite opens the path to understanding, while the work of embodying and spreading the feline spirit rests with you.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98393-6bdd876e9d2d25de5fa4/1-0000.mp3", duration = 47.7257143, start = 0},
  },
}
P.transport["quest:98397"] = {
  hash = "f31b48",
  fullHash = "f31b48",
  text = "To Darnassus. In Darnassus, you return to the Cenarion Enclave after your trial with the Great Cat Spirit. Having proved yourself to Dendrite Starblaze in Moonglade, you come to Mathrengyl Bearwalker to learn cat form. You return to Teldrassil after meeting the Great Cat Spirit under Dendrite Starblaze's guidance in Moonglade. Starblaze has seen you prove yourself as a worthy student. So he sends you to your primary instructor, Mathrengyl Bearwalker. He waits beneath the boughs of the Cenarion Enclave in Darnassus. In Darnassus, Mathrengyl Bearwalker sees the wisdom you gained from the Great Cat Spirit. Each generation of druids faces a trial shaped by this ancient spirit, playful yet deadly. Your bond is made, and your spirit is ready. Mathrengyl teaches you the final rites for taking cat form.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98397-07d375e325075c38bcb8/1-0000.mp3", duration = 50.1028571, start = 0},
  },
}
P.transport["quest:98404"] = {
  hash = "715728",
  fullHash = "715728",
  text = "The Great Windborne Cat Spirit. At the Avatar of Saeyleenan, young druids face a trial of cunning and stealth. They enter the nearby Stormrage Barrow Den to recover three relics while avoiding enraged spirits. Passing the rite earns them the blessing to wield cat form. A seeker must show the nature of a predator before drawing upon the Great Windborne Cat Spirit. The cat calls for cunning and patience, then fierce action when cornered. The spirit tests those who seek its power, asking them to think, move, and strike like wild feline hunters. Only then may an initiate earn the right to take the cat's shape. The trial leads into the Stormrage Barrow Den, just east of the spirit's avatar. Three sacred tokens lie in its halls: the Relic of the Fang, the Relic of the Claw, and the Relic of the Silent Shadow.\n\nEnraged spirits have overrun the den and attack intruders on sight. A seeker cannot rely on brute force alone, but must tread carefully through the darkness to reach the relics. The Avatar of Saeyleenan is the physical manifestation through which the Great Windborne Cat Spirit speaks to young initiates. Untutored seekers lack a seasoned predator's stealth, so a statue at the barrow den's entrance grants them temporary concealment.\n\nThose who slip past the frenzied spirits and return all three relics show they have learned the predator's ways. The Avatar recognizes their worthiness and grants the blessing to wield cat form.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98404-0809e27dc939ce97f15d/1-0000.mp3", duration = 87.797551, start = 0},
  },
}
P.transport["quest:98459"] = {
  hash = "e2c31f",
  fullHash = "e2c31f",
  text = "A Lack of Virtue. Tom Half-fish sends a parcel across the sea to Bart Tidewater in Menethil Harbor. Their old quarrel over cards and the Maiden's Virtue now reaches a traveler carrying it. Tom Half-fish asks you to carry a parcel across the water to Bart Tidewater in Menethil Harbor. The delivery is meant to sting his former companion. Tom says Bart is no true sea dog, but an actor who cheated at cards to buy his command.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98459-4f3797c3e732d3d69ab1/1-0000.mp3", duration = 24.3461224, start = 0},
  },
}
P.transport["quest:98461"] = {
  hash = "2e7387",
  fullHash = "2e7387",
  text = "Unrequited Love. In Auberdine, Hollee sends a personal note across the sea to Tarrel Rockweaver, the classmate she still loves. Hollee watches travelers board ships in Auberdine, the port town on Darkshore’s coast. She hopes one bound for the Eastern Kingdoms will carry her message to Tarrel Rockweaver. They studied excavation together for years. Then graduation sent them to opposite continents. Hollee recalls Tarrel’s sharp mind and skill with excavation, but falters when she speaks of his wife, Merrin. Though Tarrel is married and far away, Hollee entrusts you with a personal letter. She asks you to find him near Menethil Harbor and make sure he is safe.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98461-ac1a045c611c6ab0d6fa/1-0000.mp3", duration = 38.8702041, start = 0},
  },
}
P.transport["quest:98463"] = {
  hash = "21f965",
  fullHash = "21f965",
  text = "Talk of the Town. Travelers seeking livelier company are directed toward Booty Bay in Stranglethorn Vale. For wilder gatherings, they are sent to Nixxrax Fillamug at the Salty Sailor Tavern. A friendly bartender sends travelers toward Booty Bay, where the port draws those who seek wilder spectacles. Drink servers pass the word to patrons, and it travels beyond the counter. The Salty Sailor Tavern stands in Booty Bay, amid Stranglethorn Vale. Goblins run the lively tavern, where Nixxrax Fillamug keeps the cups filled for all who enter.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98463-a34106ef0c73bc47e45a/1-0000.mp3", duration = 33.044898, start = 0},
  },
}
P.transport["quest:986"] = {
  hash = "92ca2f",
  fullHash = "92ca2f",
  text = "A Lost Master. In Auberdine, Terenthis prepares a way to search for Volcor, missing in Darkshore. He can weave a cloak of camouflage, but first needs pelts from the coast's fiercest moonstalkers. In Auberdine, Terenthis fears for Volcor and his companion Grimclaw as danger closes around Darkshore's coast. Aggressive predators and corrupted wildlife roam the southern wilds. Terenthis will not send an unprotected scout into that danger, so he plans a cloak woven with wild illusions. Ordinary hides cannot fool Darkshore's beasts. Terenthis needs fine pelts from mature moonstalker sires or matriarchs. The great cats roam the woodlands south of Auberdine, near the Wildbend River and toward Ashenvale's forested border. Moonstalker fur and nature enchantments let the wearer pass through hostile territory while searching for Volcor. Terenthis warns that the illusion is delicate. Strenuous activity or combat breaks the enchantment and leaves the searcher exposed.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_986-5571aaa2dcaedc56c455/1-0000.mp3", duration = 59.1412245, start = 0},
  },
}
P.transport["quest:98738"] = {
  hash = "235e5b",
  fullHash = "235e5b",
  text = "Blessings of the Great Windborne Cat Spirit. After meeting the Great Cat Spirit of Zephras, an initiate returns to Dendrite with a newly awakened aura. The blessing brings the wild cat's stealth, speed, and ferocity, and Dendrite prepares the initiate for further instruction. An initiate returns to Dendrite after seeking the Great Cat Spirit of Zephras and earning its favor. The communion has awakened the wild cat's cunning, predatory stealth, and ferocity within them. Dendrite reads the initiate's newly awakened aura with subtle gestures. Sensing feline instincts woven into their spirit, he sees that the initiate is ready to focus their mind and call upon the true aspect of the cat.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98738-a5f6b9447091a98793e7/1-0000.mp3", duration = 37.7208163, start = 0},
  },
}
P.transport["quest:98824"] = {
  hash = "3272a3",
  fullHash = "3272a3",
  text = "Prehistoric Prism. In the Wetlands, Prospector Whelgar has found a relic marked by the keepers. He sends you to Ironforge so the Explorers' League can study the titans' legacy. Prospector Whelgar finds a remarkable artifact while surveying the Wetlands. Keeper inscriptions cover its many facets, and he authenticates the titan-like markings. He asks you to carry it to Ironforge, where scholars can study it. Whelgar hopes the discovery enters the official catalogue, with credit given to you for recovering it and to him for authenticating it. High Explorer Magellas receives the relic for the Explorers' League in Ironforge's Hall of Explorers. The maker marks confirm its authenticity. Magellas says light through its polished facets recalls wonders from his first excavation in Uldaman. Your donation preserves the artifact for study and adds to the League's records of the titans' legacy.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98824-df193d43e059b9dcd714/1-0000.mp3", duration = 50.9387755, start = 0},
  },
}
P.transport["quest:993"] = {
  hash = "a3e7ac",
  fullHash = "a3e7ac",
  text = "A Lost Master. In Darkshore, you follow Grimclaw’s trail to find the missing scout Volcor. Terenthis has made an Enchanted Moonstalker Cloak from fine moonstalker pelts for the search. Terenthis waits in Auberdine with the Enchanted Moonstalker Cloak he has woven. South of the settlement, Grimclaw waits on the road for help sent by Terenthis. The loyal bear belongs to the missing night elf scout Volcor. Give Grimclaw a familiar greeting, and he leads you from the road toward the cave where Volcor is hiding.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_993-5ea462fe931c563a9e2c/1-0000.mp3", duration = 28.5779592, start = 0},
  },
}
P.transport["quest:994"] = {
  hash = "3b9a8a",
  fullHash = "3b9a8a",
  text = "Escape Through Force. In Darkshore, Volcor fights through the wild to reach safety. He finds Grimclaw by the road, and you bring word of his escape to Terenthis in Auberdine. Volcor is stranded in Darkshore’s perilous wilderness, with danger closing around him. He chooses to fight the hostile creatures instead of slipping away unseen. His skill clears a path to the main road and safety.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_994-8f5ae88d9c7e26772306/1-0000.mp3", duration = 22.9616327, start = 0},
  },
}
P.transport["quest:995"] = {
  hash = "581b06",
  fullHash = "581b06",
  text = "Escape Through Stealth. In Darkshore, Volcor needs your help escaping a furbolg den. Guide the trapped night elf scout past hostile beasts, then report to Terenthis in Auberdine. Volcor, a night elf scout, was sent to investigate Darkshore's growing threats. Now he is trapped inside a furbolg cave, cut off from the main roads and outnumbered. He needs your help to escape before the furbolgs discover him. Volcor takes a careful path through the cave instead of charging its corrupted denizens. Once outside, he runs ahead on foot. He asks you to meet him in Auberdine, where he can travel faster alone. Back in Auberdine, you bring news of Volcor's rescue to Terenthis, a night elf leader who works to protect the troubled coast. Volcor's safe return shows that discipline and teamwork can resist the darkness spreading through Darkshore and the wilderness beyond.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_995-65372201a7cd78951a47/1-0000.mp3", duration = 51.722449, start = 0},
  },
}
